export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductComponent } from '../types';
import { X, Plus, Search, Trash2, Save, Package, Layers, Settings, ArrowRight, Box, Filter, Factory, ShoppingCart, Wrench, Building, Download, Upload, FolderTree } from 'lucide-react';

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[]; // NOW REQUIRED
  onAddCategory?: (name: string) => void;
  onDeleteCategory?: (name: string) => void; // New prop for deletion
  onImportCatalog?: (file: File) => void; // New
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen,
  onClose,
  products,
  onAddProduct,
  onUpdateProduct,
  onDeleteProduct,
  customCategories,
  onAddCategory,
  onDeleteCategory,
  onImportCatalog
}) => {
  // MODE SWITCH: 'stock' (Simple items) vs 'sets' (Composite items)
  const [mode, setMode] = useState<'stock' | 'sets'>('stock');

  const [activeCategory, setActiveCategory] = useState(customCategories[0] || 'Dvere');
  const [activeSubcategory, setActiveSubcategory] = useState<string>('ALL'); // Filter by Subcat

  const [searchTerm, setSearchTerm] = useState('');

  // New Supplier Filter
  const [supplierFilter, setSupplierFilter] = useState<string>('');

  // EDITOR STATE
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);

  const [name, setName] = useState('');
  const [manufacturer, setManufacturer] = useState('');
  const [supplier, setSupplier] = useState('');
  const [unit, setUnit] = useState('ks');
  const [price, setPrice] = useState('');
  const [subcategory, setSubcategory] = useState(''); // New Subcategory Field

  // Composite Logic
  const [subProducts, setSubProducts] = useState<ProductComponent[]>([]);
  const [componentSearch, setComponentSearch] = useState('');
  const [componentSourceCategory, setComponentSourceCategory] = useState<string>('ALL');

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Use passed categories as source of truth
  const allCategories = customCategories;

  // Unique suppliers for filter dropdown
  const uniqueSuppliers = Array.from(new Set(products.map(p => p.supplier).filter(Boolean))) as string[];

  // Get Subcategories for current category
  const getSubcategories = (category: string) => {
      // Special logic for Doors
      if (category === 'Dvere') return ['Šachtové', 'Kabínové'];
      // For others, derive from existing products
      const existing = Array.from(new Set(
          products.filter(p => p.category === category && p.subcategory).map(p => p.subcategory)
      ));
      return existing as string[];
  };

  const availableSubcategories = getSubcategories(activeCategory);

  // Reset filter when changing active category or closing
  useEffect(() => {
      if (!isEditing) {
          setComponentSourceCategory(activeCategory);
          setActiveSubcategory('ALL');
      }
  }, [activeCategory, isEditing]);

  // Ensure active category is valid if list changes
  useEffect(() => {
      if (!allCategories.includes(activeCategory) && allCategories.length > 0) {
          setActiveCategory(allCategories[0]);
      }
  }, [allCategories]);

  if (!isOpen) return null;

  const filteredProducts = products.filter(p => 
    p.category === activeCategory && 
    (activeSubcategory === 'ALL' || p.subcategory === activeSubcategory) &&
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) &&
    (mode === 'stock' ? (!p.type || p.type === 'simple') : p.type === 'composite') &&
    (!supplierFilter || p.supplier === supplierFilter)
  );

  const handleEditClick = (p: Product) => {
      setEditId(p.id);
      setName(p.name);
      setManufacturer(p.manufacturer || '');
      setSupplier(p.supplier || '');
      setUnit(p.unit);
      setPrice(p.price.toString());
      setSubcategory(p.subcategory || '');
      setSubProducts(p.subProducts || []);
      setComponentSourceCategory(p.category);
      setIsEditing(true);
  };

  const handleNewClick = () => {
      setEditId(null);
      setName('');
      setManufacturer('');
      setSupplier('');
      setUnit('ks');
      setPrice('');
      setSubcategory(activeSubcategory !== 'ALL' ? activeSubcategory : '');
      setSubProducts([]);
      setComponentSourceCategory(activeCategory);
      setIsEditing(true);
  };

  const handleSaveCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setActiveCategory(newCatName);
          setIsAddingCategory(false);
          setNewCatName('');
      }
  };

  const handleDeleteCat = (cat: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (onDeleteCategory && confirm(`Naozaj chcete vymazať kategóriu "${cat}"?`)) {
          // If active, switch to first available
          if (activeCategory === cat) {
              setActiveCategory(allCategories.find(c => c !== cat) || '');
          }
          onDeleteCategory(cat);
      }
  };

  const handleSave = () => {
      if (!name) return;

      let finalPrice = parseFloat(price) || 0;

      // If creating a SET, price is calculated (or manual override allowed in future)
      if (mode === 'sets') {
          finalPrice = subProducts.reduce((acc, item) => {
              const p = products.find(prod => prod.id === item.productId);
              return acc + ((p?.price || 0) * item.quantity);
          }, 0);
      }

      const newProduct: Product = {
          id: editId || crypto.randomUUID(),
          category: activeCategory,
          subcategory: subcategory || undefined,
          name,
          manufacturer: manufacturer || undefined,
          supplier: supplier || undefined,
          unit,
          price: finalPrice,
          type: mode === 'sets' ? 'composite' : 'simple',
          subProducts: mode === 'sets' ? subProducts : undefined
      };

      if (editId) {
          onUpdateProduct(newProduct);
      } else {
          onAddProduct(newProduct);
      }
      setIsEditing(false);
  };

  const addComponent = (productId: string) => {
      const existing = subProducts.find(sp => sp.productId === productId);
      if (existing) {
          setSubProducts(subProducts.map(sp => sp.productId === productId ? { ...sp, quantity: sp.quantity + 1 } : sp));
      } else {
          setSubProducts([...subProducts, { productId, quantity: 1 }]);
      }
  };

  const removeComponent = (productId: string) => {
      setSubProducts(subProducts.filter(sp => sp.productId !== productId));
  };

  const updateComponentQty = (productId: string, qty: number) => {
      setSubProducts(subProducts.map(sp => sp.productId === productId ? { ...sp, quantity: qty } : sp));
  };

  const getProductName = (id: string) => products.find(p => p.id === id)?.name || 'Neznámy produkt';
  const getProductPrice = (id: string) => products.find(p => p.id === id)?.price || 0;

  // -- EXPORT / IMPORT --
  const handleExport = () => {
      const blob = new Blob([JSON.stringify(products, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `katalog_produktov_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleImportClick = () => {
      if (fileInputRef.current) fileInputRef.current.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file && onImportCatalog) {
          onImportCatalog(file);
      }
  };

  const availableComponents = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(componentSearch.toLowerCase());
      const matchesCategory = componentSourceCategory === 'ALL' || p.category === componentSourceCategory;
      const isNotSelf = p.id !== editId;
      const isSimple = !p.type || p.type === 'simple'; // Only simple items go into sets
      return matchesSearch && matchesCategory && isNotSelf && isSimple;
  });

  return (
    <div className="fixed inset-0 bg-white z-[100] flex flex-col">

        {/* Header - Fixed Top */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 shadow-sm shrink-0">
          <div className="flex items-center gap-4">
            <div className="bg-blue-100 p-2 rounded-lg"><Package className="text-blue-700" size={24} /></div>
            <div>
                <h2 className="text-2xl font-bold text-gray-800">Manažér Katalógu</h2>
                <div className="text-sm text-gray-500">Master Data Produktov</div>
            </div>
          </div>

          {/* Data Actions */}
          <div className="flex gap-2">
              <button onClick={handleExport} className="px-4 py-2 bg-white border border-gray-300 rounded text-sm font-bold text-gray-700 flex items-center gap-2 hover:bg-gray-100" title="Zálohovať produkty">
                  <Download size={16}/> Export
              </button>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden"/>
              {onImportCatalog && (
                  <button onClick={handleImportClick} className="px-4 py-2 bg-white border border-gray-300 rounded text-sm font-bold text-gray-700 flex items-center gap-2 hover:bg-gray-100" title="Obnoviť produkty">
                      <Upload size={16}/> Import
                  </button>
              )}
              <div className="w-px bg-gray-300 mx-4"></div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
                <X size={28}/>
              </button>
          </div>
        </div>

        {/* WORKFLOW SWITCHER - TOP BAR */}
        {!isEditing && (
        <div className="p-4 bg-white border-b flex gap-6 justify-center shrink-0">
            <button 
                onClick={() => setMode('stock')}
                className={`flex-1 max-w-sm py-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${mode === 'stock' ? 'border-blue-500 bg-blue-50 text-blue-700 shadow-md ring-1 ring-blue-500' : 'border-gray-200 text-gray-500 hover:border-blue-200 hover:bg-gray-50'}`}
            >
                <ShoppingCart size={32} className={mode === 'stock' ? 'text-blue-600' : 'text-gray-400'}/>
                <div>
                    <div className="font-bold text-lg">NÁKUP NA SKLAD</div>
                    <div className="text-xs opacity-70">Nahrávanie dielov z dodacích listov</div>
                </div>
            </button>

            <button 
                onClick={() => setMode('sets')}
                className={`flex-1 max-w-sm py-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${mode === 'sets' ? 'border-purple-500 bg-purple-50 text-purple-700 shadow-md ring-1 ring-purple-500' : 'border-gray-200 text-gray-500 hover:border-purple-200 hover:bg-gray-50'}`}
            >
                <Wrench size={32} className={mode === 'sets' ? 'text-purple-600' : 'text-gray-400'}/>
                <div>
                    <div className="font-bold text-lg">TVORBA SETOV</div>
                    <div className="text-xs opacity-70">Skladanie dielov do celkov (napr. Kabína)</div>
                </div>
            </button>
        </div>
        )}

        {/* Categories */}
        {!isEditing && (
            <div className="p-2 border-b bg-gray-50 flex gap-2 overflow-x-auto items-center shrink-0 custom-scrollbar">
                {allCategories.map(cat => (
                <button
                    key={cat}
                    onClick={() => setActiveCategory(cat)}
                    className={`group px-6 py-3 rounded-lg text-base font-bold whitespace-nowrap transition flex items-center gap-2 ${
                    activeCategory === cat 
                        ? (mode === 'stock' ? 'bg-blue-600 text-white shadow-md' : 'bg-purple-600 text-white shadow-md')
                        : 'bg-white border text-gray-600 hover:bg-gray-200'
                    }`}
                >
                    {cat}
                    {/* ALWAYS SHOW DELETE for any category if delete handler exists */}
                    {onDeleteCategory && (
                        <span 
                            onClick={(e) => handleDeleteCat(cat, e)}
                            className="p-0.5 rounded-full hover:bg-red-500 hover:text-white opacity-0 group-hover:opacity-100 transition-opacity ml-2"
                            title="Vymazať kategóriu"
                        >
                            <X size={14}/>
                        </span>
                    )}
                </button>
                ))}

                {isAddingCategory ? (
                    <div className="flex items-center gap-1 bg-white border rounded-full px-2 py-1">
                        <input autoFocus className="w-32 text-sm outline-none bg-transparent" placeholder="Názov..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleSaveCategory()} />
                        <button onClick={handleSaveCategory} className="text-green-600 hover:bg-green-100 rounded-full p-1"><Plus size={16}/></button>
                        <button onClick={()=>setIsAddingCategory(false)} className="text-red-500 hover:bg-red-100 rounded-full p-1"><X size={16}/></button>
                    </div>
                ) : (
                    <button onClick={()=>setIsAddingCategory(true)} className="px-4 py-3 rounded-lg border border-dashed border-gray-400 text-gray-500 hover:border-blue-500 hover:text-blue-600 flex items-center gap-1 text-sm whitespace-nowrap"><Plus size={16}/> Pridať Kategóriu</button>
                )}
            </div>
        )}

        {/* MAIN CONTENT */}
        <div className="flex-1 overflow-hidden flex flex-col bg-gray-100">

            {/* EDITOR MODE */}
            {isEditing ? (
                <div className="flex-1 overflow-y-auto p-8">
                    <div className={`bg-white p-8 rounded-xl border shadow-lg max-w-5xl mx-auto ${mode === 'stock' ? 'border-blue-200 shadow-blue-100' : 'border-purple-200 shadow-purple-100'}`}>
                        <div className="flex justify-between items-center mb-8 border-b pb-4">
                            <div>
                                <h3 className={`text-2xl font-bold ${mode === 'stock' ? 'text-blue-800' : 'text-purple-800'}`}>
                                    {editId ? 'Upraviť' : 'Nový'} {mode === 'stock' ? 'Skladový Diel' : 'SET (Skladačka)'}
                                </h3>
                                <div className="text-sm text-gray-500 uppercase font-bold mt-1 flex items-center gap-2">
                                    Kategória: <span className="text-black">{activeCategory}</span>
                                </div>
                            </div>
                            <div className={`px-4 py-2 rounded text-sm font-bold uppercase border ${mode === 'stock' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-purple-50 border-purple-200 text-purple-700'}`}>
                                {mode === 'stock' ? 'Jednoduchý produkt' : 'Kompozitný SET'}
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-6 mb-6">
                            <div className="col-span-2">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Názov {mode === 'stock' ? 'Dielu' : 'Setu'}</label>
                                <input value={name} onChange={e => setName(e.target.value)} className="w-full p-3 text-lg border rounded font-bold focus:ring-2 focus:ring-blue-500 outline-none" placeholder={mode === 'stock' ? "Napr. Skrutka M12x40" : "Napr. Rám Kabíny BP1000 (Komplet)"} autoFocus />
                            </div>

                            {/* NEW SUBCATEGORY FIELD */}
                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase flex items-center gap-1"><FolderTree size={12}/> Podkategória (Voliteľné)</label>
                                <div className="relative">
                                    <input 
                                        list="subcat-options"
                                        value={subcategory} 
                                        onChange={e => setSubcategory(e.target.value)} 
                                        className="w-full p-3 border rounded text-sm bg-gray-50 focus:bg-white transition" 
                                        placeholder={activeCategory === 'Dvere' ? "Napr. Šachtové" : "Napr. Skrutky, Profily..."} 
                                    />
                                    <datalist id="subcat-options">
                                        {activeCategory === 'Dvere' && (
                                            <>
                                                <option value="Šachtové">Šachtové Dvere</option>
                                                <option value="Kabínové">Kabínové Dvere</option>
                                            </>
                                        )}
                                        {availableSubcategories.map(s => <option key={s} value={s}/>)}
                                    </datalist>
                                </div>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Jednotka</label>
                                <select value={unit} onChange={e => setUnit(e.target.value)} className="w-full p-3 border rounded bg-white font-medium">
                                    <option value="ks">ks</option><option value="m">m</option><option value="kpl">kpl</option><option value="hod">hod</option>
                                    <option value="set">set</option>
                                </select>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Výrobca (Značka)</label>
                                <div className="relative">
                                    <Factory className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/>
                                    <input value={manufacturer} onChange={e => setManufacturer(e.target.value)} className="w-full pl-10 p-3 border rounded text-sm" placeholder="Napr. Wittur, Fermator..." />
                                </div>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Dodávateľ (Kde kúpené)</label>
                                <div className="relative">
                                    <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/>
                                    <input value={supplier} onChange={e => setSupplier(e.target.value)} className="w-full pl-10 p-3 border rounded text-sm" placeholder="Napr. Eshop, Lokálny predajca..." />
                                </div>
                            </div>

                            <div className="col-span-2 bg-gray-50 p-4 rounded border border-gray-200">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Nákupná Cena (€)</label>
                                <input 
                                    type="number" 
                                    value={mode === 'sets' ? subProducts.reduce((acc, i) => acc + (getProductPrice(i.productId)*i.quantity), 0).toFixed(2) : price} 
                                    onChange={e => setPrice(e.target.value)} 
                                    className={`w-full p-3 border rounded font-bold text-right text-2xl ${mode === 'sets' ? 'bg-gray-200 text-gray-500' : 'bg-white text-black'}`}
                                    disabled={mode === 'sets'}
                                    placeholder="0.00"
                                />
                                {mode === 'sets' && <div className="text-xs text-purple-600 text-right mt-2 font-bold flex items-center justify-end gap-1"><Settings size={12}/> Automatický súčet komponentov</div>}
                            </div>
                        </div>

                        {/* COMPOSITE EDITOR (SET BUILDER) */}
                        {mode === 'sets' && (
                            <div className="border-t pt-6 mt-6 bg-purple-50/50 -mx-8 px-8 pb-6">
                                <h4 className="font-bold text-purple-800 mb-2 flex items-center gap-2 text-lg"><Layers size={24}/> Obsah SETU</h4>
                                <div className="text-sm text-gray-500 mb-4">
                                    Vyskladajte tento SET z položiek, ktoré už máte na Sklade.
                                </div>

                                {/* Current Components List */}
                                <div className="bg-white rounded-lg p-4 mb-4 space-y-2 border border-purple-100 min-h-[120px]">
                                    {subProducts.length === 0 && <div className="text-sm text-gray-400 italic text-center py-8">Zatiaľ prázdny set. Pridajte diely zo skladu nižšie.</div>}
                                    {subProducts.map((sp, idx) => (
                                        <div key={idx} className="flex justify-between items-center bg-purple-50 p-3 rounded shadow-sm border border-purple-100">
                                            <div className="flex-1">
                                                <div className="text-base font-bold text-gray-800">{getProductName(sp.productId)}</div>
                                            </div>
                                            <div className="flex items-center gap-4">
                                                <span className="text-sm text-gray-500 font-mono">{getProductPrice(sp.productId).toFixed(2)} €/ks</span>
                                                <div className="flex items-center border rounded bg-white">
                                                    <span className="text-xs px-2 text-gray-500 font-bold">x</span>
                                                    <input 
                                                        type="number" 
                                                        min="0.01"
                                                        step="0.01" 
                                                        value={sp.quantity} 
                                                        onChange={e => updateComponentQty(sp.productId, +e.target.value)}
                                                        className="w-20 p-2 text-center text-sm font-bold bg-white focus:outline-none text-purple-700"
                                                    />
                                                </div>
                                                <button onClick={() => removeComponent(sp.productId)} className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded"><Trash2 size={20}/></button>
                                            </div>
                                        </div>
                                    ))}
                                </div>

                                {/* Component Search & Filter */}
                                <div className="bg-white p-4 rounded-lg border border-gray-200">
                                    <div className="text-sm font-bold text-gray-500 mb-2 uppercase flex items-center gap-2"><Search size={16}/> Hľadať v Sklade</div>
                                    <div className="flex gap-4 mb-4 items-center">
                                         <select 
                                            value={componentSourceCategory}
                                            onChange={(e) => setComponentSourceCategory(e.target.value)}
                                            className="text-sm border rounded p-2 bg-gray-50 font-bold text-gray-700 focus:ring-1 focus:ring-blue-500 outline-none flex-1 max-w-[250px]"
                                         >
                                             <option value="ALL">Celý Sklad</option>
                                             {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                         </select>
                                         <input 
                                            placeholder="Názov dielu..." 
                                            className="flex-1 p-2 border rounded text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                            value={componentSearch}
                                            onChange={e => setComponentSearch(e.target.value)}
                                        />
                                    </div>

                                    {/* Search Results */}
                                    <div className="border rounded mt-1 max-h-48 overflow-y-auto bg-gray-50 shadow-inner">
                                        {availableComponents.length === 0 ? (
                                            <div className="p-4 text-center text-sm text-gray-400">
                                                {componentSearch ? 'Nenašli sa žiadne produkty.' : 'Začnite písať pre vyhľadanie dielov...'}
                                            </div>
                                        ) : (
                                            availableComponents.map(p => (
                                                <button key={p.id} onClick={() => { addComponent(p.id); setComponentSearch(''); }} className="w-full text-left p-3 hover:bg-green-50 text-sm flex justify-between border-b last:border-0 items-center transition group">
                                                    <div>
                                                        <div className="font-bold text-gray-800 text-base group-hover:text-green-700">{p.name}</div>
                                                        <div className="flex gap-2 text-xs text-gray-400 uppercase mt-1">
                                                            <span>{p.category}</span>
                                                            {p.subcategory && <span> • {p.subcategory}</span>}
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <span className="font-mono text-sm bg-white px-2 py-1 rounded border shadow-sm">{p.price.toFixed(2)} €</span>
                                                        <Plus size={20} className="text-green-600 bg-green-100 rounded-full p-1"/>
                                                    </div>
                                                </button>
                                            ))
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-end gap-4 mt-8 pt-4 border-t">
                            <button onClick={() => setIsEditing(false)} className="px-6 py-3 text-gray-600 hover:bg-gray-100 rounded-lg font-bold">Zrušiť</button>
                            <button onClick={handleSave} className={`px-8 py-3 text-white font-bold rounded-lg flex items-center gap-2 shadow-lg hover:shadow-xl transition transform hover:scale-[1.02] ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                                <Save size={20}/> {mode === 'stock' ? 'Naskladniť Diel' : 'Uložiť SET'}
                            </button>
                        </div>
                    </div>
                </div>
            ) : (
                /* LIST MODE */
                <div className="flex-1 overflow-y-auto p-6 bg-gray-100">
                     <div className="flex gap-4 mb-6">
                        {/* Subcategory Filter */}
                        {availableSubcategories.length > 0 && (
                             <div className="relative min-w-[200px]">
                                <FolderTree className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                                <select 
                                    value={activeSubcategory}
                                    onChange={(e) => setActiveSubcategory(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                                >
                                    <option value="ALL">Všetky Podkategórie</option>
                                    {availableSubcategories.map(s => <option key={s} value={s}>{s}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                            <input 
                            type="text"
                            placeholder={`Hľadať v kategórii ${activeCategory}...`}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm text-base"
                            />
                        </div>
                        {/* Supplier Filter */}
                        <div className="relative w-56">
                            <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                            <select 
                                value={supplierFilter}
                                onChange={(e) => setSupplierFilter(e.target.value)}
                                className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                            >
                                <option value="">Všetci Dodávatelia</option>
                                {uniqueSuppliers.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <button onClick={handleNewClick} className={`px-6 py-3 text-white rounded-xl font-bold flex items-center gap-2 shadow-md transition transform hover:scale-105 ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                            <Plus size={20}/> Nový {mode === 'stock' ? 'Diel' : 'SET'}
                        </button>
                    </div>

                    <div className="space-y-3">
                        {filteredProducts.length === 0 && <div className="text-center py-20 text-gray-400 italic text-lg">Žiadne položky.<br/><span className="text-sm">Začnite pridaním nového {mode === 'stock' ? 'dielu' : 'setu'}.</span></div>}

                        {filteredProducts.map(product => (
                            <div key={product.id} className={`bg-white p-5 rounded-xl border shadow-sm flex justify-between items-center group transition-all ${mode === 'sets' ? 'hover:border-purple-300' : 'hover:border-blue-300 border-gray-200'}`}>
                                <div>
                                    <div className="font-bold text-gray-800 flex items-center gap-3 text-xl">
                                        {product.name}
                                        {product.type === 'composite' && (
                                            <span className="text-xs bg-purple-100 text-purple-700 px-3 py-1 rounded-full border border-purple-200 flex items-center gap-1 uppercase tracking-wider font-bold">
                                                <Layers size={12}/> SET
                                            </span>
                                        )}
                                        {product.subcategory && (
                                             <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded border border-gray-200">
                                                 {product.subcategory}
                                             </span>
                                        )}
                                    </div>
                                    <div className="text-sm text-gray-500 flex items-center gap-4 mt-2">
                                        {product.manufacturer && <span className="bg-gray-50 px-2 py-1 rounded text-xs font-bold text-gray-600 border border-gray-100 flex items-center gap-1"><Factory size={12}/> {product.manufacturer}</span>}
                                        {product.supplier && <span className="bg-gray-50 px-2 py-1 rounded text-xs font-bold text-blue-600 border border-gray-100 flex items-center gap-1"><Building size={12}/> {product.supplier}</span>}
                                        <span className="font-mono text-black font-bold text-lg bg-gray-50 px-2 rounded">{product.price.toFixed(2)} € / {product.unit}</span>
                                        {product.type === 'composite' && <span className="text-xs text-purple-500 font-bold">({product.subProducts?.length} komponentov)</span>}
                                    </div>
                                </div>
                                <div className="flex gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={() => handleEditClick(product)} className="px-4 py-2 bg-gray-100 hover:bg-blue-50 text-blue-600 rounded-lg font-bold text-sm flex items-center gap-2 transition"><Settings size={16}/> Upraviť</button>
                                    <button onClick={() => onDeleteProduct(product.id)} className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition"><Trash2 size={20}/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product } from '../types';
import { X, Calculator, Check, AlertTriangle, Settings, Box, Zap, Construction, Truck, Package, Hammer, ArrowLeft, ArrowRight, ListCheck, Search, Plus, Filter, Layers, Save, Trash2, GripVertical, Gauge, ScanLine } from 'lucide-react';

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[]; // These are ALL available categories (Master + Custom)
  onAddCategory?: (name: string) => void;
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean; // Flag to distinguish calculated vs manual items
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    categoryOrder: string[]; // Only active categories
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen,
  onClose,
  layout,
  onInsert,
  products,
  customCategories,
  onAddCategory
}) => {
  // Configurable Tabs Order
  const [tabs, setTabs] = useState<{id: string, label: string, color: string}[]>([]);
  const [activeTab, setActiveTab] = useState('Dvere'); // Default to first logical
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);

  // Active Categories State (User can toggle which categories to include)
  const [activeCategories, setActiveCategories] = useState<Set<string>>(new Set());

  const [isCategorySettingsOpen, setIsCategorySettingsOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  // Options - DEFAULT OFF
  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);

  // Memory Option
  const [rememberManual, setRememberManual] = useState(true);

  // Drag State
  const [draggedItemIdx, setDraggedItemIdx] = useState<number | null>(null);

  // Initialize Active Categories on Open
  useEffect(() => {
      if(isOpen && customCategories.length > 0) {
          // Default all to active if empty (first run)
          if(activeCategories.size === 0) {
              setActiveCategories(new Set(customCategories));
          }
      }
  }, [isOpen, customCategories]);

  // Sync Tabs with Active Categories
  useEffect(() => {
    // Generate tabs from customCategories (which contains MASTER + Custom)
    const generatedTabs = customCategories
        .filter(cat => {
            // Special Logic: 'Oceľová konštrukcia' is only visible if configured
            if (cat === 'Oceľová konštrukcia' && !layout.hasExternalShaft) return false;
            // Always exclude 'addons' from tabs list, handled in footer
            if (['Montáž', 'Doprava', 'Balné'].includes(cat)) return false;
            // Only show if active
            return activeCategories.has(cat);
        })
        .map(cat => ({
            id: cat,
            label: cat,
            color: 'blue' // Default color
        }));

    setTabs(generatedTabs);

    // If active tab is gone, switch to first available
    if (!generatedTabs.find(t => t.id === activeTab)) {
        if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);
    }
  }, [customCategories, activeCategories, layout.hasExternalShaft, activeTab]);

  // --- HELPER FUNCTIONS ---

  // UPDATED: Added Subcategory Filter Logic
  const findStockItem = (keywords: string[], category?: string, subcategory?: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      return products.find(p => {
          const matchName = lowerKeys.every(k => p.name.toLowerCase().includes(k));
          const matchCat = category ? p.category === category : true;
          const matchSub = subcategory ? p.subcategory === subcategory : true;
          return matchName && matchCat && matchSub;
      });
  };

  const findMatchProps = (keys: string[], category?: string, subcategory?: string) => {
      const p = findStockItem(keys, category, subcategory);
      return { productId: p?.id, price: p?.price };
  };

  useEffect(() => {
    if (isOpen) {
        calculateBOM();
    }
  }, [isOpen, layout]);

  const calculateBOM = () => {
    const items: MaterialWizardData['items'] = [];

    const travel = layout.travelHeight || 0;
    const totalHeight = travel + (layout.headroomHeight || 0) + (layout.pitDepth || 0);
    const cwtPos = layout.counterWeightPosition || 'left';
    const railLength = layout.guideRailLength || 5000;
    const railLengthLabel = railLength === 2500 ? '(2.5m)' : '(5m)';

    // --- MAP INTERNAL LOGIC TO CATEGORY NAMES ---
    // This allows us to put calculated items into the correct dynamic category
    const catMap = {
        guides: 'Vodítka a kotvenie',
        doors: 'Dvere',
        cabin: 'Kabína a rám',
        drive: 'Pohon',
        electro: 'Elektro',
        shaftInt: 'Ostatné šachta', // Internals
        construction: 'Oceľová konštrukcia' // Steel Structure
    };

    // --- GUIDES ---
    // Use configured rail length for calculation
    const railsPerLine = Math.ceil(Math.max(0, totalHeight) / railLength) || 1;

    const carRails = railsPerLine * 2;
    const cwtRails = railsPerLine * 2;
    const carFish = Math.max(0, railsPerLine - 1) * 2;
    const cwtFish = Math.max(0, railsPerLine - 1) * 2;

    // Brackets Logic
    const bracketRows = 1 + Math.ceil(Math.max(0, totalHeight - 500) / 2800);
    let mainBrackets = 0, busBrackets = 0, cwtBrackets = 0;

    const isCombined = layout.bracketType === 'combined';

    if (isCombined && (cwtPos === 'left' || cwtPos === 'right')) {
        busBrackets = bracketRows; // 1 per row (Combined BUS console)
        mainBrackets = bracketRows; // 1 per row (Other side)
        cwtBrackets = 0; // BUS console handles CWT
    } else {
        mainBrackets = bracketRows * 2; 
        cwtBrackets = bracketRows;
        busBrackets = 0;
    }

    // Clips Logic
    const isBigCarRail = ['T89', 'T90', 'T125', 'T127'].includes(layout.guideTypeCar || '');
    const isBigCwtRail = ['T89', 'T90', 'T125', 'T127'].includes(layout.guideTypeCwt || '');

    const clipsT2 = (isBigCarRail ? (busBrackets*2 + mainBrackets*2) : 0) + (isBigCwtRail ? (cwtBrackets*2) : 0);
    const clipsT1 = (!isBigCarRail ? (busBrackets*2 + mainBrackets*2) : 0) + (!isBigCwtRail ? (cwtBrackets*2) : 0);

    // --- GENERATE BOM ITEMS (MARKED AS AUTO) ---
    const addAutoItem = (item: any) => items.push({ ...item, isAuto: true });

    // 1. Guides
    const pCarRail = findStockItem([layout.guideTypeCar || 'T90'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Vodidlá Kabína ${layout.guideTypeCar} ${railLengthLabel}`, quantity: carRails, unit: 'ks', productId: pCarRail?.id, price: pCarRail?.price });

    const pCwtRail = findStockItem([layout.guideTypeCwt || 'T50'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Vodidlá Protiváha ${layout.guideTypeCwt} ${railLengthLabel}`, quantity: cwtRails, unit: 'ks', productId: pCwtRail?.id, price: pCwtRail?.price });

    const pCarFish = findStockItem(['spojka', layout.guideTypeCar || 'T90'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Spojka ${layout.guideTypeCar}`, quantity: carFish, unit: 'ks', productId: pCarFish?.id, price: pCarFish?.price });
    const pCwtFish = findStockItem(['spojka', layout.guideTypeCwt || 'T50'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Spojka ${layout.guideTypeCwt}`, quantity: cwtFish, unit: 'ks', productId: pCwtFish?.id, price: pCwtFish?.price });

    if (mainBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola Hlavná', quantity: mainBrackets, unit: 'ks', ...findMatchProps(['konzola', 'hlavná'], catMap.guides) });
    if (busBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola BUS (Kombinovaná)', quantity: busBrackets, unit: 'ks', ...findMatchProps(['konzola', 'bus'], catMap.guides) });
    if (cwtBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola Protiváhová', quantity: cwtBrackets, unit: 'ks', ...findMatchProps(['konzola', 'protiváh'], catMap.guides) });

    if (clipsT2 > 0) addAutoItem({ category: catMap.guides, description: 'Príchytky T2 (Veľké)', quantity: clipsT2, unit: 'ks', ...findMatchProps(['príchytka', 't2'], catMap.guides) });
    if (clipsT1 > 0) addAutoItem({ category: catMap.guides, description: 'Príchytky T1 (Malé)', quantity: clipsT1, unit: 'ks', ...findMatchProps(['príchytka', 't1'], catMap.guides) });

    // 2. Doors (UPDATED WITH SUBCATEGORY)
    const shaftDoorTxt = layout.doorOperation === 'manual' ? 'Manuálne' : 'Automatické';
    const cabinDoorTxt = layout.doorType === 'bus' ? 'BUS' : 'Automatické';

    if (layout.numberOfStops) {
        addAutoItem({ 
            category: catMap.doors, 
            description: `Šachtové dvere ${shaftDoorTxt} ${layout.doorWidth}mm`, 
            quantity: layout.numberOfStops, 
            unit: 'ks', 
            ...findMatchProps([shaftDoorTxt === 'Manuálne' ? 'krídlové' : 'automatické'], catMap.doors, 'Šachtové') 
        });
    }
    addAutoItem({ 
        category: catMap.doors, 
        description: `Kabínové dvere ${cabinDoorTxt} ${layout.doorWidth}mm`, 
        quantity: layout.isThroughCar ? 2 : 1, 
        unit: 'ks', 
        ...findMatchProps([cabinDoorTxt === 'BUS' ? 'bus' : 'automatické'], catMap.doors, 'Kabínové') 
    });

    // 3. Cabin
    addAutoItem({ category: catMap.cabin, description: 'Kabína Kompletná', quantity: 1, unit: 'ks', ...findMatchProps(['kabína'], catMap.cabin) });
    addAutoItem({ category: catMap.cabin, description: 'Rám Kabíny', quantity: 1, unit: 'ks', ...findMatchProps(['rám', String(layout.ratedLoad)], catMap.cabin) });

    // 4. Drive
    const driveKey = layout.tractionMedium === 'ctp' ? 'ctp' : 'lan';
    addAutoItem({ category: catMap.drive, description: 'Trakčný stroj', quantity: 1, unit: 'ks', ...findMatchProps([driveKey, 'stroj'], catMap.drive) });

    const frameKey = layout.machineRoomPosition === 'head' ? 'mrl' : 'rošt';
    addAutoItem({ category: catMap.drive, description: layout.machineRoomPosition === 'head' ? 'Rám pod stroj MRL' : 'Roznášací rošt', quantity: 1, unit: 'ks', ...findMatchProps(['rám', frameKey], catMap.drive) });

    if (layout.suspensionType === '1:1') {
        addAutoItem({ category: catMap.drive, description: 'Odkláňacie kladky', quantity: 2, unit: 'ks', ...findMatchProps(['kladk'], catMap.drive) });
    }

    // 5. Electro
    addAutoItem({ category: catMap.electro, description: 'Rozvádzač a riadenie', quantity: 1, unit: 'ks', ...findMatchProps(['rozvádzač'], catMap.electro) });
    addAutoItem({ category: catMap.electro, description: 'Revízna jazda', quantity: 1, unit: 'ks', ...findMatchProps(['revízna'], catMap.electro) });
    addAutoItem({ category: catMap.electro, description: 'Privolávače a kabeláž', quantity: 1, unit: 'kpl', ...findMatchProps(['kabeláž'], catMap.electro) });

    // 6. Shaft
    addAutoItem({ category: catMap.shaftInt, description: 'Osvetlenie šachty', quantity: 1, unit: 'kpl', ...findMatchProps(['osvetlenie'], catMap.shaftInt) });
    addAutoItem({ category: catMap.shaftInt, description: 'Rebrík do priehlbeňe', quantity: 1, unit: 'ks', ...findMatchProps(['rebrík'], catMap.shaftInt) });

    // 7. Structure (Only if configured)
    if (layout.hasExternalShaft) {
        addAutoItem({ category: catMap.construction, description: 'Oceľové profily (Konštrukcia)', quantity: 1, unit: 'kpl', ...findMatchProps(['profil', 'oceľ'], catMap.construction) });
        addAutoItem({ category: catMap.construction, description: 'Opláštenie (Sklo/Sádrokartón)', quantity: 45, unit: 'm2', ...findMatchProps(['opláštenie', 'sklo'], catMap.construction) });
    }

    // --- LOAD SAVED MANUAL ITEMS ---
    if (rememberManual) {
        try {
            const savedManualItemsStr = localStorage.getItem('smartquote_manual_items');
            if (savedManualItemsStr) {
                const savedManualItems: MaterialWizardData['items'] = JSON.parse(savedManualItemsStr);
                // Validate saved items (ensure category is still valid?) - we just append
                savedManualItems.forEach(manualItem => {
                    // Update price if product ID exists (in case price changed in DB)
                    if (manualItem.productId) {
                        const p = products.find(prod => prod.id === manualItem.productId);
                        if(p) manualItem.price = p.price;
                    }
                    items.push({ ...manualItem, isAuto: false });
                });
            }
        } catch (e) {
            console.error("Failed to load saved manual items", e);
        }
    }

    setBomItems(items);
  };

  const moveTab = (index: number, direction: 'left' | 'right') => {
      if (direction === 'left' && index === 0) return;
      if (direction === 'right' && index === tabs.length - 1) return;

      const newTabs = [...tabs];
      const targetIndex = direction === 'left' ? index - 1 : index + 1;
      [newTabs[index], newTabs[targetIndex]] = [newTabs[targetIndex], newTabs[index]];
      setTabs(newTabs);
  };

  const toggleCategory = (catId: string) => {
      const newSet = new Set(activeCategories);
      if (newSet.has(catId)) {
          newSet.delete(catId);
      } else {
          newSet.add(catId);
      }
      setActiveCategories(newSet);
  };

  const handleAddCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setNewCatName('');
          toggleCategory(newCatName); // Auto activate
      }
  };

  const updateItem = (idx: number, field: string, value: any) => {
      const newItems = [...bomItems];
      // @ts-ignore
      newItems[idx][field] = value;
      if (field === 'productId') {
          const p = products.find(prod => prod.id === value);
          if (p) {
              newItems[idx].price = p.price;
              newItems[idx].description = p.name;
              newItems[idx].unit = p.unit;
          }
      }
      setBomItems(newItems);
  };

  const handleDeleteItem = (index: number) => {
      const newItems = bomItems.filter((_, i) => i !== index);
      setBomItems(newItems);
  };

  const addCustomItem = (isSet: boolean = false) => {
      const cat = activeTab;
      setBomItems([
          ...bomItems, 
          { 
              category: cat, 
              description: isSet ? 'Výber SETU...' : 'Nová požiadavka', 
              quantity: 1, 
              unit: isSet ? 'set' : 'ks', 
              price: 0,
              isAuto: false // Marked as Manual
          }
      ]);
  };

  const handleInsert = () => {
      // SAVE MANUAL ITEMS TO LOCALSTORAGE
      if (rememberManual) {
          const manualItems = bomItems.filter(item => !item.isAuto);
          localStorage.setItem('smartquote_manual_items', JSON.stringify(manualItems));
      } else {
          localStorage.removeItem('smartquote_manual_items');
      }

      // Pass categoryOrder as the list of ACTIVE tabs only
      onInsert({
          items: bomItems,
          includeTransport: includeTransport,
          includePackaging: includePackaging,
          includeAssembly: includeAssembly,
          categoryOrder: tabs.map(t => t.id)
      });
      onClose();
  };

  // DRAG AND DROP FOR BOM ITEMS
  const onDragStartItem = (e: React.DragEvent, index: number) => {
      setDraggedItemIdx(index);
      e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOverItem = (e: React.DragEvent, targetIndex: number) => {
      e.preventDefault();
      if (draggedItemIdx === null || draggedItemIdx === targetIndex) return;

      const newItems = [...bomItems];
      const [reorderedItem] = newItems.splice(draggedItemIdx, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      setBomItems(newItems);
      setDraggedItemIdx(targetIndex);
  };

  if (!isOpen) return null;

  // Items for active tab
  const currentCatName = activeTab;
  const currentItems = bomItems.map((item, index) => ({ item, index })).filter(({ item }) => item.category === currentCatName);

  // Products for dropdown - Filter by active category AND SUBCATEGORY IF DOOR
  const currentAvailableProducts = products.filter(p => {
      if (p.category !== currentCatName) return false;
      // Filter Logic for Doors:
      if (currentCatName === 'Dvere') {
          // Can't easily filter the dropdown PER row if they are different types of doors (shaft/cabin)
          // But we can enable all doors in dropdown.
          return true;
      }
      return true;
  });

  // CABIN AREA CALCULATION
  const cabinArea = ((layout.cabinWidth || 0) * (layout.cabinDepth || 0) / 1000000).toFixed(2);
  const cabinPerimeter = 2 * ((layout.cabinWidth || 0) + (layout.cabinDepth || 0)) / 1000;
  const cabinWallArea = (cabinPerimeter * 2.04).toFixed(2); // 2040mm height (Fundermax)

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Calculator className="text-orange-500" />
            <div>
                <h2 className="text-xl font-bold text-gray-800">Materiálový Sprievodca</h2>
                <div className="text-xs text-gray-500">Nákupný zoznam komponentov</div>
            </div>
          </div>

          {/* CABIN AREA DASHBOARD */}
          <div className="hidden md:flex gap-4 items-center bg-white border px-3 py-1 rounded shadow-sm">
              <div className="flex items-center gap-2 text-sm text-gray-600 border-r pr-3">
                  <ScanLine size={16} className="text-blue-500"/>
                  Podlaha: <span className="font-bold text-black">{cabinArea} m²</span>
              </div>
              <div className="flex items-center gap-2 text-sm text-gray-600">
                  <Gauge size={16} className="text-purple-500"/>
                  Steny (2040mm): <span className="font-bold text-black">{cabinWallArea} m²</span>
              </div>
          </div>

          <div className="flex gap-2">
               <button onClick={() => setIsCategorySettingsOpen(!isCategorySettingsOpen)} className={`p-2 rounded-full border transition ${isCategorySettingsOpen ? 'bg-blue-100 text-blue-600 border-blue-300' : 'text-gray-500 hover:bg-gray-100'}`} title="Správa Kategórií">
                    <Filter size={20}/>
               </button>
               <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
          </div>
        </div>

        {/* Category Settings Popover */}
        {isCategorySettingsOpen && (
            <div className="bg-gray-50 border-b p-4 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4 shadow-inner max-h-48 overflow-y-auto">
                <div className="col-span-full text-xs font-bold text-gray-500 uppercase">Vyberte kategórie, ktoré chcete riešiť (Vypnuté sa vymažú):</div>
                {customCategories.filter(c => !['Montáž','Doprava','Balné'].includes(c)).map(c => (
                    <label key={c} className="flex items-center gap-2 cursor-pointer bg-white border p-2 rounded shadow-sm hover:bg-blue-50">
                        <input type="checkbox" checked={activeCategories.has(c)} onChange={() => toggleCategory(c)} className="rounded text-blue-600"/>
                        <span className="text-sm font-medium break-all">{c}</span>
                    </label>
                ))}

                {/* Add Custom Category Input */}
                <div className="col-span-full flex gap-2 pt-2 border-t mt-2">
                    <input className="border rounded px-2 py-1 text-sm w-48" placeholder="Nová kategória..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleAddCategory()}/>
                    <button onClick={handleAddCategory} className="px-3 py-1 bg-blue-600 text-white rounded text-xs font-bold">Pridať</button>
                </div>
            </div>
        )}

        {/* Tabs with Reordering */}
        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-2 py-2 transition ${activeTab===tab.id ? 'bg-white border-gray-300' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`}>
                     {activeTab === tab.id && idx > 0 && <button onClick={() => moveTab(idx, 'left')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowLeft size={12}/></button>}

                     <button 
                        onClick={() => setActiveTab(tab.id)} 
                        className={`mx-2 text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? `text-${tab.color}-600` : 'text-gray-500'}`}
                     >
                         {tab.label}
                     </button>

                     {activeTab === tab.id && idx < tabs.length - 1 && <button onClick={() => moveTab(idx, 'right')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowRight size={12}/></button>}
                 </div>
            ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">
            {currentItems.length === 0 && <div className="text-center text-gray-400 italic py-8">Žiadne položky v tejto kategórii.<br/>Kliknite na tlačidlá nižšie pre pridanie.</div>}

            {currentItems.length > 0 && (
            <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                        <tr>
                            <th className="w-8"></th>
                            <th className="p-3 text-left w-1/3">Požiadavka (Výpočet)</th>
                            <th className="p-3 text-left w-1/3">Produkt zo Skladu / SET</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {currentItems.map(({ item, index: originalIndex }) => {
                            // Filter logic for specific row dropdown
                            let rowProducts = currentAvailableProducts;
                            if (currentCatName === 'Dvere') {
                                // Smart filtering based on item description content
                                if (item.description.includes('Šachtové')) {
                                    rowProducts = currentAvailableProducts.filter(p => !p.subcategory || p.subcategory === 'Šachtové');
                                } else if (item.description.includes('Kabínové')) {
                                    rowProducts = currentAvailableProducts.filter(p => !p.subcategory || p.subcategory === 'Kabínové');
                                }
                            }

                            return (
                                <tr 
                                    key={originalIndex} 
                                    draggable
                                    onDragStart={(e) => onDragStartItem(e, originalIndex)}
                                    onDragOver={(e) => onDragOverItem(e, originalIndex)}
                                    className={`transition ${item.isAuto ? 'hover:bg-blue-50' : 'bg-yellow-50 hover:bg-yellow-100'}`}
                                >
                                    <td className="p-2 text-center text-gray-300 cursor-grab hover:text-gray-500">
                                        <GripVertical size={16}/>
                                    </td>
                                    <td className="p-3 relative">
                                        <input 
                                            value={item.description} 
                                            onChange={e => updateItem(originalIndex, 'description', e.target.value)}
                                            className="w-full bg-transparent font-medium text-gray-800 focus:outline-none"
                                        />
                                        {!item.isAuto && <span className="text-[9px] font-bold text-yellow-600 uppercase absolute top-1 right-2 bg-yellow-100 px-1 rounded">Manual</span>}
                                    </td>
                                    <td className="p-3">
                                        <div className="relative">
                                            <select 
                                                value={item.productId || ''} 
                                                onChange={e => updateItem(originalIndex, 'productId', e.target.value)}
                                                className={`w-full p-2 border rounded text-sm font-bold ${item.productId ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-400 border-gray-200'}`}
                                            >
                                                <option value="">-- Vybrať --</option>
                                                {rowProducts.sort((a,b) => (a.type === 'composite' ? -1 : 1)).map(p => (
                                                    <option key={p.id} value={p.id}>
                                                        {p.type === 'composite' ? '📦 [SET] ' : ''}{p.name} ({p.price}€)
                                                    </option>
                                                ))}
                                            </select>
                                            {!item.productId && (
                                                <div title="Položka nie je spárovaná so skladom" className="absolute right-8 top-1/2 -translate-y-1/2 text-orange-400 pointer-events-none">
                                                    <AlertTriangle size={14} />
                                                </div>
                                            )}
                                        </div>
                                    </td>
                                    <td className="p-3 text-right">
                                        <input 
                                            type="number" 
                                            value={item.quantity} 
                                            onChange={e => updateItem(originalIndex, 'quantity', +e.target.value)}
                                            className="w-full text-right font-bold text-blue-600 bg-transparent focus:outline-none text-base"
                                        />
                                    </td>
                                    <td className="p-3 text-right font-mono text-gray-600">
                                        {item.price ? item.price.toFixed(2) : '-'} €
                                    </td>
                                    <td className="p-3 text-center">
                                        <button 
                                            onClick={() => handleDeleteItem(originalIndex)}
                                            className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition"
                                            title="Vymazať položku"
                                        >
                                            <Trash2 size={16}/>
                                        </button>
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            )}

            <div className="flex gap-2">
                <button 
                    onClick={() => addCustomItem(false)}
                    className="flex-1 py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-600 hover:bg-blue-50 transition flex justify-center items-center gap-2 font-medium"
                >
                    <Plus size={18} /> Pridať vlastnú požiadavku
                </button>
                <button 
                    onClick={() => addCustomItem(true)}
                    className="flex-1 py-3 border-2 border-dashed border-purple-300 rounded-lg text-purple-600 hover:border-purple-500 hover:bg-purple-50 transition flex justify-center items-center gap-2 font-bold bg-purple-50/50"
                >
                    <Layers size={18} /> + Pridať SET
                </button>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">

            {/* Addons Checkboxes - DEFAULT OFF */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 bg-blue-50 p-3 rounded border border-blue-100">
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Hammer size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Montáž technológie</span>
                 </label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Truck size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Doprava materiálu</span>
                 </label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Package size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Balné a manipulácia</span>
                 </label>
            </div>

            <div className="flex justify-between items-center">
                <div className="text-xs text-gray-500 flex items-center gap-4">
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-yellow-50 px-3 py-1 rounded">
                        <input type="checkbox" checked={rememberManual} onChange={e => setRememberManual(e.target.checked)} className="rounded text-yellow-600"/>
                        <span className="font-bold text-yellow-800 text-xs">💾 Zapamätať manuálne položky pre ďalšie ponuky</span>
                    </label>
                </div>
                <div className="flex gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium transition">
                        Zrušiť
                    </button>
                    <button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold flex items-center gap-2 shadow-sm transition">
                        <Check size={18} /> Potvrdiť a Vložiť
                    </button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { QuoteCategory, QuoteItem } from '../types';
import { Trash2, Plus, Sparkles, Bold, Italic, Link, Image as ImageIcon, Table, List, ListOrdered, FileText, ChevronDown, ChevronUp, BookOpen, Layers, Box, Eye, EyeOff, Replace, Printer, Percent, GripVertical } from 'lucide-react';

interface CategoryTableProps {
  category: QuoteCategory;
  currency: string;
  globalMargin: number;
  onUpdateCategory: (id: string, field: keyof QuoteCategory, value: any) => void;
  onDeleteCategory: (id: string) => void;
  onAddItem: (categoryId: string, isSurcharge?: boolean) => void;
  onUpdateItem: (categoryId: string, itemId: string, field: keyof QuoteItem, value: any) => void;
  onDeleteItem: (categoryId: string, itemId: string) => void;
  onAiSuggest: (categoryId: string, categoryName: string) => void;
  onOpenCatalog: (categoryId: string, itemId?: string) => void;
  onMoveCategory?: (id: string, direction: 'up' | 'down') => void;
  isAiLoading: boolean;
  readOnly?: boolean; // New prop for locking edits
  hidePrices?: boolean; // New prop for hiding price columns (Contract mode or Toggle)

  // Drag Category Props
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent, id: string) => void;
  onDragOver?: (e: React.DragEvent, id: string) => void;
  onDragEnd?: (e: React.DragEvent) => void;
}

export const CategoryTable: React.FC<CategoryTableProps> = ({
  category,
  currency,
  globalMargin,
  onUpdateCategory,
  onDeleteCategory,
  onAddItem,
  onUpdateItem,
  onDeleteItem,
  onAiSuggest,
  onOpenCatalog,
  onMoveCategory,
  isAiLoading,
  readOnly = false,
  hidePrices = false,
  draggable, onDragStart, onDragOver, onDragEnd
}) => {
  const [showRichText, setShowRichText] = useState(!!category.textContent);
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Sync initial content
  useEffect(() => {
    if (showRichText && editorRef.current && category.textContent && editorRef.current.innerHTML !== category.textContent) {
       editorRef.current.innerHTML = category.textContent;
    }
  }, [showRichText, category.id]); 

  const formatNumber = (num: number) => {
    return num.toLocaleString('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const getSellingPrice = (costPrice: number) => {
    return costPrice * (1 + globalMargin / 100);
  };

  const isEmpty = category.items.length === 0 && !category.textContent;
  const isHidden = category.isHidden;
  const isHiddenFromPrint = category.isHiddenFromPrint;

  // --- Editor Logic ---
  const handleInput = () => {
    if (editorRef.current && !readOnly) {
      onUpdateCategory(category.id, 'textContent', editorRef.current.innerHTML);
    }
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const insertImage = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (readerEvent) => {
          const result = readerEvent.target?.result as string;
          execCmd('insertImage', result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const insertLink = () => {
    const url = prompt('Vložte URL odkazu (napr. na video):');
    if (url) execCmd('createLink', url);
  };

  const insertTable = () => {
    const html = `
      <table style="width: 100%; border-collapse: collapse; margin: 10px 0;">
        <tbody>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
        </tbody>
      </table>
      <p><br/></p>
    `;
    execCmd('insertHTML', html);
  };

  const toggleRichText = () => {
      setShowRichText(!showRichText);
  };

  const toggleSection = () => {
      if(readOnly) return;
      const newSection = category.section === 'shaft' ? 'lift' : 'shaft';
      onUpdateCategory(category.id, 'section', newSection);
  };

  const toggleVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHidden', !isHidden);
  };

  const togglePrintVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHiddenFromPrint', !isHiddenFromPrint);
  }

  // --- ITEM DRAG & DROP HANDLERS ---
  const onDragStartItem = (e: React.DragEvent, itemId: string) => {
      e.stopPropagation(); // Stop propagation so category D&D doesn't trigger
      setDraggedItemId(itemId);
      e.dataTransfer.effectAllowed = 'move';
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndItem = (e: React.DragEvent) => {
      e.stopPropagation();
      setDraggedItemId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverItem = (e: React.DragEvent, targetItemId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!draggedItemId || draggedItemId === targetItemId) return;

      const items = category.items;
      const draggedIndex = items.findIndex(i => i.id === draggedItemId);
      const targetIndex = items.findIndex(i => i.id === targetItemId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      onUpdateCategory(category.id, 'items', newItems);
  };

  // Determine classes based on hidden states
  let wrapperClasses = "mb-4 flex border rounded-lg overflow-hidden bg-white shadow-sm break-inside-avoid transition-all";
  if (isHidden) {
      // Completely hidden (Grayed out)
      wrapperClasses += " opacity-60 grayscale border-dashed border-gray-400 print:hidden";
  } else if (isHiddenFromPrint) {
      // Hidden from Print ONLY (Red dashed border in UI)
      wrapperClasses += " border-red-300 border-2 border-dashed print:hidden bg-red-50/30";
  } else {
      // Normal
      wrapperClasses += " border-gray-300 print:border-gray-300 print:shadow-none";
  }

  if (isEmpty) wrapperClasses += " print:hidden";
  if (readOnly) wrapperClasses += " border-gray-200";

  return (
    <div className={wrapperClasses}>

      {/* STRICT PRINT HIDING LOGIC */}
      {/* This allows Admin to see prices on screen, but enforces hiding in Print */}
      {hidePrices && (
          <style>{`
              @media print {
                  .price-column-strict { display: none !important; }
              }
          `}</style>
      )}

      {/* Left Vertical Sidebar - Category Name (With D&D Handle) */}
      <div 
          className={`w-10 border-r border-gray-300 flex flex-col items-center py-2 relative print:border-gray-300 print:w-8 ${isHidden ? 'bg-gray-200' : isHiddenFromPrint ? 'bg-red-50' : 'bg-gray-100'} ${draggable && !readOnly ? 'cursor-grab active:cursor-grabbing' : ''}`}
          draggable={draggable && !readOnly}
          onDragStart={(e) => onDragStart && onDragStart(e, category.id)}
          onDragOver={(e) => onDragOver && onDragOver(e, category.id)}
          onDragEnd={onDragEnd}
      >

        {/* Section Toggle (Lift/Shaft) */}
        <button 
            onClick={toggleSection}
            disabled={readOnly}
            className={`no-print p-1 rounded mb-2 transition ${category.section === 'shaft' ? 'text-blue-600 bg-blue-100 hover:bg-blue-200' : 'text-gray-500 hover:bg-gray-200'} ${readOnly ? 'opacity-50 cursor-not-allowed' : ''}`}
            title={category.section === 'shaft' ? "Patrí do: Šachta / Konštrukcia" : "Patrí do: Výťah / Technológia"}
        >
            {category.section === 'shaft' ? <Box size={18} /> : <Layers size={18} />}
        </button>

        {/* Vertically Centered Text */}
        <div className="flex-1 flex items-center justify-center">
             <div className="transform -rotate-90 whitespace-nowrap">
                {readOnly ? (
                    <span className="font-bold text-lg text-gray-800 w-64 text-center block">{category.name}</span>
                ) : (
                    <input
                        type="text"
                        value={category.name}
                        onChange={(e) => onUpdateCategory(category.id, 'name', e.target.value)}
                        className="bg-transparent font-bold text-lg text-gray-800 text-center focus:outline-none focus:text-black placeholder-gray-400 print:text-black w-64"
                        placeholder="Názov Kategórie"
                    />
                )}
            </div>
        </div>
      </div>

      {/* Right Content - Table & Actions */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Category Toolbar - Hide most actions if ReadOnly */}
        <div className={`bg-gray-50 p-1 flex justify-end gap-2 border-b border-gray-200 print:hidden ${readOnly ? 'bg-gray-100' : ''}`}>

           {/* Move Buttons */}
           {!readOnly && onMoveCategory && (
                <div className="flex gap-1 mr-auto border-r pr-2 border-gray-300">
                     <button onClick={() => onMoveCategory(category.id, 'up')} className="p-1 hover:bg-gray-200 rounded text-gray-600" title="Posunúť hore"><ChevronUp size={16}/></button>
                     <button onClick={() => onMoveCategory(category.id, 'down')} className="p-1 hover:bg-gray-200 rounded text-gray-600" title="Posunúť dole"><ChevronDown size={16}/></button>
                </div>
           )}

           {category.section === 'shaft' && (
               <span className="mr-auto text-xs font-bold text-blue-600 uppercase tracking-wider bg-blue-50 px-2 py-1 rounded border border-blue-100 flex items-center gap-1">
                   <Box size={12}/> Šachta / Konštrukcia
               </span>
           )}

            {!readOnly && (
                <>
                    {/* HIDE FROM PRINT (But Calculate) */}
                    <button
                        onClick={togglePrintVisibility}
                        className={`flex items-center gap-1 px-2 py-1 text-xs font-medium rounded transition ${isHiddenFromPrint ? 'bg-red-100 text-red-600 border border-red-200' : 'text-gray-400 hover:bg-gray-200 hover:text-black'}`}
                        title={isHiddenFromPrint ? "Položka sa TLAČÍ (Zahrnutá v cene)" : "Skryť pri tlači (ALE POČÍTAŤ CENU)"}
                    >
                         <div className="relative">
                            <Printer size={18} />
                            {isHiddenFromPrint && <div className="absolute inset-0 flex items-center justify-center"><div className="w-full h-0.5 bg-red-600 rotate-45 transform"></div></div>}
                         </div>
                    </button>

                    {/* HIDE COMPLETELY (Exclude) */}
                    <button
                        onClick={toggleVisibility}
                        className={`flex items-center gap-1 px-2 py-1 text-xs font-medium rounded transition ${isHidden ? 'bg-gray-300 text-gray-700' : 'text-gray-400 hover:bg-gray-200 hover:text-black'}`}
                        title={isHidden ? "Zobraziť (Zahrnúť do ceny)" : "Skryť ÚPLNE (Vyradiť z ceny)"}
                    >
                        {isHidden ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>

                    <div className="w-px bg-gray-300 mx-1"></div>

                    <button
                        onClick={toggleRichText}
                        className={`flex items-center gap-1 px-3 py-1 text-xs font-medium rounded transition ${showRichText ? 'bg-blue-100 text-blue-700' : 'text-gray-600 hover:bg-gray-200'}`}
                        title="Pridať textový popis, obrázky alebo tabuľky"
                    >
                        <FileText size={14} />
                        {showRichText ? 'Skryť popis' : 'Pridať technický popis'}
                    </button>
                    <button
                        onClick={() => onAiSuggest(category.id, category.name)}
                        disabled={isAiLoading}
                        className="flex items-center gap-1 px-3 py-1 text-xs font-medium text-black bg-yellow-400 rounded hover:bg-yellow-500 transition disabled:opacity-50"
                        title="AI Navrhnúť položky"
                    >
                        <Sparkles size={14} />
                        {isAiLoading ? '...' : 'AI Položky'}
                    </button>
                    <button
                        onClick={() => onDeleteCategory(category.id)}
                        className="text-gray-400 hover:text-red-600 transition"
                        title="Odstrániť kategóriu"
                    >
                        <Trash2 size={18} />
                    </button>
                </>
            )}
            {readOnly && (
                 <span className="text-xs text-gray-400 font-medium uppercase tracking-wider flex items-center gap-1">
                     <FileText size={12}/> Príloha
                 </span>
            )}
        </div>

        {/* 1. Items Table - REDUCED PADDING */}
        {category.items.length > 0 && (
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-100 text-gray-600 font-medium print:bg-gray-50 print:text-gray-600 print:border-b print:border-gray-300 text-xs">
              <tr>
                {!readOnly && <th className="px-1 py-1 w-6 no-print"></th>}
                <th className="px-2 py-1 w-8 no-print align-top border-b border-gray-200">#</th>
                <th className="px-2 py-1 align-top border-b border-gray-200 w-auto">Popis položky</th>
                <th className="px-2 py-1 w-14 text-right align-top border-b border-gray-200">M.J.</th>
                <th className="px-2 py-1 w-16 text-right align-top border-b border-gray-200">Mn.</th>

                {/* Price Column - Visible on Screen, Hidden in Print if toggled */}
                <th className={`px-2 py-1 w-24 text-right align-top border-b border-gray-200 price-column-strict ${hidePrices ? '' : ''}`}>
                    <span className={`print:hidden ${readOnly ? 'text-black' : 'text-blue-600'}`}>
                        {readOnly ? 'Cena/J' : 'Nákup/J'}
                    </span>
                    <span className="hidden print:inline">Cena/J</span>
                </th>

                {!readOnly && <th className="px-2 py-1 w-16 no-print align-top border-b border-gray-200"></th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 print:divide-gray-200">
              {category.items.map((item, index) => {
                const sellingPrice = getSellingPrice(item.unitPrice);
                return (
                <tr 
                    key={item.id} 
                    className={`hover:bg-gray-50 group transition-colors print:hover:bg-transparent ${item.isSurcharge ? 'bg-gray-50/50' : ''}`}
                    draggable={!readOnly}
                    onDragStart={(e) => onDragStartItem(e, item.id)}
                    onDragOver={(e) => onDragOverItem(e, item.id)}
                    onDragEnd={onDragEndItem}
                >
                  {!readOnly && (
                      <td className="px-1 py-1 text-center no-print text-gray-300 cursor-grab hover:text-gray-500">
                          <GripVertical size={14}/>
                      </td>
                  )}
                  <td className="px-2 py-1 text-gray-500 no-print align-top text-xs">{index + 1}</td>
                  <td className="px-2 py-1 align-top relative">
                    {readOnly ? (
                        <div className={`text-gray-900 whitespace-pre-wrap leading-tight ${item.isSurcharge ? 'pl-6 italic text-gray-600' : ''}`}>
                            {item.isSurcharge && <span className="absolute left-2 top-1 text-gray-400 text-[10px]">•</span>}
                            {item.description}
                        </div>
                    ) : (
                        <div className={`flex gap-2 ${item.isSurcharge ? 'pl-6' : ''}`}>
                             {item.isSurcharge && <span className="absolute left-2 top-2 text-gray-400 text-[10px]">•</span>}
                             <textarea
                                rows={1}
                                value={item.description}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'description', e.target.value)}
                                className={`w-full bg-transparent focus:outline-none focus:text-black resize-y min-h-[1.5rem] placeholder-gray-400 print:text-black leading-tight ${item.isSurcharge ? 'italic text-gray-600' : 'text-gray-900'}`}
                                placeholder="Názov položky..."
                            />
                            {/* In-row Catalog Button = Swap Item */}
                            <button
                                onClick={() => onOpenCatalog(category.id, item.id)}
                                className="no-print self-start p-1.5 text-blue-400 bg-blue-50 hover:bg-blue-100 hover:text-blue-700 rounded transition opacity-0 group-hover:opacity-100 focus:opacity-100"
                                title="Vybrať variant z katalógu (Vymeniť)"
                            >
                                <BookOpen size={14} />
                            </button>
                        </div>
                    )}
                  </td>
                  <td className="px-2 py-1 align-top text-right">
                    {readOnly ? (
                         <span className="text-gray-900 text-xs">{item.unit}</span>
                    ) : (
                        <select
                            value={item.unit}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'unit', e.target.value)}
                            className="w-full text-right bg-white text-gray-900 border border-gray-300 rounded px-1 py-0 focus:outline-none focus:border-yellow-500 appearance-none print:bg-transparent print:text-black print:border-none print:appearance-auto text-xs"
                        >
                            <option value="ks">ks</option>
                            <option value="m">m</option>
                            <option value="hod">hod</option>
                            <option value="kpl">kpl</option>
                        </select>
                    )}
                  </td>
                  <td className="px-2 py-1 align-top text-right">
                    {readOnly ? (
                        <span className="text-gray-900 font-medium text-xs">{item.quantity}</span>
                    ) : (
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={item.quantity}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'quantity', parseFloat(e.target.value) || 0)}
                            className="w-full text-right bg-transparent text-gray-900 font-medium focus:outline-none print:text-black text-xs"
                        />
                    )}
                  </td>

                  {/* Price Column - Controlled by CSS Style Block */}
                  <td className="px-2 py-1 align-top text-right price-column-strict">
                    {readOnly ? (
                        <span className="text-xs font-medium text-black block">
                            {formatNumber(sellingPrice)} {currency}
                        </span>
                    ) : (
                        <>
                            {/* EDIT MODE: Input for Cost - Visually dimmed if intended hidden, but still visible to admin */}
                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={item.unitPrice}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                                className={`w-full text-right bg-transparent font-bold focus:outline-none text-xs print:hidden cursor-text ${hidePrices ? 'text-gray-400' : 'text-blue-700 bg-blue-50/20'}`}
                                placeholder="0.00"
                                title="Upraviť cenu (Len pre túto ponuku)"
                            />
                            {/* PRINT MODE: Calculated Selling Price */}
                            <span className="hidden print:block text-xs font-medium text-black">
                                {formatNumber(sellingPrice)} {currency}
                            </span>
                        </>
                    )}
                  </td>

                  {/* Delete/Add Surcharge Action - Hidden in ReadOnly */}
                  {!readOnly && (
                    <td className="px-2 py-1 text-center no-print align-top flex justify-center gap-1">
                        <button
                            onClick={() => onAddItem(category.id, true)}
                            className="text-gray-300 hover:text-blue-500 hover:bg-blue-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                            title="Pridať príplatok / pod-položku"
                        >
                            <Percent size={14} />
                        </button>
                        <button
                            onClick={() => onDeleteItem(category.id, item.id)}
                            className="text-gray-300 hover:text-red-500 hover:bg-red-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <Trash2 size={14} />
                        </button>
                    </td>
                  )}
                </tr>
              )})}
            </tbody>
          </table>
        </div>
        )}

          {!readOnly && (
            <div className="p-2 border-t border-gray-200 bg-gray-50 no-print flex gap-2">
                <button
                onClick={() => onAddItem(category.id)}
                className="flex items-center gap-1 text-sm font-medium text-gray-600 hover:text-black px-2 py-1 rounded hover:bg-gray-200 transition"
                >
                <Plus size={16} /> Pridať položku
                </button>
                <button
                onClick={() => onOpenCatalog(category.id)}
                className="flex items-center gap-1 text-sm font-medium text-blue-600 hover:text-blue-800 px-2 py-1 rounded hover:bg-blue-50 transition ml-auto"
                >
                <BookOpen size={16} /> Z katalógu
                </button>
            </div>
          )}

          {/* 2. Embedded Rich Text Area - RENDERED BELOW ITEMS */}
          {(showRichText || (readOnly && category.textContent)) && (
            <div className="border-t border-gray-200 p-4 bg-white">
                <div className="mb-2 text-xs font-bold text-gray-400 uppercase tracking-wider print:hidden">Technická špecifikácia / Prílohy</div>

                {/* Editor Content */}
                <div
                    ref={editorRef}
                    contentEditable={!readOnly}
                    onInput={handleInput}
                    className={`rich-text-content w-full min-h-[80px] outline-none text-gray-900 text-sm ${readOnly ? 'pointer-events-none' : ''}`}
                    dangerouslySetInnerHTML={{ __html: category.textContent || '' }}
                />
            </div>
          )}
      </div>
    </div>
  );
};

import React from 'react';
import { LiftLayoutData } from '../types';
import { Eye, EyeOff, ClipboardList, AlertTriangle } from 'lucide-react';

interface TechSpecTableProps {
  data: LiftLayoutData;
  isVisible: boolean;
  onToggleVisibility: () => void;
  embedded?: boolean;
}

export const TechSpecTable: React.FC<TechSpecTableProps> = ({
  data,
  isVisible,
  onToggleVisibility,
  embedded = false
}) => {

  const getLiftTypeLabel = (val: string) => {
      const map: Record<string, string> = { 
          'passenger': 'Osobný výťah', 
          'freight': 'Nákladný výťah', 
          'home': 'Domáci výťah', 
          'hospital': 'Lôžkový výťah',
          'invalid': 'Výťah pre invalidov (EN 81-70)'
      };
      return map[val] || val;
  };
  const getDriveLabel = (val: string) => {
      const map: Record<string, string> = { 'traction': 'Trakčný (Lanový)', 'hydraulic': 'Hydraulický', 'mrl': 'Trakčný MRL (Bez strojovne)', 'drum': 'Bubnový' };
      return map[val] || val;
  };
  const getDoorLabel = (val?: string) => {
      const map: Record<string, string> = { 'central': 'Automatické Centrálne', 'telescopic': 'Automatické Teleskopické', 'bus': 'Ručné (Šachta) + BUS (Kabína)' };
      return map[val || 'central'] || val;
  };
  const getMediumLabel = (val?: string) => {
      const map: Record<string, string> = { 'ropes': 'Oceľové laná', 'belts': 'Ploché pásy', 'ctp': 'CTP laná (Plast)' };
      return map[val || 'ropes'] || val;
  };
  const getFrameLabel = (val?: string) => {
      const map: Record<string, string> = { 'backpack': 'Ruksak (Backpack)', 'central': 'Centrálny (Záves)' };
      return map[val || 'backpack'] || val;
  };
  const getMachineRoomLabel = (val?: string) => {
      const map: Record<string, string> = { 'head': 'MRL (V šachte)', 'above': 'Strojovňa nad šachtou', 'cabinet': 'Skrinka (Hydraulika)' };
      return map[val || 'head'] || val;
  };

  // EN 81-21 & EN 81-70 Logic Check
  const getSafetyMeasures = () => {
      const measures = [];
      if (data.pitDepth < 1100 || data.headroomHeight < 3400) {
          measures.push("Riešenie: ELGO LIMAX 33 CP (podľa EN 81-21)");
      }
      if (data.liftType === 'invalid') {
          measures.push("EN 81-70: Zrkadlo, Madlo, Hlasový oznamovač, Braillovo písmo");
      }
      return measures;
  };

  const safetyMeasures = getSafetyMeasures();
  const stationCount = data.stationLabels ? data.stationLabels.split(',').length : 0;

  if (!isVisible) {
      return (
          <div className="mb-8 no-print p-4 border border-dashed border-gray-300 rounded bg-gray-50 text-gray-400 flex justify-between items-center">
              <span>Technická špecifikácia je skrytá.</span>
              <button onClick={onToggleVisibility}><Eye size={20}/></button>
          </div>
      );
  }

  const TableContent = (
    <table className="w-full text-sm text-left border-collapse">
        <caption className="text-left py-2 font-bold uppercase text-sm border-b border-gray-300 mb-2">Technická Špecifikácia</caption>
        <thead className="bg-gray-100 text-gray-700 font-bold print:bg-gray-200 print:text-black text-xs uppercase">
            <tr>
            <th className="px-3 py-1.5 border-b border-r border-gray-300 w-1/4">Parameter</th>
            <th className="px-3 py-1.5 border-b border-gray-300 w-1/4">Hodnota</th>
            <th className="px-3 py-1.5 border-b border-l border-r border-gray-300 w-1/4">Parameter</th>
            <th className="px-3 py-1.5 border-b border-gray-300 w-1/4">Hodnota</th>
            </tr>
        </thead>
        <tbody className="text-gray-800 print:text-black text-xs">
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Typ zariadenia</td>
                <td className="px-3 py-1.5">{getLiftTypeLabel(data.liftType)}</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Pohonný systém</td>
                <td className="px-3 py-1.5">{getDriveLabel(data.driveType)}</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Nosnosť (Q)</td>
                <td className="px-3 py-1.5 font-bold">{data.ratedLoad} kg</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Počet osôb</td>
                <td className="px-3 py-1.5 font-bold">{data.numberOfPersons} osôb</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Rýchlosť</td>
                <td className="px-3 py-1.5">{data.ratedSpeed} m/s (VVVF)</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Napájanie</td>
                <td className="px-3 py-1.5">{data.powerSupply}</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Počet staníc</td>
                <td className="px-3 py-1.5">{stationCount} staníc {data.isThroughCar ? '(Prechodný)' : ''}</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Zdvih</td>
                <td className="px-3 py-1.5">{data.travelHeight} mm</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Kabína (ŠxH)</td>
                <td className="px-3 py-1.5 font-mono font-bold">{Math.round(data.cabinWidth)} x {Math.round(data.cabinDepth)} mm</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Šachta (ŠxH)</td>
                <td className="px-3 py-1.5 font-mono font-bold">{data.shaftWidth} x {data.shaftDepth} mm</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Dvere (Typ)</td>
                <td className="px-3 py-1.5">{getDoorLabel(data.doorType)} ({data.doorOperation === 'manual' ? 'Manuálne' : 'Automatické'})</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Dvere (Šírka)</td>
                <td className="px-3 py-1.5">PL {data.doorWidth} mm</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Strojovňa</td>
                <td className="px-3 py-1.5">{getMachineRoomLabel(data.machineRoomPosition)}</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Rám</td>
                <td className="px-3 py-1.5">{getFrameLabel(data.frameType)}</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Trakčné médium</td>
                <td className="px-3 py-1.5">{getMediumLabel(data.tractionMedium)}</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Lanovanie</td>
                <td className="px-3 py-1.5">{data.suspensionType}</td>
            </tr>
             <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Hlava (HQ)</td>
                <td className="px-3 py-1.5">{data.headroomHeight} mm</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Priehlbeň (HS)</td>
                <td className="px-3 py-1.5">{data.pitDepth} mm</td>
            </tr>
            <tr className="border-b border-gray-200">
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Vodidlá Kabína</td>
                <td className="px-3 py-1.5">{data.guideTypeCar || '-'}</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Vodidlá Protiváha</td>
                <td className="px-3 py-1.5">{data.guideTypeCwt || '-'}</td>
            </tr>
             <tr>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-r border-gray-200">Stanice</td>
                <td className="px-3 py-1.5 break-all">{data.stationLabels}</td>
                <td className="px-3 py-1.5 font-bold bg-gray-50 border-l border-r border-gray-200">Trieda Kabíny</td>
                <td className="px-3 py-1.5 font-bold text-blue-800">{data.cabinClass || 'FUN'}</td>
            </tr>
            {safetyMeasures.length > 0 && (
                <tr className="bg-yellow-50 border-t border-yellow-200">
                    <td className="px-3 py-1.5 font-bold text-yellow-800 border-r border-yellow-200 flex items-center gap-2">
                        <AlertTriangle size={14}/> Opatrenia
                    </td>
                    <td colSpan={3} className="px-3 py-1.5 font-bold text-yellow-900">
                        {safetyMeasures.join(', ')}
                    </td>
                </tr>
            )}
        </tbody>
    </table>
  );

  if (embedded) {
      return <div className="h-full bg-white">{TableContent}</div>;
  }

  return (
    <div className="mb-8 break-inside-avoid">
      <div className="flex items-center justify-between mb-2 border-b border-gray-300 pb-1 no-print">
         <div className="flex items-center gap-2">
            <ClipboardList className="text-blue-600" size={18}/>
            <h3 className="text-sm font-bold uppercase text-gray-800 tracking-wider">Technická špecifikácia</h3>
         </div>
         <button onClick={onToggleVisibility} className="p-1 rounded text-gray-400 hover:text-black hover:bg-gray-100"><EyeOff size={16} /></button>
      </div>
      <div className="border border-gray-300 rounded-lg overflow-hidden bg-white shadow-sm">
        {TableContent}
      </div>
    </div>
  );
};

