            </div>

            <div className={`no-print my-4 p-2 bg-gray-50 rounded border border-gray-200 flex gap-4 items-center justify-center ${isContractMode ? 'hidden' : ''}`}>
                <div className="flex items-center gap-2"><span className="text-xs font-bold uppercase">Výťah</span>
                    <button onClick={() => { setTemplateContext('lift'); setTemplateModalMode('select'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-blue-50"><LayoutTemplate size={12}/></button>
                    <button onClick={() => { setTemplateContext('lift'); setTemplateModalMode('save'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-green-50"><Save size={12}/></button>
                </div>
                <div className="h-4 w-px bg-gray-300 mx-2"></div>
                <div className="flex items-center gap-2"><span className="text-xs font-bold uppercase">Šachta</span>
                    {hasShaft && <><button onClick={() => { setTemplateContext('shaft'); setTemplateModalMode('select'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-blue-50"><LayoutTemplate size={12}/></button>
                    <button onClick={() => { setTemplateContext('shaft'); setTemplateModalMode('save'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-green-50"><Save size={12}/></button></>}
                    <button onClick={toggleShaft} className={`w-8 h-4 rounded-full relative transition-colors ${hasShaft?'bg-blue-600':'bg-gray-300'}`}><span className={`w-3 h-3 bg-white rounded-full absolute top-0.5 transition-all ${hasShaft?'right-0.5':'left-0.5'}`}/></button>
                </div>
             </div>

        </div>
        <div className="hidden print:block print-break-after-page"></div>
        <div className="print-page-2-content pt-8">
            <div className="mb-12">
            {data.categories.length === 0 && !isContractMode && (
                <div className="no-print p-8 text-center text-gray-400 border-2 border-dashed border-gray-200 rounded-xl bg-gray-50">
                    <Calculator size={48} className="mx-auto mb-4 text-gray-300"/>
                    <h3 className="text-lg font-bold mb-2">Ponuka je prázdna</h3>
                    <p className="text-sm mb-4">Použite Materiálový Sprievodca pre pridanie položiek.</p>
                    <button onClick={() => setIsMaterialModalOpen(true)} className="px-4 py-2 bg-blue-600 text-white rounded font-bold hover:bg-blue-700">Otvoriť Sprievodcu</button>
                </div>
            )}

            {data.categories.map(category => (
                category.type === 'text' ? (
                    <RichTextEditor key={category.id} category={category} onUpdateCategory={(id, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===id?{...c, [f as string]:v}:c)}))} onDeleteCategory={id => setData(prev => ({...prev, categories: prev.categories.filter(c => c.id!==id)}))} />
                ) : (
                    <CategoryTable 
                        key={category.id} 
                        category={category} 
                        currency={data.currency} 
                        globalMargin={category.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===id?{...c, [f as string]:v}:c)}))}
                        onDeleteCategory={id => setData(prev => ({...prev, categories: prev.categories.filter(c => c.id!==id)}))}
                        onUpdateItem={(cid, iid, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===cid ? {...c, items:c.items.map(i => i.id===iid?{...i, [f as string]:v}:i)} : c)}))}
                        onDeleteItem={(cid, iid) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===cid ? {...c, items:c.items.filter(i => i.id!==iid)} : c)}))}
                        onAiSuggest={handleAiCategoryItems} 
                        onOpenCatalog={handleOpenCatalog} 
                        isAiLoading={isAiLoading === category.id} 
                        readOnly={isContractMode} 
                        // STRICT PRICE HIDING: Contract OR Order Mode OR Toggle
                        hidePrices={isContractMode || isOrderMode || data.hideItemPrices}
                        onAddItem={handleAddItem}
                        onMoveCategory={moveCategory}
                        // DRAG PROPS
                        draggable={true}
                        onDragStart={onDragStartCat}
                        onDragOver={onDragOverCat}
                        onDragEnd={onDragEndCat}
                    />
                )
            ))}
            </div>

            <div className="flex justify-end mt-8 mb-8 break-inside-avoid">
                <div className="w-full md:w-96">
                    {!isContractMode && !isOrderMode && (
                        <div className="bg-yellow-50 p-3 mb-4 rounded border border-yellow-200 no-print">
                            <div className="text-xs font-bold uppercase mb-2">Marža</div>
                            <div className="flex justify-between items-center mb-1"><span className="text-sm">Výťah %</span><input type="number" value={data.globalMargin} onChange={e=>setData(prev=>({...prev, globalMargin:+e.target.value}))} className="w-16 border rounded text-right font-bold"/></div>
                            <div className="flex justify-between items-center"><span className="text-sm">Šachta %</span><input type="number" value={data.shaftMargin} onChange={e=>setData(prev=>({...prev, shaftMargin:+e.target.value}))} className="w-16 border rounded text-right font-bold"/></div>
                        </div>
                    )}

                    {/* Totals Display */}
                    <div className="bg-gray-50 p-6 rounded border">
                        <div className="flex justify-between mb-2 font-bold"><span>Spolu bez DPH:</span><span>{formatCurrency(totals.totalSelling)}</span></div>
                        <div className="flex justify-between mb-2 text-gray-600"><span>DPH 23%:</span><span>{formatCurrency(totals.vat)}</span></div>
                        <div className="border-t pt-2 mt-2 flex justify-between font-bold text-xl"><span>K úhrade:</span><span>{formatCurrency(totals.gross)}</span></div>
                    </div>
                </div>
            </div>
            {!isContractMode && <div className="break-inside-avoid print:break-before-page mt-8">
                <h3 className="font-bold uppercase mb-2">Podmienky</h3>
                <textarea value={data.terms} onChange={e=>setData({...data, terms:e.target.value})} className="w-full bg-gray-50 p-4 rounded min-h-[300px] text-sm whitespace-pre-wrap"/>
            </div>}
        </div>
      </div>
      <div className="print-footer no-print">SmartQuote SK - Strana <span className="pageNumber"></span></div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductComponent, CabinClass } from '../types';
import { X, Plus, Search, Trash2, Save, Package, Layers, Settings, ArrowRight, Box, Filter, Factory, ShoppingCart, Wrench, Building, Download, Upload, FolderTree, Star } from 'lucide-react';

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  onDeleteCategory?: (name: string) => void;
  onImportCatalog?: (file: File) => void;

  // Cabin Class Props
  cabinClasses?: CabinClass[];
  onAddCabinClass?: (cc: CabinClass) => void;
  onDeleteCabinClass?: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen,
  onClose,
  products,
  onAddProduct,
  onUpdateProduct,
  onDeleteProduct,
  customCategories,
  onAddCategory,
  onDeleteCategory,
  onImportCatalog,
  cabinClasses,
  onAddCabinClass,
  onDeleteCabinClass
}) => {
  // MODE SWITCH: 'stock' (Simple items) vs 'sets' (Composite items) vs 'classes' (Cabin Types)
  const [mode, setMode] = useState<'stock' | 'sets' | 'classes'>('stock');

  const [activeCategory, setActiveCategory] = useState(customCategories[0] || 'Dvere');
  const [activeSubcategory, setActiveSubcategory] = useState<string>('ALL'); // Filter by Subcat

  const [searchTerm, setSearchTerm] = useState('');

  // New Supplier Filter
  const [supplierFilter, setSupplierFilter] = useState<string>('');

  // EDITOR STATE
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);

  const [name, setName] = useState('');
  const [manufacturer, setManufacturer] = useState('');
  const [supplier, setSupplier] = useState('');
  const [unit, setUnit] = useState('ks');
  const [price, setPrice] = useState('');
  const [subcategory, setSubcategory] = useState(''); // New Subcategory Field

  // Composite Logic
  const [subProducts, setSubProducts] = useState<ProductComponent[]>([]);
  const [componentSearch, setComponentSearch] = useState('');
  const [componentSourceCategory, setComponentSourceCategory] = useState<string>('ALL');

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  // Cabin Class Form
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Use passed categories as source of truth
  const allCategories = customCategories;

  // Unique suppliers for filter dropdown
  const uniqueSuppliers = Array.from(new Set(products.map(p => p.supplier).filter(Boolean))) as string[];

  // Get Subcategories for current category
  const getSubcategories = (category: string) => {
      // Special logic for Doors
      if (category === 'Dvere') return ['Šachtové', 'Kabínové'];
      // For others, derive from existing products
      const existing = Array.from(new Set(
          products.filter(p => p.category === category && p.subcategory).map(p => p.subcategory)
      ));
      return existing as string[];
  };

  const availableSubcategories = getSubcategories(activeCategory);

  // Reset filter when changing active category or closing
  useEffect(() => {
      if (!isEditing && mode !== 'classes') {
          setComponentSourceCategory(activeCategory);
          setActiveSubcategory('ALL');
      }
  }, [activeCategory, isEditing, mode]);

  // Ensure active category is valid if list changes
  useEffect(() => {
      if (!allCategories.includes(activeCategory) && allCategories.length > 0) {
          setActiveCategory(allCategories[0]);
      }
  }, [allCategories]);

  if (!isOpen) return null;

  const filteredProducts = products.filter(p => 
    p.category === activeCategory && 
    (activeSubcategory === 'ALL' || p.subcategory === activeSubcategory) &&
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) &&
    (mode === 'stock' ? (!p.type || p.type === 'simple') : p.type === 'composite') &&
    (!supplierFilter || p.supplier === supplierFilter)
  );

  const handleEditClick = (p: Product) => {
      setEditId(p.id);
      setName(p.name);
      setManufacturer(p.manufacturer || '');
      setSupplier(p.supplier || '');
      setUnit(p.unit);
      setPrice(p.price.toString());
      setSubcategory(p.subcategory || '');
      setSubProducts(p.subProducts || []);
      setComponentSourceCategory(p.category);
      setIsEditing(true);
  };

  const handleNewClick = () => {
      setEditId(null);
      setName('');
      setManufacturer('');
      setSupplier('');
      setUnit('ks');
      setPrice('');
      setSubcategory(activeSubcategory !== 'ALL' ? activeSubcategory : '');
      setSubProducts([]);
      setComponentSourceCategory(activeCategory);
      setIsEditing(true);
  };

  const handleSaveCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setActiveCategory(newCatName);
          setIsAddingCategory(false);
          setNewCatName('');
      }
  };

  const handleDeleteCat = (cat: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (onDeleteCategory && confirm(`Naozaj chcete vymazať kategóriu "${cat}"?`)) {
          // If active, switch to first available
          if (activeCategory === cat) {
              setActiveCategory(allCategories.find(c => c !== cat) || '');
          }
          onDeleteCategory(cat);
      }
  };

  const handleSave = () => {
      if (!name) return;

      let finalPrice = parseFloat(price) || 0;

      // If creating a SET, price is calculated (or manual override allowed in future)
      if (mode === 'sets') {
          finalPrice = subProducts.reduce((acc, item) => {
              const p = products.find(prod => prod.id === item.productId);
              return acc + ((p?.price || 0) * item.quantity);
          }, 0);
      }

      const newProduct: Product = {
          id: editId || crypto.randomUUID(),
          category: activeCategory,
          subcategory: subcategory || undefined,
          name,
          manufacturer: manufacturer || undefined,
          supplier: supplier || undefined,
          unit,
          price: finalPrice,
          type: mode === 'sets' ? 'composite' : 'simple',
          subProducts: mode === 'sets' ? subProducts : undefined
      };

      if (editId) {
          onUpdateProduct(newProduct);
      } else {
          onAddProduct(newProduct);
      }
      setIsEditing(false);
  };

  const handleAddClass = () => {
      if(newClassName && onAddCabinClass) {
          onAddCabinClass({
              id: crypto.randomUUID(),
              name: newClassName,
              description: newClassDesc || 'Vlastný typ'
          });
          setNewClassName('');
          setNewClassDesc('');
      }
  };

  const addComponent = (productId: string) => {
      const existing = subProducts.find(sp => sp.productId === productId);
      if (existing) {
          setSubProducts(subProducts.map(sp => sp.productId === productId ? { ...sp, quantity: sp.quantity + 1 } : sp));
      } else {
          setSubProducts([...subProducts, { productId, quantity: 1 }]);
      }
  };

  const removeComponent = (productId: string) => {
      setSubProducts(subProducts.filter(sp => sp.productId !== productId));
  };

  const updateComponentQty = (productId: string, qty: number) => {
      setSubProducts(subProducts.map(sp => sp.productId === productId ? { ...sp, quantity: qty } : sp));
  };

  const getProductName = (id: string) => products.find(p => p.id === id)?.name || 'Neznámy produkt';
  const getProductPrice = (id: string) => products.find(p => p.id === id)?.price || 0;

  // -- EXPORT / IMPORT --
  const handleExport = () => {
      const blob = new Blob([JSON.stringify(products, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `katalog_produktov_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleImportClick = () => {
      if (fileInputRef.current) fileInputRef.current.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file && onImportCatalog) {
          onImportCatalog(file);
      }
  };

  const availableComponents = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(componentSearch.toLowerCase());
      const matchesCategory = componentSourceCategory === 'ALL' || p.category === componentSourceCategory;
      const isNotSelf = p.id !== editId;
      const isSimple = !p.type || p.type === 'simple'; // Only simple items go into sets
      return matchesSearch && matchesCategory && isNotSelf && isSimple;
  });

  return (
    <div className="fixed inset-0 bg-white z-[100] flex flex-col">

        {/* Header - Fixed Top */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 shadow-sm shrink-0">
          <div className="flex items-center gap-4">
            <div className="bg-blue-100 p-2 rounded-lg"><Package className="text-blue-700" size={24} /></div>
            <div>
                <h2 className="text-2xl font-bold text-gray-800">Manažér Katalógu</h2>
                <div className="text-sm text-gray-500">Master Data Produktov</div>
            </div>
          </div>

          {/* Data Actions */}
          <div className="flex gap-2">
              <button 
                  onClick={() => setMode('classes')} 
                  className={`px-4 py-2 border rounded text-sm font-bold flex items-center gap-2 hover:bg-yellow-50 ${mode === 'classes' ? 'bg-yellow-100 text-yellow-800 border-yellow-300' : 'bg-white border-gray-300 text-gray-700'}`} 
                  title="Spravovať Typy Kabín"
              >
                  <Star size={16}/> Triedy Kabín
              </button>

              <div className="w-px bg-gray-300 mx-2"></div>

              <button onClick={handleExport} className="px-4 py-2 bg-white border border-gray-300 rounded text-sm font-bold text-gray-700 flex items-center gap-2 hover:bg-gray-100" title="Zálohovať produkty">
                  <Download size={16}/> Export
              </button>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden"/>
              {onImportCatalog && (
                  <button onClick={handleImportClick} className="px-4 py-2 bg-white border border-gray-300 rounded text-sm font-bold text-gray-700 flex items-center gap-2 hover:bg-gray-100" title="Obnoviť produkty">
                      <Upload size={16}/> Import
                  </button>
              )}
              <div className="w-px bg-gray-300 mx-4"></div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
                <X size={28}/>
              </button>
          </div>
        </div>

        {/* WORKFLOW SWITCHER - TOP BAR */}
        {!isEditing && mode !== 'classes' && (
        <div className="p-4 bg-white border-b flex gap-6 justify-center shrink-0">
            <button 
                onClick={() => setMode('stock')}
                className={`flex-1 max-w-sm py-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${mode === 'stock' ? 'border-blue-500 bg-blue-50 text-blue-700 shadow-md ring-1 ring-blue-500' : 'border-gray-200 text-gray-500 hover:border-blue-200 hover:bg-gray-50'}`}
            >
                <ShoppingCart size={32} className={mode === 'stock' ? 'text-blue-600' : 'text-gray-400'}/>
                <div>
                    <div className="font-bold text-lg">NÁKUP NA SKLAD</div>
                    <div className="text-xs opacity-70">Nahrávanie dielov z dodacích listov</div>
                </div>
            </button>

            <button 
                onClick={() => setMode('sets')}
                className={`flex-1 max-w-sm py-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${mode === 'sets' ? 'border-purple-500 bg-purple-50 text-purple-700 shadow-md ring-1 ring-purple-500' : 'border-gray-200 text-gray-500 hover:border-purple-200 hover:bg-gray-50'}`}
            >
                <Wrench size={32} className={mode === 'sets' ? 'text-purple-600' : 'text-gray-400'}/>
                <div>
                    <div className="font-bold text-lg">TVORBA SETOV</div>
                    <div className="text-xs opacity-70">Skladanie dielov do celkov (napr. Kabína)</div>
                </div>
            </button>
        </div>
        )}

        {/* Categories */}
        {!isEditing && mode !== 'classes' && (
            <div className="p-2 border-b bg-gray-50 flex gap-2 overflow-x-auto items-center shrink-0 custom-scrollbar">
                {allCategories.map(cat => (
                <button
                    key={cat}
                    onClick={() => setActiveCategory(cat)}
                    className={`group px-6 py-3 rounded-lg text-base font-bold whitespace-nowrap transition flex items-center gap-2 ${
                    activeCategory === cat 
                        ? (mode === 'stock' ? 'bg-blue-600 text-white shadow-md' : 'bg-purple-600 text-white shadow-md')
                        : 'bg-white border text-gray-600 hover:bg-gray-200'
                    }`}
                >
                    {cat}
                    {/* ALWAYS SHOW DELETE for any category if delete handler exists */}
                    {onDeleteCategory && (
                        <span 
                            onClick={(e) => handleDeleteCat(cat, e)}
                            className="p-0.5 rounded-full hover:bg-red-500 hover:text-white opacity-0 group-hover:opacity-100 transition-opacity ml-2"
                            title="Vymazať kategóriu"
                        >
                            <X size={14}/>
                        </span>
                    )}
                </button>
                ))}

                {isAddingCategory ? (
                    <div className="flex items-center gap-1 bg-white border rounded-full px-2 py-1">
                        <input autoFocus className="w-32 text-sm outline-none bg-transparent" placeholder="Názov..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleSaveCategory()} />
                        <button onClick={handleSaveCategory} className="text-green-600 hover:bg-green-100 rounded-full p-1"><Plus size={16}/></button>
                        <button onClick={()=>setIsAddingCategory(false)} className="text-red-500 hover:bg-red-100 rounded-full p-1"><X size={16}/></button>
                    </div>
                ) : (
                    <button onClick={()=>setIsAddingCategory(true)} className="px-4 py-3 rounded-lg border border-dashed border-gray-400 text-gray-500 hover:border-blue-500 hover:text-blue-600 flex items-center gap-1 text-sm whitespace-nowrap"><Plus size={16}/> Pridať Kategóriu</button>
                )}
            </div>
        )}

        {/* MAIN CONTENT */}
        <div className="flex-1 overflow-hidden flex flex-col bg-gray-100">

            {/* CABIN CLASS MANAGER MODE */}
            {mode === 'classes' ? (
                <div className="flex-1 overflow-y-auto p-8 flex justify-center">
                    <div className="w-full max-w-4xl">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-2xl font-bold text-gray-800 flex items-center gap-2"><Star className="text-yellow-500"/> Správa Tried Kabín</h3>
                            <button onClick={() => setMode('stock')} className="text-gray-500 hover:text-blue-600 font-bold text-sm">← Späť na produkty</button>
                        </div>

                        <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
                            {/* Add Form */}
                            <div className="p-6 bg-yellow-50 border-b border-yellow-100 flex gap-4 items-end">
                                <div className="flex-1">
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Kód Triedy (Názov)</label>
                                    <input 
                                        className="w-full p-2 border rounded font-bold text-sm" 
                                        placeholder="Napr. LUXURY" 
                                        value={newClassName}
                                        onChange={e => setNewClassName(e.target.value)}
                                    />
                                </div>
                                <div className="flex-[2]">
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Popis (Materiály)</label>
                                    <input 
                                        className="w-full p-2 border rounded text-sm" 
                                        placeholder="Napr. Koža / Zrkadlá / LED" 
                                        value={newClassDesc}
                                        onChange={e => setNewClassDesc(e.target.value)}
                                    />
                                </div>
                                <button 
                                    onClick={handleAddClass}
                                    disabled={!newClassName}
                                    className="px-6 py-2 bg-yellow-500 text-white font-bold rounded shadow hover:bg-yellow-600 disabled:opacity-50"
                                >
                                    Pridať
                                </button>
                            </div>

                            {/* List */}
                            <div className="divide-y divide-gray-100">
                                {cabinClasses?.length === 0 && <div className="p-8 text-center text-gray-400 italic">Žiadne definované triedy.</div>}
                                {cabinClasses?.map(cc => (
                                    <div key={cc.id} className="p-4 flex items-center justify-between hover:bg-gray-50 group">
                                        <div>
                                            <div className="font-bold text-lg text-gray-800">{cc.name}</div>
                                            <div className="text-sm text-gray-500">{cc.description}</div>
                                        </div>
                                        <button 
                                            onClick={() => onDeleteCabinClass && onDeleteCabinClass(cc.id)}
                                            className="p-2 text-gray-300 hover:text-red-600 hover:bg-red-50 rounded transition"
                                            title="Vymazať"
                                        >
                                            <Trash2 size={18}/>
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            ) : isEditing ? (
            /* EDITOR MODE */
                <div className="flex-1 overflow-y-auto p-8">
                    <div className={`bg-white p-8 rounded-xl border shadow-lg max-w-5xl mx-auto ${mode === 'stock' ? 'border-blue-200 shadow-blue-100' : 'border-purple-200 shadow-purple-100'}`}>
                        <div className="flex justify-between items-center mb-8 border-b pb-4">
                            <div>
                                <h3 className={`text-2xl font-bold ${mode === 'stock' ? 'text-blue-800' : 'text-purple-800'}`}>
                                    {editId ? 'Upraviť' : 'Nový'} {mode === 'stock' ? 'Skladový Diel' : 'SET (Skladačka)'}
                                </h3>
                                <div className="text-sm text-gray-500 uppercase font-bold mt-1 flex items-center gap-2">
                                    Kategória: <span className="text-black">{activeCategory}</span>
                                </div>
                            </div>
                            <div className={`px-4 py-2 rounded text-sm font-bold uppercase border ${mode === 'stock' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-purple-50 border-purple-200 text-purple-700'}`}>
                                {mode === 'stock' ? 'Jednoduchý produkt' : 'Kompozitný SET'}
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-6 mb-6">
                            <div className="col-span-2">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Názov {mode === 'stock' ? 'Dielu' : 'Setu'}</label>
                                <input value={name} onChange={e => setName(e.target.value)} className="w-full p-3 text-lg border rounded font-bold focus:ring-2 focus:ring-blue-500 outline-none" placeholder={mode === 'stock' ? "Napr. Skrutka M12x40" : "Napr. Rám Kabíny BP1000 (Komplet)"} autoFocus />
                            </div>

                            {/* NEW SUBCATEGORY FIELD */}
                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase flex items-center gap-1"><FolderTree size={12}/> Podkategória (Voliteľné)</label>
                                <div className="relative">
                                    <input 
                                        list="subcat-options"
                                        value={subcategory} 
                                        onChange={e => setSubcategory(e.target.value)} 
                                        className="w-full p-3 border rounded text-sm bg-gray-50 focus:bg-white transition" 
                                        placeholder={activeCategory === 'Dvere' ? "Napr. Šachtové" : "Napr. Skrutky, Profily..."} 
                                    />
                                    <datalist id="subcat-options">
                                        {activeCategory === 'Dvere' && (
                                            <>
                                                <option value="Šachtové">Šachtové Dvere</option>
                                                <option value="Kabínové">Kabínové Dvere</option>
                                            </>
                                        )}
                                        {availableSubcategories.map(s => <option key={s} value={s}/>)}
                                    </datalist>
                                </div>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Jednotka</label>
                                <select value={unit} onChange={e => setUnit(e.target.value)} className="w-full p-3 border rounded bg-white font-medium">
                                    <option value="ks">ks</option><option value="m">m</option><option value="kpl">kpl</option><option value="hod">hod</option>
                                    <option value="set">set</option>
                                </select>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Výrobca (Značka)</label>
                                <div className="relative">
                                    <Factory className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/>
                                    <input value={manufacturer} onChange={e => setManufacturer(e.target.value)} className="w-full pl-10 p-3 border rounded text-sm" placeholder="Napr. Wittur, Fermator..." />
                                </div>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Dodávateľ (Kde kúpené)</label>
                                <div className="relative">
                                    <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/>
                                    <input value={supplier} onChange={e => setSupplier(e.target.value)} className="w-full pl-10 p-3 border rounded text-sm" placeholder="Napr. Eshop, Lokálny predajca..." />
                                </div>
                            </div>

                            <div className="col-span-2 bg-gray-50 p-4 rounded border border-gray-200">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Nákupná Cena (€)</label>
                                <input 
                                    type="number" 
                                    value={mode === 'sets' ? subProducts.reduce((acc, i) => acc + (getProductPrice(i.productId)*i.quantity), 0).toFixed(2) : price} 
                                    onChange={e => setPrice(e.target.value)} 
                                    className={`w-full p-3 border rounded font-bold text-right text-2xl ${mode === 'sets' ? 'bg-gray-200 text-gray-500' : 'bg-white text-black'}`}
                                    disabled={mode === 'sets'}
                                    placeholder="0.00"
                                />
                                {mode === 'sets' && <div className="text-xs text-purple-600 text-right mt-2 font-bold flex items-center justify-end gap-1"><Settings size={12}/> Automatický súčet komponentov</div>}
                            </div>
                        </div>

                        {/* COMPOSITE EDITOR (SET BUILDER) */}
                        {mode === 'sets' && (
                            <div className="border-t pt-6 mt-6 bg-purple-50/50 -mx-8 px-8 pb-6">
                                <h4 className="font-bold text-purple-800 mb-2 flex items-center gap-2 text-lg"><Layers size={24}/> Obsah SETU</h4>
                                <div className="text-sm text-gray-500 mb-4">
                                    Vyskladajte tento SET z položiek, ktoré už máte na Sklade.
                                </div>

                                {/* Current Components List */}
                                <div className="bg-white rounded-lg p-4 mb-4 space-y-2 border border-purple-100 min-h-[120px]">
                                    {subProducts.length === 0 && <div className="text-sm text-gray-400 italic text-center py-8">Zatiaľ prázdny set. Pridajte diely zo skladu nižšie.</div>}
                                    {subProducts.map((sp, idx) => (
                                        <div key={idx} className="flex justify-between items-center bg-purple-50 p-3 rounded shadow-sm border border-purple-100">
                                            <div className="flex-1">
                                                <div className="text-base font-bold text-gray-800">{getProductName(sp.productId)}</div>
                                            </div>
                                            <div className="flex items-center gap-4">
                                                <span className="text-sm text-gray-500 font-mono">{getProductPrice(sp.productId).toFixed(2)} €/ks</span>
                                                <div className="flex items-center border rounded bg-white">
                                                    <span className="text-xs px-2 text-gray-500 font-bold">x</span>
                                                    <input 
                                                        type="number" 
                                                        min="0.01"
                                                        step="0.01" 
                                                        value={sp.quantity} 
                                                        onChange={e => updateComponentQty(sp.productId, +e.target.value)}
                                                        className="w-20 p-2 text-center text-sm font-bold bg-white focus:outline-none text-purple-700"
                                                    />
                                                </div>
                                                <button onClick={() => removeComponent(sp.productId)} className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded"><Trash2 size={20}/></button>
                                            </div>
                                        </div>
                                    ))}
                                </div>

                                {/* Component Search & Filter */}
                                <div className="bg-white p-4 rounded-lg border border-gray-200">
                                    <div className="text-sm font-bold text-gray-500 mb-2 uppercase flex items-center gap-2"><Search size={16}/> Hľadať v Sklade</div>
                                    <div className="flex gap-4 mb-4 items-center">
                                         <select 
                                            value={componentSourceCategory}
                                            onChange={(e) => setComponentSourceCategory(e.target.value)}
                                            className="text-sm border rounded p-2 bg-gray-50 font-bold text-gray-700 focus:ring-1 focus:ring-blue-500 outline-none flex-1 max-w-[250px]"
                                         >
                                             <option value="ALL">Celý Sklad</option>
                                             {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                         </select>
                                         <input 
                                            placeholder="Názov dielu..." 
                                            className="flex-1 p-2 border rounded text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                            value={componentSearch}
                                            onChange={e => setComponentSearch(e.target.value)}
                                        />
                                    </div>

                                    {/* Search Results */}
                                    <div className="border rounded mt-1 max-h-48 overflow-y-auto bg-gray-50 shadow-inner">
                                        {availableComponents.length === 0 ? (
                                            <div className="p-4 text-center text-sm text-gray-400">
                                                {componentSearch ? 'Nenašli sa žiadne produkty.' : 'Začnite písať pre vyhľadanie dielov...'}
                                            </div>
                                        ) : (
                                            availableComponents.map(p => (
                                                <button key={p.id} onClick={() => { addComponent(p.id); setComponentSearch(''); }} className="w-full text-left p-3 hover:bg-green-50 text-sm flex justify-between border-b last:border-0 items-center transition group">
                                                    <div>
                                                        <div className="font-bold text-gray-800 text-base group-hover:text-green-700">{p.name}</div>
                                                        <div className="flex gap-2 text-xs text-gray-400 uppercase mt-1">
                                                            <span>{p.category}</span>
                                                            {p.subcategory && <span> • {p.subcategory}</span>}
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <span className="font-mono text-sm bg-white px-2 py-1 rounded border shadow-sm">{p.price.toFixed(2)} €</span>
                                                        <Plus size={20} className="text-green-600 bg-green-100 rounded-full p-1"/>
                                                    </div>
                                                </button>
                                            ))
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-end gap-4 mt-8 pt-4 border-t">
                            <button onClick={() => setIsEditing(false)} className="px-6 py-3 text-gray-600 hover:bg-gray-100 rounded-lg font-bold">Zrušiť</button>
                            <button onClick={handleSave} className={`px-8 py-3 text-white font-bold rounded-lg flex items-center gap-2 shadow-lg hover:shadow-xl transition transform hover:scale-[1.02] ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                                <Save size={20}/> {mode === 'stock' ? 'Naskladniť Diel' : 'Uložiť SET'}
                            </button>
                        </div>
                    </div>
                </div>
            ) : (
                /* LIST MODE */
                <div className="flex-1 overflow-y-auto p-6 bg-gray-100">
                     <div className="flex gap-4 mb-6">
                        {/* Subcategory Filter */}
                        {availableSubcategories.length > 0 && (
                             <div className="relative min-w-[200px]">
                                <FolderTree className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                                <select 
                                    value={activeSubcategory}
                                    onChange={(e) => setActiveSubcategory(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                                >
                                    <option value="ALL">Všetky Podkategórie</option>
                                    {availableSubcategories.map(s => <option key={s} value={s}>{s}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                            <input 
                            type="text"
                            placeholder={`Hľadať v kategórii ${activeCategory}...`}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm text-base"
                            />
                        </div>
                        {/* Supplier Filter */}
                        <div className="relative w-56">
                            <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                            <select 
                                value={supplierFilter}
                                onChange={(e) => setSupplierFilter(e.target.value)}
                                className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                            >
                                <option value="">Všetci Dodávatelia</option>
                                {uniqueSuppliers.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <button onClick={handleNewClick} className={`px-6 py-3 text-white rounded-xl font-bold flex items-center gap-2 shadow-md transition transform hover:scale-105 ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                            <Plus size={20}/> Nový {mode === 'stock' ? 'Diel' : 'SET'}
                        </button>
                    </div>

                    <div className="space-y-3">
                        {filteredProducts.length === 0 && <div className="text-center py-20 text-gray-400 italic text-lg">Žiadne položky.<br/><span className="text-sm">Začnite pridaním nového {mode === 'stock' ? 'dielu' : 'setu'}.</span></div>}

                        {filteredProducts.map(product => (
                            <div key={product.id} className={`bg-white p-5 rounded-xl border shadow-sm flex justify-between items-center group transition-all ${mode === 'sets' ? 'hover:border-purple-300' : 'hover:border-blue-300 border-gray-200'}`}>
                                <div>
                                    <div className="font-bold text-gray-800 flex items-center gap-3 text-xl">
                                        {product.name}
                                        {product.type === 'composite' && (
                                            <span className="text-xs bg-purple-100 text-purple-700 px-3 py-1 rounded-full border border-purple-200 flex items-center gap-1 uppercase tracking-wider font-bold">
                                                <Layers size={12}/> SET
                                            </span>
                                        )}
                                        {product.subcategory && (
                                             <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded border border-gray-200">
                                                 {product.subcategory}
                                             </span>
                                        )}
                                    </div>
                                    <div className="text-sm text-gray-500 flex items-center gap-4 mt-2">
                                        {product.manufacturer && <span className="bg-gray-50 px-2 py-1 rounded text-xs font-bold text-gray-600 border border-gray-100 flex items-center gap-1"><Factory size={12}/> {product.manufacturer}</span>}
                                        {product.supplier && <span className="bg-gray-50 px-2 py-1 rounded text-xs font-bold text-blue-600 border border-gray-100 flex items-center gap-1"><Building size={12}/> {product.supplier}</span>}
                                        <span className="font-mono text-black font-bold text-lg bg-gray-50 px-2 rounded">{product.price.toFixed(2)} € / {product.unit}</span>
                                        {product.type === 'composite' && <span className="text-xs text-purple-500 font-bold">({product.subProducts?.length} komponentov)</span>}
                                    </div>
                                </div>
                                <div className="flex gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={() => handleEditClick(product)} className="px-4 py-2 bg-gray-100 hover:bg-blue-50 text-blue-600 rounded-lg font-bold text-sm flex items-center gap-2 transition"><Settings size={16}/> Upraviť</button>
                                    <button onClick={() => onDeleteProduct(product.id)} className="p-3 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition"><Trash2 size={20}/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

