import React, { useState, useEffect, useRef } from 'react';
import { Product, ProductComponent, CabinClass } from '../types';
import { X, Plus, Search, Trash2, Save, Package, Layers, Settings, ArrowRight, Box, Filter, Factory, ShoppingCart, Wrench, Building, Download, Upload, FolderTree, Star, Eye, EyeOff, Calculator, DollarSign } from 'lucide-react';

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory?: (name: string) => void;
  onDeleteCategory?: (name: string) => void;
  onImportCatalog?: (file: File) => void;

  // Cabin Class Props
  cabinClasses?: CabinClass[];
  onAddCabinClass?: (cc: CabinClass) => void;
  onUpdateCabinClass?: (cc: CabinClass) => void; // Added update prop
  onDeleteCabinClass?: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen,
  onClose,
  products,
  onAddProduct,
  onUpdateProduct,
  onDeleteProduct,
  customCategories,
  onAddCategory,
  onDeleteCategory,
  onImportCatalog,
  cabinClasses,
  onAddCabinClass,
  onUpdateCabinClass, // New prop handled inside
  onDeleteCabinClass
}) => {
  // MODE SWITCH: 'stock' (Simple items) vs 'sets' (Composite items) vs 'classes' (Cabin Types)
  const [mode, setMode] = useState<'stock' | 'sets' | 'classes'>('stock');

  const [activeCategory, setActiveCategory] = useState(customCategories[0] || 'Dvere');
  const [activeSubcategory, setActiveSubcategory] = useState<string>('ALL'); // Filter by Subcat

  const [searchTerm, setSearchTerm] = useState('');

  // New Supplier Filter
  const [supplierFilter, setSupplierFilter] = useState<string>('');

  // EDITOR STATE
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);

  const [name, setName] = useState('');
  const [manufacturer, setManufacturer] = useState('');
  const [supplier, setSupplier] = useState('');
  const [unit, setUnit] = useState('ks');
  const [price, setPrice] = useState('');
  const [subcategory, setSubcategory] = useState(''); // New Subcategory Field

  // Composite Logic
  const [subProducts, setSubProducts] = useState<ProductComponent[]>([]);
  const [componentSearch, setComponentSearch] = useState('');
  const [componentSourceCategory, setComponentSourceCategory] = useState<string>('ALL');

  // NEW SET OPTIONS
  const [priceType, setPriceType] = useState<'calculated' | 'fixed'>('calculated');
  const [displayMode, setDisplayMode] = useState<'itemized' | 'single_line'>('itemized');

  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  // Cabin Class Form
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLink, setNewClassLink] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Use passed categories as source of truth
  const allCategories = customCategories;

  // Unique suppliers for filter dropdown
  const uniqueSuppliers = Array.from(new Set(products.map(p => p.supplier).filter(Boolean))) as string[];

  // Get Subcategories for current category
  const getSubcategories = (category: string) => {
      // Special logic for Doors
      if (category === 'Dvere') return ['Šachtové', 'Kabínové'];
      // For others, derive from existing products
      const existing = Array.from(new Set(
          products.filter(p => p.category === category && p.subcategory).map(p => p.subcategory)
      ));
      return existing as string[];
  };

  const availableSubcategories = getSubcategories(activeCategory);

  // Reset filter when changing active category or closing
  useEffect(() => {
      if (!isEditing && mode !== 'classes') {
          setComponentSourceCategory(activeCategory);
          setActiveSubcategory('ALL');
      }
  }, [activeCategory, isEditing, mode]);

  // Ensure active category is valid if list changes
  useEffect(() => {
      if (!allCategories.includes(activeCategory) && allCategories.length > 0) {
          setActiveCategory(allCategories[0]);
      }
  }, [allCategories]);

  if (!isOpen) return null;

  const filteredProducts = products.filter(p => 
    p.category === activeCategory && 
    (activeSubcategory === 'ALL' || p.subcategory === activeSubcategory) &&
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) &&
    (mode === 'stock' ? (!p.type || p.type === 'simple') : p.type === 'composite') &&
    (!supplierFilter || p.supplier === supplierFilter)
  );

  const handleEditClick = (p: Product) => {
      setEditId(p.id);
      setName(p.name);
      setManufacturer(p.manufacturer || '');
      setSupplier(p.supplier || '');
      setUnit(p.unit);
      setPrice(p.price.toString());
      setSubcategory(p.subcategory || '');
      setSubProducts(p.subProducts || []);
      setComponentSourceCategory(p.category);

      // Load Set Options
      setPriceType(p.priceType || 'calculated');
      setDisplayMode(p.displayMode || 'itemized');

      setIsEditing(true);
  };

  const handleNewClick = () => {
      setEditId(null);
      setName('');
      setManufacturer('');
      setSupplier('');
      setUnit('ks');
      setPrice('');
      setSubcategory(activeSubcategory !== 'ALL' ? activeSubcategory : '');
      setSubProducts([]);
      setComponentSourceCategory(activeCategory);

      // Defaults for New Set
      setPriceType('calculated');
      setDisplayMode('itemized');

      setIsEditing(true);
  };

  const handleSaveCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setActiveCategory(newCatName);
          setIsAddingCategory(false);
          setNewCatName('');
      }
  };

  const handleDeleteCat = (cat: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (onDeleteCategory && confirm(`Naozaj chcete vymazať kategóriu "${cat}"?`)) {
          // If active, switch to first available
          if (activeCategory === cat) {
              setActiveCategory(allCategories.find(c => c !== cat) || '');
          }
          onDeleteCategory(cat);
      }
  };

  const handleSave = () => {
      if (!name) return;

      let finalPrice = parseFloat(price) || 0;

      // If creating a SET
      if (mode === 'sets') {
          // If Calculated, sum components. If Fixed, use entered price.
          if (priceType === 'calculated') {
              finalPrice = subProducts.reduce((acc, item) => {
                  const p = products.find(prod => prod.id === item.productId);
                  return acc + ((p?.price || 0) * item.quantity);
              }, 0);
          }
      }

      const newProduct: Product = {
          id: editId || crypto.randomUUID(),
          category: activeCategory,
          subcategory: subcategory || undefined,
          name,
          manufacturer: manufacturer || undefined,
          supplier: supplier || undefined,
          unit,
          price: finalPrice,
          type: mode === 'sets' ? 'composite' : 'simple',
          subProducts: mode === 'sets' ? subProducts : undefined,
          priceType: mode === 'sets' ? priceType : undefined,
          displayMode: mode === 'sets' ? displayMode : undefined
      };

      if (editId) {
          onUpdateProduct(newProduct);
      } else {
          onAddProduct(newProduct);
      }
      setIsEditing(false);
  };

  const handleAddClass = () => {
      if(newClassName && onAddCabinClass) {
          onAddCabinClass({
              id: crypto.randomUUID(),
              name: newClassName,
              description: newClassDesc || 'Vlastný typ',
              linkedProductId: newClassLink || undefined
          });
          setNewClassName('');
          setNewClassDesc('');
          setNewClassLink('');
      }
  };

  // Basic update for linking (Simple implementation for now)
  const handleLinkClass = (classId: string, productId: string) => {
      if (onUpdateCabinClass && cabinClasses) {
          const cls = cabinClasses.find(c => c.id === classId);
          if (cls) {
              // This relies on parent having handleUpdateCabinClass which updates the state array
              // Since App.tsx doesn't have explicit update, we simulate it via add/delete or expect parent change
              // For now, let's assume we can just pass the modified object to a handler or context
              // Ideally App.tsx needs handleUpdateCabinClass. 
              // We will patch the App logic via props in next step if needed, but for now lets use add/delete trick or direct state update if passed
              // Actually, best is to update the state in App.tsx. I will assume onAddCabinClass can also be used or I need to add onUpdateCabinClass to App.tsx.
              // Current App.tsx doesn't have onUpdateCabinClass. I'll add it to the code below in App.tsx section.

              // For this component, simply trigger the prop
              onUpdateCabinClass({ ...cls, linkedProductId: productId });
          }
      }
  };

  const addComponent = (productId: string) => {
      const existing = subProducts.find(sp => sp.productId === productId);
      if (existing) {
          setSubProducts(subProducts.map(sp => sp.productId === productId ? { ...sp, quantity: sp.quantity + 1 } : sp));
      } else {
          setSubProducts([...subProducts, { productId, quantity: 1 }]);
      }
  };

  const removeComponent = (productId: string) => {
      setSubProducts(subProducts.filter(sp => sp.productId !== productId));
  };

  const updateComponentQty = (productId: string, qty: number) => {
      setSubProducts(subProducts.map(sp => sp.productId === productId ? { ...sp, quantity: qty } : sp));
  };

  const getProductName = (id: string) => products.find(p => p.id === id)?.name || 'Neznámy produkt';
  const getProductPrice = (id: string) => products.find(p => p.id === id)?.price || 0;

  // -- EXPORT / IMPORT --
  const handleExport = () => {
      const blob = new Blob([JSON.stringify(products, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `katalog_produktov_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleImportClick = () => {
      if (fileInputRef.current) fileInputRef.current.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file && onImportCatalog) {
          onImportCatalog(file);
      }
  };

  const availableComponents = products.filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(componentSearch.toLowerCase());
      const matchesCategory = componentSourceCategory === 'ALL' || p.category === componentSourceCategory;
      const isNotSelf = p.id !== editId;
      const isSimple = !p.type || p.type === 'simple'; // Only simple items go into sets
      return matchesSearch && matchesCategory && isNotSelf && isSimple;
  });

  // Available Sets for Linking (Composite products)
  const availableSets = products.filter(p => p.type === 'composite');

  return (
    <div className="fixed inset-0 bg-white z-[100] flex flex-col">

        {/* Header - Fixed Top */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 shadow-sm shrink-0">
          <div className="flex items-center gap-4">
            <div className="bg-blue-100 p-2 rounded-lg"><Package className="text-blue-700" size={24} /></div>
            <div>
                <h2 className="text-2xl font-bold text-gray-800">Manažér Katalógu</h2>
                <div className="text-sm text-gray-500">Master Data Produktov</div>
            </div>
          </div>

          {/* Data Actions */}
          <div className="flex gap-2">
              <button 
                  onClick={() => setMode('classes')} 
                  className={`px-4 py-2 border rounded text-sm font-bold flex items-center gap-2 hover:bg-yellow-50 ${mode === 'classes' ? 'bg-yellow-100 text-yellow-800 border-yellow-300' : 'bg-white border-gray-300 text-gray-700'}`} 
                  title="Spravovať Typy Kabín"
              >
                  <Star size={16}/> Triedy Kabín
              </button>

              <div className="w-px bg-gray-300 mx-2"></div>

              <button onClick={handleExport} className="px-4 py-2 bg-white border border-gray-300 rounded text-sm font-bold text-gray-700 flex items-center gap-2 hover:bg-gray-100" title="Zálohovať produkty">
                  <Download size={16}/> Export
              </button>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} accept=".json" className="hidden"/>
              {onImportCatalog && (
                  <button onClick={handleImportClick} className="px-4 py-2 bg-white border border-gray-300 rounded text-sm font-bold text-gray-700 flex items-center gap-2 hover:bg-gray-100" title="Obnoviť produkty">
                      <Upload size={16}/> Import
                  </button>
              )}
              <div className="w-px bg-gray-300 mx-4"></div>
              <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
                <X size={28}/>
              </button>
          </div>
        </div>

        {/* WORKFLOW SWITCHER - TOP BAR */}
        {!isEditing && mode !== 'classes' && (
        <div className="p-4 bg-white border-b flex gap-6 justify-center shrink-0">
            <button 
                onClick={() => setMode('stock')}
                className={`flex-1 max-w-sm py-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${mode === 'stock' ? 'border-blue-500 bg-blue-50 text-blue-700 shadow-md ring-1 ring-blue-500' : 'border-gray-200 text-gray-500 hover:border-blue-200 hover:bg-gray-50'}`}
            >
                <ShoppingCart size={32} className={mode === 'stock' ? 'text-blue-600' : 'text-gray-400'}/>
                <div>
                    <div className="font-bold text-lg">NÁKUP NA SKLAD</div>
                    <div className="text-xs opacity-70">Nahrávanie dielov z dodacích listov</div>
                </div>
            </button>

            <button 
                onClick={() => setMode('sets')}
                className={`flex-1 max-w-sm py-4 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-all ${mode === 'sets' ? 'border-purple-500 bg-purple-50 text-purple-700 shadow-md ring-1 ring-purple-500' : 'border-gray-200 text-gray-500 hover:border-purple-200 hover:bg-gray-50'}`}
            >
                <Wrench size={32} className={mode === 'sets' ? 'text-purple-600' : 'text-gray-400'}/>
                <div>
                    <div className="font-bold text-lg">TVORBA SETOV</div>
                    <div className="text-xs opacity-70">Skladanie dielov do celkov (napr. Kabína)</div>
                </div>
            </button>
        </div>
        )}

        {/* Categories */}
        {!isEditing && mode !== 'classes' && (
            <div className="p-2 border-b bg-gray-50 flex gap-2 overflow-x-auto items-center shrink-0 custom-scrollbar">
                {allCategories.map(cat => (
                <button
                    key={cat}
                    onClick={() => setActiveCategory(cat)}
                    className={`group px-6 py-3 rounded-lg text-base font-bold whitespace-nowrap transition flex items-center gap-2 ${
                    activeCategory === cat 
                        ? (mode === 'stock' ? 'bg-blue-600 text-white shadow-md' : 'bg-purple-600 text-white shadow-md')
                        : 'bg-white border text-gray-600 hover:bg-gray-200'
                    }`}
                >
                    {cat}
                    {/* ALWAYS SHOW DELETE for any category if delete handler exists */}
                    {onDeleteCategory && (
                        <span 
                            onClick={(e) => handleDeleteCat(cat, e)}
                            className="p-0.5 rounded-full hover:bg-red-500 hover:text-white opacity-0 group-hover:opacity-100 transition-opacity ml-2"
                            title="Vymazať kategóriu"
                        >
                            <X size={14}/>
                        </span>
                    )}
                </button>
                ))}

                {isAddingCategory ? (
                    <div className="flex items-center gap-1 bg-white border rounded-full px-2 py-1">
                        <input autoFocus className="w-32 text-sm outline-none bg-transparent" placeholder="Názov..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleSaveCategory()} />
                        <button onClick={handleSaveCategory} className="text-green-600 hover:bg-green-100 rounded-full p-1"><Plus size={16}/></button>
                        <button onClick={()=>setIsAddingCategory(false)} className="text-red-500 hover:bg-red-100 rounded-full p-1"><X size={16}/></button>
                    </div>
                ) : (
                    <button onClick={()=>setIsAddingCategory(true)} className="px-4 py-3 rounded-lg border border-dashed border-gray-400 text-gray-500 hover:border-blue-500 hover:text-blue-600 flex items-center gap-1 text-sm whitespace-nowrap"><Plus size={16}/> Pridať Kategóriu</button>
                )}
            </div>
        )}

        {/* MAIN CONTENT */}
        <div className="flex-1 overflow-hidden flex flex-col bg-gray-100">

            {/* CABIN CLASS MANAGER MODE */}
            {mode === 'classes' ? (
                <div className="flex-1 overflow-y-auto p-8 flex justify-center">
                    <div className="w-full max-w-4xl">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-2xl font-bold text-gray-800 flex items-center gap-2"><Star className="text-yellow-500"/> Správa Tried Kabín</h3>
                            <button onClick={() => setMode('stock')} className="text-gray-500 hover:text-blue-600 font-bold text-sm">← Späť na produkty</button>
                        </div>

                        <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
                            {/* Add Form */}
                            <div className="p-6 bg-yellow-50 border-b border-yellow-100 flex gap-4 items-end">
                                <div className="flex-1">
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Kód Triedy (Názov)</label>
                                    <input 
                                        className="w-full p-2 border rounded font-bold text-sm" 
                                        placeholder="Napr. LUXURY" 
                                        value={newClassName}
                                        onChange={e => setNewClassName(e.target.value)}
                                    />
                                </div>
                                <div className="flex-[2]">
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Popis (Materiály)</label>
                                    <input 
                                        className="w-full p-2 border rounded text-sm" 
                                        placeholder="Napr. Koža / Zrkadlá / LED" 
                                        value={newClassDesc}
                                        onChange={e => setNewClassDesc(e.target.value)}
                                    />
                                </div>
                                <div className="flex-[2]">
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Prepojený SET (Skladačka)</label>
                                    <select
                                        className="w-full p-2 border rounded text-sm bg-white"
                                        value={newClassLink}
                                        onChange={e => setNewClassLink(e.target.value)}
                                    >
                                        <option value="">-- Bez prepojenia --</option>
                                        {availableSets.map(set => (
                                            <option key={set.id} value={set.id}>{set.name}</option>
                                        ))}
                                    </select>
                                </div>
                                <button 
                                    onClick={handleAddClass}
                                    disabled={!newClassName}
                                    className="px-6 py-2 bg-yellow-500 text-white font-bold rounded shadow hover:bg-yellow-600 disabled:opacity-50"
                                >
                                    Pridať
                                </button>
                            </div>

                            {/* List */}
                            <div className="divide-y divide-gray-100">
                                {cabinClasses?.length === 0 && <div className="p-8 text-center text-gray-400 italic">Žiadne definované triedy.</div>}
                                {cabinClasses?.map(cc => (
                                    <div key={cc.id} className="p-4 flex items-center justify-between hover:bg-gray-50 group">
                                        <div>
                                            <div className="font-bold text-lg text-gray-800">{cc.name}</div>
                                            <div className="text-sm text-gray-500">{cc.description}</div>
                                        </div>
                                        <div className="flex items-center gap-4">
                                            <div className="flex items-center gap-2">
                                                <span className="text-xs font-bold text-gray-400 uppercase">Prepojenie:</span>
                                                <select
                                                    className={`p-1 border rounded text-sm max-w-[200px] ${cc.linkedProductId ? 'text-purple-600 font-bold bg-purple-50 border-purple-200' : 'text-gray-400 bg-gray-50'}`}
                                                    value={cc.linkedProductId || ''}
                                                    onChange={(e) => handleLinkClass(cc.id, e.target.value)}
                                                >
                                                    <option value="">-- Neprepojené --</option>
                                                    {availableSets.map(set => (
                                                        <option key={set.id} value={set.id}>{set.name}</option>
                                                    ))}
                                                </select>
                                            </div>
                                            <button 
                                                onClick={() => onDeleteCabinClass && onDeleteCabinClass(cc.id)}
                                                className="p-2 text-gray-300 hover:text-red-600 hover:bg-red-50 rounded transition"
                                                title="Vymazať"
                                            >
                                                <Trash2 size={18}/>
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            ) : isEditing ? (
            /* EDITOR MODE */
                <div className="flex-1 overflow-y-auto p-8">
                    <div className={`bg-white p-8 rounded-xl border shadow-lg max-w-5xl mx-auto ${mode === 'stock' ? 'border-blue-200 shadow-blue-100' : 'border-purple-200 shadow-purple-100'}`}>
                        <div className="flex justify-between items-center mb-8 border-b pb-4">
                            <div>
                                <h3 className={`text-2xl font-bold ${mode === 'stock' ? 'text-blue-800' : 'text-purple-800'}`}>
                                    {editId ? 'Upraviť' : 'Nový'} {mode === 'stock' ? 'Skladový Diel' : 'SET (Skladačka)'}
                                </h3>
                                <div className="text-sm text-gray-500 uppercase font-bold mt-1 flex items-center gap-2">
                                    Kategória: <span className="text-black">{activeCategory}</span>
                                </div>
                            </div>
                            <div className={`px-4 py-2 rounded text-sm font-bold uppercase border ${mode === 'stock' ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-purple-50 border-purple-200 text-purple-700'}`}>
                                {mode === 'stock' ? 'Jednoduchý produkt' : 'Kompozitný SET'}
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-6 mb-6">
                            <div className="col-span-2">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Názov {mode === 'stock' ? 'Dielu' : 'Setu'}</label>
                                <input value={name} onChange={e => setName(e.target.value)} className="w-full p-3 text-lg border rounded font-bold focus:ring-2 focus:ring-blue-500 outline-none" placeholder={mode === 'stock' ? "Napr. Skrutka M12x40" : "Napr. Rám Kabíny BP1000 (Komplet)"} autoFocus />
                            </div>

                            {/* NEW SUBCATEGORY FIELD */}
                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase flex items-center gap-1"><FolderTree size={12}/> Podkategória (Voliteľné)</label>
                                <div className="relative">
                                    <input 
                                        list="subcat-options"
                                        value={subcategory} 
                                        onChange={e => setSubcategory(e.target.value)} 
                                        className="w-full p-3 border rounded text-sm bg-gray-50 focus:bg-white transition" 
                                        placeholder={activeCategory === 'Dvere' ? "Napr. Šachtové" : "Napr. Skrutky, Profily..."} 
                                    />
                                    <datalist id="subcat-options">
                                        {activeCategory === 'Dvere' && (
                                            <>
                                                <option value="Šachtové">Šachtové Dvere</option>
                                                <option value="Kabínové">Kabínové Dvere</option>
                                            </>
                                        )}
                                        {availableSubcategories.map(s => <option key={s} value={s}/>)}
                                    </datalist>
                                </div>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Jednotka</label>
                                <select value={unit} onChange={e => setUnit(e.target.value)} className="w-full p-3 border rounded bg-white font-medium">
                                    <option value="ks">ks</option><option value="m">m</option><option value="kpl">kpl</option><option value="hod">hod</option>
                                    <option value="set">set</option>
                                </select>
                            </div>

                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Výrobca (Značka)</label>
                                <div className="relative">
                                    <Factory className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/>
                                    <input value={manufacturer} onChange={e => setManufacturer(e.target.value)} className="w-full pl-10 p-3 border rounded text-sm" placeholder="Napr. Wittur, Fermator..." />
                                </div>
                            </div>
                            <div className="col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Dodávateľ (Kde kúpené)</label>
                                <div className="relative">
                                    <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/>
                                    <input value={supplier} onChange={e => setSupplier(e.target.value)} className="w-full pl-10 p-3 border rounded text-sm" placeholder="Napr. Eshop, Lokálny predajca..." />
                                </div>
                            </div>

                            <div className="col-span-2 bg-gray-50 p-4 rounded border border-gray-200">
                                <div className="flex justify-between mb-2">
                                    <label className="block text-xs font-bold text-gray-500 uppercase">Nákupná Cena (€)</label>
                                    {mode === 'sets' && (
                                        <div className="flex items-center gap-2">
                                            <span className="text-xs text-gray-500">Typ ceny:</span>
                                            <button 
                                                onClick={() => setPriceType('calculated')} 
                                                className={`px-2 py-0.5 rounded text-xs font-bold ${priceType === 'calculated' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-500'}`}
                                            >
                                                <Settings size={10} className="inline mr-1"/> Auto
                                            </button>
                                            <button 
                                                onClick={() => setPriceType('fixed')} 
                                                className={`px-2 py-0.5 rounded text-xs font-bold ${priceType === 'fixed' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-500'}`}
                                            >
                                                <DollarSign size={10} className="inline mr-1"/> Manuál
                                            </button>
                                        </div>
                                    )}
                                </div>
                                <input 
                                    type="number" 
                                    value={mode === 'sets' && priceType === 'calculated' ? subProducts.reduce((acc, i) => acc + (getProductPrice(i.productId)*i.quantity), 0).toFixed(2) : price} 
                                    onChange={e => setPrice(e.target.value)} 
                                    className={`w-full p-3 border rounded font-bold text-right text-2xl ${mode === 'sets' && priceType === 'calculated' ? 'bg-gray-200 text-gray-500' : 'bg-white text-black'}`}
                                    disabled={mode === 'sets' && priceType === 'calculated'}
                                    placeholder="0.00"
                                />
                                {mode === 'sets' && priceType === 'calculated' && <div className="text-xs text-purple-600 text-right mt-2 font-bold flex items-center justify-end gap-1"><Calculator size={12}/> Automatický súčet komponentov</div>}
                                {mode === 'sets' && priceType === 'fixed' && <div className="text-xs text-orange-600 text-right mt-2 font-bold">⚠️ Cena je zadaná manuálne, ignoruje súčet položiek.</div>}
                            </div>
                        </div>

                        {/* COMPOSITE EDITOR (SET BUILDER) */}
                        {mode === 'sets' && (
                            <div className="border-t pt-6 mt-6 bg-purple-50/50 -mx-8 px-8 pb-6">
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="font-bold text-purple-800 flex items-center gap-2 text-lg"><Layers size={24}/> Obsah SETU</h4>

                                    {/* DISPLAY MODE TOGGLE */}
                                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-purple-200 shadow-sm">
                                        <span className="text-xs font-bold text-gray-500 uppercase">V ponuke zobraziť:</span>
                                        <button 
                                            onClick={() => setDisplayMode('itemized')} 
                                            className={`px-2 py-1 rounded text-xs font-bold flex items-center gap-1 ${displayMode === 'itemized' ? 'bg-purple-600 text-white' : 'hover:bg-gray-100 text-gray-600'}`}
                                            title="Rozpísať v ponuke všetky komponenty pod seba"
                                        >
                                            <Eye size={12}/> Rozpísať položky
                                        </button>
                                        <button 
                                            onClick={() => setDisplayMode('single_line')} 
                                            className={`px-2 py-1 rounded text-xs font-bold flex items-center gap-1 ${displayMode === 'single_line' ? 'bg-purple-600 text-white' : 'hover:bg-gray-100 text-gray-600'}`}
                                            title="V ponuke bude len jeden riadok (Názov Setu), komponenty sú skryté"
                                        >
                                            <EyeOff size={12}/> Len názov setu
                                        </button>
                                    </div>
                                </div>

                                <div className="text-sm text-gray-500 mb-4">
                                    Vyskladajte tento SET z položiek, ktoré už máte na Sklade.
                                </div>

                                {/* Current Components List */}
