                        <div className="bg-yellow-50 p-3 mb-4 rounded border border-yellow-200 no-print">
                            <div className="text-xs font-bold uppercase mb-2">Marža</div>
                            <div className="flex justify-between items-center mb-1"><span className="text-sm">Výťah %</span><input type="number" value={data.globalMargin} onChange={e=>setData(prev=>({...prev, globalMargin:+e.target.value}))} className="w-16 border rounded text-right font-bold"/></div>
                            <div className="flex justify-between items-center"><span className="text-sm">Šachta %</span><input type="number" value={data.shaftMargin} onChange={e=>setData(prev=>({...prev, shaftMargin:+e.target.value}))} className="w-16 border rounded text-right font-bold"/></div>
                        </div>
                    )}

                    {/* Totals Display */}
                    <div className="bg-gray-50 p-6 rounded border">
                        <div className="flex justify-between mb-2 font-bold"><span>Spolu bez DPH:</span><span>{formatCurrency(totals.totalSelling)}</span></div>
                        <div className="flex justify-between mb-2 text-gray-600"><span>DPH 23%:</span><span>{formatCurrency(totals.vat)}</span></div>
                        <div className="border-t pt-2 mt-2 flex justify-between font-bold text-xl"><span>K úhrade:</span><span>{formatCurrency(totals.gross)}</span></div>
                    </div>
                </div>
            </div>
            {!isContractMode && <div className="break-inside-avoid print:break-before-page mt-8">
                <h3 className="font-bold uppercase mb-2">Podmienky</h3>
                <textarea value={data.terms} onChange={e=>setData({...data, terms:e.target.value})} className="w-full bg-gray-50 p-4 rounded min-h-[300px] text-sm whitespace-pre-wrap"/>
            </div>}
        </div>
      </div>
      <div className="print-footer no-print">SmartQuote SK - Strana <span className="pageNumber"></span></div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, CabinClass } from '../types';
import { X, Calculator, Check, AlertTriangle, Settings, Box, Zap, Construction, Truck, Package, Hammer, ArrowLeft, ArrowRight, ListCheck, Search, Plus, Filter, Layers, Save, Trash2, GripVertical, Gauge, ScanLine } from 'lucide-react';

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[]; // These are ALL available categories (Master + Custom)
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[]; // Passed from App to resolve links
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean; // Flag to distinguish calculated vs manual items
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    categoryOrder: string[]; // Only active categories
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen,
  onClose,
  layout,
  onInsert,
  products,
  customCategories,
  onAddCategory,
  cabinClasses
}) => {
  // Configurable Tabs Order
  const [tabs, setTabs] = useState<{id: string, label: string, color: string}[]>([]);
  const [activeTab, setActiveTab] = useState('Dvere'); // Default to first logical
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);

  // Active Categories State (User can toggle which categories to include)
  const [activeCategories, setActiveCategories] = useState<Set<string>>(new Set());

  const [isCategorySettingsOpen, setIsCategorySettingsOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  // Options - DEFAULT OFF
  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);

  // Memory Option
  const [rememberManual, setRememberManual] = useState(true);

  // Drag State
  const [draggedItemIdx, setDraggedItemIdx] = useState<number | null>(null);

  // Initialize Active Categories on Open
  useEffect(() => {
      if(isOpen && customCategories.length > 0) {
          // Default all to active if empty (first run)
          if(activeCategories.size === 0) {
              setActiveCategories(new Set(customCategories));
          }
      }
  }, [isOpen, customCategories]);

  // Sync Tabs with Active Categories
  useEffect(() => {
    // Generate tabs from customCategories (which contains MASTER + Custom)
    const generatedTabs = customCategories
        .filter(cat => {
            // Special Logic: 'Oceľová konštrukcia' is only visible if configured
            if (cat === 'Oceľová konštrukcia' && !layout.hasExternalShaft) return false;
            // Always exclude 'addons' from tabs list, handled in footer
            if (['Montáž', 'Doprava', 'Balné'].includes(cat)) return false;
            // Only show if active
            return activeCategories.has(cat);
        })
        .map(cat => ({
            id: cat,
            label: cat,
            color: 'blue' // Default color
        }));

    setTabs(generatedTabs);

    // If active tab is gone, switch to first available
    if (!generatedTabs.find(t => t.id === activeTab)) {
        if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);
    }
  }, [customCategories, activeCategories, layout.hasExternalShaft, activeTab]);

  // --- HELPER FUNCTIONS ---

  // UPDATED: Added Subcategory Filter Logic
  const findStockItem = (keywords: string[], category?: string, subcategory?: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      return products.find(p => {
          const matchName = lowerKeys.every(k => p.name.toLowerCase().includes(k));
          const matchCat = category ? p.category === category : true;
          const matchSub = subcategory ? p.subcategory === subcategory : true;
          return matchName && matchCat && matchSub;
      });
  };

  const findMatchProps = (keys: string[], category?: string, subcategory?: string) => {
      const p = findStockItem(keys, category, subcategory);
      return { productId: p?.id, price: p?.price };
  };

  useEffect(() => {
    if (isOpen) {
        calculateBOM();
    }
  }, [isOpen, layout]);

  const calculateBOM = () => {
    const items: MaterialWizardData['items'] = [];

    const travel = layout.travelHeight || 0;
    const totalHeight = travel + (layout.headroomHeight || 0) + (layout.pitDepth || 0);
    const cwtPos = layout.counterWeightPosition || 'left';
    const railLength = layout.guideRailLength || 5000;
    const railLengthLabel = railLength === 2500 ? '(2.5m)' : '(5m)';

    // --- MAP INTERNAL LOGIC TO CATEGORY NAMES ---
    // This allows us to put calculated items into the correct dynamic category
    const catMap = {
        guides: 'Vodítka a kotvenie',
        doors: 'Dvere',
        cabin: 'Kabína a rám',
        drive: 'Pohon',
        electro: 'Elektro',
        shaftInt: 'Ostatné šachta', // Internals
        construction: 'Oceľová konštrukcia' // Steel Structure
    };

    // --- GUIDES ---
    // Use configured rail length for calculation
    const railsPerLine = Math.ceil(Math.max(0, totalHeight) / railLength) || 1;

    const carRails = railsPerLine * 2;
    const cwtRails = railsPerLine * 2;
    const carFish = Math.max(0, railsPerLine - 1) * 2;
    const cwtFish = Math.max(0, railsPerLine - 1) * 2;

    // Brackets Logic
    const bracketRows = 1 + Math.ceil(Math.max(0, totalHeight - 500) / 2800);
    let mainBrackets = 0, busBrackets = 0, cwtBrackets = 0;

    const isCombined = layout.bracketType === 'combined';

    if (isCombined && (cwtPos === 'left' || cwtPos === 'right')) {
        busBrackets = bracketRows; // 1 per row (Combined BUS console)
        mainBrackets = bracketRows; // 1 per row (Other side)
        cwtBrackets = 0; // BUS console handles CWT
    } else {
        mainBrackets = bracketRows * 2; 
        cwtBrackets = bracketRows;
        busBrackets = 0;
    }

    // Clips Logic
    const isBigCarRail = ['T89', 'T90', 'T125', 'T127'].includes(layout.guideTypeCar || '');
    const isBigCwtRail = ['T89', 'T90', 'T125', 'T127'].includes(layout.guideTypeCwt || '');

    const clipsT2 = (isBigCarRail ? (busBrackets*2 + mainBrackets*2) : 0) + (isBigCwtRail ? (cwtBrackets*2) : 0);
    const clipsT1 = (!isBigCarRail ? (busBrackets*2 + mainBrackets*2) : 0) + (!isBigCwtRail ? (cwtBrackets*2) : 0);

    // --- GENERATE BOM ITEMS (MARKED AS AUTO) ---
    const addAutoItem = (item: any) => items.push({ ...item, isAuto: true });

    // 1. Guides
    const pCarRail = findStockItem([layout.guideTypeCar || 'T90'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Vodidlá Kabína ${layout.guideTypeCar} ${railLengthLabel}`, quantity: carRails, unit: 'ks', productId: pCarRail?.id, price: pCarRail?.price });

    const pCwtRail = findStockItem([layout.guideTypeCwt || 'T50'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Vodidlá Protiváha ${layout.guideTypeCwt} ${railLengthLabel}`, quantity: cwtRails, unit: 'ks', productId: pCwtRail?.id, price: pCwtRail?.price });

    const pCarFish = findStockItem(['spojka', layout.guideTypeCar || 'T90'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Spojka ${layout.guideTypeCar}`, quantity: carFish, unit: 'ks', productId: pCarFish?.id, price: pCarFish?.price });
    const pCwtFish = findStockItem(['spojka', layout.guideTypeCwt || 'T50'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Spojka ${layout.guideTypeCwt}`, quantity: cwtFish, unit: 'ks', productId: pCwtFish?.id, price: pCwtFish?.price });

    if (mainBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola Hlavná', quantity: mainBrackets, unit: 'ks', ...findMatchProps(['konzola', 'hlavná'], catMap.guides) });
    if (busBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola BUS (Kombinovaná)', quantity: busBrackets, unit: 'ks', ...findMatchProps(['konzola', 'bus'], catMap.guides) });
    if (cwtBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola Protiváhová', quantity: cwtBrackets, unit: 'ks', ...findMatchProps(['konzola', 'protiváh'], catMap.guides) });

    if (clipsT2 > 0) addAutoItem({ category: catMap.guides, description: 'Príchytky T2 (Veľké)', quantity: clipsT2, unit: 'ks', ...findMatchProps(['príchytka', 't2'], catMap.guides) });
    if (clipsT1 > 0) addAutoItem({ category: catMap.guides, description: 'Príchytky T1 (Malé)', quantity: clipsT1, unit: 'ks', ...findMatchProps(['príchytka', 't1'], catMap.guides) });

    // 2. Doors (UPDATED WITH SUBCATEGORY)
    const shaftDoorTxt = layout.doorOperation === 'manual' ? 'Manuálne' : 'Automatické';
    const cabinDoorTxt = layout.doorType === 'bus' ? 'BUS' : 'Automatické';

    if (layout.numberOfStops) {
        addAutoItem({ 
            category: catMap.doors, 
            description: `Šachtové dvere ${shaftDoorTxt} ${layout.doorWidth}mm`, 
            quantity: layout.numberOfStops, 
            unit: 'ks', 
            ...findMatchProps([shaftDoorTxt === 'Manuálne' ? 'krídlové' : 'automatické'], catMap.doors, 'Šachtové') 
        });
    }
    addAutoItem({ 
        category: catMap.doors, 
        description: `Kabínové dvere ${cabinDoorTxt} ${layout.doorWidth}mm`, 
        quantity: layout.isThroughCar ? 2 : 1, 
        unit: 'ks', 
        ...findMatchProps([cabinDoorTxt === 'BUS' ? 'bus' : 'automatické'], catMap.doors, 'Kabínové') 
    });

    // 3. Cabin (UPDATED WITH CLASS LINKING)
    // Try to find if the selected class has a linked Set
    let linkedCabinProduct: Product | undefined;
    if (cabinClasses && layout.cabinClass) {
        const selectedClass = cabinClasses.find(c => c.name === layout.cabinClass);
        if (selectedClass?.linkedProductId) {
            linkedCabinProduct = products.find(p => p.id === selectedClass.linkedProductId);
        }
    }

    if (linkedCabinProduct) {
        // Use the linked set
        addAutoItem({ 
            category: catMap.cabin, 
            description: linkedCabinProduct.name, // Use name of the set (e.g., Kabína SKY Set)
            quantity: 1, 
            unit: 'ks', 
            productId: linkedCabinProduct.id, 
            price: linkedCabinProduct.price 
        });
    } else {
        // Fallback to generic search
        addAutoItem({ category: catMap.cabin, description: `Kabína Kompletná (${layout.cabinClass || 'FUN'})`, quantity: 1, unit: 'ks', ...findMatchProps(['kabína'], catMap.cabin) });
    }

    addAutoItem({ category: catMap.cabin, description: 'Rám Kabíny', quantity: 1, unit: 'ks', ...findMatchProps(['rám', String(layout.ratedLoad)], catMap.cabin) });

    // 4. Drive
    const driveKey = layout.tractionMedium === 'ctp' ? 'ctp' : 'lan';
    addAutoItem({ category: catMap.drive, description: 'Trakčný stroj', quantity: 1, unit: 'ks', ...findMatchProps([driveKey, 'stroj'], catMap.drive) });

    const frameKey = layout.machineRoomPosition === 'head' ? 'mrl' : 'rošt';
    addAutoItem({ category: catMap.drive, description: layout.machineRoomPosition === 'head' ? 'Rám pod stroj MRL' : 'Roznášací rošt', quantity: 1, unit: 'ks', ...findMatchProps(['rám', frameKey], catMap.drive) });

    if (layout.suspensionType === '1:1') {
        addAutoItem({ category: catMap.drive, description: 'Odkláňacie kladky', quantity: 2, unit: 'ks', ...findMatchProps(['kladk'], catMap.drive) });
    }

    // 5. Electro
    addAutoItem({ category: catMap.electro, description: 'Rozvádzač a riadenie', quantity: 1, unit: 'ks', ...findMatchProps(['rozvádzač'], catMap.electro) });
    addAutoItem({ category: catMap.electro, description: 'Revízna jazda', quantity: 1, unit: 'ks', ...findMatchProps(['revízna'], catMap.electro) });
    addAutoItem({ category: catMap.electro, description: 'Privolávače a kabeláž', quantity: 1, unit: 'kpl', ...findMatchProps(['kabeláž'], catMap.electro) });

    // 6. Shaft
    addAutoItem({ category: catMap.shaftInt, description: 'Osvetlenie šachty', quantity: 1, unit: 'kpl', ...findMatchProps(['osvetlenie'], catMap.shaftInt) });
    addAutoItem({ category: catMap.shaftInt, description: 'Rebrík do priehlbeňe', quantity: 1, unit: 'ks', ...findMatchProps(['rebrík'], catMap.shaftInt) });

    // 7. Structure (Only if configured)
    if (layout.hasExternalShaft) {
        addAutoItem({ category: catMap.construction, description: 'Oceľové profily (Konštrukcia)', quantity: 1, unit: 'kpl', ...findMatchProps(['profil', 'oceľ'], catMap.construction) });
        addAutoItem({ category: catMap.construction, description: 'Opláštenie (Sklo/Sádrokartón)', quantity: 45, unit: 'm2', ...findMatchProps(['opláštenie', 'sklo'], catMap.construction) });
    }

    // --- LOAD SAVED MANUAL ITEMS ---
    if (rememberManual) {
        try {
            const savedManualItemsStr = localStorage.getItem('smartquote_manual_items');
            if (savedManualItemsStr) {
                const savedManualItems: MaterialWizardData['items'] = JSON.parse(savedManualItemsStr);
                // Validate saved items (ensure category is still valid?) - we just append
                savedManualItems.forEach(manualItem => {
                    // Update price if product ID exists (in case price changed in DB)
                    if (manualItem.productId) {
                        const p = products.find(prod => prod.id === manualItem.productId);
                        if(p) manualItem.price = p.price;
                    }
                    items.push({ ...manualItem, isAuto: false });
                });
            }
        } catch (e) {
            console.error("Failed to load saved manual items", e);
        }
    }

    setBomItems(items);
  };

  const moveTab = (index: number, direction: 'left' | 'right') => {
      if (direction === 'left' && index === 0) return;
      if (direction === 'right' && index === tabs.length - 1) return;

      const newTabs = [...tabs];
      const targetIndex = direction === 'left' ? index - 1 : index + 1;
      [newTabs[index], newTabs[targetIndex]] = [newTabs[targetIndex], newTabs[index]];
      setTabs(newTabs);
  };

  const toggleCategory = (catId: string) => {
      const newSet = new Set(activeCategories);
      if (newSet.has(catId)) {
          newSet.delete(catId);
      } else {
          newSet.add(catId);
      }
      setActiveCategories(newSet);
  };

  const handleAddCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setNewCatName('');
          toggleCategory(newCatName); // Auto activate
      }
  };

  const updateItem = (idx: number, field: string, value: any) => {
      const newItems = [...bomItems];
      // @ts-ignore
      newItems[idx][field] = value;
      if (field === 'productId') {
          const p = products.find(prod => prod.id === value);
          if (p) {
              newItems[idx].price = p.price;
              newItems[idx].description = p.name;
              newItems[idx].unit = p.unit;
          }
      }
      setBomItems(newItems);
  };

  const handleDeleteItem = (index: number) => {
      const newItems = bomItems.filter((_, i) => i !== index);
      setBomItems(newItems);
  };

  const addCustomItem = (isSet: boolean = false) => {
      const cat = activeTab;
      setBomItems([
          ...bomItems, 
          { 
              category: cat, 
              description: isSet ? 'Výber SETU...' : 'Nová požiadavka', 
              quantity: 1, 
              unit: isSet ? 'set' : 'ks', 
              price: 0,
              isAuto: false // Marked as Manual
          }
      ]);
  };

  const handleInsert = () => {
      // SAVE MANUAL ITEMS TO LOCALSTORAGE
      if (rememberManual) {
          const manualItems = bomItems.filter(item => !item.isAuto);
          localStorage.setItem('smartquote_manual_items', JSON.stringify(manualItems));
      } else {
          localStorage.removeItem('smartquote_manual_items');
      }

      // Pass categoryOrder as the list of ACTIVE tabs only
      onInsert({
          items: bomItems,
          includeTransport: includeTransport,
          includePackaging: includePackaging,
          includeAssembly: includeAssembly,
          categoryOrder: tabs.map(t => t.id)
      });
      onClose();
  };

  // DRAG AND DROP FOR BOM ITEMS
  const onDragStartItem = (e: React.DragEvent, index: number) => {
      setDraggedItemIdx(index);
      e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOverItem = (e: React.DragEvent, targetIndex: number) => {
      e.preventDefault();
      if (draggedItemIdx === null || draggedItemIdx === targetIndex) return;

      const newItems = [...bomItems];
      const [reorderedItem] = newItems.splice(draggedItemIdx, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      setBomItems(newItems);
      setDraggedItemIdx(targetIndex);
  };

  if (!isOpen) return null;

  // Items for active tab
  const currentCatName = activeTab;
  const currentItems = bomItems.map((item, index) => ({ item, index })).filter(({ item }) => item.category === currentCatName);

  // Products for dropdown - Filter by active category AND SUBCATEGORY IF DOOR
  const currentAvailableProducts = products.filter(p => {
      if (p.category !== currentCatName) return false;
      // Filter Logic for Doors:
      if (currentCatName === 'Dvere') {
          // Can't easily filter the dropdown PER row if they are different types of doors (shaft/cabin)
          // But we can enable all doors in dropdown.
          return true;
      }
      return true;
  });

  // CABIN AREA CALCULATION
  const cabinArea = ((layout.cabinWidth || 0) * (layout.cabinDepth || 0) / 1000000).toFixed(2);
  const cabinPerimeter = 2 * ((layout.cabinWidth || 0) + (layout.cabinDepth || 0)) / 1000;
  const cabinWallArea = (cabinPerimeter * 2.04).toFixed(2); // 2040mm height (Fundermax)

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Calculator className="text-orange-500" />
            <div>
                <h2 className="text-xl font-bold text-gray-800">Materiálový Sprievodca</h2>
                <div className="text-xs text-gray-500">Nákupný zoznam komponentov</div>
            </div>
          </div>

          {/* CABIN AREA DASHBOARD */}
          <div className="hidden md:flex gap-4 items-center bg-white border px-3 py-1 rounded shadow-sm">
              <div className="flex items-center gap-2 text-sm text-gray-600 border-r pr-3">
                  <ScanLine size={16} className="text-blue-500"/>
                  Podlaha: <span className="font-bold text-black">{cabinArea} m²</span>
              </div>
              <div className="flex items-center gap-2 text-sm text-gray-600">
                  <Gauge size={16} className="text-purple-500"/>
                  Steny (2040mm): <span className="font-bold text-black">{cabinWallArea} m²</span>
              </div>
          </div>

          <div className="flex gap-2">
               <button onClick={() => setIsCategorySettingsOpen(!isCategorySettingsOpen)} className={`p-2 rounded-full border transition ${isCategorySettingsOpen ? 'bg-blue-100 text-blue-600 border-blue-300' : 'text-gray-500 hover:bg-gray-100'}`} title="Správa Kategórií">
                    <Filter size={20}/>
               </button>
               <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
          </div>
        </div>

        {/* Category Settings Popover */}
        {isCategorySettingsOpen && (
            <div className="bg-gray-50 border-b p-4 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4 shadow-inner max-h-48 overflow-y-auto">
                <div className="col-span-full text-xs font-bold text-gray-500 uppercase">Vyberte kategórie, ktoré chcete riešiť (Vypnuté sa vymažú):</div>
                {customCategories.filter(c => !['Montáž','Doprava','Balné'].includes(c)).map(c => (
                    <label key={c} className="flex items-center gap-2 cursor-pointer bg-white border p-2 rounded shadow-sm hover:bg-blue-50">
                        <input type="checkbox" checked={activeCategories.has(c)} onChange={() => toggleCategory(c)} className="rounded text-blue-600"/>
                        <span className="text-sm font-medium break-all">{c}</span>
                    </label>
                ))}

                {/* Add Custom Category Input */}
                <div className="col-span-full flex gap-2 pt-2 border-t mt-2">
                    <input className="border rounded px-2 py-1 text-sm w-48" placeholder="Nová kategória..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleAddCategory()}/>
                    <button onClick={handleAddCategory} className="px-3 py-1 bg-blue-600 text-white rounded text-xs font-bold">Pridať</button>
                </div>
            </div>
        )}

        {/* Tabs with Reordering */}
        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-2 py-2 transition ${activeTab===tab.id ? 'bg-white border-gray-300' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`}>
                     {activeTab === tab.id && idx > 0 && <button onClick={() => moveTab(idx, 'left')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowLeft size={12}/></button>}

                     <button 
                        onClick={() => setActiveTab(tab.id)} 
                        className={`mx-2 text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? `text-${tab.color}-600` : 'text-gray-500'}`}
                     >
                         {tab.label}
                     </button>

                     {activeTab === tab.id && idx < tabs.length - 1 && <button onClick={() => moveTab(idx, 'right')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowRight size={12}/></button>}
                 </div>
            ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">
            {currentItems.length === 0 && <div className="text-center text-gray-400 italic py-8">Žiadne položky v tejto kategórii.<br/>Kliknite na tlačidlá nižšie pre pridanie.</div>}

            {currentItems.length > 0 && (
            <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                        <tr>
                            <th className="w-8"></th>
                            <th className="p-3 text-left w-1/3">Požiadavka (Výpočet)</th>
                            <th className="p-3 text-left w-1/3">Produkt zo Skladu / SET</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {currentItems.map(({ item, index: originalIndex }) => {
                            // Filter logic for specific row dropdown
                            let rowProducts = currentAvailableProducts;
                            if (currentCatName === 'Dvere') {
                                // Smart filtering based on item description content
                                if (item.description.includes('Šachtové')) {
                                    rowProducts = currentAvailableProducts.filter(p => !p.subcategory || p.subcategory === 'Šachtové');
                                } else if (item.description.includes('Kabínové')) {
                                    rowProducts = currentAvailableProducts.filter(p => !p.subcategory || p.subcategory === 'Kabínové');
                                }
                            }

                            return (
                                <tr 
                                    key={originalIndex} 
                                    draggable
                                    onDragStart={(e) => onDragStartItem(e, originalIndex)}
                                    onDragOver={(e) => onDragOverItem(e, originalIndex)}
                                    className={`transition ${item.isAuto ? 'hover:bg-blue-50' : 'bg-yellow-50 hover:bg-yellow-100'}`}
                                >
                                    <td className="p-2 text-center text-gray-300 cursor-grab hover:text-gray-500">
                                        <GripVertical size={16}/>
                                    </td>
                                    <td className="p-3 relative">
                                        <input 
                                            value={item.description} 
                                            onChange={e => updateItem(originalIndex, 'description', e.target.value)}
                                            className="w-full bg-transparent font-medium text-gray-800 focus:outline-none"
                                        />
                                        {!item.isAuto && <span className="text-[9px] font-bold text-yellow-600 uppercase absolute top-1 right-2 bg-yellow-100 px-1 rounded">Manual</span>}
                                    </td>
                                    <td className="p-3">
                                        <div className="relative">
                                            <select 
                                                value={item.productId || ''} 
                                                onChange={e => updateItem(originalIndex, 'productId', e.target.value)}
                                                className={`w-full p-2 border rounded text-sm font-bold ${item.productId ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-400 border-gray-200'}`}
                                            >
                                                <option value="">-- Vybrať --</option>
                                                {rowProducts.sort((a,b) => (a.type === 'composite' ? -1 : 1)).map(p => (
                                                    <option key={p.id} value={p.id}>
                                                        {p.type === 'composite' ? '📦 [SET] ' : ''}{p.name} ({p.price}€)
                                                    </option>
                                                ))}
                                            </select>
                                            {!item.productId && (
                                                <div title="Položka nie je spárovaná so skladom" className="absolute right-8 top-1/2 -translate-y-1/2 text-orange-400 pointer-events-none">
                                                    <AlertTriangle size={14} />
                                                </div>
                                            )}
                                        </div>
                                    </td>
                                    <td className="p-3 text-right">
                                        <input 
                                            type="number" 
                                            value={item.quantity} 
                                            onChange={e => updateItem(originalIndex, 'quantity', +e.target.value)}
                                            className="w-full text-right font-bold text-blue-600 bg-transparent focus:outline-none text-base"
                                        />
                                    </td>
                                    <td className="p-3 text-right font-mono text-gray-600">
                                        {item.price ? item.price.toFixed(2) : '-'} €
                                    </td>
                                    <td className="p-3 text-center">
                                        <button 
                                            onClick={() => handleDeleteItem(originalIndex)}
                                            className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition"
                                            title="Vymazať položku"
                                        >
                                            <Trash2 size={16}/>
                                        </button>
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            )}

            <div className="flex gap-2">
                <button 
                    onClick={() => addCustomItem(false)}
                    className="flex-1 py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-600 hover:bg-blue-50 transition flex justify-center items-center gap-2 font-medium"
                >
                    <Plus size={18} /> Pridať vlastnú požiadavku
                </button>
                <button 
                    onClick={() => addCustomItem(true)}
                    className="flex-1 py-3 border-2 border-dashed border-purple-300 rounded-lg text-purple-600 hover:border-purple-500 hover:bg-purple-50 transition flex justify-center items-center gap-2 font-bold bg-purple-50/50"
                >
                    <Layers size={18} /> + Pridať SET
                </button>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">

            {/* Addons Checkboxes - DEFAULT OFF */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 bg-blue-50 p-3 rounded border border-blue-100">
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Hammer size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Montáž technológie</span>
                 </label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Truck size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Doprava materiálu</span>
                 </label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Package size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Balné a manipulácia</span>
                 </label>
            </div>

            <div className="flex justify-between items-center">
                <div className="text-xs text-gray-500 flex items-center gap-4">
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-yellow-50 px-3 py-1 rounded">
                        <input type="checkbox" checked={rememberManual} onChange={e => setRememberManual(e.target.checked)} className="rounded text-yellow-600"/>
                        <span className="font-bold text-yellow-800 text-xs">💾 Zapamätať manuálne položky pre ďalšie ponuky</span>
                    </label>
                </div>
                <div className="flex gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium transition">
                        Zrušiť
                    </button>
                    <button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold flex items-center gap-2 shadow-sm transition">
                        <Check size={18} /> Potvrdiť a Vložiť
                    </button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

