                                    value={activeSubcategory}
                                    onChange={(e) => setActiveSubcategory(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                                >
                                    <option value="ALL">Všetky Podkategórie</option>
                                    {availableSubcategories.map(s => <option key={s} value={s}>{s}</option>)}
                                </select>
                             </div>
                        )}

                        {/* ADD SUBCATEGORY BUTTON */}
                        <div className="relative">
                            {isAddingSubcat ? (
                                <div className="flex items-center gap-1 bg-white border rounded-xl px-2 py-1 shadow h-full">
                                    <input 
                                        autoFocus
                                        className="w-32 text-sm outline-none bg-transparent py-2"
                                        placeholder="Názov..." 
                                        value={newSubcatName} 
                                        onChange={e=>setNewSubcatName(e.target.value)} 
                                        onKeyDown={e=>e.key==='Enter'&&handleCreateSubcategory()} 
                                    />
                                    <button onClick={handleCreateSubcategory} className="text-green-600 hover:bg-green-100 rounded-full p-1"><Plus size={16}/></button>
                                    <button onClick={()=>setIsAddingSubcat(false)} className="text-red-500 hover:bg-red-100 rounded-full p-1"><X size={16}/></button>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setIsAddingSubcat(true)} 
                                    className="h-full px-3 bg-white border border-dashed border-gray-300 rounded-xl hover:border-blue-400 text-gray-500 hover:text-blue-600 flex items-center justify-center"
                                    title="Vytvoriť novú podkategóriu"
                                >
                                    <FolderTree size={20} /> <Plus size={14} className="ml-1"/>
                                </button>
                            )}
                        </div>

                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                            <input 
                            type="text"
                            placeholder={`Hľadať v kategórii ${activeCategory}...`}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm text-base"
                            />
                        </div>
                        {/* Supplier Filter */}
                        <div className="relative w-56">
                            <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                            <select 
                                value={supplierFilter}
                                onChange={(e) => setSupplierFilter(e.target.value)}
                                className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                            >
                                <option value="">Všetci Dodávatelia</option>
                                {uniqueSuppliers.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <button onClick={handleNewClick} className={`px-6 py-3 text-white rounded-xl font-bold flex items-center gap-2 shadow-md transition transform hover:scale-105 ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                            <Plus size={20}/> Nový {mode === 'stock' ? 'Diel' : 'SET'}
                        </button>
                    </div>

                    {/* BATCH ACTIONS BAR */}
                    {selectedIds.size > 0 && (
                        <div className="bg-blue-50 border border-blue-200 p-3 rounded-xl mb-4 flex items-center justify-between animate-in slide-in-from-top-2">
                            <div className="flex items-center gap-3">
                                <span className="bg-blue-600 text-white text-xs font-bold px-2 py-1 rounded-full">{selectedIds.size}</span>
                                <span className="text-sm text-blue-900 font-bold">Vybrané položky</span>
                                <button onClick={() => setSelectedIds(new Set())} className="text-xs text-blue-500 hover:underline">Zrušiť výber</button>
                            </div>

                            <div className="flex gap-2">
                                {isBulkMoveMode ? (
                                    <div className="flex items-center gap-2 bg-white rounded-lg p-1 border">
                                        <span className="text-xs font-bold text-gray-500 ml-2">Presunúť do:</span>
                                        {availableSubcategories.length > 0 && (
                                            <select 
                                                className="text-sm border rounded p-1"
                                                onChange={(e) => { if(e.target.value) handleBulkMove(activeCategory, e.target.value) }}
                                                defaultValue=""
                                            >
                                                <option value="" disabled>Vybrať Podkategóriu...</option>
                                                {availableSubcategories.map(s => <option key={s} value={s}>{s}</option>)}
                                            </select>
                                        )}
                                        <select 
                                            className="text-sm border rounded p-1 font-bold text-blue-700"
                                            onChange={(e) => { if(e.target.value) handleBulkMove(e.target.value) }}
                                            defaultValue=""
                                        >
                                            <option value="" disabled>Vybrať Kategóriu...</option>
                                            {allCategories.filter(c => c !== activeCategory).map(c => <option key={c} value={c}>{c}</option>)}
                                        </select>
                                        <button onClick={() => setIsBulkMoveMode(false)} className="p-1 hover:bg-gray-100 rounded"><X size={16}/></button>
                                    </div>
                                ) : (
                                    <button onClick={() => setIsBulkMoveMode(true)} className="px-3 py-1.5 bg-white border border-blue-200 text-blue-700 font-bold rounded text-sm hover:bg-blue-100 flex items-center gap-2">
                                        <CornerDownRight size={16}/> Presunúť
                                    </button>
                                )}
                                <button onClick={() => {
                                    if(confirm(`Naozaj vymazať ${selectedIds.size} položiek?`)) {
                                        selectedIds.forEach(id => onDeleteProduct(id));
                                        setSelectedIds(new Set());
                                    }
                                }} className="px-3 py-1.5 bg-white border border-red-200 text-red-600 font-bold rounded text-sm hover:bg-red-50 flex items-center gap-2">
                                    <Trash2 size={16}/> Vymazať
                                </button>
                            </div>
                        </div>
                    )}

                    {/* PRODUCTS TABLE HEADER (Fake) */}
                    <div className="flex items-center px-5 pb-2 text-xs font-bold text-gray-400 uppercase">
                        <div className="w-8 flex justify-center cursor-pointer" onClick={toggleSelectAll}>
                            {selectedIds.size > 0 && selectedIds.size === filteredProducts.length ? <CheckSquare size={16} className="text-blue-600"/> : <Square size={16}/>}
                        </div>
                        <div className="flex-1">Názov</div>
                        <div className="w-32">Výrobca/Dodávateľ</div>
                        <div className="w-24 text-right">Cena</div>
                        <div className="w-24 text-center">Akcie</div>
                    </div>

                    <div className="space-y-2">
                        {filteredProducts.length === 0 && <div className="text-center py-20 text-gray-400 italic text-lg">Žiadne položky.<br/><span className="text-sm">Začnite pridaním nového {mode === 'stock' ? 'dielu' : 'setu'}.</span></div>}

                        {filteredProducts.map(product => (
                            <div 
                                key={product.id} 
                                draggable
                                onDragStart={(e) => handleDragStart(e, product.id)}
                                className={`bg-white p-3 rounded-xl border shadow-sm flex items-center group transition-all cursor-default ${mode === 'sets' ? 'hover:border-purple-300' : 'hover:border-blue-300 border-gray-200'} ${selectedIds.has(product.id) ? 'ring-2 ring-blue-500 bg-blue-50' : ''}`}
                            >
                                <div 
                                    className="w-8 flex justify-center text-gray-400 hover:text-blue-600 cursor-pointer"
                                    onClick={() => toggleSelection(product.id)}
                                >
                                    {selectedIds.has(product.id) ? <CheckSquare size={18} className="text-blue-600"/> : <Square size={18}/>}
                                </div>

                                <div className="flex-1 pr-4">
                                    <div className="font-bold text-gray-800 flex items-center gap-3 text-lg">
                                        <GripVertical size={16} className="text-gray-300 cursor-grab active:cursor-grabbing"/>
                                        {product.name}
                                        {product.type === 'composite' && (
                                            <span className="text-[10px] bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full border border-purple-200 flex items-center gap-1 uppercase tracking-wider font-bold">
                                                <Layers size={10}/> SET
                                            </span>
                                        )}
                                        {product.subcategory && (
                                             <span className="text-[10px] bg-gray-100 text-gray-600 px-2 py-0.5 rounded border border-gray-200 font-bold">
                                                 {product.subcategory}
                                             </span>
                                        )}
                                    </div>
                                </div>

                                <div className="w-32 text-xs text-gray-500 flex flex-col gap-1">
                                    {product.manufacturer && <span className="flex items-center gap-1"><Factory size={10}/> {product.manufacturer}</span>}
                                    {product.supplier && <span className="flex items-center gap-1 text-blue-600"><Building size={10}/> {product.supplier}</span>}
                                </div>

                                <div className="w-24 text-right">
                                    <div className="font-mono text-black font-bold text-base">{product.price.toFixed(2)} €</div>
                                    <div className="text-[10px] text-gray-400">/ {product.unit}</div>
                                </div>

                                <div className="w-24 flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={() => handleEditClick(product)} className="p-2 bg-gray-100 hover:bg-blue-50 text-blue-600 rounded-lg transition" title="Upraviť"><Settings size={18}/></button>
                                    <button onClick={() => onDeleteProduct(product.id)} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition" title="Vymazať"><Trash2 size={18}/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

