                            type="text"
                            placeholder={`Hľadať v kategórii ${activeCategory}...`}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm text-base"
                            />
                        </div>
                        {/* Supplier Filter */}
                        <div className="relative w-56">
                            <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                            <select 
                                value={supplierFilter}
                                onChange={(e) => setSupplierFilter(e.target.value)}
                                className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                            >
                                <option value="">Všetci Dodávatelia</option>
                                {uniqueSuppliers.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <button onClick={handleNewClick} className={`px-6 py-3 text-white rounded-xl font-bold flex items-center gap-2 shadow-md transition transform hover:scale-105 ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                            <Plus size={20}/> Nový {mode === 'stock' ? 'Diel' : 'SET'}
                        </button>
                    </div>

                    {/* BATCH ACTIONS BAR */}
                    {selectedIds.size > 0 && (
                        <div className="bg-blue-50 border border-blue-200 p-3 rounded-xl mb-4 flex items-center justify-between animate-in slide-in-from-top-2 sticky top-0 z-10 shadow-lg">
                            <div className="flex items-center gap-3">
                                <span className="bg-blue-600 text-white text-xs font-bold px-2 py-1 rounded-full">{selectedIds.size}</span>
                                <span className="text-sm text-blue-900 font-bold">Vybrané položky</span>
                                <button onClick={() => setSelectedIds(new Set())} className="text-xs text-blue-500 hover:underline">Zrušiť výber</button>
                            </div>

                            <div className="flex gap-2">
                                {isBulkMoveMode ? (
                                    <div className="flex items-center gap-2 bg-white rounded-lg p-1 border">
