                            {/* SECTION 2: PRICING & UNIT */}
                            <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-lg border border-gray-200">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Jednotka</label>
                                    <select value={unit} onChange={e => setUnit(e.target.value)} className="w-full p-2 border rounded bg-white font-bold text-sm">
                                        <option value="ks">ks</option><option value="m">m</option><option value="kpl">kpl</option><option value="hod">hod</option>
                                        <option value="set">set</option>
                                    </select>
                                </div>
                                <div>
                                    <div className="flex justify-between mb-1">
                                        <label className="block text-xs font-bold text-gray-500 uppercase">Nákupná Cena (€)</label>
                                        {mode === 'sets' && (
                                            <div className="flex gap-1">
                                                <button onClick={() => setPriceType('calculated')} className={`px-2 py-0.5 rounded text-[10px] font-bold ${priceType === 'calculated' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-500'}`}>Auto</button>
                                                <button onClick={() => setPriceType('fixed')} className={`px-2 py-0.5 rounded text-[10px] font-bold ${priceType === 'fixed' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-500'}`}>Manuál</button>
                                            </div>
                                        )}
                                    </div>
                                    <input 
                                        type="number" 
                                        value={mode === 'sets' && priceType === 'calculated' ? subProducts.reduce((acc, i) => acc + (getProductPrice(i.productId)*i.quantity), 0).toFixed(2) : price} 
                                        onChange={e => setPrice(e.target.value)} 
                                        className={`w-full p-2 border rounded font-bold text-right text-xl ${mode === 'sets' && priceType === 'calculated' ? 'bg-gray-200 text-gray-500' : 'bg-white text-black'}`}
                                        disabled={mode === 'sets' && priceType === 'calculated'}
                                        placeholder="0.00"
                                    />
                                </div>
                            </div>

                            {/* SECTION 3: DETAILS */}
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Výrobca (Značka)</label>
                                    <div className="relative">
                                        <Factory className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14}/>
                                        <input value={manufacturer} onChange={e => setManufacturer(e.target.value)} className="w-full pl-9 p-2 border rounded text-sm" placeholder="Voliteľné..." />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Dodávateľ</label>
                                    <div className="relative">
                                        <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14}/>
                                        <input value={supplier} onChange={e => setSupplier(e.target.value)} className="w-full pl-9 p-2 border rounded text-sm" placeholder="Voliteľné..." />
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* COMPOSITE EDITOR (SET BUILDER) */}
                        {mode === 'sets' && (
                            <div className="border-t pt-6 mt-6 bg-purple-50/50 -mx-8 px-8 pb-6">
                                <div className="flex justify-between items-center mb-4">
                                    <h4 className="font-bold text-purple-800 flex items-center gap-2 text-lg"><Layers size={24}/> Obsah SETU</h4>

                                    {/* DISPLAY MODE TOGGLE */}
                                    <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-purple-200 shadow-sm">
                                        <span className="text-xs font-bold text-gray-500 uppercase">V ponuke zobraziť:</span>
                                        <button 
                                            onClick={() => setDisplayMode('itemized')} 
                                            className={`px-2 py-1 rounded text-xs font-bold flex items-center gap-1 ${displayMode === 'itemized' ? 'bg-purple-600 text-white' : 'hover:bg-gray-100 text-gray-600'}`}
                                            title="Rozpísať v ponuke všetky komponenty pod seba"
                                        >
                                            <Eye size={12}/> Rozpísať položky
                                        </button>
                                        <button 
                                            onClick={() => setDisplayMode('single_line')} 
                                            className={`px-2 py-1 rounded text-xs font-bold flex items-center gap-1 ${displayMode === 'single_line' ? 'bg-purple-600 text-white' : 'hover:bg-gray-100 text-gray-600'}`}
                                            title="V ponuke bude len jeden riadok (Názov Setu), komponenty sú skryté"
                                        >
                                            <EyeOff size={12}/> Len názov setu
                                        </button>
                                    </div>
                                </div>

                                <div className="text-sm text-gray-500 mb-4">
                                    Vyskladajte tento SET z položiek, ktoré už máte na Sklade.
                                </div>

                                {/* Current Components List */}
                                <div className="bg-white rounded-lg p-4 mb-4 space-y-2 border border-purple-100 min-h-[120px]">
                                    {subProducts.length === 0 && <div className="text-sm text-gray-400 italic text-center py-8">Zatiaľ prázdny set. {priceType==='fixed' ? 'Pri fixnej cene nie sú komponenty povinné.' : 'Pridajte diely zo skladu nižšie.'}</div>}
                                    {subProducts.map((sp, idx) => (
                                        <div key={idx} className="flex justify-between items-center bg-purple-50 p-3 rounded shadow-sm border border-purple-100">
                                            <div className="flex-1">
                                                <div className="text-base font-bold text-gray-800">{getProductName(sp.productId)}</div>
                                            </div>
                                            <div className="flex items-center gap-4">
                                                <span className="text-sm text-gray-500 font-mono">{getProductPrice(sp.productId).toFixed(2)} €/ks</span>
                                                <div className="flex items-center border rounded bg-white">
                                                    <span className="text-xs px-2 text-gray-500 font-bold">x</span>
                                                    <input 
                                                        type="number" 
                                                        min="0.01"
                                                        step="0.01" 
                                                        value={sp.quantity} 
                                                        onChange={e => updateComponentQty(sp.productId, +e.target.value)}
                                                        className="w-20 p-2 text-center text-sm font-bold bg-white focus:outline-none text-purple-700"
                                                    />
                                                </div>
                                                <button onClick={() => removeComponent(sp.productId)} className="text-red-400 hover:text-red-600 p-2 hover:bg-red-50 rounded"><Trash2 size={20}/></button>
                                            </div>
                                        </div>
                                    ))}
                                </div>

                                {/* Component Search & Filter */}
                                <div className="bg-white p-4 rounded-lg border border-gray-200">
                                    <div className="text-sm font-bold text-gray-500 mb-2 uppercase flex items-center gap-2"><Search size={16}/> Hľadať v Sklade</div>
                                    <div className="flex gap-4 mb-4 items-center">
                                         <select 
                                            value={componentSourceCategory}
                                            onChange={(e) => setComponentSourceCategory(e.target.value)}
                                            className="text-sm border rounded p-2 bg-gray-50 font-bold text-gray-700 focus:ring-1 focus:ring-blue-500 outline-none flex-1 max-w-[250px]"
                                         >
                                             <option value="ALL">Celý Sklad</option>
                                             {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                         </select>
                                         <input 
                                            placeholder="Názov dielu..." 
                                            className="flex-1 p-2 border rounded text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                            value={componentSearch}
                                            onChange={e => setComponentSearch(e.target.value)}
                                        />
                                    </div>

                                    {/* Search Results */}
                                    <div className="border rounded mt-1 max-h-48 overflow-y-auto bg-gray-50 shadow-inner">
                                        {availableComponents.length === 0 ? (
                                            <div className="p-4 text-center text-sm text-gray-400">
                                                {componentSearch ? 'Nenašli sa žiadne produkty.' : 'Začnite písať pre vyhľadanie dielov...'}
                                            </div>
                                        ) : (
                                            availableComponents.map(p => (
                                                <button key={p.id} onClick={() => { addComponent(p.id); setComponentSearch(''); }} className="w-full text-left p-3 hover:bg-green-50 text-sm flex justify-between border-b last:border-0 items-center transition group">
                                                    <div>
                                                        <div className="font-bold text-gray-800 text-base group-hover:text-green-700">{p.name}</div>
                                                        <div className="flex gap-2 text-xs text-gray-400 uppercase mt-1">
                                                            <span>{p.category}</span>
                                                            {p.subcategory && <span> • {p.subcategory}</span>}
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <span className="font-mono text-sm bg-white px-2 py-1 rounded border shadow-sm">{p.price.toFixed(2)} €</span>
                                                        <Plus size={20} className="text-green-600 bg-green-100 rounded-full p-1"/>
                                                    </div>
                                                </button>
                                            ))
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}

                        <div className="flex justify-end gap-4 mt-8 pt-4 border-t">
                            <button onClick={() => setIsEditing(false)} className="px-6 py-3 text-gray-600 hover:bg-gray-100 rounded-lg font-bold">Zrušiť</button>
                            <button onClick={handleSave} className={`px-8 py-3 text-white font-bold rounded-lg flex items-center gap-2 shadow-lg hover:shadow-xl transition transform hover:scale-[1.02] ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                                <Save size={20}/> {mode === 'stock' ? 'Naskladniť Diel' : 'Uložiť SET'}
                            </button>
                        </div>
                    </div>
                </div>
            ) : (
                /* LIST MODE */
                <div className="flex-1 overflow-y-auto p-6 bg-gray-100">
                     <div className="flex gap-4 mb-6">
                        {/* Subcategory Filter */}
                        {availableSubcategories.length > 0 && (
                             <div className="relative min-w-[200px]">
                                <FolderTree className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                                <select 
                                    value={activeSubcategory}
                                    onChange={(e) => setActiveSubcategory(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                                >
                                    <option value="ALL">Všetky Podkategórie</option>
                                    {availableSubcategories.map(s => <option key={s} value={s}>{s}</option>)}
                                </select>
                             </div>
                        )}

                        <div className="relative flex-1">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                            <input 
                            type="text"
                            placeholder={`Hľadať v kategórii ${activeCategory}...`}
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm text-base"
                            />
                        </div>
                        {/* Supplier Filter */}
                        <div className="relative w-56">
                            <Building className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                            <select 
                                value={supplierFilter}
                                onChange={(e) => setSupplierFilter(e.target.value)}
                                className="w-full pl-10 pr-4 py-3 border rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm font-bold bg-white shadow-sm"
                            >
                                <option value="">Všetci Dodávatelia</option>
                                {uniqueSuppliers.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <button onClick={handleNewClick} className={`px-6 py-3 text-white rounded-xl font-bold flex items-center gap-2 shadow-md transition transform hover:scale-105 ${mode === 'stock' ? 'bg-blue-600 hover:bg-blue-700' : 'bg-purple-600 hover:bg-purple-700'}`}>
                            <Plus size={20}/> Nový {mode === 'stock' ? 'Diel' : 'SET'}
                        </button>
                    </div>

                    {/* BATCH ACTIONS BAR */}
                    {selectedIds.size > 0 && (
                        <div className="bg-blue-50 border border-blue-200 p-3 rounded-xl mb-4 flex items-center justify-between animate-in slide-in-from-top-2 sticky top-0 z-10 shadow-lg">
                            <div className="flex items-center gap-3">
                                <span className="bg-blue-600 text-white text-xs font-bold px-2 py-1 rounded-full">{selectedIds.size}</span>
                                <span className="text-sm text-blue-900 font-bold">Vybrané položky</span>
                                <button onClick={() => setSelectedIds(new Set())} className="text-xs text-blue-500 hover:underline">Zrušiť výber</button>
                            </div>

                            <div className="flex gap-2 items-center">
                                {isBulkMoveMode ? (
                                    <div className="flex items-center gap-2 bg-white rounded-lg p-1 border shadow-sm">
                                        <span className="text-xs font-bold text-gray-500 ml-2">Presunúť do:</span>
                                        {/* Target Category Select */}
                                        <select 
                                            className="text-sm border rounded p-1 font-bold text-blue-700 outline-none"
                                            value={bulkTargetCat}
                                            onChange={(e) => { setBulkTargetCat(e.target.value); setBulkTargetSubcat(''); }}
                                        >
                                            <option value="" disabled>Vybrať Kategóriu...</option>
                                            {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                        </select>

                                        {/* Target Subcategory Input/Select */}
                                        {bulkTargetCat && (
                                            <div className="relative w-40">
                                                <input 
                                                    list="bulk-subcat-options"
                                                    placeholder="Podkategória (Voliteľné)"
                                                    className="w-full text-sm border rounded p-1 px-2 outline-none"
                                                    value={bulkTargetSubcat}
                                                    onChange={e => setBulkTargetSubcat(e.target.value)}
                                                />
                                                <datalist id="bulk-subcat-options">
                                                    {bulkTargetSubcategories.map(s => <option key={s} value={s}/>)}
                                                </datalist>
                                            </div>
                                        )}

                                        <button 
                                            onClick={handleBulkMoveConfirm} 
                                            disabled={!bulkTargetCat}
                                            className="bg-green-500 text-white p-1 rounded hover:bg-green-600 disabled:opacity-50"
                                            title="Potvrdiť presun"
                                        >
                                            <ArrowRightCircle size={18}/>
                                        </button>
                                        <button onClick={() => setIsBulkMoveMode(false)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><X size={18}/></button>
                                    </div>
                                ) : (
                                    <button onClick={() => setIsBulkMoveMode(true)} className="px-3 py-1.5 bg-white border border-blue-200 text-blue-700 font-bold rounded text-sm hover:bg-blue-100 flex items-center gap-2">
                                        <CornerDownRight size={16}/> Presunúť
                                    </button>
                                )}
                                <button onClick={() => {
                                    if(confirm(`Naozaj vymazať ${selectedIds.size} položiek?`)) {
                                        selectedIds.forEach(id => onDeleteProduct(id));
                                        setSelectedIds(new Set());
                                    }
                                }} className="px-3 py-1.5 bg-white border border-red-200 text-red-600 font-bold rounded text-sm hover:bg-red-50 flex items-center gap-2">
                                    <Trash2 size={16}/> Vymazať
                                </button>
                            </div>
                        </div>
                    )}

                    {/* LIST HEADER with Checkbox */}
                    <div className="flex items-center px-5 pb-2 text-xs font-bold text-gray-400 uppercase">
                        <div className="w-8 flex justify-center cursor-pointer" onClick={toggleSelectAll}>
                            {selectedIds.size > 0 && selectedIds.size === filteredProducts.length ? <CheckSquare size={16} className="text-blue-600"/> : <Square size={16}/>}
                        </div>
                        <div className="flex-1">Názov</div>
                        <div className="w-32">Výrobca/Dodávateľ</div>
                        <div className="w-24 text-right">Cena</div>
                        <div className="w-24 text-center">Akcie</div>
                    </div>

                    <div className="space-y-3">
                        {filteredProducts.length === 0 && <div className="text-center py-20 text-gray-400 italic text-lg">Žiadne položky.<br/><span className="text-sm">Začnite pridaním nového {mode === 'stock' ? 'dielu' : 'setu'}.</span></div>}

                        {filteredProducts.map(product => (
                            <div 
                                key={product.id} 
                                className={`bg-white p-3 rounded-xl border shadow-sm flex items-center group transition-all ${mode === 'sets' ? 'hover:border-purple-300' : 'hover:border-blue-300 border-gray-200'} ${selectedIds.has(product.id) ? 'ring-2 ring-blue-500 bg-blue-50' : ''}`}
                            >
                                <div 
                                    className="w-8 flex justify-center text-gray-400 hover:text-blue-600 cursor-pointer"
                                    onClick={() => toggleSelection(product.id)}
                                >
                                    {selectedIds.has(product.id) ? <CheckSquare size={18} className="text-blue-600"/> : <Square size={18}/>}
                                </div>

                                <div className="flex-1 pr-4">
                                    <div className="font-bold text-gray-800 flex items-center gap-3 text-lg">
                                        {product.name}
                                        {product.type === 'composite' && (
                                            <span className="text-[10px] bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full border border-purple-200 flex items-center gap-1 uppercase tracking-wider font-bold">
                                                <Layers size={10}/> SET
                                            </span>
                                        )}
                                        {product.subcategory && (
                                             <span className="text-[10px] bg-gray-100 text-gray-600 px-2 py-0.5 rounded border border-gray-200 font-bold flex items-center gap-1">
                                                 <FolderTree size={10}/> {product.subcategory}
                                             </span>
                                        )}
                                    </div>
                                </div>

                                <div className="w-32 text-xs text-gray-500 flex flex-col gap-1">
                                    {product.manufacturer && <span className="flex items-center gap-1"><Factory size={10}/> {product.manufacturer}</span>}
                                    {product.supplier && <span className="flex items-center gap-1 text-blue-600"><Building size={10}/> {product.supplier}</span>}
                                </div>

                                <div className="w-24 text-right">
                                    <div className="font-mono text-black font-bold text-base">{product.price.toFixed(2)} €</div>
                                    <div className="text-[10px] text-gray-400">/ {product.unit}</div>
                                </div>

                                <div className="w-24 flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={() => handleEditClick(product)} className="p-2 bg-gray-100 hover:bg-blue-50 text-blue-600 rounded-lg transition" title="Upraviť"><Settings size={18}/></button>
                                    <button onClick={() => onDeleteProduct(product.id)} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition" title="Vymazať"><Trash2 size={18}/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

