  const handleMaterialWizardInsert = (wData: MaterialWizardData) => {
      setData(prev => {
          const newData = { ...prev };

          // 1. Base Active Categories from Wizard (Tabs)
          const activeCategoryNames = new Set(wData.categoryOrder);

          // 2. Add Addons STRICTLY based on checkbox (Source of Truth)
          if (wData.includeAssembly) activeCategoryNames.add('Montáž');
          else activeCategoryNames.delete('Montáž');

          if (wData.includeTransport) activeCategoryNames.add('Doprava');
          else activeCategoryNames.delete('Doprava');

          if (wData.includePackaging) activeCategoryNames.add('Balné');
          else activeCategoryNames.delete('Balné');

          // 3. STRICT FILTER: Keep ONLY what is in the active set (plus text sections)
          newData.categories = newData.categories.filter(c => {
              if (c.type === 'text') return true; // Always keep text sections
              // KEEP 'Oceľová konštrukcia' if enabled in layout, even if not in standard wizard tabs
              if (c.name === 'Oceľová konštrukcia' && newData.layout?.hasExternalShaft) return true;
              return activeCategoryNames.has(c.name);
          });

          // 4. CLEAR items in existing valid categories to avoid duplicates
          //    We are about to re-fill them from the Wizard data
          newData.categories.forEach(c => {
              if (activeCategoryNames.has(c.name) && c.type === 'items') {
                  c.items = []; 
              }
          });

          // 5. Create missing categories if they are active but don't exist yet
          activeCategoryNames.forEach(catName => {
               if (!catName) return;
               let cat = newData.categories.find(c => c.name === catName);
               if (!cat) {
                   cat = {
                       id: generateId(),
                       name: catName,
                       type: 'items',
                       items: [],
                       isExpanded: true,
                       section: catName === 'Oceľová konštrukcia' ? 'shaft' : 'lift'
                   };
                   newData.categories.push(cat);
               }
          });

          // Helper to find category in the new structure
          const findCat = (namePart: string) => newData.categories.find(c => c.name === namePart);

          // 6. Process BOM items from Wizard
          wData.items.forEach(bomItem => {
              // Only insert if the category is allowed (Double check)
              if (!activeCategoryNames.has(bomItem.category)) return;

              const category = findCat(bomItem.category);
              if (category) {
                  const product = bomItem.productId ? products.find(p => p.id === bomItem.productId) : null;

                  // NEW: Handle Composite Explosion vs Single Line Logic
                  if (product && product.type === 'composite') {

                      if (product.displayMode === 'single_line') {
                          // SINGLE LINE: Insert just the Set itself
                          category.items.push({
                              id: generateId(),
                              description: product.name,
                              unit: product.unit,
                              quantity: bomItem.quantity, // Usually 1 for a set
                              unitPrice: product.price, // Uses calculated or fixed price from Product
                              purchasePrice: 0,
                              vatRate: 23
                          });
                      } else {
                          // ITEMIZED: Explode components (Default behavior)
                          if (product.subProducts && product.subProducts.length > 0) {
                              product.subProducts.forEach(sub => {
                                  const subP = products.find(p => p.id === sub.productId);
                                  if (subP) {
                                      category.items.push({
                                          id: generateId(),
                                          description: subP.name,
                                          unit: subP.unit,
                                          quantity: bomItem.quantity * sub.quantity,
                                          unitPrice: subP.price,
                                          purchasePrice: 0,
                                          vatRate: 23
                                      });
                                  }
                              });
                          } else {
                              // Fallback if no subproducts but it's composite (e.g. manual set without parts)
                              // Treat as single line
                              category.items.push({
                                  id: generateId(),
                                  description: product.name,
                                  unit: product.unit,
                                  quantity: bomItem.quantity,
                                  unitPrice: product.price,
                                  purchasePrice: 0,
                                  vatRate: 23
                              });
                          }
                      }

                  } else {
                      // Insert Simple Item
                      category.items.push({
                          id: generateId(),
                          description: bomItem.description,
                          unit: bomItem.unit,
                          quantity: bomItem.quantity,
                          unitPrice: bomItem.price || 0,
                          purchasePrice: 0,
                          vatRate: 23
                      });
                  }
              }
          });

          // 7. Addons - Insert items only if enabled (Category exists due to step 2)
          if (wData.includeAssembly) {
              const cat = findCat('Montáž');
              if (cat && cat.items.length === 0) {
                  cat.items.push({ id: generateId(), description: 'Montáž výťahovej technológie', unit: 'kpl', quantity: 1, unitPrice: 1500, purchasePrice: 0, vatRate: 23 });
              }
          }
          if (wData.includeTransport) {
               const cat = findCat('Doprava');
               if (cat && cat.items.length === 0) {
                   cat.items.push({ id: generateId(), description: 'Doprava materiálu na stavbu', unit: 'kpl', quantity: 1, unitPrice: 200, purchasePrice: 0, vatRate: 23 });
               }
          }
          if (wData.includePackaging) {
               const cat = findCat('Balné');
               if (cat && cat.items.length === 0) {
                   cat.items.push({ id: generateId(), description: 'Balné a manipulácia', unit: 'kpl', quantity: 1, unitPrice: 50, purchasePrice: 0, vatRate: 23 });
               }
          }

          return newData;
      });
  };

