                <div className="w-full xl:w-2/5 print:w-2/5 flex items-center justify-center bg-white p-4">
                    <LiftLayoutSketch data={data.layout || DEFAULT_LAYOUT} onChange={handleLayoutChange} isVisible={showLayout} onToggleVisibility={() => setShowLayout(!showLayout)}/>
