            </div>

            <div className={`no-print my-4 p-2 bg-gray-50 rounded border border-gray-200 flex gap-4 items-center justify-center ${isContractMode ? 'hidden' : ''}`}>
                <div className="flex items-center gap-2"><span className="text-xs font-bold uppercase">Výťah</span>
                    <button onClick={() => { setTemplateContext('lift'); setTemplateModalMode('select'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-blue-50"><LayoutTemplate size={12}/></button>
                    <button onClick={() => { setTemplateContext('lift'); setTemplateModalMode('save'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-green-50"><Save size={12}/></button>
                </div>
                <div className="h-4 w-px bg-gray-300 mx-2"></div>
                <div className="flex items-center gap-2"><span className="text-xs font-bold uppercase">Šachta</span>
                    {hasShaft && <><button onClick={() => { setTemplateContext('shaft'); setTemplateModalMode('select'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-blue-50"><LayoutTemplate size={12}/></button>
                    <button onClick={() => { setTemplateContext('shaft'); setTemplateModalMode('save'); setIsTemplateModalOpen(true); }} className="px-2 py-0.5 bg-white border rounded text-xs hover:bg-green-50"><Save size={12}/></button></>}
                    <button onClick={toggleShaft} className={`w-8 h-4 rounded-full relative transition-colors ${hasShaft?'bg-blue-600':'bg-gray-300'}`}><span className={`w-3 h-3 bg-white rounded-full absolute top-0.5 transition-all ${hasShaft?'right-0.5':'left-0.5'}`}/></button>
                </div>
             </div>

        </div>
        <div className="hidden print:block print-break-after-page"></div>
        <div className="print-page-2-content pt-8">
            <div className="mb-12">
            {data.categories.length === 0 && !isContractMode && (
                <div className="no-print p-8 text-center text-gray-400 border-2 border-dashed border-gray-200 rounded-xl bg-gray-50">
                    <Calculator size={48} className="mx-auto mb-4 text-gray-300"/>
                    <h3 className="text-lg font-bold mb-2">Ponuka je prázdna</h3>
                    <p className="text-sm mb-4">Použite Materiálový Sprievodca pre pridanie položiek.</p>
                    <button onClick={() => setIsMaterialModalOpen(true)} className="px-4 py-2 bg-blue-600 text-white rounded font-bold hover:bg-blue-700">Otvoriť Sprievodcu</button>
                </div>
            )}

            {data.categories.map(category => (
                category.type === 'text' ? (
                    <RichTextEditor key={category.id} category={category} onUpdateCategory={(id, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===id?{...c, [f as string]:v}:c)}))} onDeleteCategory={id => setData(prev => ({...prev, categories: prev.categories.filter(c => c.id!==id)}))} />
                ) : (
                    <CategoryTable 
                        key={category.id} 
                        category={category} 
                        currency={data.currency} 
                        globalMargin={category.section === 'shaft' ? data.shaftMargin : data.globalMargin}
                        onUpdateCategory={(id, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===id?{...c, [f as string]:v}:c)}))}
                        onDeleteCategory={id => setData(prev => ({...prev, categories: prev.categories.filter(c => c.id!==id)}))}
                        onUpdateItem={(cid, iid, f, v) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===cid ? {...c, items:c.items.map(i => i.id===iid?{...i, [f as string]:v}:i)} : c)}))}
                        onDeleteItem={(cid, iid) => setData(prev => ({...prev, categories: prev.categories.map(c => c.id===cid ? {...c, items:c.items.filter(i => i.id!==iid)} : c)}))}
                        onAiSuggest={handleAiCategoryItems} 
                        onOpenCatalog={handleOpenCatalog} 
                        isAiLoading={isAiLoading === category.id} 
                        readOnly={isContractMode} 
                        // STRICT PRICE HIDING: Contract OR Order Mode OR Toggle
                        hidePrices={isContractMode || isOrderMode || data.hideItemPrices}
                        onAddItem={handleAddItem}
                        onMoveCategory={moveCategory}
                        // DRAG PROPS
                        draggable={true}
                        onDragStart={onDragStartCat}
                        onDragOver={onDragOverCat}
                        onDragEnd={onDragEndCat}
                    />
                )
            ))}
            </div>

            <div className="flex justify-end mt-8 mb-8 break-inside-avoid">
                <div className="w-full md:w-96">
                    {!isContractMode && !isOrderMode && (
                        <div className="bg-yellow-50 p-3 mb-4 rounded border border-yellow-200 no-print">
                            <div className="text-xs font-bold uppercase mb-2">Marža</div>
                            <div className="flex justify-between items-center mb-1"><span className="text-sm">Výťah %</span><input type="number" value={data.globalMargin} onChange={e=>setData(prev=>({...prev, globalMargin:+e.target.value}))} className="w-16 border rounded text-right font-bold"/></div>
                            <div className="flex justify-between items-center"><span className="text-sm">Šachta %</span><input type="number" value={data.shaftMargin} onChange={e=>setData(prev=>({...prev, shaftMargin:+e.target.value}))} className="w-16 border rounded text-right font-bold"/></div>
                        </div>
                    )}

                    {/* Totals Display */}
                    <div className="bg-gray-50 p-6 rounded border">
