import { Settings, Package, Users, Building, Plus } from 'lucide-react';

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [quotes, setQuotes] = useState<QuoteData[]>([]);
  const [templates, setTemplates] = useState<QuoteTemplate[]>([]);
  const [contractTemplates, setContractTemplates] = useState<ContractTemplate[]>([]);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);
  const [customCategories, setCustomCategories] = useState<string[]>([
    'Pohon', 'Kabína a rám', 'Dvere', 'Vodítka a kotvenie', 'Obmedzovač', 
    'Elektro', 'Montáž', 'Ostatné šachta', 'Ostatné', 
    'Oceľová konštrukcia', 'Doprava', 'Balné'
  ]);
  const [settings, setSettings] = useState<AppSettings>({
    nextCpSequence: 100,
    nextObjSequence: 100,
    nextPlSequence: 100
  });

  // Modal States
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isClientDbOpen, setIsClientDbOpen] = useState(false);
  const [isSupplierDbOpen, setIsSupplierDbOpen] = useState(false);

  // Persistence (Simplified)
  useEffect(() => {
    const saved = localStorage.getItem('smartquote_data');
    if (saved) {
        try {
            const data = JSON.parse(saved);
            if (data.products) setProducts(data.products);
            if (data.clients) setClients(data.clients);
            if (data.suppliers) setSuppliers(data.suppliers);
            if (data.quotes) setQuotes(data.quotes);
            if (data.templates) setTemplates(data.templates);
            if (data.contractTemplates) setContractTemplates(data.contractTemplates);
            if (data.cabinClasses) setCabinClasses(data.cabinClasses);
            if (data.customCategories) setCustomCategories(data.customCategories);
            if (data.settings) setSettings(data.settings);
        } catch (e) { console.error("Failed to load data", e); }
    }
  }, []);

  useEffect(() => {
      const data = { products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings };
      localStorage.setItem('smartquote_data', JSON.stringify(data));
  }, [products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings]);


  // --- HANDLERS ---
  const handleUpdateProduct = (p: Product) => setProducts(prev => prev.map(prod => prod.id === p.id ? p : prod));
  const handleDeleteProduct = (id: string) => setProducts(prev => prev.filter(p => p.id !== id));
  const handleAddProduct = (p: Product) => setProducts(prev => [...prev, p]);

  const handleImportData = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = e.target?.result as string;
        const backup: BackupData = JSON.parse(json);

        if (backup.products) setProducts(backup.products);
        if (backup.clients) setClients(backup.clients);
        if (backup.suppliers) setSuppliers(backup.suppliers);
        if (backup.quotes) setQuotes(backup.quotes);
        if (backup.templates) setTemplates(backup.templates);
        if (backup.contractTemplates) setContractTemplates(backup.contractTemplates);
        if (backup.settings) setSettings(backup.settings);
        if (backup.cabinClasses) setCabinClasses(backup.cabinClasses);
        if (backup.customCategories) setCustomCategories(backup.customCategories);

        alert("Dáta boli úspešne obnovené.");
      } catch (error) {
        console.error("Import failed", error);
        alert("Chyba pri importe dát.");
      }
    };
    reader.readAsText(file);
  };

  const handleExportData = () => {
    const backup: BackupData = {
      version: 1,
      appVersion: "1.0.0",
      timestamp: Date.now(),
      settings,
      quotes,
      products,
      clients,
      suppliers,
      templates,
      contractTemplates,
      cabinClasses,
      customCategories
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `smartquote_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const handleFactoryReset = () => {
      if (window.confirm("Naozaj vymazať všetko?")) {
        setProducts([]);
        setQuotes([]);
        setClients([]);
        setSuppliers([]);
        setTemplates([]);
        setContractTemplates([]);
        setCabinClasses([]);
        localStorage.removeItem('smartquote_data');
        window.location.reload();
      }
  };

  if (!isAuthenticated) return <LoginGate onLogin={() => setIsAuthenticated(true)} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
        <header className="bg-white border-b px-6 py-3 flex justify-between items-center sticky top-0 z-40 shadow-sm">
            <div className="flex items-center gap-2">
                <div className="bg-blue-600 text-white p-1.5 rounded font-bold">SQ</div>
                <h1 className="font-bold text-xl tracking-tight">SmartQuote SK</h1>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setIsClientDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Klienti"><Users size={20}/></button>
                <button onClick={() => setIsSupplierDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Dodávatelia"><Building size={20}/></button>
                <button onClick={() => setIsCatalogOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Katalóg"><Package size={20}/></button>
                <button onClick={() => setIsSettingsOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Nastavenia"><Settings size={20}/></button>
            </div>
        </header>

        <main className="p-6 max-w-7xl mx-auto">
             <div className="text-center py-16">
                 <h2 className="text-3xl font-bold text-gray-800 mb-4">Dashboard</h2>
                 <p className="text-gray-500 mb-8">Vitajte v systéme pre tvorbu cenových ponúk výťahov.</p>
                 <button className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold shadow hover:bg-blue-700 flex items-center gap-2 mx-auto">
                    <Plus size={20}/> Nová Ponuka
                 </button>
             </div>

             {/* Quote List Placeholder */}
             <div className="mt-8">
                 <h3 className="text-lg font-bold text-gray-700 mb-4">Posledné ponuky</h3>
                 {quotes.length === 0 ? (
                     <div className="text-center p-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-400 italic">
                         Zatiaľ žiadne ponuky.
                     </div>
                 ) : (
                     <div className="grid gap-4">
                         {quotes.map(q => <div key={q.id}>{q.title}</div>)}
                     </div>
                 )}
             </div>
        </main>

        {isSettingsOpen && (
          <SettingsModal 
            isOpen={isSettingsOpen} 
            onClose={() => setIsSettingsOpen(false)} 
            settings={settings}
            onSaveSettings={setSettings}
            onExportData={handleExportData}
            onImportData={handleImportData}
            onFactoryReset={handleFactoryReset}
            appVersion="1.0.0"
          />
        )}

        {isCatalogOpen && (
          <CatalogManagerModal
            isOpen={isCatalogOpen}
            onClose={() => setIsCatalogOpen(false)}
            products={products}
            onAddProduct={handleAddProduct}
            onUpdateProduct={handleUpdateProduct}
            onDeleteProduct={handleDeleteProduct}
            customCategories={customCategories}
            onAddCategory={(name) => setCustomCategories([...customCategories, name])}
            onDeleteCategory={(name) => setCustomCategories(customCategories.filter(c => c !== name))}
            onImportCatalog={() => {}} 
            cabinClasses={cabinClasses}
            onAddCabinClass={(cc) => setCabinClasses([...cabinClasses, cc])}
            onUpdateCabinClass={(cc) => setCabinClasses(cabinClasses.map(c => c.id === cc.id ? cc : c))}
            onDeleteCabinClass={(id) => setCabinClasses(cabinClasses.filter(c => c.id !== id))}
          />
       )}

       {isClientDbOpen && (
         <ClientDatabaseModal
            isOpen={isClientDbOpen}
            onClose={() => setIsClientDbOpen(false)}
            clients={clients}
            onSelectClient={() => {}}
            onAddClient={(c) => setClients([...clients, c])}
            onDeleteClient={(id) => setClients(clients.filter(c => c.id !== id))}
         />
       )}

       {isSupplierDbOpen && (
         <SupplierDatabaseModal
            isOpen={isSupplierDbOpen}
            onClose={() => setIsSupplierDbOpen(false)}
            suppliers={suppliers}
            onSelectSupplier={() => {}}
            onAddSupplier={(s) => setSuppliers([...suppliers, s])}
            onDeleteSupplier={(id) => setSuppliers(suppliers.filter(s => s.id !== id))}
         />
       )}
    </div>
  );
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, FolderOpen, Folder,
  AlertTriangle, Box
} from 'lucide-react';

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk Actions State
  const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());
  const [isBulkMoveMode, setIsBulkMoveMode] = useState(false);
  const [bulkTargetCat, setBulkTargetCat] = useState('');
  const [bulkTargetSubcat, setBulkTargetSubcat] = useState('');

  // Editing State
  const [editingProductId, setEditingProductId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<Product>>({});

  // New Category State
  const [newCategoryName, setNewCategoryName] = useState('');

  // New Class State
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLinkedSet, setNewClassLinkedSet] = useState('');

  // Grouping State (Expanded Subcategories)
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize active category
  useEffect(() => {
      if (customCategories.length > 0 && !activeCategory) {
          setActiveCategory(customCategories[0]);
      }
  }, [customCategories, activeCategory]);

  // Filtered Products
  const filteredProducts = products.filter(p => {
      const matchCat = activeCategory ? p.category === activeCategory : true;
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCat && matchSearch;
  });

  // GROUPING LOGIC
  const { generalProducts, groupedProducts, sortedSubcategories } = useMemo(() => {
      const general: Product[] = [];
      const groups: Record<string, Product[]> = {};

      filteredProducts.forEach(p => {
          if (p.subcategory) {
              if (!groups[p.subcategory]) groups[p.subcategory] = [];
              groups[p.subcategory].push(p);
          } else {
              general.push(p);
          }
      });

      return {
          generalProducts: general,
          groupedProducts: groups,
          sortedSubcategories: Object.keys(groups).sort()
      };
  }, [filteredProducts]);

  // Derived Data
  const allCategories = customCategories;

  // Get all unique subcategories for the selected target category (for suggestions)
  const bulkTargetSubcategoriesOptions = Array.from(new Set(
      products
        .filter(p => p.category === bulkTargetCat && p.subcategory)
        .map(p => p.subcategory!)
  ));

  // --- Handlers ---

  const handleBulkSelection = (id: string) => {
      const newSet = new Set(selectedProductIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedProductIds(newSet);
  };

  const toggleSelectAll = () => {
      if (selectedProductIds.size === filteredProducts.length && filteredProducts.length > 0) {
          setSelectedProductIds(new Set());
      } else {
          setSelectedProductIds(new Set(filteredProducts.map(p => p.id)));
      }
  };

  const toggleGroupExpand = (subcat: string) => {
      const newSet = new Set(expandedGroups);
      if (newSet.has(subcat)) newSet.delete(subcat);
      else newSet.add(subcat);
      setExpandedGroups(newSet);
  };

  const handleBulkMoveConfirm = () => {
      if (!bulkTargetCat) return;

      const targetSub = bulkTargetSubcat.trim();
      const idsToMove = Array.from(selectedProductIds);

      idsToMove.forEach(id => {
          const product = products.find(p => p.id === id);
          if (product) {
              onUpdateProduct({
                  ...product,
                  category: bulkTargetCat,
                  subcategory: targetSub || undefined 
              });
          }
      });

      // Auto expand the target group if we are staying in the same category
      if (activeCategory === bulkTargetCat && targetSub) {
           setExpandedGroups(prev => {
               const next = new Set(prev);
               next.add(targetSub);
               return next;
           });
      }

      setSelectedProductIds(new Set());
      setIsBulkMoveMode(false);
      setBulkTargetCat('');
      setBulkTargetSubcat('');
  };

  const handleDeleteSelected = () => {
      if (window.confirm(`Naozaj vymazať ${selectedProductIds.size} produktov?`)) {
          selectedProductIds.forEach(id => onDeleteProduct(id));
          setSelectedProductIds(new Set());
      }
  };

  const handleStartEdit = (p: Product) => {
      setEditingProductId(p.id);
      setEditForm({...p});
  };

  const handleSaveEdit = () => {
      if (editingProductId && editForm.name) {
          const original = products.find(p => p.id === editingProductId);
          if (original) {
              onUpdateProduct({ ...original, ...editForm } as Product);
          }
          setEditingProductId(null);
          setEditForm({});
      }
  };

  const handleAddCategorySubmit = () => {
      if (newCategoryName && !customCategories.includes(newCategoryName)) {
          onAddCategory(newCategoryName);
          setNewCategoryName('');
      }
  };

  const handleAddClassSubmit = () => {
      if (newClassName) {
          onAddCabinClass({
              id: crypto.randomUUID(),
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
          setNewClassName('');
          setNewClassDesc('');
          setNewClassLinkedSet('');
      }
  };

  // Helper to render a single row
  const renderProductRow = (product: Product) => (
    <tr key={product.id} className={`hover:bg-blue-50 transition ${selectedProductIds.has(product.id) ? 'bg-blue-50' : ''}`}>
        <td className="p-3 w-10 text-center">
            <button onClick={() => handleBulkSelection(product.id)} className={`text-gray-400 hover:text-purple-600 ${selectedProductIds.has(product.id) ? 'text-purple-600' : ''}`}>
                {selectedProductIds.has(product.id) ? <CheckSquare size={16}/> : <Square size={16}/>}
            </button>
        </td>

        {/* Name */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded font-bold" 
                    value={editForm.name || ''} 
                    onChange={e => setEditForm({...editForm, name: e.target.value})}
                    autoFocus
                />
            ) : (
                <div className="font-bold text-gray-800">{product.name}</div>
            )}
        </td>

        {/* Subcategory */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded text-xs" 
                    value={editForm.subcategory || ''} 
                    onChange={e => setEditForm({...editForm, subcategory: e.target.value})}
                    placeholder="-"
                />
            ) : (
                <span className={`text-xs px-2 py-1 rounded-full border ${product.subcategory ? 'bg-blue-50 text-blue-700 border-blue-100' : 'bg-gray-50 text-gray-400 border-gray-200'}`}>
                    {product.subcategory || '-'}
                </span>
            )}
        </td>

        {/* Price */}
        <td className="p-3 text-right font-mono">
            {editingProductId === product.id ? (
                <input 
                    type="number"
                    className="w-full border p-1 rounded text-right" 
                    value={editForm.price || ''} 
                    onChange={e => setEditForm({...editForm, price: parseFloat(e.target.value) || 0})}
                />
            ) : (
                product.price.toFixed(2)
            )}
        </td>

        {/* Unit */}
        <td className="p-3 text-right">
            {editingProductId === product.id ? (
                <select
                    className="border p-1 rounded text-xs" 
                    value={editForm.unit || 'ks'} 
                    onChange={e => setEditForm({...editForm, unit: e.target.value})}
                >
                    <option value="ks">ks</option>
                    <option value="m">m</option>
                    <option value="kpl">kpl</option>
                </select>
            ) : (
                <span className="text-gray-500 text-xs">{product.unit}</span>
            )}
        </td>

        {/* Actions */}
        <td className="p-3 text-center">
            {editingProductId === product.id ? (
                <div className="flex justify-center gap-1">
                    <button onClick={handleSaveEdit} className="p-1 bg-green-100 text-green-700 rounded hover:bg-green-200"><Check size={16}/></button>
                    <button onClick={() => setEditingProductId(null)} className="p-1 bg-gray-100 text-gray-500 rounded hover:bg-gray-200"><X size={16}/></button>
                </div>
            ) : (
                <div className="flex justify-center gap-1">
                    <button onClick={() => handleStartEdit(product)} className="p-1 text-blue-500 hover:bg-blue-50 rounded"><Edit size={16}/></button>
                    <button onClick={() => onDeleteProduct(product.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                </div>
            )}
        </td>
    </tr>
  );

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-6xl max-h-[90vh] flex flex-col">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Settings className="text-purple-600" />
            <h2 className="text-xl font-bold text-gray-800">Správca Katalógu</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
            <X size={20}/>
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200">
            <button 
                onClick={() => setActiveTab('products')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='products' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Produkty
            </button>
            <button 
                onClick={() => setActiveTab('categories')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='categories' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Kategórie
            </button>
            <button 
                onClick={() => setActiveTab('classes')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='classes' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Triedy Kabín
            </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-hidden flex flex-col">

            {/* --- PRODUCTS TAB --- */}
            {activeTab === 'products' && (
                <div className="flex-1 flex flex-col min-h-0">
                    {/* Toolbar */}
                    <div className="p-4 border-b bg-white flex flex-wrap gap-4 items-center justify-between">
                        <div className="flex items-center gap-2 flex-1">
                            {/* Category Filter */}
                            <select 
                                value={activeCategory} 
                                onChange={e => setActiveCategory(e.target.value)} 
                                className="border rounded-lg px-3 py-2 text-sm font-bold bg-gray-50 min-w-[150px]"
                            >
                                {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>

                            {/* Search */}
                            <div className="relative flex-1 max-w-sm">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                                <input 
                                    type="text" 
                                    placeholder="Hľadať produkt..." 
                                    value={searchTerm} 
                                    onChange={e => setSearchTerm(e.target.value)}
                                    className="w-full pl-9 pr-3 py-2 border rounded-lg text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                />
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                             {/* Bulk Actions */}
                             {selectedProductIds.size > 0 && (
                                <div className="flex items-center gap-2 bg-purple-50 px-3 py-1.5 rounded-lg border border-purple-100 mr-2 animate-in fade-in">
                                    <span className="text-xs font-bold text-purple-700">{selectedProductIds.size} vybraných</span>

                                    {isBulkMoveMode ? (
                                        <div className="flex items-center gap-2 bg-white rounded-lg p-1 border shadow-sm">
                                            <span className="text-xs font-bold text-gray-500 ml-2">Presunúť do:</span>
                                            {/* Target Category Select */}
                                            <select 
                                                className="text-sm border rounded p-1 font-bold text-blue-700 outline-none max-w-[150px]"
                                                value={bulkTargetCat}
                                                onChange={(e) => { setBulkTargetCat(e.target.value); setBulkTargetSubcat(''); }}
                                            >
                                                <option value="" disabled>Vybrať Kategóriu...</option>
                                                {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                            </select>

                                            {/* Target Subcategory Input/Select */}
                                            {bulkTargetCat && (
                                                <div className="relative w-40">
                                                    <input 
                                                        list="bulk-subcat-options"
                                                        placeholder="Podkategória..."
                                                        className="w-full text-sm border rounded p-1 px-2 outline-none font-bold text-gray-700"
                                                        value={bulkTargetSubcat}
                                                        onChange={e => setBulkTargetSubcat(e.target.value)}
                                                        onKeyDown={e => e.key === 'Enter' && handleBulkMoveConfirm()}
                                                        autoFocus
                                                    />
                                                    <datalist id="bulk-subcat-options">
                                                        {bulkTargetSubcategoriesOptions.map(s => <option key={s} value={s}/>)}
                                                    </datalist>
                                                </div>
                                            )}

                                            <button 
                                                onClick={handleBulkMoveConfirm} 
                                                disabled={!bulkTargetCat}
                                                className="bg-green-500 text-white p-1 rounded hover:bg-green-600 disabled:opacity-50"
                                                title="Potvrdiť presun"
                                            >
                                                <ArrowRightCircle size={18}/>
                                            </button>
                                            <button onClick={() => setIsBulkMoveMode(false)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><X size={18}/></button>
                                        </div>
                                    ) : (
                                        <button onClick={() => { setIsBulkMoveMode(true); setBulkTargetCat(activeCategory); }} className="px-3 py-1.5 bg-white border border-blue-200 text-blue-700 font-bold rounded text-sm hover:bg-blue-100 flex items-center gap-2">
                                            <CornerDownRight size={16}/> Presunúť
                                        </button>
                                    )}

                                    {!isBulkMoveMode && (
                                        <button onClick={handleDeleteSelected} className="px-3 py-1.5 bg-white border border-red-200 text-red-600 font-bold rounded text-sm hover:bg-red-50 flex items-center gap-2">
                                            <Trash2 size={16}/> Vymazať
                                        </button>
                                    )}
                                </div>
                             )}

                            {/* Import Button */}
                            <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => e.target.files?.[0] && onImportCatalog(e.target.files[0])} />
                            <button onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Importovať JSON katalóg">
                                <Upload size={20}/>
                            </button>
                        </div>
                    </div>

                    {/* Products Table */}
                    <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                        <table className="w-full text-sm bg-white border rounded-lg shadow-sm overflow-hidden">
                            <thead className="bg-gray-100 text-gray-600 font-bold uppercase text-xs sticky top-0 z-10 shadow-sm">
                                <tr>
                                    <th className="p-3 w-10 text-center">
                                        <button onClick={toggleSelectAll} className="text-gray-500 hover:text-black">
                                            {selectedProductIds.size > 0 && selectedProductIds.size === filteredProducts.length ? <CheckSquare size={16}/> : <Square size={16}/>}
                                        </button>
                                    </th>
                                    <th className="p-3 text-left">Názov Produktu</th>
                                    <th className="p-3 text-left w-32">Podkategória</th>
                                    <th className="p-3 text-right w-24">Cena (€)</th>
                                    <th className="p-3 text-right w-20">MJ</th>
                                    <th className="p-3 text-center w-24">Akcie</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {/* 1. General Products (No Subcategory) */}
                                {generalProducts.map(renderProductRow)}

                                {/* 2. Grouped Products */}
                                {sortedSubcategories.map(subcat => {
                                    const items = groupedProducts[subcat];
                                    const isExpanded = expandedGroups.has(subcat);

                                    return (
                                        <React.Fragment key={subcat}>
                                            {/* Subcategory Header */}
                                            <tr 
                                                className="bg-gray-100 cursor-pointer hover:bg-gray-200 transition border-y border-gray-200"
                                                onClick={() => toggleGroupExpand(subcat)}
                                            >
                                                <td className="p-2 text-center text-gray-500">
                                                    {isExpanded ? <ChevronDown size={16}/> : <ChevronRight size={16}/>}
                                                </td>
                                                <td colSpan={5} className="p-2">
                                                    <div className="flex items-center gap-2 font-bold text-gray-800 uppercase text-xs tracking-wider">
                                                        {isExpanded ? <FolderOpen size={18} className="text-blue-600"/> : <Folder size={18} className="text-gray-400"/>}
                                                        {subcat}
                                                        <span className="ml-2 bg-white text-gray-600 px-2 py-0.5 rounded-full text-[10px] border border-gray-300 shadow-sm">
                                                            {items.length} produktov
                                                        </span>
                                                    </div>
                                                </td>
                                            </tr>
                                            {/* Items in Group */}
                                            {isExpanded && items.map(renderProductRow)}
                                        </React.Fragment>
                                    );
                                })}

                                {filteredProducts.length === 0 && (
                                    <tr>
                                        <td colSpan={6} className="text-center py-8 text-gray-400 italic">Žiadne produkty v tejto kategórii.</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* --- CATEGORIES TAB --- */}
            {activeTab === 'categories' && (
                <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
                    <div className="max-w-3xl mx-auto space-y-6">
                        {/* Add New Category */}
                        <div className="bg-white p-4 rounded-xl border border-purple-200 shadow-sm flex gap-2">
                            <input 
                                className="flex-1 border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-purple-500"
                                placeholder="Názov novej kategórie..."
                                value={newCategoryName}
                                onChange={e => setNewCategoryName(e.target.value)}
                            />
                            <button onClick={handleAddCategorySubmit} className="bg-purple-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-purple-700">
                                <Plus size={18}/> Pridať
                            </button>
                        </div>

                        {/* List */}
                        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="p-3 bg-gray-100 text-xs font-bold text-gray-500 uppercase border-b">Existujúce Kategórie</div>
                            <div className="divide-y divide-gray-100">
                                {customCategories.map(cat => (
                                    <div key={cat} className="p-4 flex justify-between items-center hover:bg-gray-50 group">
                                        <div className="flex items-center gap-3">
                                            <Layers className="text-gray-400" size={20}/>
                                            <span className="font-bold text-gray-800">{cat}</span>
                                            <span className="text-xs text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">
                                                {products.filter(p => p.category === cat).length} produktov
                                            </span>
                                        </div>
                                        <button onClick={() => onDeleteCategory(cat)} className="text-gray-300 hover:text-red-500 transition">
                                            <Trash2 size={18}/>
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* --- CLASSES TAB --- */}
            {activeTab === 'classes' && (
                <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
                    <div className="max-w-4xl mx-auto space-y-6">
                        <div className="bg-blue-50 p-4 rounded-lg border border-blue-100 text-sm text-blue-800 flex gap-2">
                            <AlertTriangle size={18} className="shrink-0"/>
                            <div>
                                Tu môžete definovať <strong>Triedy Kabín</strong> (napr. FUN, SKY, NEREZ).
                                Ku každej triede môžete priradiť <strong>SET Produkt</strong> z katalógu.
                                Ak je set priradený, Materiálový Sprievodca automaticky vloží tento set namiesto generickej kabíny.
                            </div>
                        </div>

                        {/* Add New Class */}
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <h3 className="font-bold text-lg mb-4 text-gray-800">Nová Trieda</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                <input 
                                    className="border rounded px-3 py-2" placeholder="Názov (napr. EXCLUSIVE)"
                                    value={newClassName} onChange={e => setNewClassName(e.target.value)}
                                />
                                <input 
                                    className="border rounded px-3 py-2" placeholder="Popis (napr. Sklo / Kameň)"
                                    value={newClassDesc} onChange={e => setNewClassDesc(e.target.value)}
                                />
                                <div className="md:col-span-2">
                                    <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Prepojený SET Produkt (Voliteľné)</label>
                                    <select 
                                        className="w-full border rounded px-3 py-2 text-sm bg-white"
                                        value={newClassLinkedSet}
                                        onChange={e => setNewClassLinkedSet(e.target.value)}
                                    >
                                        <option value="">-- Žiadne prepojenie --</option>
                                        {products.filter(p => p.type === 'composite').map(p => (
                                            <option key={p.id} value={p.id}>📦 {p.name} ({p.price}€)</option>
                                        ))}
                                    </select>
                                </div>
                            </div>
                            <button onClick={handleAddClassSubmit} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700">
                                Uložiť Triedu
                            </button>
                        </div>

                        {/* Classes List */}
                        <div className="space-y-2">
                            {cabinClasses.map(cc => {
                                const linkedProduct = products.find(p => p.id === cc.linkedProductId);
                                return (
                                    <div key={cc.id} className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex justify-between items-center group">
                                        <div>
                                            <div className="font-bold text-lg text-gray-800">{cc.name}</div>
                                            <div className="text-gray-500 text-sm">{cc.description}</div>
                                            {linkedProduct && (
                                                <div className="mt-2 text-xs bg-green-50 text-green-700 px-2 py-1 rounded inline-flex items-center gap-1 border border-green-100">
                                                    <Box size={12}/> Link: <strong>{linkedProduct.name}</strong>
                                                </div>
                                            )}
                                        </div>
                                        <button onClick={() => onDeleteCabinClass(cc.id)} className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded transition">
                                            <Trash2 size={20}/>
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, FolderOpen, Folder,
  AlertTriangle, Box
} from 'lucide-react';

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk Actions State
  const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());
  const [isBulkMoveMode, setIsBulkMoveMode] = useState(false);
  const [bulkTargetCat, setBulkTargetCat] = useState('');
  const [bulkTargetSubcat, setBulkTargetSubcat] = useState('');

  // Editing State
  const [editingProductId, setEditingProductId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<Product>>({});

  // New Category State
  const [newCategoryName, setNewCategoryName] = useState('');

  // New Class State
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLinkedSet, setNewClassLinkedSet] = useState('');

  // Grouping State (Expanded Subcategories)
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize active category
  useEffect(() => {
      if (customCategories.length > 0 && !activeCategory) {
          setActiveCategory(customCategories[0]);
      }
  }, [customCategories, activeCategory]);

  // Filtered Products
  const filteredProducts = products.filter(p => {
      const matchCat = activeCategory ? p.category === activeCategory : true;
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCat && matchSearch;
  });

  // GROUPING LOGIC
  const { generalProducts, groupedProducts, sortedSubcategories } = useMemo(() => {
      const general: Product[] = [];
      const groups: Record<string, Product[]> = {};

      filteredProducts.forEach(p => {
          if (p.subcategory) {
              if (!groups[p.subcategory]) groups[p.subcategory] = [];
              groups[p.subcategory].push(p);
          } else {
              general.push(p);
          }
      });

      return {
          generalProducts: general,
          groupedProducts: groups,
          sortedSubcategories: Object.keys(groups).sort()
      };
  }, [filteredProducts]);

  // Derived Data
  const allCategories = customCategories;

  // Get all unique subcategories for the selected target category (for suggestions)
  const bulkTargetSubcategoriesOptions = Array.from(new Set(
      products
        .filter(p => p.category === bulkTargetCat && p.subcategory)
        .map(p => p.subcategory!)
  ));

  // --- Handlers ---

  const handleBulkSelection = (id: string) => {
      const newSet = new Set(selectedProductIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedProductIds(newSet);
  };

  const toggleSelectAll = () => {
      if (selectedProductIds.size === filteredProducts.length && filteredProducts.length > 0) {
          setSelectedProductIds(new Set());
      } else {
          setSelectedProductIds(new Set(filteredProducts.map(p => p.id)));
      }
  };

  const toggleGroupExpand = (subcat: string) => {
      const newSet = new Set(expandedGroups);
      if (newSet.has(subcat)) newSet.delete(subcat);
      else newSet.add(subcat);
      setExpandedGroups(newSet);
  };

  const handleBulkMoveConfirm = () => {
      if (!bulkTargetCat) return;

      const targetSub = bulkTargetSubcat.trim();
      const idsToMove = Array.from(selectedProductIds);

      idsToMove.forEach(id => {
          const product = products.find(p => p.id === id);
          if (product) {
              onUpdateProduct({
                  ...product,
                  category: bulkTargetCat,
                  subcategory: targetSub || undefined 
              });
          }
      });

      // Auto expand the target group if we are staying in the same category
      if (activeCategory === bulkTargetCat && targetSub) {
           setExpandedGroups(prev => {
               const next = new Set(prev);
               next.add(targetSub);
               return next;
           });
      }

      setSelectedProductIds(new Set());
      setIsBulkMoveMode(false);
      setBulkTargetCat('');
      setBulkTargetSubcat('');
  };

  const handleDeleteSelected = () => {
      if (window.confirm(`Naozaj vymazať ${selectedProductIds.size} produktov?`)) {
          selectedProductIds.forEach(id => onDeleteProduct(id));
          setSelectedProductIds(new Set());
      }
  };

  const handleStartEdit = (p: Product) => {
      setEditingProductId(p.id);
      setEditForm({...p});
  };

  const handleSaveEdit = () => {
      if (editingProductId && editForm.name) {
          const original = products.find(p => p.id === editingProductId);
          if (original) {
              onUpdateProduct({ ...original, ...editForm } as Product);
          }
          setEditingProductId(null);
          setEditForm({});
      }
  };

  const handleAddCategorySubmit = () => {
      if (newCategoryName && !customCategories.includes(newCategoryName)) {
          onAddCategory(newCategoryName);
          setNewCategoryName('');
      }
  };

  const handleAddClassSubmit = () => {
      if (newClassName) {
          onAddCabinClass({
              id: crypto.randomUUID(),
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
          setNewClassName('');
          setNewClassDesc('');
          setNewClassLinkedSet('');
      }
  };

  if (!isOpen) return null;

  // Helper to render a single row
  const renderProductRow = (product: Product) => (
    <tr key={product.id} className={`hover:bg-blue-50 transition ${selectedProductIds.has(product.id) ? 'bg-blue-50' : ''}`}>
        <td className="p-3 w-10 text-center">
            <button onClick={() => handleBulkSelection(product.id)} className={`text-gray-400 hover:text-purple-600 ${selectedProductIds.has(product.id) ? 'text-purple-600' : ''}`}>
                {selectedProductIds.has(product.id) ? <CheckSquare size={16}/> : <Square size={16}/>}
            </button>
        </td>

        {/* Name */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded font-bold" 
                    value={editForm.name || ''} 
                    onChange={e => setEditForm({...editForm, name: e.target.value})}
                    autoFocus
                />
            ) : (
                <div className="font-bold text-gray-800">{product.name}</div>
            )}
        </td>

        {/* Subcategory */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded text-xs" 
                    value={editForm.subcategory || ''} 
                    onChange={e => setEditForm({...editForm, subcategory: e.target.value})}
                    placeholder="-"
                />
            ) : (
                <span className={`text-xs px-2 py-1 rounded-full border ${product.subcategory ? 'bg-blue-50 text-blue-700 border-blue-100' : 'bg-gray-50 text-gray-400 border-gray-200'}`}>
                    {product.subcategory || '-'}
                </span>
            )}
        </td>

        {/* Price */}
        <td className="p-3 text-right font-mono">
            {editingProductId === product.id ? (
                <input 
                    type="number"
                    className="w-full border p-1 rounded text-right" 
                    value={editForm.price || ''} 
                    onChange={e => setEditForm({...editForm, price: parseFloat(e.target.value) || 0})}
                />
            ) : (
                product.price.toFixed(2)
            )}
        </td>

        {/* Unit */}
        <td className="p-3 text-right">
            {editingProductId === product.id ? (
                <select
                    className="border p-1 rounded text-xs" 
                    value={editForm.unit || 'ks'} 
                    onChange={e => setEditForm({...editForm, unit: e.target.value})}
                >
                    <option value="ks">ks</option>
                    <option value="m">m</option>
                    <option value="kpl">kpl</option>
                </select>
            ) : (
                <span className="text-gray-500 text-xs">{product.unit}</span>
            )}
        </td>

        {/* Actions */}
        <td className="p-3 text-center">
            {editingProductId === product.id ? (
                <div className="flex justify-center gap-1">
                    <button onClick={handleSaveEdit} className="p-1 bg-green-100 text-green-700 rounded hover:bg-green-200"><Check size={16}/></button>
                    <button onClick={() => setEditingProductId(null)} className="p-1 bg-gray-100 text-gray-500 rounded hover:bg-gray-200"><X size={16}/></button>
                </div>
            ) : (
                <div className="flex justify-center gap-1">
                    <button onClick={() => handleStartEdit(product)} className="p-1 text-blue-500 hover:bg-blue-50 rounded"><Edit size={16}/></button>
                    <button onClick={() => onDeleteProduct(product.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                </div>
            )}
        </td>
    </tr>
  );

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-6xl max-h-[90vh] flex flex-col">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Settings className="text-purple-600" />
            <h2 className="text-xl font-bold text-gray-800">Správca Katalógu</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
            <X size={20}/>
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200">
            <button 
                onClick={() => setActiveTab('products')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='products' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Produkty
            </button>
            <button 
                onClick={() => setActiveTab('categories')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='categories' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Kategórie
            </button>
            <button 
                onClick={() => setActiveTab('classes')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='classes' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Triedy Kabín
            </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-hidden flex flex-col">

            {/* --- PRODUCTS TAB --- */}
            {activeTab === 'products' && (
                <div className="flex-1 flex flex-col min-h-0">
                    {/* Toolbar */}
                    <div className="p-4 border-b bg-white flex flex-wrap gap-4 items-center justify-between">
                        <div className="flex items-center gap-2 flex-1">
                            {/* Category Filter */}
                            <select 
                                value={activeCategory} 
                                onChange={e => setActiveCategory(e.target.value)} 
                                className="border rounded-lg px-3 py-2 text-sm font-bold bg-gray-50 min-w-[150px]"
                            >
                                {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>

                            {/* Search */}
                            <div className="relative flex-1 max-w-sm">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                                <input 
                                    type="text" 
                                    placeholder="Hľadať produkt..." 
                                    value={searchTerm} 
                                    onChange={e => setSearchTerm(e.target.value)}
                                    className="w-full pl-9 pr-3 py-2 border rounded-lg text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                />
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                             {/* Bulk Actions */}
                             {selectedProductIds.size > 0 && (
                                <div className="flex items-center gap-2 bg-purple-50 px-3 py-1.5 rounded-lg border border-purple-100 mr-2 animate-in fade-in">
                                    <span className="text-xs font-bold text-purple-700">{selectedProductIds.size} vybraných</span>

                                    {isBulkMoveMode ? (
                                        <div className="flex items-center gap-2 bg-white rounded-lg p-1 border shadow-sm">
                                            <span className="text-xs font-bold text-gray-500 ml-2">Presunúť do:</span>
                                            {/* Target Category Select */}
                                            <select 
                                                className="text-sm border rounded p-1 font-bold text-blue-700 outline-none max-w-[150px]"
                                                value={bulkTargetCat}
                                                onChange={(e) => { setBulkTargetCat(e.target.value); setBulkTargetSubcat(''); }}
                                            >
                                                <option value="" disabled>Vybrať Kategóriu...</option>
                                                {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                            </select>

                                            {/* Target Subcategory Input/Select */}
                                            {bulkTargetCat && (
                                                <div className="relative w-40">
                                                    <input 
                                                        list="bulk-subcat-options"
                                                        placeholder="Podkategória..."
                                                        className="w-full text-sm border rounded p-1 px-2 outline-none font-bold text-gray-700"
                                                        value={bulkTargetSubcat}
                                                        onChange={e => setBulkTargetSubcat(e.target.value)}
                                                        onKeyDown={e => e.key === 'Enter' && handleBulkMoveConfirm()}
                                                        autoFocus
                                                    />
                                                    <datalist id="bulk-subcat-options">
                                                        {bulkTargetSubcategoriesOptions.map(s => <option key={s} value={s}/>)}
                                                    </datalist>
                                                </div>
                                            )}

                                            <button 
                                                onClick={handleBulkMoveConfirm} 
                                                disabled={!bulkTargetCat}
                                                className="bg-green-500 text-white p-1 rounded hover:bg-green-600 disabled:opacity-50"
                                                title="Potvrdiť presun"
                                            >
                                                <ArrowRightCircle size={18}/>
                                            </button>
                                            <button onClick={() => setIsBulkMoveMode(false)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><X size={18}/></button>
                                        </div>
                                    ) : (
                                        <button onClick={() => { setIsBulkMoveMode(true); setBulkTargetCat(activeCategory); }} className="px-3 py-1.5 bg-white border border-blue-200 text-blue-700 font-bold rounded text-sm hover:bg-blue-100 flex items-center gap-2">
                                            <CornerDownRight size={16}/> Presunúť
                                        </button>
                                    )}

                                    {!isBulkMoveMode && (
                                        <button onClick={handleDeleteSelected} className="px-3 py-1.5 bg-white border border-red-200 text-red-600 font-bold rounded text-sm hover:bg-red-50 flex items-center gap-2">
                                            <Trash2 size={16}/> Vymazať
                                        </button>
                                    )}
                                </div>
                             )}

                            {/* Import Button */}
                            <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => e.target.files?.[0] && onImportCatalog(e.target.files[0])} />
                            <button onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Importovať JSON katalóg">
                                <Upload size={20}/>
                            </button>
                        </div>
                    </div>

                    {/* Products Table */}
                    <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                        <table className="w-full text-sm bg-white border rounded-lg shadow-sm overflow-hidden">
                            <thead className="bg-gray-100 text-gray-600 font-bold uppercase text-xs sticky top-0 z-10 shadow-sm">
                                <tr>
                                    <th className="p-3 w-10 text-center">
                                        <button onClick={toggleSelectAll} className="text-gray-500 hover:text-black">
                                            {selectedProductIds.size > 0 && selectedProductIds.size === filteredProducts.length ? <CheckSquare size={16}/> : <Square size={16}/>}
                                        </button>
                                    </th>
                                    <th className="p-3 text-left">Názov Produktu</th>
                                    <th className="p-3 text-left w-32">Podkategória</th>
                                    <th className="p-3 text-right w-24">Cena (€)</th>
                                    <th className="p-3 text-right w-20">MJ</th>
                                    <th className="p-3 text-center w-24">Akcie</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {/* 1. General Products (No Subcategory) */}
                                {generalProducts.map(renderProductRow)}

                                {/* 2. Grouped Products */}
                                {sortedSubcategories.map(subcat => {
                                    const items = groupedProducts[subcat];
                                    const isExpanded = expandedGroups.has(subcat);

                                    return (
                                        <React.Fragment key={subcat}>
                                            {/* Subcategory Header */}
                                            <tr 
                                                className="bg-gray-100 cursor-pointer hover:bg-gray-200 transition border-y border-gray-200"
                                                onClick={() => toggleGroupExpand(subcat)}
                                            >
                                                <td className="p-2 text-center text-gray-500">
                                                    {isExpanded ? <ChevronDown size={16}/> : <ChevronRight size={16}/>}
                                                </td>
                                                <td colSpan={5} className="p-2">
                                                    <div className="flex items-center gap-2 font-bold text-gray-800 uppercase text-xs tracking-wider">
                                                        {isExpanded ? <FolderOpen size={18} className="text-blue-600"/> : <Folder size={18} className="text-gray-400"/>}
                                                        {subcat}
                                                        <span className="ml-2 bg-white text-gray-600 px-2 py-0.5 rounded-full text-[10px] border border-gray-300 shadow-sm">
                                                            {items.length} produktov
                                                        </span>
                                                    </div>
                                                </td>
                                            </tr>
                                            {/* Items in Group */}
                                            {isExpanded && items.map(renderProductRow)}
                                        </React.Fragment>
                                    );
                                })}

                                {filteredProducts.length === 0 && (
                                    <tr>
                                        <td colSpan={6} className="text-center py-8 text-gray-400 italic">Žiadne produkty v tejto kategórii.</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* --- CATEGORIES TAB --- */}
            {activeTab === 'categories' && (
                <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
                    <div className="max-w-3xl mx-auto space-y-6">
                        {/* Add New Category */}
                        <div className="bg-white p-4 rounded-xl border border-purple-200 shadow-sm flex gap-2">
                            <input 
                                className="flex-1 border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-purple-500"
                                placeholder="Názov novej kategórie..."
                                value={newCategoryName}
                                onChange={e => setNewCategoryName(e.target.value)}
                            />
                            <button onClick={handleAddCategorySubmit} className="bg-purple-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-purple-700">
                                <Plus size={18}/> Pridať
                            </button>
                        </div>

                        {/* List */}
                        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="p-3 bg-gray-100 text-xs font-bold text-gray-500 uppercase border-b">Existujúce Kategórie</div>
                            <div className="divide-y divide-gray-100">
                                {customCategories.map(cat => (
                                    <div key={cat} className="p-4 flex justify-between items-center hover:bg-gray-50 group">
                                        <div className="flex items-center gap-3">
                                            <Layers className="text-gray-400" size={20}/>
                                            <span className="font-bold text-gray-800">{cat}</span>
                                            <span className="text-xs text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">
                                                {products.filter(p => p.category === cat).length} produktov
                                            </span>
                                        </div>
                                        <button onClick={() => onDeleteCategory(cat)} className="text-gray-300 hover:text-red-500 transition">
                                            <Trash2 size={18}/>
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* --- CLASSES TAB --- */}
            {activeTab === 'classes' && (
                <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
                    <div className="max-w-4xl mx-auto space-y-6">
                        <div className="bg-blue-50 p-4 rounded-lg border border-blue-100 text-sm text-blue-800 flex gap-2">
                            <AlertTriangle size={18} className="shrink-0"/>
                            <div>
                                Tu môžete definovať <strong>Triedy Kabín</strong> (napr. FUN, SKY, NEREZ).
                                Ku každej triede môžete priradiť <strong>SET Produkt</strong> z katalógu.
                                Ak je set priradený, Materiálový Sprievodca automaticky vloží tento set namiesto generickej kabíny.
                            </div>
                        </div>

                        {/* Add New Class */}
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <h3 className="font-bold text-lg mb-4 text-gray-800">Nová Trieda</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                <input 
                                    className="border rounded px-3 py-2" placeholder="Názov (napr. EXCLUSIVE)"
                                    value={newClassName} onChange={e => setNewClassName(e.target.value)}
                                />
                                <input 
                                    className="border rounded px-3 py-2" placeholder="Popis (napr. Sklo / Kameň)"
                                    value={newClassDesc} onChange={e => setNewClassDesc(e.target.value)}
                                />
                                <div className="md:col-span-2">
                                    <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Prepojený SET Produkt (Voliteľné)</label>
                                    <select 
                                        className="w-full border rounded px-3 py-2 text-sm bg-white"
                                        value={newClassLinkedSet}
                                        onChange={e => setNewClassLinkedSet(e.target.value)}
                                    >
                                        <option value="">-- Žiadne prepojenie --</option>
                                        {products.filter(p => p.type === 'composite').map(p => (
                                            <option key={p.id} value={p.id}>📦 {p.name} ({p.price}€)</option>
                                        ))}
                                    </select>
                                </div>
                            </div>
                            <button onClick={handleAddClassSubmit} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700">
                                Uložiť Triedu
                            </button>
                        </div>

                        {/* Classes List */}
                        <div className="space-y-2">
                            {cabinClasses.map(cc => {
                                const linkedProduct = products.find(p => p.id === cc.linkedProductId);
                                return (
                                    <div key={cc.id} className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex justify-between items-center group">
                                        <div>
                                            <div className="font-bold text-lg text-gray-800">{cc.name}</div>
                                            <div className="text-gray-500 text-sm">{cc.description}</div>
                                            {linkedProduct && (
                                                <div className="mt-2 text-xs bg-green-50 text-green-700 px-2 py-1 rounded inline-flex items-center gap-1 border border-green-100">
                                                    <Box size={12}/> Link: <strong>{linkedProduct.name}</strong>
                                                </div>
                                            )}
                                        </div>
                                        <button onClick={() => onDeleteCabinClass(cc.id)} className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded transition">
                                            <Trash2 size={20}/>
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
  QuoteData, QuoteCategory, QuoteItem, Product, Client, Supplier, QuoteTemplate, 
  ContractTemplate, AppSettings, LiftLayoutData, CabinClass, BackupData 
} from './types';
import { LoginGate } from './components/LoginGate';
import { CategoryTable } from './components/CategoryTable';
import { LiftLayoutSketch } from './components/LiftLayoutSketch';
import { TechSpecTable } from './components/TechSpecTable';
import { MaterialCalculatorModal } from './components/MaterialCalculatorModal';
import { SettingsModal } from './components/SettingsModal';
import { CatalogManagerModal } from './components/CatalogManagerModal';
import { ClientDatabaseModal } from './components/ClientDatabaseModal';
import { SupplierDatabaseModal } from './components/SupplierDatabaseModal';
import { TemplateDatabaseModal } from './components/TemplateDatabaseModal';
import { EmailModal } from './components/EmailModal';
import { ProductDatabaseModal } from './components/ProductDatabaseModal';
import { ContractRepositoryModal } from './components/ContractRepositoryModal';
import { StandaloneRichTextEditor } from './components/StandaloneRichTextEditor';
import { generateSuggestion } from './services/geminiService';
import { 
  Printer, Save, Trash2, Plus, Download, Mail, Copy, 
  Settings, User, Building, Package, ArrowLeft, LayoutTemplate, 
  FileText, Users, Calculator, Lightbulb, RefreshCw, PenTool, CheckCircle, FileCheck
} from 'lucide-react';

const defaultLayout: LiftLayoutData = {
  liftType: 'passenger', driveType: 'traction', ratedLoad: 630, numberOfPersons: 8, ratedSpeed: 1.0, powerSupply: '3x400V',
  shaftWidth: 1600, shaftDepth: 1800, cabinWidth: 1100, cabinDepth: 1400, doorWidth: 900, doorOffsetL: 0,
  pitDepth: 1100, headroomHeight: 3400, travelHeight: 15000,
  doorType: 'central', doorOperation: 'automatic', counterWeightPosition: 'back', machineRoomPosition: 'head',
  suspensionType: '1:1', tractionMedium: 'ropes', frameType: 'backpack',
  gapLeft: 50, gapRight: 50, gapRear: 50, gapFront: 50,
  guideTypeCar: 'T90', guideTypeCwt: 'T50', guideRailLength: 5000,
  notes: ''
};

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [quotes, setQuotes] = useState<QuoteData[]>([]);
  const [templates, setTemplates] = useState<QuoteTemplate[]>([]);
  const [contractTemplates, setContractTemplates] = useState<ContractTemplate[]>([]);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);
  const [customCategories, setCustomCategories] = useState<string[]>([
    'Pohon', 'Kabína a rám', 'Dvere', 'Vodítka a kotvenie', 'Obmedzovač', 
    'Elektro', 'Montáž', 'Ostatné šachta', 'Ostatné', 
    'Oceľová konštrukcia', 'Doprava', 'Balné'
  ]);
  const [settings, setSettings] = useState<AppSettings>({
    nextCpSequence: 100, nextObjSequence: 100, nextPlSequence: 100
  });

  const [activeQuote, setActiveQuote] = useState<QuoteData | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isTechSpecVisible, setIsTechSpecVisible] = useState(true);
  const [isSketchVisible, setIsSketchVisible] = useState(true);

  // Modal States
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isClientDbOpen, setIsClientDbOpen] = useState(false);
  const [isSupplierDbOpen, setIsSupplierDbOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [templateModalMode, setTemplateModalMode] = useState<'select' | 'save'>('select');
  const [templateModalType, setTemplateModalType] = useState<'lift' | 'shaft'>('lift');
  const [isProductDbOpen, setIsProductDbOpen] = useState(false);
  const [activeCategoryForProduct, setActiveCategoryForProduct] = useState<string | null>(null);
  const [activeItemForProduct, setActiveItemForProduct] = useState<string | null>(null);
  const [isMaterialCalcOpen, setIsMaterialCalcOpen] = useState(false);
  const [isEmailOpen, setIsEmailOpen] = useState(false);
  const [isContractRepoOpen, setIsContractRepoOpen] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('smartquote_data');
    if (saved) {
        try {
            const data = JSON.parse(saved);
            if (data.products) setProducts(data.products);
            if (data.clients) setClients(data.clients);
            if (data.suppliers) setSuppliers(data.suppliers);
            if (data.quotes) setQuotes(data.quotes);
            if (data.templates) setTemplates(data.templates);
            if (data.contractTemplates) setContractTemplates(data.contractTemplates);
            if (data.cabinClasses) setCabinClasses(data.cabinClasses);
            if (data.customCategories) setCustomCategories(data.customCategories);
            if (data.settings) setSettings(data.settings);
        } catch (e) { console.error("Failed to load", e); }
    }
  }, []);

  useEffect(() => {
      const data = { products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings };
      localStorage.setItem('smartquote_data', JSON.stringify(data));
  }, [products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings]);

  // --- ACTIONS ---

  const handleCreateQuote = () => {
    const newQuote: QuoteData = {
      id: crypto.randomUUID(),
      number: `CP_SK_${settings.nextCpSequence}_${new Date().getFullYear().toString().slice(-2)}_BA`,
      type: 'quote',
      title: 'Nová Cenová Ponuka',
      date: new Date().toISOString().split('T')[0],
      validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
      supplier: { name: '', details: '' },
      client: { name: '', details: '' },
      categories: customCategories.map(name => ({ id: crypto.randomUUID(), type: 'items', name, items: [], isExpanded: true, section: 'lift' })),
      currency: '€',
      globalMargin: 10,
      shaftMargin: 10,
      terms: '',
      layout: { ...defaultLayout }
    };
    setActiveQuote(newQuote);
    setSettings(prev => ({...prev, nextCpSequence: prev.nextCpSequence + 1}));
  };

  const handleSaveQuote = () => {
    if (!activeQuote) return;
    const updated = { ...activeQuote, lastUpdated: Date.now() };
    setQuotes(prev => {
        const idx = prev.findIndex(q => q.id === updated.id);
        if (idx >= 0) {
            const copy = [...prev]; copy[idx] = updated; return copy;
        }
        return [...prev, updated];
    });
    alert('Ponuka bola uložená.');
  };

  const handleDeleteQuote = (id: string) => {
      if(window.confirm("Naozaj vymazať ponuku?")) {
          setQuotes(prev => prev.filter(q => q.id !== id));
      }
  };

  const calculateTotals = () => {
      if (!activeQuote) return { cost: 0, price: 0, profit: 0 };
      let totalCost = 0;
      let totalPrice = 0;

      activeQuote.categories.forEach(cat => {
          if (cat.isHidden) return; // Skip completely hidden
          cat.items.forEach(item => {
               const quantity = item.quantity || 0;
               const unitPrice = item.unitPrice || 0;
               const cost = quantity * unitPrice;

               // Apply correct margin based on section
               const margin = cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin;
               const price = cost * (1 + margin / 100);

               totalCost += cost;
               totalPrice += price;
          });
      });

      return { cost: totalCost, price: totalPrice, profit: totalPrice - totalCost };
  };

  // --- ITEM HANDLERS ---
  const handleUpdateCategory = (id: string, field: keyof QuoteCategory, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => c.id === id ? { ...c, [field]: value } : c)
      });
  };

  const handleAddItem = (catId: string, isSurcharge = false) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: [...c.items, {
                      id: crypto.randomUUID(),
                      description: isSurcharge ? 'Príplatok: ' : '',
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20,
                      isSurcharge
                  }]
              };
          })
      });
  };

  const handleUpdateItem = (catId: string, itemId: string, field: keyof QuoteItem, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: c.items.map(i => i.id === itemId ? { ...i, [field]: value } : i)
              };
          })
      });
  };

  const handleSelectProduct = (product: Product) => {
      if (!activeQuote || !activeCategoryForProduct) return;

      const targetCatId = activeCategoryForProduct;
      const targetItemId = activeItemForProduct; // If replacing specific item

      setActiveQuote(prev => {
        if (!prev) return null;
        return {
            ...prev,
            categories: prev.categories.map(cat => {
                if (cat.id !== targetCatId) return cat;

                // Case A: Replacing existing item
                if (targetItemId) {
                    return {
                        ...cat,
                        items: cat.items.map(item => {
                            if (item.id !== targetItemId) return item;
                            return {
                                ...item,
                                description: product.name,
                                unit: product.unit,
                                unitPrice: product.price,
                                purchasePrice: product.price
                            };
                        })
                    };
                }

                // Case B: Adding new item
                return {
                    ...cat,
                    items: [...cat.items, {
                        id: crypto.randomUUID(),
                        description: product.name,
                        quantity: 1,
                        unit: product.unit,
                        unitPrice: product.price,
                        purchasePrice: product.price,
                        vatRate: 20
                    }]
                };
            })
        };
      });
      setIsProductDbOpen(false);
      setActiveItemForProduct(null);
  };

  // --- AI HANDLERS ---
  const handleAiSuggest = async (catId: string, catName: string) => {
      setIsAiLoading(true);
      const text = await generateSuggestion(`Navrhni 3 položky pre kategóriu "${catName}" pre výťah.`, 'category_items');
      setIsAiLoading(false);
      if (text) {
          const lines = text.split(',').map(s => s.trim()).filter(s => s);
          if (!activeQuote) return;
          setActiveQuote({
              ...activeQuote,
              categories: activeQuote.categories.map(c => {
                  if (c.id !== catId) return c;
                  const newItems = lines.map(desc => ({
                      id: crypto.randomUUID(),
                      description: desc,
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20
                  }));
                  return { ...c, items: [...c.items, ...newItems] };
              })
          });
      }
  };

  const handleGenerateTerms = async () => {
      setIsAiLoading(true);
      const text = await generateSuggestion("Navrhni obchodné podmienky pre inštaláciu výťahu.", 'terms');
      setIsAiLoading(false);
      if (activeQuote && text) setActiveQuote({ ...activeQuote, terms: text });
  };

  // --- MATERIAL WIZARD ---
  const handleMaterialInsert = (data: any) => {
    if (!activeQuote) return;

    // Create map of existing categories by name to find IDs
    const catMap = new Map(activeQuote.categories.map(c => [c.name, c.id]));

    // Prepare updates
    let updatedCategories = [...activeQuote.categories];

    // Helper to find or create category
    const getCatId = (name: string) => {
        if (catMap.has(name)) return catMap.get(name)!;
        // Create if missing
        const newId = crypto.randomUUID();
        const newCat: QuoteCategory = { 
            id: newId, 
            type: 'items', 
            name: name, 
            items: [], 
            isExpanded: true,
            section: name === 'Oceľová konštrukcia' || name === 'Ostatné šachta' ? 'shaft' : 'lift'
        };
        updatedCategories.push(newCat);
        catMap.set(name, newId);
        return newId;
    };

    // Clear existing items in target categories IF they are being overwritten? 
    // No, usually we append or user clears manually. Let's append for safety.

    data.items.forEach((item: any) => {
        const catId = getCatId(item.category);
        const catIndex = updatedCategories.findIndex(c => c.id === catId);
        if (catIndex >= 0) {
            updatedCategories[catIndex].items.push({
                id: crypto.randomUUID(),
                description: item.description,
                quantity: item.quantity,
                unit: item.unit,
                unitPrice: item.price || 0,
                purchasePrice: item.price || 0,
                vatRate: 20
            });
        }
    });

    // Addons
    if (data.includeTransport) {
        const cid = getCatId('Doprava');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: crypto.randomUUID(), description: 'Doprava materiálu na stavbu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includePackaging) {
        const cid = getCatId('Balné');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: crypto.randomUUID(), description: 'Balné a palety', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includeAssembly) {
        const cid = getCatId('Montáž');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: crypto.randomUUID(), description: 'Montáž technológie výťahu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }

    setActiveQuote({ ...activeQuote, categories: updatedCategories });
  };

  // --- TEMPLATES & EXPORT ---
  const handlePrint = () => window.print();

  const handleSaveTemplate = (name: string, type: 'lift' | 'shaft') => {
      if (!activeQuote) return;
      const newTemplate: QuoteTemplate = {
          id: crypto.randomUUID(),
          name,
          type,
          data: {
              categories: activeQuote.categories.map(c => ({...c})), // Deep copy needed in real app
              layout: activeQuote.layout,
              margin: activeQuote.globalMargin
          }
      };
      setTemplates([...templates, newTemplate]);
  };

  const handleApplyTemplate = (t: QuoteTemplate) => {
      if (!activeQuote) return;
      // Merge categories
      // Ideally we replace or append. Let's replace items if category exists
      const newCats = [...activeQuote.categories];
      t.data.categories.forEach(tc => {
          const existing = newCats.find(c => c.name === tc.name);
          if (existing) {
              existing.items = [...existing.items, ...tc.items]; // Append
          } else {
              newCats.push({ ...tc, id: crypto.randomUUID() });
          }
      });

      setActiveQuote({
          ...activeQuote,
          categories: newCats,
          layout: t.data.layout ? { ...activeQuote.layout, ...t.data.layout } : activeQuote.layout,
          globalMargin: t.data.margin || activeQuote.globalMargin
      });
      setIsTemplateModalOpen(false);
  };

  // --- RENDER ---

  if (!isAuthenticated) return <LoginGate onLogin={() => setIsAuthenticated(true)} />;

  if (!activeQuote) {
      return (
        <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
            <header className="bg-white border-b px-6 py-3 flex justify-between items-center sticky top-0 z-40 shadow-sm">
                <div className="flex items-center gap-2">
                    <div className="bg-blue-600 text-white p-1.5 rounded font-bold">SQ</div>
                    <h1 className="font-bold text-xl tracking-tight">SmartQuote SK</h1>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setIsClientDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Klienti"><Users size={20}/></button>
                    <button onClick={() => setIsSupplierDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Dodávatelia"><Building size={20}/></button>
                    <button onClick={() => setIsCatalogOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Katalóg"><Package size={20}/></button>
                    <button onClick={() => setIsSettingsOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Nastavenia"><Settings size={20}/></button>
                </div>
            </header>

            <main className="p-6 max-w-7xl mx-auto">
                 <div className="text-center py-16">
                     <h2 className="text-3xl font-bold text-gray-800 mb-4">Dashboard</h2>
                     <p className="text-gray-500 mb-8">Vitajte v systéme pre tvorbu cenových ponúk výťahov.</p>
                     <button onClick={handleCreateQuote} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold shadow hover:bg-blue-700 flex items-center gap-2 mx-auto transition transform hover:scale-105">
                        <Plus size={20}/> Nová Ponuka
                     </button>
                 </div>

                 <div className="mt-8">
                     <h3 className="text-lg font-bold text-gray-700 mb-4">Posledné ponuky</h3>
                     {quotes.length === 0 ? (
                         <div className="text-center p-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-400 italic">
                             Zatiaľ žiadne ponuky.
                         </div>
                     ) : (
                         <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                             {quotes.map(q => (
                                 <div key={q.id} className="bg-white p-4 rounded-xl border hover:border-blue-400 shadow-sm transition group cursor-pointer" onClick={() => setActiveQuote(q)}>
                                     <div className="flex justify-between items-start mb-2">
                                         <div className="font-bold text-blue-600">{q.number}</div>
                                         <button onClick={(e) => {e.stopPropagation(); handleDeleteQuote(q.id);}} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                                     </div>
                                     <div className="font-bold text-gray-800 mb-1">{q.title}</div>
                                     <div className="text-sm text-gray-500 mb-2">{q.client.name || 'Bez klienta'}</div>
                                     <div className="text-xs text-gray-400">{q.date}</div>
                                 </div>
                             ))}
                         </div>
                     )}
                 </div>
            </main>

            {/* GLOBAL MODALS (When no quote is active) */}
            {isSettingsOpen && <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} onSaveSettings={setSettings} onExportData={() => {}} onImportData={() => {}} onFactoryReset={() => {}} appVersion="1.0.0" />}
            {isCatalogOpen && <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={p => setProducts([...products, p])} onUpdateProduct={p => setProducts(products.map(pr => pr.id === p.id ? p : pr))} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} onDeleteCategory={c => setCustomCategories(customCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={c => setCabinClasses([...cabinClasses, c])} onUpdateCabinClass={c => setCabinClasses(cabinClasses.map(cc => cc.id === c.id ? c : cc))} onDeleteCabinClass={id => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />}
            {isClientDbOpen && <ClientDatabaseModal isOpen={isClientDbOpen} onClose={() => setIsClientDbOpen(false)} clients={clients} onSelectClient={() => {}} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />}
            {isSupplierDbOpen && <SupplierDatabaseModal isOpen={isSupplierDbOpen} onClose={() => setIsSupplierDbOpen(false)} suppliers={suppliers} onSelectSupplier={() => {}} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />}
        </div>
      );
  }

  // --- EDITOR VIEW ---
  const totals = calculateTotals();

  return (
    <div className="min-h-screen bg-gray-100 text-gray-900 font-sans pb-32 print:pb-0 print:bg-white">
        {/* Editor Toolbar */}
        <header className="bg-white border-b px-4 py-2 sticky top-0 z-40 shadow-sm print:hidden flex justify-between items-center">
            <div className="flex items-center gap-4">
                <button onClick={() => setActiveQuote(null)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Späť na Dashboard"><ArrowLeft size={20}/></button>
                <div>
                    <div className="font-bold text-sm text-gray-500">{activeQuote.number}</div>
                    <input 
                        className="font-bold text-gray-800 bg-transparent outline-none focus:border-b border-blue-500 w-64"
                        value={activeQuote.title}
                        onChange={e => setActiveQuote({...activeQuote, title: e.target.value})}
                    />
                </div>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setIsMaterialCalcOpen(true)} className="p-2 text-orange-600 bg-orange-50 hover:bg-orange-100 rounded font-bold flex items-center gap-2 text-sm"><Calculator size={16}/> Materiál</button>
                <div className="w-px bg-gray-300 mx-2"></div>
                <button onClick={handleSaveQuote} className="p-2 text-blue-600 hover:bg-blue-50 rounded" title="Uložiť"><Save size={20}/></button>
                <button onClick={handlePrint} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Tlačiť"><Printer size={20}/></button>
                <button onClick={() => setIsEmailOpen(true)} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Email"><Mail size={20}/></button>
            </div>
        </header>

        <main className="max-w-[210mm] mx-auto bg-white shadow-lg min-h-screen my-8 p-8 print:shadow-none print:m-0 print:p-0 print:w-full">

            {/* Header / Info */}
            <div className="flex justify-between mb-8 print:mb-4">
                <div className="w-1/2 pr-4">
                    <h1 className="text-2xl font-bold text-blue-800 mb-4">{activeQuote.title}</h1>
                    <div className="space-y-4">
                         {/* Supplier */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsSupplierDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Dodávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Firma..." value={activeQuote.supplier.name} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.supplier.details} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, details: e.target.value}})} />
                         </div>
                         {/* Client */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsClientDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Objednávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Klient..." value={activeQuote.client.name} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.client.details} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, details: e.target.value}})} />
                         </div>
                    </div>
                </div>
                <div className="w-1/2 pl-4 text-right">
                    {/* Meta Data */}
                    <div className="space-y-1 mb-6 text-sm">
                        <div><span className="text-gray-500">Číslo ponuky:</span> <span className="font-bold">{activeQuote.number}</span></div>
                        <div><span className="text-gray-500">Dátum:</span> <input type="date" value={activeQuote.date} onChange={e => setActiveQuote({...activeQuote, date: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                        <div><span className="text-gray-500">Platnosť do:</span> <input type="date" value={activeQuote.validUntil} onChange={e => setActiveQuote({...activeQuote, validUntil: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                    </div>
                    {/* Lift Sketch */}
                    <div className="border border-gray-200 rounded-lg p-2 inline-block bg-white print:border-none">
                         <LiftLayoutSketch 
                            data={activeQuote.layout || defaultLayout} 
                            onChange={(f,v) => activeQuote.layout && setActiveQuote({...activeQuote, layout: {...activeQuote.layout, [f]: v}})}
                            isVisible={isSketchVisible}
                            onToggleVisibility={() => setIsSketchVisible(!isSketchVisible)}
                        />
                    </div>
                </div>
            </div>

            {/* Technical Specs */}
            {activeQuote.layout && (
                <TechSpecTable 
                    data={activeQuote.layout} 
                    isVisible={isTechSpecVisible} 
                    onToggleVisibility={() => setIsTechSpecVisible(!isTechSpecVisible)} 
                />
            )}

            {/* Category Tables */}
            <div className="space-y-6 mt-8">
                {activeQuote.categories.map((cat, idx) => (
                    <CategoryTable 
                        key={cat.id}
                        category={cat}
                        currency={activeQuote.currency}
                        globalMargin={cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin}
                        onUpdateCategory={handleUpdateCategory}
                        onDeleteCategory={() => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.filter(c => c.id !== cat.id)});
                        }}
                        onAddItem={(catId, isSurcharge) => handleAddItem(catId, isSurcharge)}
                        onUpdateItem={handleUpdateItem}
                        onDeleteItem={(catId, itemId) => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.map(c => c.id === catId ? {...c, items: c.items.filter(i => i.id !== itemId)} : c)})
                        }}
                        onAiSuggest={handleAiSuggest}
                        onOpenCatalog={(catId, itemId) => {
                             setActiveCategoryForProduct(catId);
                             setActiveItemForProduct(itemId || null);
                             setIsProductDbOpen(true);
                        }}
                        onMoveCategory={(id, dir) => {
                            const cats = [...activeQuote.categories];
                            const index = cats.findIndex(c => c.id === id);
                            if (dir === 'up' && index > 0) {
                                [cats[index], cats[index-1]] = [cats[index-1], cats[index]];
                            } else if (dir === 'down' && index < cats.length - 1) {
                                [cats[index], cats[index+1]] = [cats[index+1], cats[index]];
                            }
                            setActiveQuote({...activeQuote, categories: cats});
                        }}
                        isAiLoading={isAiLoading}
                    />
                ))}

                {/* Add Category Button */}
                <div className="no-print border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-blue-400 transition cursor-pointer" onClick={() => {
                    const name = prompt("Názov novej kategórie:");
                    if (name) {
                        const newCat: QuoteCategory = { id: crypto.randomUUID(), type: 'items', name, items: [], isExpanded: true, section: 'lift' };
                        setActiveQuote({...activeQuote, categories: [...activeQuote.categories, newCat]});
                    }
                }}>
                    <div className="text-gray-500 font-bold flex items-center justify-center gap-2"><Plus/> Pridať Kategóriu</div>
                </div>
            </div>

            {/* Totals */}
            <div className="mt-12 border-t-2 border-gray-800 pt-4 flex justify-end print:break-inside-avoid">
                <div className="w-64">
                    <div className="flex justify-between mb-2 text-sm text-gray-500 no-print">
                        <span>Náklady (bez DPH):</span>
                        <span>{totals.cost.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between mb-2 text-sm text-green-600 no-print">
                        <span>Zisk ({((totals.profit/totals.cost)*100 || 0).toFixed(1)}%):</span>
                        <span>{totals.profit.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between text-xl font-bold text-gray-900 border-t pt-2">
                        <span>Cena Celkom:</span>
                        <span>{totals.price.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="text-right text-xs text-gray-500 mt-1">bez DPH</div>
                </div>
            </div>

            {/* Terms & Conditions */}
            <div className="mt-12 print:break-inside-avoid">
                <div className="flex justify-between items-center mb-4 no-print">
                    <h3 className="font-bold uppercase text-sm">Obchodné podmienky</h3>
                    <div className="flex gap-2">
                        <button onClick={handleGenerateTerms} disabled={isAiLoading} className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded hover:bg-yellow-200 flex items-center gap-1"><Lightbulb size={12}/> AI Návrh</button>
                        <button onClick={() => setIsContractRepoOpen(true)} className="text-xs bg-gray-100 text-gray-800 px-2 py-1 rounded hover:bg-gray-200 flex items-center gap-1"><FileText size={12}/> Zo Šablóny</button>
                    </div>
                </div>
                <StandaloneRichTextEditor 
                    content={activeQuote.terms} 
                    onChange={val => setActiveQuote({...activeQuote, terms: val})}
                    placeholder="Sem vložte text obchodných podmienok..."
                />
            </div>

            {/* Signature Area */}
            <div className="mt-16 flex justify-between print:break-inside-avoid text-sm">
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Objednávateľ)</div>
                </div>
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Dodávateľ)</div>
                </div>
            </div>
        </main>

        {/* Editor Modals */}
        {isProductDbOpen && <ProductDatabaseModal isOpen={isProductDbOpen} onClose={() => setIsProductDbOpen(false)} products={products} onSelectProduct={handleSelectProduct} onAddProduct={p => setProducts([...products, p])} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} layout={activeQuote.layout} />}
        {isMaterialCalcOpen && activeQuote.layout && <MaterialCalculatorModal isOpen={isMaterialCalcOpen} onClose={() => setIsMaterialCalcOpen(false)} layout={activeQuote.layout} onInsert={handleMaterialInsert} products={products} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} cabinClasses={cabinClasses} />}
        {isEmailOpen && <EmailModal isOpen={isEmailOpen} onClose={() => setIsEmailOpen(false)} onSend={(to, sub, msg) => window.open(`mailto:${to}?subject=${encodeURIComponent(sub)}&body=${encodeURIComponent(msg)}`)} defaultTo={activeQuote.client.email} defaultSubject={`Cenová ponuka ${activeQuote.number}`} defaultMessage={`Dobrý deň,\n\nv prílohe posielame cenovú ponuku č. ${activeQuote.number}.\n\nS pozdravom,\n${activeQuote.supplier.name}`} />}
        {isSupplierDbOpen && <SupplierDatabaseModal isOpen={isSupplierDbOpen} onClose={() => setIsSupplierDbOpen(false)} suppliers={suppliers} onSelectSupplier={s => setActiveQuote({...activeQuote, supplier: { name: s.name, details: s.details, email: s.email, phone: s.phone }})} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />}
        {isClientDbOpen && <ClientDatabaseModal isOpen={isClientDbOpen} onClose={() => setIsClientDbOpen(false)} clients={clients} onSelectClient={c => setActiveQuote({...activeQuote, client: { name: c.name, details: c.details, email: c.email, phone: c.phone }})} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />}
        {isContractRepoOpen && <ContractRepositoryModal isOpen={isContractRepoOpen} onClose={() => setIsContractRepoOpen(false)} templates={contractTemplates} onSelectTemplate={content => setActiveQuote({...activeQuote, terms: content})} onSaveCurrent={name => setContractTemplates([...contractTemplates, { id: crypto.randomUUID(), name, content: activeQuote.terms }])} onDeleteTemplate={id => setContractTemplates(contractTemplates.filter(t => t.id !== id))} />}

    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
  QuoteData, QuoteCategory, QuoteItem, Product, Client, Supplier, QuoteTemplate, 
  ContractTemplate, AppSettings, LiftLayoutData, CabinClass, BackupData 
} from './types';
import { LoginGate } from './components/LoginGate';
import { CategoryTable } from './components/CategoryTable';
import { LiftLayoutSketch } from './components/LiftLayoutSketch';
import { TechSpecTable } from './components/TechSpecTable';
import { MaterialCalculatorModal } from './components/MaterialCalculatorModal';
import { SettingsModal } from './components/SettingsModal';
import { CatalogManagerModal } from './components/CatalogManagerModal';
import { ClientDatabaseModal } from './components/ClientDatabaseModal';
import { SupplierDatabaseModal } from './components/SupplierDatabaseModal';
import { TemplateDatabaseModal } from './components/TemplateDatabaseModal';
import { EmailModal } from './components/EmailModal';
import { ProductDatabaseModal } from './components/ProductDatabaseModal';
import { ContractRepositoryModal } from './components/ContractRepositoryModal';
import { StandaloneRichTextEditor } from './components/StandaloneRichTextEditor';
import { generateSuggestion } from './services/geminiService';
import { 
  Printer, Save, Trash2, Plus, Download, Mail, Copy, 
  Settings, User, Building, Package, ArrowLeft, LayoutTemplate, 
  FileText, Users, Calculator, Lightbulb, RefreshCw, PenTool, CheckCircle, FileCheck, Search
} from 'lucide-react';

const defaultLayout: LiftLayoutData = {
  liftType: 'passenger', driveType: 'traction', ratedLoad: 630, numberOfPersons: 8, ratedSpeed: 1.0, powerSupply: '3x400V',
  shaftWidth: 1600, shaftDepth: 1800, cabinWidth: 1100, cabinDepth: 1400, doorWidth: 900, doorOffsetL: 0,
  pitDepth: 1100, headroomHeight: 3400, travelHeight: 15000,
  doorType: 'central', doorOperation: 'automatic', counterWeightPosition: 'back', machineRoomPosition: 'head',
  suspensionType: '1:1', tractionMedium: 'ropes', frameType: 'backpack',
  gapLeft: 50, gapRight: 50, gapRear: 50, gapFront: 50,
  guideTypeCar: 'T90', guideTypeCwt: 'T50', guideRailLength: 5000,
  notes: ''
};

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [quotes, setQuotes] = useState<QuoteData[]>([]);
  const [templates, setTemplates] = useState<QuoteTemplate[]>([]);
  const [contractTemplates, setContractTemplates] = useState<ContractTemplate[]>([]);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);
  const [customCategories, setCustomCategories] = useState<string[]>([
    'Pohon', 'Kabína a rám', 'Dvere', 'Vodítka a kotvenie', 'Obmedzovač', 
    'Elektro', 'Montáž', 'Ostatné šachta', 'Ostatné', 
    'Oceľová konštrukcia', 'Doprava', 'Balné'
  ]);
  const [settings, setSettings] = useState<AppSettings>({
    nextCpSequence: 100, nextObjSequence: 100, nextPlSequence: 100
  });

  const [activeQuote, setActiveQuote] = useState<QuoteData | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isTechSpecVisible, setIsTechSpecVisible] = useState(true);
  const [isSketchVisible, setIsSketchVisible] = useState(true);

  // Modal States
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isClientDbOpen, setIsClientDbOpen] = useState(false);
  const [isSupplierDbOpen, setIsSupplierDbOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [templateModalMode, setTemplateModalMode] = useState<'select' | 'save'>('select');
  const [templateModalType, setTemplateModalType] = useState<'lift' | 'shaft'>('lift');
  const [isProductDbOpen, setIsProductDbOpen] = useState(false);
  const [activeCategoryForProduct, setActiveCategoryForProduct] = useState<string | null>(null);
  const [activeItemForProduct, setActiveItemForProduct] = useState<string | null>(null);
  const [isMaterialCalcOpen, setIsMaterialCalcOpen] = useState(false);
  const [isEmailOpen, setIsEmailOpen] = useState(false);
  const [isContractRepoOpen, setIsContractRepoOpen] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('smartquote_data');
    if (saved) {
        try {
            const data = JSON.parse(saved);
            if (data.products) setProducts(data.products);
            if (data.clients) setClients(data.clients);
            if (data.suppliers) setSuppliers(data.suppliers);
            if (data.quotes) setQuotes(data.quotes);
            if (data.templates) setTemplates(data.templates);
            if (data.contractTemplates) setContractTemplates(data.contractTemplates);
            if (data.cabinClasses) setCabinClasses(data.cabinClasses);
            if (data.customCategories) setCustomCategories(data.customCategories);
            if (data.settings) setSettings(data.settings);
        } catch (e) { console.error("Failed to load", e); }
    }
  }, []);

  useEffect(() => {
      const data = { products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings };
      localStorage.setItem('smartquote_data', JSON.stringify(data));
  }, [products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings]);

  // --- ACTIONS ---

  const handleCreateQuote = () => {
    const newQuote: QuoteData = {
      id: crypto.randomUUID(),
      number: `CP_SK_${settings.nextCpSequence}_${new Date().getFullYear().toString().slice(-2)}_BA`,
      type: 'quote',
      title: 'Nová Cenová Ponuka',
      date: new Date().toISOString().split('T')[0],
      validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
      supplier: { name: '', details: '' },
      client: { name: '', details: '' },
      categories: customCategories.map(name => ({ id: crypto.randomUUID(), type: 'items', name, items: [], isExpanded: true, section: 'lift' })),
      currency: '€',
      globalMargin: 10,
      shaftMargin: 10,
      terms: '',
      layout: { ...defaultLayout }
    };
    setActiveQuote(newQuote);
    setSettings(prev => ({...prev, nextCpSequence: prev.nextCpSequence + 1}));
  };

  const handleSaveQuote = () => {
    if (!activeQuote) return;
    const updated = { ...activeQuote, lastUpdated: Date.now() };
    setQuotes(prev => {
        const idx = prev.findIndex(q => q.id === updated.id);
        if (idx >= 0) {
            const copy = [...prev]; copy[idx] = updated; return copy;
        }
        return [...prev, updated];
    });
    alert('Ponuka bola uložená.');
  };

  const handleDeleteQuote = (id: string) => {
      if(window.confirm("Naozaj vymazať ponuku?")) {
          setQuotes(prev => prev.filter(q => q.id !== id));
      }
  };

  const calculateTotals = () => {
      if (!activeQuote) return { cost: 0, price: 0, profit: 0 };
      let totalCost = 0;
      let totalPrice = 0;

      activeQuote.categories.forEach(cat => {
          if (cat.isHidden) return; // Skip completely hidden
          cat.items.forEach(item => {
               const quantity = item.quantity || 0;
               const unitPrice = item.unitPrice || 0;
               const cost = quantity * unitPrice;

               // Apply correct margin based on section
               const margin = cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin;
               const price = cost * (1 + margin / 100);

               totalCost += cost;
               totalPrice += price;
          });
      });

      return { cost: totalCost, price: totalPrice, profit: totalPrice - totalCost };
  };

  // --- ITEM HANDLERS ---
  const handleUpdateCategory = (id: string, field: keyof QuoteCategory, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => c.id === id ? { ...c, [field]: value } : c)
      });
  };

  const handleAddItem = (catId: string, isSurcharge = false) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: [...c.items, {
                      id: crypto.randomUUID(),
                      description: isSurcharge ? 'Príplatok: ' : '',
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20,
                      isSurcharge
                  }]
              };
          })
      });
  };

  const handleUpdateItem = (catId: string, itemId: string, field: keyof QuoteItem, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: c.items.map(i => i.id === itemId ? { ...i, [field]: value } : i)
              };
          })
      });
  };

  const handleSelectProduct = (product: Product) => {
      if (!activeQuote || !activeCategoryForProduct) return;

      const targetCatId = activeCategoryForProduct;
      const targetItemId = activeItemForProduct; // If replacing specific item

      setActiveQuote(prev => {
        if (!prev) return null;
        return {
            ...prev,
            categories: prev.categories.map(cat => {
                if (cat.id !== targetCatId) return cat;

                // Case A: Replacing existing item
                if (targetItemId) {
                    return {
                        ...cat,
                        items: cat.items.map(item => {
                            if (item.id !== targetItemId) return item;
                            return {
                                ...item,
                                description: product.name,
                                unit: product.unit,
                                unitPrice: product.price,
                                purchasePrice: product.price
                            };
                        })
                    };
                }

                // Case B: Adding new item
                return {
                    ...cat,
                    items: [...cat.items, {
                        id: crypto.randomUUID(),
                        description: product.name,
                        quantity: 1,
                        unit: product.unit,
                        unitPrice: product.price,
                        purchasePrice: product.price,
                        vatRate: 20
                    }]
                };
            })
        };
      });
      setIsProductDbOpen(false);
      setActiveItemForProduct(null);
  };

  // --- AI HANDLERS ---
  const handleAiSuggest = async (catId: string, catName: string) => {
      setIsAiLoading(true);
      const text = await generateSuggestion(`Navrhni 3 položky pre kategóriu "${catName}" pre výťah.`, 'category_items');
      setIsAiLoading(false);
      if (text) {
          const lines = text.split(',').map(s => s.trim()).filter(s => s);
          if (!activeQuote) return;
          setActiveQuote({
              ...activeQuote,
              categories: activeQuote.categories.map(c => {
                  if (c.id !== catId) return c;
                  const newItems = lines.map(desc => ({
                      id: crypto.randomUUID(),
                      description: desc,
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20
                  }));
                  return { ...c, items: [...c.items, ...newItems] };
              })
          });
      }
  };

  const handleGenerateTerms = async () => {
      setIsAiLoading(true);
      const text = await generateSuggestion("Navrhni obchodné podmienky pre inštaláciu výťahu.", 'terms');
      setIsAiLoading(false);
      if (activeQuote && text) setActiveQuote({ ...activeQuote, terms: text });
  };

  // --- MATERIAL WIZARD ---
  const handleMaterialInsert = (data: any) => {
    if (!activeQuote) return;

    // Create map of existing categories by name to find IDs
    const catMap = new Map(activeQuote.categories.map(c => [c.name, c.id]));

    // Prepare updates
    let updatedCategories = [...activeQuote.categories];

    // Helper to find or create category
    const getCatId = (name: string) => {
        if (catMap.has(name)) return catMap.get(name)!;
        // Create if missing
        const newId = crypto.randomUUID();
        const newCat: QuoteCategory = { 
            id: newId, 
            type: 'items', 
            name: name, 
            items: [], 
            isExpanded: true, 
            section: name === 'Oceľová konštrukcia' || name === 'Ostatné šachta' ? 'shaft' : 'lift'
        };
        updatedCategories.push(newCat);
        catMap.set(name, newId);
        return newId;
    };

    // Clear existing items in target categories IF they are being overwritten? 
    // No, usually we append or user clears manually. Let's append for safety.

    data.items.forEach((item: any) => {
        const catId = getCatId(item.category);
        const catIndex = updatedCategories.findIndex(c => c.id === catId);
        if (catIndex >= 0) {
            updatedCategories[catIndex].items.push({
                id: crypto.randomUUID(),
                description: item.description,
                quantity: item.quantity,
                unit: item.unit,
                unitPrice: item.price || 0,
                purchasePrice: item.price || 0,
                vatRate: 20
            });
        }
    });

    // Addons
    if (data.includeTransport) {
        const cid = getCatId('Doprava');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: crypto.randomUUID(), description: 'Doprava materiálu na stavbu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includePackaging) {
        const cid = getCatId('Balné');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: crypto.randomUUID(), description: 'Balné a palety', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includeAssembly) {
        const cid = getCatId('Montáž');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: crypto.randomUUID(), description: 'Montáž technológie výťahu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }

    setActiveQuote({ ...activeQuote, categories: updatedCategories });
  };

  // --- TEMPLATES & EXPORT ---
  const handlePrint = () => window.print();

  const handleSaveTemplate = (name: string, type: 'lift' | 'shaft') => {
      if (!activeQuote) return;
      const newTemplate: QuoteTemplate = {
          id: crypto.randomUUID(),
          name,
          type,
          data: {
              categories: activeQuote.categories.map(c => ({...c})), // Deep copy needed in real app
              layout: activeQuote.layout,
              margin: activeQuote.globalMargin
          }
      };
      setTemplates([...templates, newTemplate]);
  };

  const handleApplyTemplate = (t: QuoteTemplate) => {
      if (!activeQuote) return;
      // Merge categories
      // Ideally we replace or append. Let's replace items if category exists
      const newCats = [...activeQuote.categories];
      t.data.categories.forEach(tc => {
          const existing = newCats.find(c => c.name === tc.name);
          if (existing) {
              existing.items = [...existing.items, ...tc.items]; // Append
          } else {
              newCats.push({ ...tc, id: crypto.randomUUID() });
          }
      });

      setActiveQuote({
          ...activeQuote,
          categories: newCats,
          layout: t.data.layout ? { ...activeQuote.layout, ...t.data.layout } : activeQuote.layout,
          globalMargin: t.data.margin || activeQuote.globalMargin
      });
      setIsTemplateModalOpen(false);
  };

  // --- RENDER ---

  if (!isAuthenticated) return <LoginGate onLogin={() => setIsAuthenticated(true)} />;

  if (!activeQuote) {
      return (
        <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
            <header className="bg-white border-b px-6 py-3 flex justify-between items-center sticky top-0 z-40 shadow-sm">
                <div className="flex items-center gap-2">
                    <div className="bg-blue-600 text-white p-1.5 rounded font-bold">SQ</div>
                    <h1 className="font-bold text-xl tracking-tight">SmartQuote SK</h1>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setIsClientDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Klienti"><Users size={20}/></button>
                    <button onClick={() => setIsSupplierDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Dodávatelia"><Building size={20}/></button>
                    <button onClick={() => setIsCatalogOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Katalóg"><Package size={20}/></button>
                    <button onClick={() => setIsSettingsOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Nastavenia"><Settings size={20}/></button>
                </div>
            </header>

            <main className="p-6 max-w-7xl mx-auto">
                 <div className="text-center py-16">
                     <h2 className="text-3xl font-bold text-gray-800 mb-4">Dashboard</h2>
                     <p className="text-gray-500 mb-8">Vitajte v systéme pre tvorbu cenových ponúk výťahov.</p>
                     <button onClick={handleCreateQuote} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold shadow hover:bg-blue-700 flex items-center gap-2 mx-auto transition transform hover:scale-105">
                        <Plus size={20}/> Nová Ponuka
                     </button>
                 </div>

                 <div className="mt-8">
                     <h3 className="text-lg font-bold text-gray-700 mb-4">Posledné ponuky</h3>
                     {quotes.length === 0 ? (
                         <div className="text-center p-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-400 italic">
                             Zatiaľ žiadne ponuky.
                         </div>
                     ) : (
                         <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                             {quotes.map(q => (
                                 <div key={q.id} className="bg-white p-4 rounded-xl border hover:border-blue-400 shadow-sm transition group cursor-pointer" onClick={() => setActiveQuote(q)}>
                                     <div className="flex justify-between items-start mb-2">
                                         <div className="font-bold text-blue-600">{q.number}</div>
                                         <button onClick={(e) => {e.stopPropagation(); handleDeleteQuote(q.id);}} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                                     </div>
                                     <div className="font-bold text-gray-800 mb-1">{q.title}</div>
                                     <div className="text-sm text-gray-500 mb-2">{q.client.name || 'Bez klienta'}</div>
                                     <div className="text-xs text-gray-400">{q.date}</div>
                                 </div>
                             ))}
                         </div>
                     )}
                 </div>
            </main>

            {/* GLOBAL MODALS (When no quote is active) */}
            {isSettingsOpen && <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} onSaveSettings={setSettings} onExportData={() => {}} onImportData={() => {}} onFactoryReset={() => {}} appVersion="1.0.0" />}
            {isCatalogOpen && <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={p => setProducts([...products, p])} onUpdateProduct={p => setProducts(products.map(pr => pr.id === p.id ? p : pr))} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} onDeleteCategory={c => setCustomCategories(customCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={c => setCabinClasses([...cabinClasses, c])} onUpdateCabinClass={c => setCabinClasses(cabinClasses.map(cc => cc.id === c.id ? c : cc))} onDeleteCabinClass={id => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />}
            {isClientDbOpen && <ClientDatabaseModal isOpen={isClientDbOpen} onClose={() => setIsClientDbOpen(false)} clients={clients} onSelectClient={() => {}} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />}
            {isSupplierDbOpen && <SupplierDatabaseModal isOpen={isSupplierDbOpen} onClose={() => setIsSupplierDbOpen(false)} suppliers={suppliers} onSelectSupplier={() => {}} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />}
        </div>
      );
  }

  // --- EDITOR VIEW ---
  const totals = calculateTotals();

  return (
    <div className="min-h-screen bg-gray-100 text-gray-900 font-sans pb-32 print:pb-0 print:bg-white">
        {/* Editor Toolbar */}
        <header className="bg-white border-b px-4 py-2 sticky top-0 z-40 shadow-sm print:hidden flex justify-between items-center">
            <div className="flex items-center gap-4">
                <button onClick={() => setActiveQuote(null)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Späť na Dashboard"><ArrowLeft size={20}/></button>
                <div>
                    <div className="font-bold text-sm text-gray-500">{activeQuote.number}</div>
                    <input 
                        className="font-bold text-gray-800 bg-transparent outline-none focus:border-b border-blue-500 w-64"
                        value={activeQuote.title}
                        onChange={e => setActiveQuote({...activeQuote, title: e.target.value})}
                    />
                </div>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setIsMaterialCalcOpen(true)} className="p-2 text-orange-600 bg-orange-50 hover:bg-orange-100 rounded font-bold flex items-center gap-2 text-sm"><Calculator size={16}/> Materiál</button>
                <div className="w-px bg-gray-300 mx-2"></div>
                <button onClick={handleSaveQuote} className="p-2 text-blue-600 hover:bg-blue-50 rounded" title="Uložiť"><Save size={20}/></button>
                <button onClick={handlePrint} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Tlačiť"><Printer size={20}/></button>
                <button onClick={() => setIsEmailOpen(true)} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Email"><Mail size={20}/></button>
            </div>
        </header>

        <main className="max-w-[210mm] mx-auto bg-white shadow-lg min-h-screen my-8 p-8 print:shadow-none print:m-0 print:p-0 print:w-full">

            {/* Header / Info */}
            <div className="flex justify-between mb-8 print:mb-4">
                <div className="w-1/2 pr-4">
                    <h1 className="text-2xl font-bold text-blue-800 mb-4">{activeQuote.title}</h1>
                    <div className="space-y-4">
                         {/* Supplier */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsSupplierDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Dodávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Firma..." value={activeQuote.supplier.name} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.supplier.details} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, details: e.target.value}})} />
                         </div>
                         {/* Client */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsClientDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Objednávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Klient..." value={activeQuote.client.name} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.client.details} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, details: e.target.value}})} />
                         </div>
                    </div>
                </div>
                <div className="w-1/2 pl-4 text-right">
                    {/* Meta Data */}
                    <div className="space-y-1 mb-6 text-sm">
                        <div><span className="text-gray-500">Číslo ponuky:</span> <span className="font-bold">{activeQuote.number}</span></div>
                        <div><span className="text-gray-500">Dátum:</span> <input type="date" value={activeQuote.date} onChange={e => setActiveQuote({...activeQuote, date: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                        <div><span className="text-gray-500">Platnosť do:</span> <input type="date" value={activeQuote.validUntil} onChange={e => setActiveQuote({...activeQuote, validUntil: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                    </div>
                    {/* Lift Sketch */}
                    <div className="border border-gray-200 rounded-lg p-2 inline-block bg-white print:border-none">
                         <LiftLayoutSketch 
                            data={activeQuote.layout || defaultLayout} 
                            onChange={(f,v) => activeQuote.layout && setActiveQuote({...activeQuote, layout: {...activeQuote.layout, [f]: v}})}
                            isVisible={isSketchVisible}
                            onToggleVisibility={() => setIsSketchVisible(!isSketchVisible)}
                        />
                    </div>
                </div>
            </div>

            {/* Technical Specs */}
            {activeQuote.layout && (
                <TechSpecTable 
                    data={activeQuote.layout} 
                    isVisible={isTechSpecVisible} 
                    onToggleVisibility={() => setIsTechSpecVisible(!isTechSpecVisible)} 
                />
            )}

            {/* Category Tables */}
            <div className="space-y-6 mt-8">
                {activeQuote.categories.map((cat, idx) => (
                    <CategoryTable 
                        key={cat.id}
                        category={cat}
                        currency={activeQuote.currency}
                        globalMargin={cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin}
                        onUpdateCategory={handleUpdateCategory}
                        onDeleteCategory={() => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.filter(c => c.id !== cat.id)});
                        }}
                        onAddItem={(catId, isSurcharge) => handleAddItem(catId, isSurcharge)}
                        onUpdateItem={handleUpdateItem}
                        onDeleteItem={(catId, itemId) => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.map(c => c.id === catId ? {...c, items: c.items.filter(i => i.id !== itemId)} : c)})
                        }}
                        onAiSuggest={handleAiSuggest}
                        onOpenCatalog={(catId, itemId) => {
                             setActiveCategoryForProduct(catId);
                             setActiveItemForProduct(itemId || null);
                             setIsProductDbOpen(true);
                        }}
                        onMoveCategory={(id, dir) => {
                            const cats = [...activeQuote.categories];
                            const index = cats.findIndex(c => c.id === id);
                            if (dir === 'up' && index > 0) {
                                [cats[index], cats[index-1]] = [cats[index-1], cats[index]];
                            } else if (dir === 'down' && index < cats.length - 1) {
                                [cats[index], cats[index+1]] = [cats[index+1], cats[index]];
                            }
                            setActiveQuote({...activeQuote, categories: cats});
                        }}
                        isAiLoading={isAiLoading}
                    />
                ))}

                {/* Add Category Button */}
                <div className="no-print border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-blue-400 transition cursor-pointer" onClick={() => {
                    const name = prompt("Názov novej kategórie:");
                    if (name) {
                        const newCat: QuoteCategory = { id: crypto.randomUUID(), type: 'items', name, items: [], isExpanded: true, section: 'lift' };
                        setActiveQuote({...activeQuote, categories: [...activeQuote.categories, newCat]});
                    }
                }}>
                    <div className="text-gray-500 font-bold flex items-center justify-center gap-2"><Plus/> Pridať Kategóriu</div>
                </div>
            </div>

            {/* Totals */}
            <div className="mt-12 border-t-2 border-gray-800 pt-4 flex justify-end print:break-inside-avoid">
                <div className="w-64">
                    <div className="flex justify-between mb-2 text-sm text-gray-500 no-print">
                        <span>Náklady (bez DPH):</span>
                        <span>{totals.cost.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between mb-2 text-sm text-green-600 no-print">
                        <span>Zisk ({((totals.profit/totals.cost)*100 || 0).toFixed(1)}%):</span>
                        <span>{totals.profit.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between text-xl font-bold text-gray-900 border-t pt-2">
                        <span>Cena Celkom:</span>
                        <span>{totals.price.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="text-right text-xs text-gray-500 mt-1">bez DPH</div>
                </div>
            </div>

            {/* Terms & Conditions */}
            <div className="mt-12 print:break-inside-avoid">
                <div className="flex justify-between items-center mb-4 no-print">
                    <h3 className="font-bold uppercase text-sm">Obchodné podmienky</h3>
                    <div className="flex gap-2">
                        <button onClick={handleGenerateTerms} disabled={isAiLoading} className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded hover:bg-yellow-200 flex items-center gap-1"><Lightbulb size={12}/> AI Návrh</button>
                        <button onClick={() => setIsContractRepoOpen(true)} className="text-xs bg-gray-100 text-gray-800 px-2 py-1 rounded hover:bg-gray-200 flex items-center gap-1"><FileText size={12}/> Zo Šablóny</button>
                    </div>
                </div>
                <StandaloneRichTextEditor 
                    content={activeQuote.terms} 
                    onChange={val => setActiveQuote({...activeQuote, terms: val})}
                    placeholder="Sem vložte text obchodných podmienok..."
                />
            </div>

            {/* Signature Area */}
            <div className="mt-16 flex justify-between print:break-inside-avoid text-sm">
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Objednávateľ)</div>
                </div>
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Dodávateľ)</div>
                </div>
            </div>
        </main>

        {/* Editor Modals */}
        {isProductDbOpen && <ProductDatabaseModal isOpen={isProductDbOpen} onClose={() => setIsProductDbOpen(false)} products={products} onSelectProduct={handleSelectProduct} onAddProduct={p => setProducts([...products, p])} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} layout={activeQuote.layout} />}
        {isMaterialCalcOpen && activeQuote.layout && <MaterialCalculatorModal isOpen={isMaterialCalcOpen} onClose={() => setIsMaterialCalcOpen(false)} layout={activeQuote.layout} onInsert={handleMaterialInsert} products={products} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} cabinClasses={cabinClasses} />}
        {isEmailOpen && <EmailModal isOpen={isEmailOpen} onClose={() => setIsEmailOpen(false)} onSend={(to, sub, msg) => window.open(`mailto:${to}?subject=${encodeURIComponent(sub)}&body=${encodeURIComponent(msg)}`)} defaultTo={activeQuote.client.email} defaultSubject={`Cenová ponuka ${activeQuote.number}`} defaultMessage={`Dobrý deň,\n\nv prílohe posielame cenovú ponuku č. ${activeQuote.number}.\n\nS pozdravom,\n${activeQuote.supplier.name}`} />}
        {isSupplierDbOpen && <SupplierDatabaseModal isOpen={isSupplierDbOpen} onClose={() => setIsSupplierDbOpen(false)} suppliers={suppliers} onSelectSupplier={s => setActiveQuote({...activeQuote, supplier: { name: s.name, details: s.details, email: s.email, phone: s.phone }})} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />}
        {isClientDbOpen && <ClientDatabaseModal isOpen={isClientDbOpen} onClose={() => setIsClientDbOpen(false)} clients={clients} onSelectClient={c => setActiveQuote({...activeQuote, client: { name: c.name, details: c.details, email: c.email, phone: c.phone }})} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />}
        {isContractRepoOpen && <ContractRepositoryModal isOpen={isContractRepoOpen} onClose={() => setIsContractRepoOpen(false)} templates={contractTemplates} onSelectTemplate={content => setActiveQuote({...activeQuote, terms: content})} onSaveCurrent={name => setContractTemplates([...contractTemplates, { id: crypto.randomUUID(), name, content: activeQuote.terms }])} onDeleteTemplate={id => setContractTemplates(contractTemplates.filter(t => t.id !== id))} />}

    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
  QuoteData, QuoteCategory, QuoteItem, Product, Client, Supplier, QuoteTemplate, 
  ContractTemplate, AppSettings, LiftLayoutData, CabinClass, BackupData 
} from './types';
import { LoginGate } from './components/LoginGate';
import { CategoryTable } from './components/CategoryTable';
import { LiftLayoutSketch } from './components/LiftLayoutSketch';
import { TechSpecTable } from './components/TechSpecTable';
import { MaterialCalculatorModal } from './components/MaterialCalculatorModal';
import { SettingsModal } from './components/SettingsModal';
import { CatalogManagerModal } from './components/CatalogManagerModal';
import { ClientDatabaseModal } from './components/ClientDatabaseModal';
import { SupplierDatabaseModal } from './components/SupplierDatabaseModal';
import { TemplateDatabaseModal } from './components/TemplateDatabaseModal';
import { EmailModal } from './components/EmailModal';
import { ProductDatabaseModal } from './components/ProductDatabaseModal';
import { ContractRepositoryModal } from './components/ContractRepositoryModal';
import { StandaloneRichTextEditor } from './components/StandaloneRichTextEditor';
import { generateSuggestion } from './services/geminiService';
import { 
  Printer, Save, Trash2, Plus, Download, Mail, Copy, 
  Settings, User, Building, Package, ArrowLeft, LayoutTemplate, 
  FileText, Users, Calculator, Lightbulb, RefreshCw, PenTool, CheckCircle, FileCheck, Search
} from 'lucide-react';

// --- Safe ID Generator ---
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try {
      return crypto.randomUUID();
    } catch (e) {
      // Fallback if crypto is present but fails
    }
  }
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

const defaultLayout: LiftLayoutData = {
  liftType: 'passenger', driveType: 'traction', ratedLoad: 630, numberOfPersons: 8, ratedSpeed: 1.0, powerSupply: '3x400V',
  shaftWidth: 1600, shaftDepth: 1800, cabinWidth: 1100, cabinDepth: 1400, doorWidth: 900, doorOffsetL: 0,
  pitDepth: 1100, headroomHeight: 3400, travelHeight: 15000,
  doorType: 'central', doorOperation: 'automatic', counterWeightPosition: 'back', machineRoomPosition: 'head',
  suspensionType: '1:1', tractionMedium: 'ropes', frameType: 'backpack',
  gapLeft: 50, gapRight: 50, gapRear: 50, gapFront: 50,
  guideTypeCar: 'T90', guideTypeCwt: 'T50', guideRailLength: 5000,
  notes: ''
};

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [quotes, setQuotes] = useState<QuoteData[]>([]);
  const [templates, setTemplates] = useState<QuoteTemplate[]>([]);
  const [contractTemplates, setContractTemplates] = useState<ContractTemplate[]>([]);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);
  const [customCategories, setCustomCategories] = useState<string[]>([
    'Pohon', 'Kabína a rám', 'Dvere', 'Vodítka a kotvenie', 'Obmedzovač', 
    'Elektro', 'Montáž', 'Ostatné šachta', 'Ostatné', 
    'Oceľová konštrukcia', 'Doprava', 'Balné'
  ]);
  const [settings, setSettings] = useState<AppSettings>({
    nextCpSequence: 100, nextObjSequence: 100, nextPlSequence: 100
  });

  const [activeQuote, setActiveQuote] = useState<QuoteData | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isTechSpecVisible, setIsTechSpecVisible] = useState(true);
  const [isSketchVisible, setIsSketchVisible] = useState(true);

  // Modal States
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isClientDbOpen, setIsClientDbOpen] = useState(false);
  const [isSupplierDbOpen, setIsSupplierDbOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [templateModalMode, setTemplateModalMode] = useState<'select' | 'save'>('select');
  const [templateModalType, setTemplateModalType] = useState<'lift' | 'shaft'>('lift');
  const [isProductDbOpen, setIsProductDbOpen] = useState(false);
  const [activeCategoryForProduct, setActiveCategoryForProduct] = useState<string | null>(null);
  const [activeItemForProduct, setActiveItemForProduct] = useState<string | null>(null);
  const [isMaterialCalcOpen, setIsMaterialCalcOpen] = useState(false);
  const [isEmailOpen, setIsEmailOpen] = useState(false);
  const [isContractRepoOpen, setIsContractRepoOpen] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('smartquote_data');
    if (saved) {
        try {
            const data = JSON.parse(saved);
            if (data.products) setProducts(data.products);
            if (data.clients) setClients(data.clients);
            if (data.suppliers) setSuppliers(data.suppliers);
            if (data.quotes) setQuotes(data.quotes);
            if (data.templates) setTemplates(data.templates);
            if (data.contractTemplates) setContractTemplates(data.contractTemplates);
            if (data.cabinClasses) setCabinClasses(data.cabinClasses);
            if (data.customCategories) setCustomCategories(data.customCategories);
            if (data.settings) setSettings(data.settings);
        } catch (e) { console.error("Failed to load", e); }
    }
  }, []);

  useEffect(() => {
      const data = { products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings };
      localStorage.setItem('smartquote_data', JSON.stringify(data));
  }, [products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings]);

  // --- ACTIONS ---

  const handleCreateQuote = () => {
    try {
      const newQuote: QuoteData = {
        id: generateId(),
        number: `CP_SK_${settings.nextCpSequence}_${new Date().getFullYear().toString().slice(-2)}_BA`,
        type: 'quote',
        title: 'Nová Cenová Ponuka',
        date: new Date().toISOString().split('T')[0],
        validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
        supplier: { name: '', details: '' },
        client: { name: '', details: '' },
        categories: customCategories.map(name => ({ id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift' })),
        currency: '€',
        globalMargin: 10,
        shaftMargin: 10,
        terms: '',
        layout: { ...defaultLayout }
      };
      setActiveQuote(newQuote);
      setSettings(prev => ({...prev, nextCpSequence: prev.nextCpSequence + 1}));
    } catch (e) {
      console.error("Error creating quote:", e);
      alert("Chyba pri vytváraní ponuky. Skontrolujte konzolu.");
    }
  };

  const handleSaveQuote = () => {
    if (!activeQuote) return;
    const updated = { ...activeQuote, lastUpdated: Date.now() };
    setQuotes(prev => {
        const idx = prev.findIndex(q => q.id === updated.id);
        if (idx >= 0) {
            const copy = [...prev]; copy[idx] = updated; return copy;
        }
        return [...prev, updated];
    });
    alert('Ponuka bola uložená.');
  };

  const handleDeleteQuote = (id: string) => {
      if(window.confirm("Naozaj vymazať ponuku?")) {
          setQuotes(prev => prev.filter(q => q.id !== id));
      }
  };

  const calculateTotals = () => {
      if (!activeQuote) return { cost: 0, price: 0, profit: 0 };
      let totalCost = 0;
      let totalPrice = 0;

      activeQuote.categories.forEach(cat => {
          if (cat.isHidden) return; // Skip completely hidden
          cat.items.forEach(item => {
               const quantity = item.quantity || 0;
               const unitPrice = item.unitPrice || 0;
               const cost = quantity * unitPrice;

               // Apply correct margin based on section
               const margin = cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin;
               const price = cost * (1 + margin / 100);

               totalCost += cost;
               totalPrice += price;
          });
      });

      return { cost: totalCost, price: totalPrice, profit: totalPrice - totalCost };
  };

  // --- ITEM HANDLERS ---
  const handleUpdateCategory = (id: string, field: keyof QuoteCategory, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => c.id === id ? { ...c, [field]: value } : c)
      });
  };

  const handleAddItem = (catId: string, isSurcharge = false) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: [...c.items, {
                      id: generateId(),
                      description: isSurcharge ? 'Príplatok: ' : '',
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20,
                      isSurcharge
                  }]
              };
          })
      });
  };

  const handleUpdateItem = (catId: string, itemId: string, field: keyof QuoteItem, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: c.items.map(i => i.id === itemId ? { ...i, [field]: value } : i)
              };
          })
      });
  };

  const handleSelectProduct = (product: Product) => {
      if (!activeQuote || !activeCategoryForProduct) return;

      const targetCatId = activeCategoryForProduct;
      const targetItemId = activeItemForProduct; // If replacing specific item

      setActiveQuote(prev => {
        if (!prev) return null;
        return {
            ...prev,
            categories: prev.categories.map(cat => {
                if (cat.id !== targetCatId) return cat;

                // Case A: Replacing existing item
                if (targetItemId) {
                    return {
                        ...cat,
                        items: cat.items.map(item => {
                            if (item.id !== targetItemId) return item;
                            return {
                                ...item,
                                description: product.name,
                                unit: product.unit,
                                unitPrice: product.price,
                                purchasePrice: product.price
                            };
                        })
                    };
                }

                // Case B: Adding new item
                return {
                    ...cat,
                    items: [...cat.items, {
                        id: generateId(),
                        description: product.name,
                        quantity: 1,
                        unit: product.unit,
                        unitPrice: product.price,
                        purchasePrice: product.price,
                        vatRate: 20
                    }]
                };
            })
        };
      });
      setIsProductDbOpen(false);
      setActiveItemForProduct(null);
  };

  // --- AI HANDLERS ---
  const handleAiSuggest = async (catId: string, catName: string) => {
      setIsAiLoading(true);
      const text = await generateSuggestion(`Navrhni 3 položky pre kategóriu "${catName}" pre výťah.`, 'category_items');
      setIsAiLoading(false);
      if (text) {
          const lines = text.split(',').map(s => s.trim()).filter(s => s);
          if (!activeQuote) return;
          setActiveQuote({
              ...activeQuote,
              categories: activeQuote.categories.map(c => {
                  if (c.id !== catId) return c;
                  const newItems = lines.map(desc => ({
                      id: generateId(),
                      description: desc,
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20
                  }));
                  return { ...c, items: [...c.items, ...newItems] };
              })
          });
      }
  };

  const handleGenerateTerms = async () => {
      setIsAiLoading(true);
      const text = await generateSuggestion("Navrhni obchodné podmienky pre inštaláciu výťahu.", 'terms');
      setIsAiLoading(false);
      if (activeQuote && text) setActiveQuote({ ...activeQuote, terms: text });
  };

  // --- MATERIAL WIZARD ---
  const handleMaterialInsert = (data: any) => {
    if (!activeQuote) return;

    // Create map of existing categories by name to find IDs
    const catMap = new Map(activeQuote.categories.map(c => [c.name, c.id]));

    // Prepare updates
    let updatedCategories = [...activeQuote.categories];

    // Helper to find or create category
    const getCatId = (name: string) => {
        if (catMap.has(name)) return catMap.get(name)!;
        // Create if missing
        const newId = generateId();
        const newCat: QuoteCategory = { 
            id: newId, 
            type: 'items', 
            name: name, 
            items: [], 
            isExpanded: true, 
            section: name === 'Oceľová konštrukcia' || name === 'Ostatné šachta' ? 'shaft' : 'lift'
        };
        updatedCategories.push(newCat);
        catMap.set(name, newId);
        return newId;
    };

    data.items.forEach((item: any) => {
        const catId = getCatId(item.category);
        const catIndex = updatedCategories.findIndex(c => c.id === catId);
        if (catIndex >= 0) {
            updatedCategories[catIndex].items.push({
                id: generateId(),
                description: item.description,
                quantity: item.quantity,
                unit: item.unit,
                unitPrice: item.price || 0,
                purchasePrice: item.price || 0,
                vatRate: 20
            });
        }
    });

    // Addons
    if (data.includeTransport) {
        const cid = getCatId('Doprava');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: generateId(), description: 'Doprava materiálu na stavbu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includePackaging) {
        const cid = getCatId('Balné');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: generateId(), description: 'Balné a palety', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includeAssembly) {
        const cid = getCatId('Montáž');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: generateId(), description: 'Montáž technológie výťahu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }

    setActiveQuote({ ...activeQuote, categories: updatedCategories });
  };

  // --- TEMPLATES & EXPORT ---
  const handlePrint = () => window.print();

  const handleSaveTemplate = (name: string, type: 'lift' | 'shaft') => {
      if (!activeQuote) return;
      const newTemplate: QuoteTemplate = {
          id: generateId(),
          name,
          type,
          data: {
              categories: activeQuote.categories.map(c => ({...c})), // Deep copy needed in real app
              layout: activeQuote.layout,
              margin: activeQuote.globalMargin
          }
      };
      setTemplates([...templates, newTemplate]);
  };

  const handleApplyTemplate = (t: QuoteTemplate) => {
      if (!activeQuote) return;
      // Merge categories
      // Ideally we replace or append. Let's replace items if category exists
      const newCats = [...activeQuote.categories];
      t.data.categories.forEach(tc => {
          const existing = newCats.find(c => c.name === tc.name);
          if (existing) {
              existing.items = [...existing.items, ...tc.items]; // Append
          } else {
              newCats.push({ ...tc, id: generateId() });
          }
      });

      setActiveQuote({
          ...activeQuote,
          categories: newCats,
          layout: t.data.layout ? { ...activeQuote.layout, ...t.data.layout } : activeQuote.layout,
          globalMargin: t.data.margin || activeQuote.globalMargin
      });
      setIsTemplateModalOpen(false);
  };

  // --- RENDER ---

  if (!isAuthenticated) return <LoginGate onLogin={() => setIsAuthenticated(true)} />;

  if (!activeQuote) {
      return (
        <div className="min-h-screen bg-gray-50 text-gray-900 font-sans">
            <header className="bg-white border-b px-6 py-3 flex justify-between items-center sticky top-0 z-40 shadow-sm">
                <div className="flex items-center gap-2">
                    <div className="bg-blue-600 text-white p-1.5 rounded font-bold">SQ</div>
                    <h1 className="font-bold text-xl tracking-tight">SmartQuote SK</h1>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setIsClientDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Klienti"><Users size={20}/></button>
                    <button onClick={() => setIsSupplierDbOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Dodávatelia"><Building size={20}/></button>
                    <button onClick={() => setIsCatalogOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Katalóg"><Package size={20}/></button>
                    <button onClick={() => setIsSettingsOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Nastavenia"><Settings size={20}/></button>
                </div>
            </header>

            <main className="p-6 max-w-7xl mx-auto">
                 <div className="text-center py-16">
                     <h2 className="text-3xl font-bold text-gray-800 mb-4">Dashboard</h2>
                     <p className="text-gray-500 mb-8">Vitajte v systéme pre tvorbu cenových ponúk výťahov.</p>
                     <button onClick={handleCreateQuote} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold shadow hover:bg-blue-700 flex items-center gap-2 mx-auto transition transform hover:scale-105">
                        <Plus size={20}/> Nová Ponuka
                     </button>
                 </div>

                 <div className="mt-8">
                     <h3 className="text-lg font-bold text-gray-700 mb-4">Posledné ponuky</h3>
                     {quotes.length === 0 ? (
                         <div className="text-center p-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-400 italic">
                             Zatiaľ žiadne ponuky.
                         </div>
                     ) : (
                         <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                             {quotes.map(q => (
                                 <div key={q.id} className="bg-white p-4 rounded-xl border hover:border-blue-400 shadow-sm transition group cursor-pointer" onClick={() => setActiveQuote(q)}>
                                     <div className="flex justify-between items-start mb-2">
                                         <div className="font-bold text-blue-600">{q.number}</div>
                                         <button onClick={(e) => {e.stopPropagation(); handleDeleteQuote(q.id);}} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                                     </div>
                                     <div className="font-bold text-gray-800 mb-1">{q.title}</div>
                                     <div className="text-sm text-gray-500 mb-2">{q.client.name || 'Bez klienta'}</div>
                                     <div className="text-xs text-gray-400">{q.date}</div>
                                 </div>
                             ))}
                         </div>
                     )}
                 </div>
            </main>

            {/* GLOBAL MODALS (When no quote is active) */}
            {isSettingsOpen && <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} onSaveSettings={setSettings} onExportData={() => {}} onImportData={() => {}} onFactoryReset={() => {}} appVersion="1.0.0" />}
            {isCatalogOpen && <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={p => setProducts([...products, p])} onUpdateProduct={p => setProducts(products.map(pr => pr.id === p.id ? p : pr))} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} onDeleteCategory={c => setCustomCategories(customCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={c => setCabinClasses([...cabinClasses, c])} onUpdateCabinClass={c => setCabinClasses(cabinClasses.map(cc => cc.id === c.id ? c : cc))} onDeleteCabinClass={id => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />}
            {isClientDbOpen && <ClientDatabaseModal isOpen={isClientDbOpen} onClose={() => setIsClientDbOpen(false)} clients={clients} onSelectClient={() => {}} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />}
            {isSupplierDbOpen && <SupplierDatabaseModal isOpen={isSupplierDbOpen} onClose={() => setIsSupplierDbOpen(false)} suppliers={suppliers} onSelectSupplier={() => {}} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />}
        </div>
      );
  }

  // --- EDITOR VIEW ---
  const totals = calculateTotals();

  return (
    <div className="min-h-screen bg-gray-100 text-gray-900 font-sans pb-32 print:pb-0 print:bg-white">
        {/* Editor Toolbar */}
        <header className="bg-white border-b px-4 py-2 sticky top-0 z-40 shadow-sm print:hidden flex justify-between items-center">
            <div className="flex items-center gap-4">
                <button onClick={() => setActiveQuote(null)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Späť na Dashboard"><ArrowLeft size={20}/></button>
                <div>
                    <div className="font-bold text-sm text-gray-500">{activeQuote.number}</div>
                    <input 
                        className="font-bold text-gray-800 bg-transparent outline-none focus:border-b border-blue-500 w-64"
                        value={activeQuote.title}
                        onChange={e => setActiveQuote({...activeQuote, title: e.target.value})}
                    />
                </div>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setIsMaterialCalcOpen(true)} className="p-2 text-orange-600 bg-orange-50 hover:bg-orange-100 rounded font-bold flex items-center gap-2 text-sm"><Calculator size={16}/> Materiál</button>
                <div className="w-px bg-gray-300 mx-2"></div>
                <button onClick={handleSaveQuote} className="p-2 text-blue-600 hover:bg-blue-50 rounded" title="Uložiť"><Save size={20}/></button>
                <button onClick={handlePrint} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Tlačiť"><Printer size={20}/></button>
                <button onClick={() => setIsEmailOpen(true)} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Email"><Mail size={20}/></button>
            </div>
        </header>

        <main className="max-w-[210mm] mx-auto bg-white shadow-lg min-h-screen my-8 p-8 print:shadow-none print:m-0 print:p-0 print:w-full">

            {/* Header / Info */}
            <div className="flex justify-between mb-8 print:mb-4">
                <div className="w-1/2 pr-4">
                    <h1 className="text-2xl font-bold text-blue-800 mb-4">{activeQuote.title}</h1>
                    <div className="space-y-4">
                         {/* Supplier */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsSupplierDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Dodávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Firma..." value={activeQuote.supplier.name} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.supplier.details} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, details: e.target.value}})} />
                         </div>
                         {/* Client */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsClientDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Objednávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Klient..." value={activeQuote.client.name} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.client.details} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, details: e.target.value}})} />
                         </div>
                    </div>
                </div>
                <div className="w-1/2 pl-4 text-right">
                    {/* Meta Data */}
                    <div className="space-y-1 mb-6 text-sm">
                        <div><span className="text-gray-500">Číslo ponuky:</span> <span className="font-bold">{activeQuote.number}</span></div>
                        <div><span className="text-gray-500">Dátum:</span> <input type="date" value={activeQuote.date} onChange={e => setActiveQuote({...activeQuote, date: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                        <div><span className="text-gray-500">Platnosť do:</span> <input type="date" value={activeQuote.validUntil} onChange={e => setActiveQuote({...activeQuote, validUntil: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                    </div>
                    {/* Lift Sketch */}
                    <div className="border border-gray-200 rounded-lg p-2 inline-block bg-white print:border-none">
                         <LiftLayoutSketch 
                            data={activeQuote.layout || defaultLayout} 
                            onChange={(f,v) => activeQuote.layout && setActiveQuote({...activeQuote, layout: {...activeQuote.layout, [f]: v}})}
                            isVisible={isSketchVisible}
                            onToggleVisibility={() => setIsSketchVisible(!isSketchVisible)}
                        />
                    </div>
                </div>
            </div>

            {/* Technical Specs */}
            {activeQuote.layout && (
                <TechSpecTable 
                    data={activeQuote.layout} 
                    isVisible={isTechSpecVisible} 
                    onToggleVisibility={() => setIsTechSpecVisible(!isTechSpecVisible)} 
                />
            )}

            {/* Category Tables */}
            <div className="space-y-6 mt-8">
                {activeQuote.categories.map((cat, idx) => (
                    <CategoryTable 
                        key={cat.id}
                        category={cat}
                        currency={activeQuote.currency}
                        globalMargin={cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin}
                        onUpdateCategory={handleUpdateCategory}
                        onDeleteCategory={() => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.filter(c => c.id !== cat.id)});
                        }}
                        onAddItem={(catId, isSurcharge) => handleAddItem(catId, isSurcharge)}
                        onUpdateItem={handleUpdateItem}
                        onDeleteItem={(catId, itemId) => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.map(c => c.id === catId ? {...c, items: c.items.filter(i => i.id !== itemId)} : c)})
                        }}
                        onAiSuggest={handleAiSuggest}
                        onOpenCatalog={(catId, itemId) => {
                             setActiveCategoryForProduct(catId);
                             setActiveItemForProduct(itemId || null);
                             setIsProductDbOpen(true);
                        }}
                        onMoveCategory={(id, dir) => {
                            const cats = [...activeQuote.categories];
                            const index = cats.findIndex(c => c.id === id);
                            if (dir === 'up' && index > 0) {
                                [cats[index], cats[index-1]] = [cats[index-1], cats[index]];
                            } else if (dir === 'down' && index < cats.length - 1) {
                                [cats[index], cats[index+1]] = [cats[index+1], cats[index]];
                            }
                            setActiveQuote({...activeQuote, categories: cats});
                        }}
                        isAiLoading={isAiLoading}
                    />
                ))}

                {/* Add Category Button */}
                <div className="no-print border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-blue-400 transition cursor-pointer" onClick={() => {
                    const name = prompt("Názov novej kategórie:");
                    if (name) {
                        const newCat: QuoteCategory = { id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift' };
                        setActiveQuote({...activeQuote, categories: [...activeQuote.categories, newCat]});
                    }
                }}>
                    <div className="text-gray-500 font-bold flex items-center justify-center gap-2"><Plus/> Pridať Kategóriu</div>
                </div>
            </div>

            {/* Totals */}
            <div className="mt-12 border-t-2 border-gray-800 pt-4 flex justify-end print:break-inside-avoid">
                <div className="w-64">
                    <div className="flex justify-between mb-2 text-sm text-gray-500 no-print">
                        <span>Náklady (bez DPH):</span>
                        <span>{totals.cost.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between mb-2 text-sm text-green-600 no-print">
                        <span>Zisk ({((totals.profit/totals.cost)*100 || 0).toFixed(1)}%):</span>
                        <span>{totals.profit.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between text-xl font-bold text-gray-900 border-t pt-2">
                        <span>Cena Celkom:</span>
                        <span>{totals.price.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="text-right text-xs text-gray-500 mt-1">bez DPH</div>
                </div>
            </div>

            {/* Terms & Conditions */}
            <div className="mt-12 print:break-inside-avoid">
                <div className="flex justify-between items-center mb-4 no-print">
                    <h3 className="font-bold uppercase text-sm">Obchodné podmienky</h3>
                    <div className="flex gap-2">
                        <button onClick={handleGenerateTerms} disabled={isAiLoading} className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded hover:bg-yellow-200 flex items-center gap-1"><Lightbulb size={12}/> AI Návrh</button>
                        <button onClick={() => setIsContractRepoOpen(true)} className="text-xs bg-gray-100 text-gray-800 px-2 py-1 rounded hover:bg-gray-200 flex items-center gap-1"><FileText size={12}/> Zo Šablóny</button>
                    </div>
                </div>
                <StandaloneRichTextEditor 
                    content={activeQuote.terms} 
                    onChange={val => setActiveQuote({...activeQuote, terms: val})}
                    placeholder="Sem vložte text obchodných podmienok..."
                />
            </div>

            {/* Signature Area */}
            <div className="mt-16 flex justify-between print:break-inside-avoid text-sm">
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Objednávateľ)</div>
                </div>
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Dodávateľ)</div>
                </div>
            </div>
        </main>

        {/* Editor Modals */}
        {isProductDbOpen && <ProductDatabaseModal isOpen={isProductDbOpen} onClose={() => setIsProductDbOpen(false)} products={products} onSelectProduct={handleSelectProduct} onAddProduct={p => setProducts([...products, p])} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} layout={activeQuote.layout} />}
        {isMaterialCalcOpen && activeQuote.layout && <MaterialCalculatorModal isOpen={isMaterialCalcOpen} onClose={() => setIsMaterialCalcOpen(false)} layout={activeQuote.layout} onInsert={handleMaterialInsert} products={products} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} cabinClasses={cabinClasses} />}
        {isEmailOpen && <EmailModal isOpen={isEmailOpen} onClose={() => setIsEmailOpen(false)} onSend={(to, sub, msg) => window.open(`mailto:${to}?subject=${encodeURIComponent(sub)}&body=${encodeURIComponent(msg)}`)} defaultTo={activeQuote.client.email} defaultSubject={`Cenová ponuka ${activeQuote.number}`} defaultMessage={`Dobrý deň,\n\nv prílohe posielame cenovú ponuku č. ${activeQuote.number}.\n\nS pozdravom,\n${activeQuote.supplier.name}`} />}
        {isSupplierDbOpen && <SupplierDatabaseModal isOpen={isSupplierDbOpen} onClose={() => setIsSupplierDbOpen(false)} suppliers={suppliers} onSelectSupplier={s => setActiveQuote({...activeQuote, supplier: { name: s.name, details: s.details, email: s.email, phone: s.phone }})} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />}
        {isClientDbOpen && <ClientDatabaseModal isOpen={isClientDbOpen} onClose={() => setIsClientDbOpen(false)} clients={clients} onSelectClient={c => setActiveQuote({...activeQuote, client: { name: c.name, details: c.details, email: c.email, phone: c.phone }})} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />}
        {isContractRepoOpen && <ContractRepositoryModal isOpen={isContractRepoOpen} onClose={() => setIsContractRepoOpen(false)} templates={contractTemplates} onSelectTemplate={content => setActiveQuote({...activeQuote, terms: content})} onSaveCurrent={name => setContractTemplates([...contractTemplates, { id: generateId(), name, content: activeQuote.terms }])} onDeleteTemplate={id => setContractTemplates(contractTemplates.filter(t => t.id !== id))} />}

    </div>
  );
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, FolderOpen, Folder,
  AlertTriangle, Box
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try {
        return crypto.randomUUID();
      } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk Actions State
  const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());
  const [isBulkMoveMode, setIsBulkMoveMode] = useState(false);
  const [bulkTargetCat, setBulkTargetCat] = useState('');
  const [bulkTargetSubcat, setBulkTargetSubcat] = useState('');

  // Editing State
  const [editingProductId, setEditingProductId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<Product>>({});

  // New Category State
  const [newCategoryName, setNewCategoryName] = useState('');

  // New Class State
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLinkedSet, setNewClassLinkedSet] = useState('');

  // Grouping State (Expanded Subcategories)
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize active category
  useEffect(() => {
      if (customCategories.length > 0 && !activeCategory) {
          setActiveCategory(customCategories[0]);
      }
  }, [customCategories, activeCategory]);

  // Filtered Products
  const filteredProducts = products.filter(p => {
      const matchCat = activeCategory ? p.category === activeCategory : true;
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCat && matchSearch;
  });

  // GROUPING LOGIC
  const { generalProducts, groupedProducts, sortedSubcategories } = useMemo(() => {
      const general: Product[] = [];
      const groups: Record<string, Product[]> = {};

      filteredProducts.forEach(p => {
          if (p.subcategory) {
              if (!groups[p.subcategory]) groups[p.subcategory] = [];
              groups[p.subcategory].push(p);
          } else {
              general.push(p);
          }
      });

      return {
          generalProducts: general,
          groupedProducts: groups,
          sortedSubcategories: Object.keys(groups).sort()
      };
  }, [filteredProducts]);

  // Derived Data
  const allCategories = customCategories;

  // Get all unique subcategories for the selected target category (for suggestions)
  const bulkTargetSubcategoriesOptions = Array.from(new Set(
      products
        .filter(p => p.category === bulkTargetCat && p.subcategory)
        .map(p => p.subcategory!)
  ));

  // --- Handlers ---

  const handleBulkSelection = (id: string) => {
      const newSet = new Set(selectedProductIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedProductIds(newSet);
  };

  const toggleSelectAll = () => {
      if (selectedProductIds.size === filteredProducts.length && filteredProducts.length > 0) {
          setSelectedProductIds(new Set());
      } else {
          setSelectedProductIds(new Set(filteredProducts.map(p => p.id)));
      }
  };

  const toggleGroupExpand = (subcat: string) => {
      const newSet = new Set(expandedGroups);
      if (newSet.has(subcat)) newSet.delete(subcat);
      else newSet.add(subcat);
      setExpandedGroups(newSet);
  };

  const handleBulkMoveConfirm = () => {
      if (!bulkTargetCat) return;

      const targetSub = bulkTargetSubcat.trim();
      const idsToMove = Array.from(selectedProductIds);

      idsToMove.forEach(id => {
          const product = products.find(p => p.id === id);
          if (product) {
              onUpdateProduct({
                  ...product,
                  category: bulkTargetCat,
                  subcategory: targetSub || undefined 
              });
          }
      });

      // Auto expand the target group if we are staying in the same category
      if (activeCategory === bulkTargetCat && targetSub) {
           setExpandedGroups(prev => {
               const next = new Set(prev);
               next.add(targetSub);
               return next;
           });
      }

      setSelectedProductIds(new Set());
      setIsBulkMoveMode(false);
      setBulkTargetCat('');
      setBulkTargetSubcat('');
  };

  const handleDeleteSelected = () => {
      if (window.confirm(`Naozaj vymazať ${selectedProductIds.size} produktov?`)) {
          selectedProductIds.forEach(id => onDeleteProduct(id));
          setSelectedProductIds(new Set());
      }
  };

  const handleStartEdit = (p: Product) => {
      setEditingProductId(p.id);
      setEditForm({...p});
  };

  const handleSaveEdit = () => {
      if (editingProductId && editForm.name) {
          const original = products.find(p => p.id === editingProductId);
          if (original) {
              onUpdateProduct({ ...original, ...editForm } as Product);
          }
          setEditingProductId(null);
          setEditForm({});
      }
  };

  const handleAddCategorySubmit = () => {
      if (newCategoryName && !customCategories.includes(newCategoryName)) {
          onAddCategory(newCategoryName);
          setNewCategoryName('');
      }
  };

  const handleAddClassSubmit = () => {
      if (newClassName) {
          onAddCabinClass({
              id: generateId(),
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
          setNewClassName('');
          setNewClassDesc('');
          setNewClassLinkedSet('');
      }
  };

  if (!isOpen) return null;

  // Helper to render a single row
  const renderProductRow = (product: Product) => (
    <tr key={product.id} className={`hover:bg-blue-50 transition ${selectedProductIds.has(product.id) ? 'bg-blue-50' : ''}`}>
        <td className="p-3 w-10 text-center">
            <button onClick={() => handleBulkSelection(product.id)} className={`text-gray-400 hover:text-purple-600 ${selectedProductIds.has(product.id) ? 'text-purple-600' : ''}`}>
                {selectedProductIds.has(product.id) ? <CheckSquare size={16}/> : <Square size={16}/>}
            </button>
        </td>

        {/* Name */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded font-bold" 
                    value={editForm.name || ''} 
                    onChange={e => setEditForm({...editForm, name: e.target.value})}
                    autoFocus
                />
            ) : (
                <div className="font-bold text-gray-800">{product.name}</div>
            )}
        </td>

        {/* Subcategory */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded text-xs" 
                    value={editForm.subcategory || ''} 
                    onChange={e => setEditForm({...editForm, subcategory: e.target.value})}
                    placeholder="-"
                />
            ) : (
                <span className={`text-xs px-2 py-1 rounded-full border ${product.subcategory ? 'bg-blue-50 text-blue-700 border-blue-100' : 'bg-gray-50 text-gray-400 border-gray-200'}`}>
                    {product.subcategory || '-'}
                </span>
            )}
        </td>

        {/* Price */}
        <td className="p-3 text-right font-mono">
            {editingProductId === product.id ? (
                <input 
                    type="number"
                    className="w-full border p-1 rounded text-right" 
                    value={editForm.price || ''} 
                    onChange={e => setEditForm({...editForm, price: parseFloat(e.target.value) || 0})}
                />
            ) : (
                product.price.toFixed(2)
            )}
        </td>

        {/* Unit */}
        <td className="p-3 text-right">
            {editingProductId === product.id ? (
                <select
                    className="border p-1 rounded text-xs" 
                    value={editForm.unit || 'ks'} 
                    onChange={e => setEditForm({...editForm, unit: e.target.value})}
                >
                    <option value="ks">ks</option>
                    <option value="m">m</option>
                    <option value="kpl">kpl</option>
                </select>
            ) : (
                <span className="text-gray-500 text-xs">{product.unit}</span>
            )}
        </td>

        {/* Actions */}
        <td className="p-3 text-center">
            {editingProductId === product.id ? (
                <div className="flex justify-center gap-1">
                    <button onClick={handleSaveEdit} className="p-1 bg-green-100 text-green-700 rounded hover:bg-green-200"><Check size={16}/></button>
                    <button onClick={() => setEditingProductId(null)} className="p-1 bg-gray-100 text-gray-500 rounded hover:bg-gray-200"><X size={16}/></button>
                </div>
            ) : (
                <div className="flex justify-center gap-1">
                    <button onClick={() => handleStartEdit(product)} className="p-1 text-blue-500 hover:bg-blue-50 rounded"><Edit size={16}/></button>
                    <button onClick={() => onDeleteProduct(product.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                </div>
            )}
        </td>
    </tr>
  );

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-6xl max-h-[90vh] flex flex-col">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Settings className="text-purple-600" />
            <h2 className="text-xl font-bold text-gray-800">Správca Katalógu</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
            <X size={20}/>
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200">
            <button 
                onClick={() => setActiveTab('products')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='products' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Produkty
            </button>
            <button 
                onClick={() => setActiveTab('categories')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='categories' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Kategórie
            </button>
            <button 
                onClick={() => setActiveTab('classes')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='classes' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Triedy Kabín
            </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-hidden flex flex-col">

            {/* --- PRODUCTS TAB --- */}
            {activeTab === 'products' && (
                <div className="flex-1 flex flex-col min-h-0">
                    {/* Toolbar */}
                    <div className="p-4 border-b bg-white flex flex-wrap gap-4 items-center justify-between">
                        <div className="flex items-center gap-2 flex-1">
                            {/* Category Filter */}
                            <select 
                                value={activeCategory} 
                                onChange={e => setActiveCategory(e.target.value)} 
                                className="border rounded-lg px-3 py-2 text-sm font-bold bg-gray-50 min-w-[150px]"
                            >
                                {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>

                            {/* Search */}
                            <div className="relative flex-1 max-w-sm">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                                <input 
                                    type="text" 
                                    placeholder="Hľadať produkt..." 
                                    value={searchTerm} 
                                    onChange={e => setSearchTerm(e.target.value)}
                                    className="w-full pl-9 pr-3 py-2 border rounded-lg text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                />
                            </div>
                        </div>

                        <div className="flex items-center gap-2">
                             {/* Bulk Actions */}
                             {selectedProductIds.size > 0 && (
                                <div className="flex items-center gap-2 bg-purple-50 px-3 py-1.5 rounded-lg border border-purple-100 mr-2 animate-in fade-in">
                                    <span className="text-xs font-bold text-purple-700">{selectedProductIds.size} vybraných</span>

                                    {isBulkMoveMode ? (
                                        <div className="flex items-center gap-2 bg-white rounded-lg p-1 border shadow-sm">
                                            <span className="text-xs font-bold text-gray-500 ml-2">Presunúť do:</span>
                                            {/* Target Category Select */}
                                            <select 
                                                className="text-sm border rounded p-1 font-bold text-blue-700 outline-none max-w-[150px]"
                                                value={bulkTargetCat}
                                                onChange={(e) => { setBulkTargetCat(e.target.value); setBulkTargetSubcat(''); }}
                                            >
                                                <option value="" disabled>Vybrať Kategóriu...</option>
                                                {allCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                            </select>

                                            {/* Target Subcategory Input/Select */}
                                            {bulkTargetCat && (
                                                <div className="relative w-40">
                                                    <input 
                                                        list="bulk-subcat-options"
                                                        placeholder="Podkategória..."
                                                        className="w-full text-sm border rounded p-1 px-2 outline-none font-bold text-gray-700"
                                                        value={bulkTargetSubcat}
                                                        onChange={e => setBulkTargetSubcat(e.target.value)}
                                                        onKeyDown={e => e.key === 'Enter' && handleBulkMoveConfirm()}
                                                        autoFocus
                                                    />
                                                    <datalist id="bulk-subcat-options">
                                                        {bulkTargetSubcategoriesOptions.map(s => <option key={s} value={s}/>)}
                                                    </datalist>
                                                </div>
                                            )}

                                            <button 
                                                onClick={handleBulkMoveConfirm} 
                                                disabled={!bulkTargetCat}
                                                className="bg-green-500 text-white p-1 rounded hover:bg-green-600 disabled:opacity-50"
                                                title="Potvrdiť presun"
                                            >
                                                <ArrowRightCircle size={18}/>
                                            </button>
                                            <button onClick={() => setIsBulkMoveMode(false)} className="p-1 hover:bg-gray-100 rounded text-gray-400"><X size={18}/></button>
                                        </div>
                                    ) : (
                                        <button onClick={() => { setIsBulkMoveMode(true); setBulkTargetCat(activeCategory); }} className="px-3 py-1.5 bg-white border border-blue-200 text-blue-700 font-bold rounded text-sm hover:bg-blue-100 flex items-center gap-2">
                                            <CornerDownRight size={16}/> Presunúť
                                        </button>
                                    )}

                                    {!isBulkMoveMode && (
                                        <button onClick={handleDeleteSelected} className="px-3 py-1.5 bg-white border border-red-200 text-red-600 font-bold rounded text-sm hover:bg-red-50 flex items-center gap-2">
                                            <Trash2 size={16}/> Vymazať
                                        </button>
                                    )}
                                </div>
                             )}

                            {/* Import Button */}
                            <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => e.target.files?.[0] && onImportCatalog(e.target.files[0])} />
                            <button onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Importovať JSON katalóg">
                                <Upload size={20}/>
                            </button>
                        </div>
                    </div>

                    {/* Products Table */}
                    <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                        <table className="w-full text-sm bg-white border rounded-lg shadow-sm overflow-hidden">
                            <thead className="bg-gray-100 text-gray-600 font-bold uppercase text-xs sticky top-0 z-10 shadow-sm">
                                <tr>
                                    <th className="p-3 w-10 text-center">
                                        <button onClick={toggleSelectAll} className="text-gray-500 hover:text-black">
                                            {selectedProductIds.size > 0 && selectedProductIds.size === filteredProducts.length ? <CheckSquare size={16}/> : <Square size={16}/>}
                                        </button>
                                    </th>
                                    <th className="p-3 text-left">Názov Produktu</th>
                                    <th className="p-3 text-left w-32">Podkategória</th>
                                    <th className="p-3 text-right w-24">Cena (€)</th>
                                    <th className="p-3 text-right w-20">MJ</th>
                                    <th className="p-3 text-center w-24">Akcie</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {/* 1. General Products (No Subcategory) */}
                                {generalProducts.map(renderProductRow)}

                                {/* 2. Grouped Products */}
                                {sortedSubcategories.map(subcat => {
                                    const items = groupedProducts[subcat];
                                    const isExpanded = expandedGroups.has(subcat);

                                    return (
                                        <React.Fragment key={subcat}>
                                            {/* Subcategory Header */}
                                            <tr 
                                                className="bg-gray-100 cursor-pointer hover:bg-gray-200 transition border-y border-gray-200"
                                                onClick={() => toggleGroupExpand(subcat)}
                                            >
                                                <td className="p-2 text-center text-gray-500">
                                                    {isExpanded ? <ChevronDown size={16}/> : <ChevronRight size={16}/>}
                                                </td>
                                                <td colSpan={5} className="p-2">
                                                    <div className="flex items-center gap-2 font-bold text-gray-800 uppercase text-xs tracking-wider">
                                                        {isExpanded ? <FolderOpen size={18} className="text-blue-600"/> : <Folder size={18} className="text-gray-400"/>}
                                                        {subcat}
                                                        <span className="ml-2 bg-white text-gray-600 px-2 py-0.5 rounded-full text-[10px] border border-gray-300 shadow-sm">
                                                            {items.length} produktov
                                                        </span>
                                                    </div>
                                                </td>
                                            </tr>
                                            {/* Items in Group */}
                                            {isExpanded && items.map(renderProductRow)}
                                        </React.Fragment>
                                    );
                                })}

                                {filteredProducts.length === 0 && (
                                    <tr>
                                        <td colSpan={6} className="text-center py-8 text-gray-400 italic">Žiadne produkty v tejto kategórii.</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* --- CATEGORIES TAB --- */}
            {activeTab === 'categories' && (
                <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
                    <div className="max-w-3xl mx-auto space-y-6">
                        {/* Add New Category */}
                        <div className="bg-white p-4 rounded-xl border border-purple-200 shadow-sm flex gap-2">
                            <input 
                                className="flex-1 border border-gray-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-purple-500"
                                placeholder="Názov novej kategórie..."
                                value={newCategoryName}
                                onChange={e => setNewCategoryName(e.target.value)}
                            />
                            <button onClick={handleAddCategorySubmit} className="bg-purple-600 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-purple-700">
                                <Plus size={18}/> Pridať
                            </button>
                        </div>

                        {/* List */}
                        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="p-3 bg-gray-100 text-xs font-bold text-gray-500 uppercase border-b">Existujúce Kategórie</div>
                            <div className="divide-y divide-gray-100">
                                {customCategories.map(cat => (
                                    <div key={cat} className="p-4 flex justify-between items-center hover:bg-gray-50 group">
                                        <div className="flex items-center gap-3">
                                            <Layers className="text-gray-400" size={20}/>
                                            <span className="font-bold text-gray-800">{cat}</span>
                                            <span className="text-xs text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">
                                                {products.filter(p => p.category === cat).length} produktov
                                            </span>
                                        </div>
                                        <button onClick={() => onDeleteCategory(cat)} className="text-gray-300 hover:text-red-500 transition">
                                            <Trash2 size={18}/>
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* --- CLASSES TAB --- */}
            {activeTab === 'classes' && (
                <div className="flex-1 overflow-y-auto p-6 bg-gray-50">
                    <div className="max-w-4xl mx-auto space-y-6">
                        <div className="bg-blue-50 p-4 rounded-lg border border-blue-100 text-sm text-blue-800 flex gap-2">
                            <AlertTriangle size={18} className="shrink-0"/>
                            <div>
                                Tu môžete definovať <strong>Triedy Kabín</strong> (napr. FUN, SKY, NEREZ).
                                Ku každej triede môžete priradiť <strong>SET Produkt</strong> z katalógu.
                                Ak je set priradený, Materiálový Sprievodca automaticky vloží tento set namiesto generickej kabíny.
                            </div>
                        </div>

                        {/* Add New Class */}
                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
                            <h3 className="font-bold text-lg mb-4 text-gray-800">Nová Trieda</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                                <input 
                                    className="border rounded px-3 py-2" placeholder="Názov (napr. EXCLUSIVE)"
                                    value={newClassName} onChange={e => setNewClassName(e.target.value)}
                                />
                                <input 
                                    className="border rounded px-3 py-2" placeholder="Popis (napr. Sklo / Kameň)"
                                    value={newClassDesc} onChange={e => setNewClassDesc(e.target.value)}
                                />
                                <div className="md:col-span-2">
                                    <label className="text-xs font-bold text-gray-500 uppercase mb-1 block">Prepojený SET Produkt (Voliteľné)</label>
                                    <select 
                                        className="w-full border rounded px-3 py-2 text-sm bg-white"
                                        value={newClassLinkedSet}
                                        onChange={e => setNewClassLinkedSet(e.target.value)}
                                    >
                                        <option value="">-- Žiadne prepojenie --</option>
                                        {products.filter(p => p.type === 'composite').map(p => (
                                            <option key={p.id} value={p.id}>📦 {p.name} ({p.price}€)</option>
                                        ))}
                                    </select>
                                </div>
                            </div>
                            <button onClick={handleAddClassSubmit} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700">
                                Uložiť Triedu
                            </button>
                        </div>

                        {/* Classes List */}
                        <div className="space-y-2">
                            {cabinClasses.map(cc => {
                                const linkedProduct = products.find(p => p.id === cc.linkedProductId);
                                return (
                                    <div key={cc.id} className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex justify-between items-center group">
                                        <div>
                                            <div className="font-bold text-lg text-gray-800">{cc.name}</div>
                                            <div className="text-gray-500 text-sm">{cc.description}</div>
                                            {linkedProduct && (
                                                <div className="mt-2 text-xs bg-green-50 text-green-700 px-2 py-1 rounded inline-flex items-center gap-1 border border-green-100">
                                                    <Box size={12}/> Link: <strong>{linkedProduct.name}</strong>
                                                </div>
                                            )}
                                        </div>
                                        <button onClick={() => onDeleteCabinClass(cc.id)} className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded transition">
                                            <Trash2 size={20}/>
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { QuoteCategory, QuoteItem } from '../types';
import { Trash2, Plus, Sparkles, Bold, Italic, Link, Image as ImageIcon, Table, List, ListOrdered, FileText, ChevronDown, ChevronUp, BookOpen, Layers, Box, Eye, EyeOff, Replace, Printer, Percent, GripVertical } from 'lucide-react';

interface CategoryTableProps {
  category: QuoteCategory;
  currency: string;
  globalMargin: number;
  onUpdateCategory: (id: string, field: keyof QuoteCategory, value: any) => void;
  onDeleteCategory: (id: string) => void;
  onAddItem: (categoryId: string, isSurcharge?: boolean) => void;
  onUpdateItem: (categoryId: string, itemId: string, field: keyof QuoteItem, value: any) => void;
  onDeleteItem: (categoryId: string, itemId: string) => void;
  onAiSuggest: (categoryId: string, categoryName: string) => void;
  onOpenCatalog: (categoryId: string, itemId?: string) => void;
  onMoveCategory?: (id: string, direction: 'up' | 'down') => void;
  isAiLoading: boolean;
  readOnly?: boolean; // New prop for locking edits
  hidePrices?: boolean; // New prop for hiding price columns (Contract mode or Toggle)

  // Drag Category Props
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent, id: string) => void;
  onDragOver?: (e: React.DragEvent, id: string) => void;
  onDragEnd?: (e: React.DragEvent) => void;
}

export const CategoryTable: React.FC<CategoryTableProps> = ({
  category,
  currency,
  globalMargin,
  onUpdateCategory,
  onDeleteCategory,
  onAddItem,
  onUpdateItem,
  onDeleteItem,
  onAiSuggest,
  onOpenCatalog,
  onMoveCategory,
  isAiLoading,
  readOnly = false,
  hidePrices = false,
  draggable, onDragStart, onDragOver, onDragEnd
}) => {
  const [showRichText, setShowRichText] = useState(!!category.textContent);
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Sync initial content
  useEffect(() => {
    if (showRichText && editorRef.current && category.textContent && editorRef.current.innerHTML !== category.textContent) {
       editorRef.current.innerHTML = category.textContent;
    }
  }, [showRichText, category.id]); 

  const formatNumber = (num: number) => {
    return num.toLocaleString('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const getSellingPrice = (costPrice: number) => {
    return costPrice * (1 + globalMargin / 100);
  };

  const isEmpty = category.items.length === 0 && !category.textContent;
  const isHidden = category.isHidden;
  const isHiddenFromPrint = category.isHiddenFromPrint;

  // --- Editor Logic ---
  const handleInput = () => {
    if (editorRef.current && !readOnly) {
      onUpdateCategory(category.id, 'textContent', editorRef.current.innerHTML);
    }
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const insertImage = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (readerEvent) => {
          const result = readerEvent.target?.result as string;
          execCmd('insertImage', result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const insertLink = () => {
    const url = prompt('Vložte URL odkazu (napr. na video):');
    if (url) execCmd('createLink', url);
  };

  const insertTable = () => {
    const html = `
      <table style="width: 100%; border-collapse: collapse; margin: 10px 0;">
        <tbody>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
        </tbody>
      </table>
      <p><br/></p>
    `;
    execCmd('insertHTML', html);
  };

  const toggleRichText = () => {
      setShowRichText(!showRichText);
  };

  const toggleSection = () => {
      if(readOnly) return;
      const newSection = category.section === 'shaft' ? 'lift' : 'shaft';
      onUpdateCategory(category.id, 'section', newSection);
  };

  const toggleVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHidden', !isHidden);
  };

  const togglePrintVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHiddenFromPrint', !isHiddenFromPrint);
  }

  // --- ITEM DRAG & DROP HANDLERS ---
  const onDragStartItem = (e: React.DragEvent, itemId: string) => {
      e.stopPropagation(); // Stop propagation so category D&D doesn't trigger
      setDraggedItemId(itemId);
      e.dataTransfer.effectAllowed = 'move';
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndItem = (e: React.DragEvent) => {
      e.stopPropagation();
      setDraggedItemId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverItem = (e: React.DragEvent, targetItemId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!draggedItemId || draggedItemId === targetItemId) return;

      const items = category.items;
      const draggedIndex = items.findIndex(i => i.id === draggedItemId);
      const targetIndex = items.findIndex(i => i.id === targetItemId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      onUpdateCategory(category.id, 'items', newItems);
  };

  // Determine classes based on hidden states
  let wrapperClasses = "mb-4 flex border rounded-lg overflow-hidden bg-white shadow-sm break-inside-avoid transition-all";
  if (isHidden) {
      // Completely hidden (Grayed out)
      wrapperClasses += " opacity-60 grayscale border-dashed border-gray-400 print:hidden";
  } else if (isHiddenFromPrint) {
      // Hidden from Print ONLY (Red dashed border in UI)
      wrapperClasses += " border-red-300 border-2 border-dashed print:hidden bg-red-50/30";
  } else {
      // Normal
      wrapperClasses += " border-gray-300 print:border-gray-300 print:shadow-none";
  }

  if (isEmpty) wrapperClasses += " print:hidden";
  if (readOnly) wrapperClasses += " border-gray-200";

  return (
    <div className={wrapperClasses}>

      {/* STRICT PRINT HIDING LOGIC */}
      {/* This allows Admin to see prices on screen, but enforces hiding in Print */}
      {hidePrices && (
          <style>{`
              @media print {
                  .price-column-strict { display: none !important; }
              }
          `}</style>
      )}

      {/* Left Vertical Sidebar - Category Name (With D&D Handle) */}
      <div 
          className={`w-10 border-r border-gray-300 flex flex-col items-center py-2 relative print:border-gray-300 print:w-8 ${isHidden ? 'bg-gray-200' : isHiddenFromPrint ? 'bg-red-50' : 'bg-gray-100'} ${draggable && !readOnly ? 'cursor-grab active:cursor-grabbing' : ''}`}
          draggable={draggable && !readOnly}
          onDragStart={(e) => onDragStart && onDragStart(e, category.id)}
          onDragOver={(e) => onDragOver && onDragOver(e, category.id)}
          onDragEnd={onDragEnd || undefined}
      >

        {/* Section Toggle (Lift/Shaft) */}
        <button 
            onClick={toggleSection}
            disabled={readOnly}
            className={`no-print p-1 rounded mb-2 transition ${category.section === 'shaft' ? 'text-blue-600 bg-blue-100 hover:bg-blue-200' : 'text-gray-500 hover:bg-gray-200'} ${readOnly ? 'opacity-50 cursor-not-allowed' : ''}`}
            title={category.section === 'shaft' ? "Patrí do: Šachta / Konštrukcia" : "Patrí do: Výťah / Technológia"}
        >
            {category.section === 'shaft' ? <Box size={18} /> : <Layers size={18} />}
        </button>

        {/* Vertically Centered Text */}
        <div className="flex-1 flex items-center justify-center">
             <div className="transform -rotate-90 whitespace-nowrap">
                {readOnly ? (
                    <span className="font-bold text-lg text-gray-800 w-64 text-center block">{category.name}</span>
                ) : (
                    <input
                        type="text"
                        value={category.name}
                        onChange={(e) => onUpdateCategory(category.id, 'name', e.target.value)}
                        className="bg-transparent font-bold text-lg text-gray-800 text-center focus:outline-none focus:text-black placeholder-gray-400 print:text-black w-64"
                        placeholder="Názov Kategórie"
                    />
                )}
            </div>
        </div>
      </div>

      {/* Right Content - Table & Actions */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Category Toolbar - Hide most actions if ReadOnly */}
        <div className={`bg-gray-50 p-1 flex justify-end gap-2 border-b border-gray-200 print:hidden ${readOnly ? 'bg-gray-100' : ''}`}>

           {/* Move Buttons */}
           {!readOnly && onMoveCategory && (
                <div className="flex gap-1 mr-auto border-r pr-2 border-gray-300">
                     <button onClick={() => onMoveCategory(category.id, 'up')} className="p-1 hover:bg-gray-200 rounded text-gray-600" title="Posunúť hore"><ChevronUp size={16}/></button>
                     <button onClick={() => onMoveCategory(category.id, 'down')} className="p-1 hover:bg-gray-200 rounded text-gray-600" title="Posunúť dole"><ChevronDown size={16}/></button>
                </div>
           )}

           {category.section === 'shaft' && (
               <span className="mr-auto text-xs font-bold text-blue-600 uppercase tracking-wider bg-blue-50 px-2 py-1 rounded border border-blue-100 flex items-center gap-1">
                   <Box size={12}/> Šachta / Konštrukcia
               </span>
           )}

            {!readOnly && (
                <>
                    {/* HIDE FROM PRINT (But Calculate) */}
                    <button
                        onClick={togglePrintVisibility}
                        className={`flex items-center gap-1 px-2 py-1 text-xs font-medium rounded transition ${isHiddenFromPrint ? 'bg-red-100 text-red-600 border border-red-200' : 'text-gray-400 hover:bg-gray-200 hover:text-black'}`}
                        title={isHiddenFromPrint ? "Položka sa TLAČÍ (Zahrnutá v cene)" : "Skryť pri tlači (ALE POČÍTAŤ CENU)"}
                    >
                         <div className="relative">
                            <Printer size={18} />
                            {isHiddenFromPrint && <div className="absolute inset-0 flex items-center justify-center"><div className="w-full h-0.5 bg-red-600 rotate-45 transform"></div></div>}
                         </div>
                    </button>

                    {/* HIDE COMPLETELY (Exclude) */}
                    <button
                        onClick={toggleVisibility}
                        className={`flex items-center gap-1 px-2 py-1 text-xs font-medium rounded transition ${isHidden ? 'bg-gray-300 text-gray-700' : 'text-gray-400 hover:bg-gray-200 hover:text-black'}`}
                        title={isHidden ? "Zobraziť (Zahrnúť do ceny)" : "Skryť ÚPLNE (Vyradiť z ceny)"}
                    >
                        {isHidden ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>

                    <div className="w-px bg-gray-300 mx-1"></div>

                    <button
                        onClick={toggleRichText}
                        className={`flex items-center gap-1 px-3 py-1 text-xs font-medium rounded transition ${showRichText ? 'bg-blue-100 text-blue-700' : 'text-gray-600 hover:bg-gray-200'}`}
                        title="Pridať textový popis, obrázky alebo tabuľky"
                    >
                        <FileText size={14} />
                        {showRichText ? 'Skryť popis' : 'Pridať technický popis'}
                    </button>
                    <button
                        onClick={() => onAiSuggest(category.id, category.name)}
                        disabled={isAiLoading}
                        className="flex items-center gap-1 px-3 py-1 text-xs font-medium text-black bg-yellow-400 rounded hover:bg-yellow-500 transition disabled:opacity-50"
                        title="AI Navrhnúť položky"
                    >
                        <Sparkles size={14} />
                        {isAiLoading ? '...' : 'AI Položky'}
                    </button>
                    <button
                        onClick={() => onDeleteCategory(category.id)}
                        className="text-gray-400 hover:text-red-600 transition"
                        title="Odstrániť kategóriu"
                    >
                        <Trash2 size={18} />
                    </button>
                </>
            )}
            {readOnly && (
                 <span className="text-xs text-gray-400 font-medium uppercase tracking-wider flex items-center gap-1">
                     <FileText size={12}/> Príloha
                 </span>
            )}
        </div>

        {/* 1. Items Table - REDUCED PADDING */}
        {category.items.length > 0 && (
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-100 text-gray-600 font-medium print:bg-gray-50 print:text-gray-600 print:border-b print:border-gray-300 text-xs">
              <tr>
                {!readOnly && <th className="px-1 py-1 w-6 no-print"></th>}
                <th className="px-2 py-1 w-8 no-print align-top border-b border-gray-200">#</th>
                <th className="px-2 py-1 align-top border-b border-gray-200 w-auto">Popis položky</th>
                <th className="px-2 py-1 w-14 text-right align-top border-b border-gray-200">M.J.</th>
                <th className="px-2 py-1 w-16 text-right align-top border-b border-gray-200">Mn.</th>

                {/* Price Column - Visible on Screen, Hidden in Print if toggled */}
                <th className={`px-2 py-1 w-24 text-right align-top border-b border-gray-200 price-column-strict ${hidePrices ? '' : ''}`}>
                    <span className={`print:hidden ${readOnly ? 'text-black' : 'text-blue-600'}`}>
                        {readOnly ? 'Cena/J' : 'Nákup/J'}
                    </span>
                    <span className="hidden print:inline">Cena/J</span>
                </th>

                {!readOnly && <th className="px-2 py-1 w-16 no-print align-top border-b border-gray-200"></th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 print:divide-gray-200">
              {category.items.map((item, index) => {
                const sellingPrice = getSellingPrice(item.unitPrice);
                return (
                <tr 
                    key={item.id} 
                    className={`hover:bg-gray-50 group transition-colors print:hover:bg-transparent ${item.isSurcharge ? 'bg-gray-50/50' : ''}`}
                    draggable={!readOnly}
                    onDragStart={(e) => onDragStartItem(e, item.id)}
                    onDragOver={(e) => onDragOverItem(e, item.id)}
                    onDragEnd={onDragEndItem}
                >
                  {!readOnly && (
                      <td className="px-1 py-1 text-center no-print text-gray-300 cursor-grab hover:text-gray-500">
                          <GripVertical size={14}/>
                      </td>
                  )}
                  <td className="px-2 py-1 text-gray-500 no-print align-top text-xs">{index + 1}</td>
                  <td className="px-2 py-1 align-top relative">
                    {readOnly ? (
                        <div className={`text-gray-900 whitespace-pre-wrap leading-tight ${item.isSurcharge ? 'pl-6 italic text-gray-600' : ''}`}>
                            {item.isSurcharge && <span className="absolute left-2 top-1 text-gray-400 text-[10px]">•</span>}
                            {item.description}
                        </div>
                    ) : (
                        <div className={`flex gap-2 ${item.isSurcharge ? 'pl-6' : ''}`}>
                             {item.isSurcharge && <span className="absolute left-2 top-2 text-gray-400 text-[10px]">•</span>}
                             <textarea
                                rows={1}
                                value={item.description}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'description', e.target.value)}
                                className={`w-full bg-transparent focus:outline-none focus:text-black resize-y min-h-[1.5rem] placeholder-gray-400 print:text-black leading-tight ${item.isSurcharge ? 'italic text-gray-600' : 'text-gray-900'}`}
                                placeholder="Názov položky..."
                            />
                            {/* In-row Catalog Button = Swap Item */}
                            <button
                                onClick={() => onOpenCatalog(category.id, item.id)}
                                className="no-print self-start p-1.5 text-blue-400 bg-blue-50 hover:bg-blue-100 hover:text-blue-700 rounded transition opacity-0 group-hover:opacity-100 focus:opacity-100"
                                title="Vybrať variant z katalógu (Vymeniť)"
                            >
                                <BookOpen size={14} />
                            </button>
                        </div>
                    )}
                  </td>
                  <td className="px-2 py-1 align-top text-right">
                    {readOnly ? (
                         <span className="text-gray-900 text-xs">{item.unit}</span>
                    ) : (
                        <select
                            value={item.unit}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'unit', e.target.value)}
                            className="w-full text-right bg-white text-gray-900 border border-gray-300 rounded px-1 py-0 focus:outline-none focus:border-yellow-500 appearance-none print:bg-transparent print:text-black print:border-none print:appearance-auto text-xs"
                        >
                            <option value="ks">ks</option>
                            <option value="m">m</option>
                            <option value="hod">hod</option>
                            <option value="kpl">kpl</option>
                        </select>
                    )}
                  </td>
                  <td className="px-2 py-1 align-top text-right">
                    {readOnly ? (
                        <span className="text-gray-900 font-medium text-xs">{item.quantity}</span>
                    ) : (
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={item.quantity}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'quantity', parseFloat(e.target.value) || 0)}
                            className="w-full text-right bg-transparent text-gray-900 font-medium focus:outline-none print:text-black text-xs"
                        />
                    )}
                  </td>

                  {/* Price Column - Controlled by CSS Style Block */}
                  <td className="px-2 py-1 align-top text-right price-column-strict">
                    {readOnly ? (
                        <span className="text-xs font-medium text-black block">
                            {formatNumber(sellingPrice)} {currency}
                        </span>
                    ) : (
                        <>
                            {/* EDIT MODE: Input for Cost - Visually dimmed if intended hidden, but still visible to admin */}
                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={item.unitPrice}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                                className={`w-full text-right bg-transparent font-bold focus:outline-none text-xs print:hidden cursor-text ${hidePrices ? 'text-gray-400' : 'text-blue-700 bg-blue-50/20'}`}
                                placeholder="0.00"
                                title="Upraviť cenu (Len pre túto ponuku)"
                            />
                            {/* PRINT MODE: Calculated Selling Price */}
                            <span className="hidden print:block text-xs font-medium text-black">
                                {formatNumber(sellingPrice)} {currency}
                            </span>
                        </>
                    )}
                  </td>

                  {/* Delete/Add Surcharge Action - Hidden in ReadOnly */}
                  {!readOnly && (
                    <td className="px-2 py-1 text-center no-print align-top flex justify-center gap-1">
                        <button
                            onClick={() => onAddItem(category.id, true)}
                            className="text-gray-300 hover:text-blue-500 hover:bg-blue-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                            title="Pridať príplatok / pod-položku"
                        >
                            <Percent size={14} />
                        </button>
                        <button
                            onClick={() => onDeleteItem(category.id, item.id)}
                            className="text-gray-300 hover:text-red-500 hover:bg-red-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <Trash2 size={14} />
                        </button>
                    </td>
                  )}
                </tr>
              )})}
            </tbody>
          </table>
        </div>
        )}

          {!readOnly && (
            <div className="p-2 border-t border-gray-200 bg-gray-50 no-print flex gap-2">
                <button
                onClick={() => onAddItem(category.id)}
                className="flex items-center gap-1 text-sm font-medium text-gray-600 hover:text-black px-2 py-1 rounded hover:bg-gray-200 transition"
                >
                <Plus size={16} /> Pridať položku
                </button>
                <button
                onClick={() => onOpenCatalog(category.id)}
                className="flex items-center gap-1 text-sm font-medium text-blue-600 hover:text-blue-800 px-2 py-1 rounded hover:bg-blue-50 transition ml-auto"
                >
                <BookOpen size={16} /> Z katalógu
                </button>
            </div>
          )}

          {/* 2. Embedded Rich Text Area - RENDERED BELOW ITEMS */}
          {(showRichText || (readOnly && category.textContent)) && (
            <div className="border-t border-gray-200 p-4 bg-white">
                <div className="mb-2 text-xs font-bold text-gray-400 uppercase tracking-wider print:hidden">Technická špecifikácia / Prílohy</div>

                {/* Editor Content */}
                <div
                    ref={editorRef}
                    contentEditable={!readOnly}
                    onInput={handleInput}
                    className={`rich-text-content w-full min-h-[80px] outline-none text-gray-900 text-sm ${readOnly ? 'pointer-events-none' : ''}`}
                    dangerouslySetInnerHTML={{ __html: category.textContent || '' }}
                />
            </div>
          )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
