  if (!isOpen) return null;

  const filteredClients = clients.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSaveNew = () => {
    if (!newName) return;
    onAddClient({
      id: generateId(),
      name: newName,
      details: newDetails,
      email: newEmail,
      phone: newPhone
    });
    setIsAdding(false);
    setNewName('');
    setNewDetails('');
    setNewEmail('');
    setNewPhone('');
