            >
              <Plus size={18} /> Pridať nového klienta
            </button>
          )}

          {/* List */}
          <div className="space-y-2">
            {filteredClients.length === 0 ? (
              <div className="text-center py-8 text-gray-400 italic">Žiadni klienti v adresári.</div>
            ) : (
              filteredClients.map(client => (
