// --- Safe ID Generator ---
const generateId = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    try {
      return crypto.randomUUID();
    } catch (e) {}
  }
  return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

const defaultLayout: LiftLayoutData = {
  liftType: 'passenger', driveType: 'traction', ratedLoad: 630, numberOfPersons: 8, ratedSpeed: 1.0, powerSupply: '3x400V',
  shaftWidth: 1600, shaftDepth: 1800, cabinWidth: 1100, cabinDepth: 1400, doorWidth: 900, doorOffsetL: 0,
  pitDepth: 1100, headroomHeight: 3400, travelHeight: 15000,
  doorType: 'central', doorOperation: 'automatic', counterWeightPosition: 'back', machineRoomPosition: 'head',
  suspensionType: '1:1', tractionMedium: 'ropes', frameType: 'backpack',
  gapLeft: 50, gapRight: 50, gapRear: 50, gapFront: 50,
  guideTypeCar: 'T90', guideTypeCwt: 'T50', guideRailLength: 5000,
  notes: ''
};

export default function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [quotes, setQuotes] = useState<QuoteData[]>([]);
  const [templates, setTemplates] = useState<QuoteTemplate[]>([]);
  const [contractTemplates, setContractTemplates] = useState<ContractTemplate[]>([]);
  const [cabinClasses, setCabinClasses] = useState<CabinClass[]>([]);
  const [customCategories, setCustomCategories] = useState<string[]>([
    'Pohon', 'Kabína a rám', 'Dvere', 'Vodítka a kotvenie', 'Obmedzovač', 
    'Elektro', 'Montáž', 'Ostatné šachta', 'Ostatné', 
    'Oceľová konštrukcia', 'Doprava', 'Balné'
  ]);
  const [settings, setSettings] = useState<AppSettings>({
    nextCpSequence: 100, nextObjSequence: 100, nextPlSequence: 100
  });

  const [activeQuote, setActiveQuote] = useState<QuoteData | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isTechSpecVisible, setIsTechSpecVisible] = useState(true);
  const [isSketchVisible, setIsSketchVisible] = useState(true);

  // Modal States
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isClientDbOpen, setIsClientDbOpen] = useState(false);
  const [isSupplierDbOpen, setIsSupplierDbOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [templateModalMode, setTemplateModalMode] = useState<'select' | 'save'>('select');
  const [templateModalType, setTemplateModalType] = useState<'lift' | 'shaft'>('lift');
  const [isProductDbOpen, setIsProductDbOpen] = useState(false);
  const [activeCategoryForProduct, setActiveCategoryForProduct] = useState<string | null>(null);
  const [activeItemForProduct, setActiveItemForProduct] = useState<string | null>(null);
  const [isMaterialCalcOpen, setIsMaterialCalcOpen] = useState(false);
  const [isEmailOpen, setIsEmailOpen] = useState(false);
  const [isContractRepoOpen, setIsContractRepoOpen] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('smartquote_data');
    if (saved) {
        try {
            const data = JSON.parse(saved);
            if (data.products) setProducts(data.products);
            if (data.clients) setClients(data.clients);
            if (data.suppliers) setSuppliers(data.suppliers);
            if (data.quotes) setQuotes(data.quotes);
            if (data.templates) setTemplates(data.templates);
            if (data.contractTemplates) setContractTemplates(data.contractTemplates);
            if (data.cabinClasses) setCabinClasses(data.cabinClasses);
            if (data.customCategories) setCustomCategories(data.customCategories);
            if (data.settings) setSettings(data.settings);
        } catch (e) { console.error("Failed to load", e); }
    }
  }, []);

  useEffect(() => {
      const data = { products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings };
      localStorage.setItem('smartquote_data', JSON.stringify(data));
  }, [products, clients, suppliers, quotes, templates, contractTemplates, cabinClasses, customCategories, settings]);

  // --- ACTIONS ---

  const handleCreateQuote = () => {
    try {
      const newQuote: QuoteData = {
        id: generateId(),
        number: `CP_SK_${settings.nextCpSequence}_${new Date().getFullYear().toString().slice(-2)}_BA`,
        type: 'quote',
        title: 'Nová Cenová Ponuka',
        date: new Date().toISOString().split('T')[0],
        validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
        supplier: { name: '', details: '' },
        client: { name: '', details: '' },
        categories: customCategories.map(name => ({ id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift' })),
        currency: '€',
        globalMargin: 10,
        shaftMargin: 10,
        terms: '',
        layout: { ...defaultLayout }
      };
      setActiveQuote(newQuote);
      setSettings(prev => ({...prev, nextCpSequence: prev.nextCpSequence + 1}));
    } catch (e) {
      console.error("Error creating quote:", e);
      alert("Chyba pri vytváraní ponuky.");
    }
  };

  // --- AUTO-OPEN LOGIC (Bypass Dashboard) ---
  useEffect(() => {
      if (isAuthenticated && !activeQuote) {
          // If we have existing quotes, open the last one
          if (quotes.length > 0) {
              setActiveQuote(quotes[quotes.length - 1]);
          } else {
              // Otherwise create a new one immediately
              handleCreateQuote();
          }
      }
  }, [isAuthenticated]);

  const handleSaveQuote = () => {
    if (!activeQuote) return;
    const updated = { ...activeQuote, lastUpdated: Date.now() };
    setQuotes(prev => {
        const idx = prev.findIndex(q => q.id === updated.id);
        if (idx >= 0) {
            const copy = [...prev]; copy[idx] = updated; return copy;
        }
        return [...prev, updated];
    });
    alert('Ponuka bola uložená.');
  };

  const handleDeleteQuote = (id: string) => {
      if(window.confirm("Naozaj vymazať ponuku?")) {
          setQuotes(prev => prev.filter(q => q.id !== id));
      }
  };

  const calculateTotals = () => {
      if (!activeQuote) return { cost: 0, price: 0, profit: 0 };
      let totalCost = 0;
      let totalPrice = 0;

      activeQuote.categories.forEach(cat => {
          if (cat.isHidden) return; // Skip completely hidden
          cat.items.forEach(item => {
               const quantity = item.quantity || 0;
               const unitPrice = item.unitPrice || 0;
               const cost = quantity * unitPrice;

               // Apply correct margin based on section
               const margin = cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin;
               const price = cost * (1 + margin / 100);

               totalCost += cost;
               totalPrice += price;
          });
      });

      return { cost: totalCost, price: totalPrice, profit: totalPrice - totalCost };
  };

  // --- ITEM HANDLERS ---
  const handleUpdateCategory = (id: string, field: keyof QuoteCategory, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => c.id === id ? { ...c, [field]: value } : c)
      });
  };

  const handleAddItem = (catId: string, isSurcharge = false) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: [...c.items, {
                      id: generateId(),
                      description: isSurcharge ? 'Príplatok: ' : '',
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20,
                      isSurcharge
                  }]
              };
          })
      });
  };

  const handleUpdateItem = (catId: string, itemId: string, field: keyof QuoteItem, value: any) => {
      if (!activeQuote) return;
      setActiveQuote({
          ...activeQuote,
          categories: activeQuote.categories.map(c => {
              if (c.id !== catId) return c;
              return {
                  ...c,
                  items: c.items.map(i => i.id === itemId ? { ...i, [field]: value } : i)
              };
          })
      });
  };

  const handleSelectProduct = (product: Product) => {
      if (!activeQuote || !activeCategoryForProduct) return;

      const targetCatId = activeCategoryForProduct;
      const targetItemId = activeItemForProduct; // If replacing specific item

      setActiveQuote(prev => {
        if (!prev) return null;
        return {
            ...prev,
            categories: prev.categories.map(cat => {
                if (cat.id !== targetCatId) return cat;

                // Case A: Replacing existing item
                if (targetItemId) {
                    return {
                        ...cat,
                        items: cat.items.map(item => {
                            if (item.id !== targetItemId) return item;
                            return {
                                ...item,
                                description: product.name,
                                unit: product.unit,
                                unitPrice: product.price,
                                purchasePrice: product.price
                            };
                        })
                    };
                }

                // Case B: Adding new item
                return {
                    ...cat,
                    items: [...cat.items, {
                        id: generateId(),
                        description: product.name,
                        quantity: 1,
                        unit: product.unit,
                        unitPrice: product.price,
                        purchasePrice: product.price,
                        vatRate: 20
                    }]
                };
            })
        };
      });
      setIsProductDbOpen(false);
      setActiveItemForProduct(null);
  };

  // --- AI HANDLERS ---
  const handleAiSuggest = async (catId: string, catName: string) => {
      setIsAiLoading(true);
      const text = await generateSuggestion(`Navrhni 3 položky pre kategóriu "${catName}" pre výťah.`, 'category_items');
      setIsAiLoading(false);
      if (text) {
          const lines = text.split(',').map(s => s.trim()).filter(s => s);
          if (!activeQuote) return;
          setActiveQuote({
              ...activeQuote,
              categories: activeQuote.categories.map(c => {
                  if (c.id !== catId) return c;
                  const newItems = lines.map(desc => ({
                      id: generateId(),
                      description: desc,
                      quantity: 1,
                      unit: 'ks',
                      unitPrice: 0,
                      purchasePrice: 0,
                      vatRate: 20
                  }));
                  return { ...c, items: [...c.items, ...newItems] };
              })
          });
      }
  };

  const handleGenerateTerms = async () => {
      setIsAiLoading(true);
      const text = await generateSuggestion("Navrhni obchodné podmienky pre inštaláciu výťahu.", 'terms');
      setIsAiLoading(false);
      if (activeQuote && text) setActiveQuote({ ...activeQuote, terms: text });
  };

  // --- MATERIAL WIZARD ---
  const handleMaterialInsert = (data: any) => {
    if (!activeQuote) return;

    // Create map of existing categories by name to find IDs
    const catMap = new Map(activeQuote.categories.map(c => [c.name, c.id]));

    // Prepare updates
    let updatedCategories = [...activeQuote.categories];

    // Helper to find or create category
    const getCatId = (name: string) => {
        if (catMap.has(name)) return catMap.get(name)!;
        // Create if missing
        const newId = generateId();
        const newCat: QuoteCategory = { 
            id: newId, 
            type: 'items', 
            name: name, 
            items: [], 
            isExpanded: true, 
            section: name === 'Oceľová konštrukcia' || name === 'Ostatné šachta' ? 'shaft' : 'lift'
        };
        updatedCategories.push(newCat);
        catMap.set(name, newId);
        return newId;
    };

    data.items.forEach((item: any) => {
        const catId = getCatId(item.category);
        const catIndex = updatedCategories.findIndex(c => c.id === catId);
        if (catIndex >= 0) {
            updatedCategories[catIndex].items.push({
                id: generateId(),
                description: item.description,
                quantity: item.quantity,
                unit: item.unit,
                unitPrice: item.price || 0,
                purchasePrice: item.price || 0,
                vatRate: 20
            });
        }
    });

    // Addons
    if (data.includeTransport) {
        const cid = getCatId('Doprava');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: generateId(), description: 'Doprava materiálu na stavbu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includePackaging) {
        const cid = getCatId('Balné');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: generateId(), description: 'Balné a palety', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }
    if (data.includeAssembly) {
        const cid = getCatId('Montáž');
        const cidx = updatedCategories.findIndex(c => c.id === cid);
        updatedCategories[cidx].items.push({ id: generateId(), description: 'Montáž technológie výťahu', quantity: 1, unit: 'kpl', unitPrice: 0, purchasePrice: 0, vatRate: 20 });
    }

    setActiveQuote({ ...activeQuote, categories: updatedCategories });
  };

  // --- TEMPLATES & EXPORT ---
  const handlePrint = () => window.print();

  const handleSaveTemplate = (name: string, type: 'lift' | 'shaft') => {
      if (!activeQuote) return;
      const newTemplate: QuoteTemplate = {
          id: generateId(),
          name,
          type,
          data: {
              categories: activeQuote.categories.map(c => ({...c})), // Deep copy needed in real app
              layout: activeQuote.layout,
              margin: activeQuote.globalMargin
          }
      };
      setTemplates([...templates, newTemplate]);
  };

  const handleApplyTemplate = (t: QuoteTemplate) => {
      if (!activeQuote) return;
      // Merge categories
      // Ideally we replace or append. Let's replace items if category exists
      const newCats = [...activeQuote.categories];
      t.data.categories.forEach(tc => {
          const existing = newCats.find(c => c.name === tc.name);
          if (existing) {
              existing.items = [...existing.items, ...tc.items]; // Append
          } else {
              newCats.push({ ...tc, id: generateId() });
          }
      });

      setActiveQuote({
          ...activeQuote,
          categories: newCats,
          layout: t.data.layout ? { ...activeQuote.layout, ...t.data.layout } : activeQuote.layout,
          globalMargin: t.data.margin || activeQuote.globalMargin
      });
      setIsTemplateModalOpen(false);
  };

  // --- RENDER ---

  if (!isAuthenticated) return <LoginGate onLogin={() => setIsAuthenticated(true)} />;

  if (!activeQuote) {
      // Logic for showing dashboard ONLY if auto-open failed or explicitly closed (though in V4.5.0 we prefer direct editor)
      // Since we added auto-open logic, this part might flash briefly or show if creating quote fails.
      // But we will keep it as fallback.
      return (
        <div className="min-h-screen bg-gray-50 text-gray-900 font-sans flex items-center justify-center">
            <div className="text-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
                <p className="text-gray-500">Načítavam systém...</p>
            </div>
        </div>
      );
  }

  // --- EDITOR VIEW ---
  const totals = calculateTotals();

  return (
    <div className="min-h-screen bg-gray-100 text-gray-900 font-sans pb-32 print:pb-0 print:bg-white">
        {/* Editor Toolbar */}
        <header className="bg-white border-b px-4 py-2 sticky top-0 z-40 shadow-sm print:hidden flex justify-between items-center">
            <div className="flex items-center gap-4">
                <button onClick={() => setActiveQuote(null)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Zoznam ponúk"><ArrowLeft size={20}/></button>
                <div>
                    <div className="font-bold text-sm text-gray-500">{activeQuote.number}</div>
                    <input 
                        className="font-bold text-gray-800 bg-transparent outline-none focus:border-b border-blue-500 w-64"
                        value={activeQuote.title}
                        onChange={e => setActiveQuote({...activeQuote, title: e.target.value})}
                    />
                </div>
            </div>
            <div className="flex gap-2">
                <button onClick={() => setIsMaterialCalcOpen(true)} className="p-2 text-orange-600 bg-orange-50 hover:bg-orange-100 rounded font-bold flex items-center gap-2 text-sm"><Calculator size={16}/> Materiál</button>
                <div className="w-px bg-gray-300 mx-2"></div>
                <button onClick={handleSaveQuote} className="p-2 text-blue-600 hover:bg-blue-50 rounded" title="Uložiť"><Save size={20}/></button>
                <button onClick={handlePrint} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Tlačiť"><Printer size={20}/></button>
                <button onClick={() => setIsEmailOpen(true)} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Email"><Mail size={20}/></button>
                <button onClick={() => setIsSettingsOpen(true)} className="p-2 hover:bg-gray-100 rounded text-gray-600" title="Nastavenia"><Settings size={20}/></button>
            </div>
        </header>

        <main className="max-w-[210mm] mx-auto bg-white shadow-lg min-h-screen my-8 p-8 print:shadow-none print:m-0 print:p-0 print:w-full">

            {/* Header / Info */}
            <div className="flex justify-between mb-8 print:mb-4">
                <div className="w-1/2 pr-4">
                    <h1 className="text-2xl font-bold text-blue-800 mb-4">{activeQuote.title}</h1>
                    <div className="space-y-4">
                         {/* Supplier */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsSupplierDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Dodávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Firma..." value={activeQuote.supplier.name} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.supplier.details} onChange={e => setActiveQuote({...activeQuote, supplier: {...activeQuote.supplier, details: e.target.value}})} />
                         </div>
                         {/* Client */}
                         <div className="group relative border rounded p-3 hover:border-blue-400">
                             <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition no-print flex gap-1">
                                 <button onClick={() => setIsClientDbOpen(true)} className="p-1 bg-gray-100 hover:bg-blue-100 rounded text-blue-600"><Search size={14}/></button>
                             </div>
                             <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Objednávateľ</label>
                             <input className="w-full font-bold mb-1 outline-none" placeholder="Klient..." value={activeQuote.client.name} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, name: e.target.value}})} />
                             <textarea className="w-full text-sm resize-none outline-none text-gray-600" rows={3} placeholder="Adresa..." value={activeQuote.client.details} onChange={e => setActiveQuote({...activeQuote, client: {...activeQuote.client, details: e.target.value}})} />
                         </div>
                    </div>
                </div>
                <div className="w-1/2 pl-4 text-right">
                    {/* Meta Data */}
                    <div className="space-y-1 mb-6 text-sm">
                        <div><span className="text-gray-500">Číslo ponuky:</span> <span className="font-bold">{activeQuote.number}</span></div>
                        <div><span className="text-gray-500">Dátum:</span> <input type="date" value={activeQuote.date} onChange={e => setActiveQuote({...activeQuote, date: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                        <div><span className="text-gray-500">Platnosť do:</span> <input type="date" value={activeQuote.validUntil} onChange={e => setActiveQuote({...activeQuote, validUntil: e.target.value})} className="font-bold bg-transparent text-right outline-none"/></div>
                    </div>
                    {/* Lift Sketch */}
                    <div className="border border-gray-200 rounded-lg p-2 inline-block bg-white print:border-none">
                         <LiftLayoutSketch 
                            data={activeQuote.layout || defaultLayout} 
                            onChange={(f,v) => activeQuote.layout && setActiveQuote({...activeQuote, layout: {...activeQuote.layout, [f]: v}})}
                            isVisible={isSketchVisible}
                            onToggleVisibility={() => setIsSketchVisible(!isSketchVisible)}
                        />
                    </div>
                </div>
            </div>

            {/* Technical Specs */}
            {activeQuote.layout && (
                <TechSpecTable 
                    data={activeQuote.layout} 
                    isVisible={isTechSpecVisible} 
                    onToggleVisibility={() => setIsTechSpecVisible(!isTechSpecVisible)} 
                />
            )}

            {/* Category Tables */}
            <div className="space-y-6 mt-8">
                {activeQuote.categories.map((cat, idx) => (
                    <CategoryTable 
                        key={cat.id}
                        category={cat}
                        currency={activeQuote.currency}
                        globalMargin={cat.section === 'shaft' ? activeQuote.shaftMargin : activeQuote.globalMargin}
                        onUpdateCategory={handleUpdateCategory}
                        onDeleteCategory={() => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.filter(c => c.id !== cat.id)});
                        }}
                        onAddItem={(catId, isSurcharge) => handleAddItem(catId, isSurcharge)}
                        onUpdateItem={handleUpdateItem}
                        onDeleteItem={(catId, itemId) => {
                             setActiveQuote({...activeQuote, categories: activeQuote.categories.map(c => c.id === catId ? {...c, items: c.items.filter(i => i.id !== itemId)} : c)})
                        }}
                        onAiSuggest={handleAiSuggest}
                        onOpenCatalog={(catId, itemId) => {
                             setActiveCategoryForProduct(catId);
                             setActiveItemForProduct(itemId || null);
                             setIsProductDbOpen(true);
                        }}
                        onMoveCategory={(id, dir) => {
                            const cats = [...activeQuote.categories];
                            const index = cats.findIndex(c => c.id === id);
                            if (dir === 'up' && index > 0) {
                                [cats[index], cats[index-1]] = [cats[index-1], cats[index]];
                            } else if (dir === 'down' && index < cats.length - 1) {
                                [cats[index], cats[index+1]] = [cats[index+1], cats[index]];
                            }
                            setActiveQuote({...activeQuote, categories: cats});
                        }}
                        isAiLoading={isAiLoading}
                    />
                ))}

                {/* Add Category Button */}
                <div className="no-print border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-blue-400 transition cursor-pointer" onClick={() => {
                    const name = prompt("Názov novej kategórie:");
                    if (name) {
                        const newCat: QuoteCategory = { id: generateId(), type: 'items', name, items: [], isExpanded: true, section: 'lift' };
                        setActiveQuote({...activeQuote, categories: [...activeQuote.categories, newCat]});
                    }
                }}>
                    <div className="text-gray-500 font-bold flex items-center justify-center gap-2"><Plus/> Pridať Kategóriu</div>
                </div>
            </div>

            {/* Totals */}
            <div className="mt-12 border-t-2 border-gray-800 pt-4 flex justify-end print:break-inside-avoid">
                <div className="w-64">
                    <div className="flex justify-between mb-2 text-sm text-gray-500 no-print">
                        <span>Náklady (bez DPH):</span>
                        <span>{totals.cost.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between mb-2 text-sm text-green-600 no-print">
                        <span>Zisk ({((totals.profit/totals.cost)*100 || 0).toFixed(1)}%):</span>
                        <span>{totals.profit.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="flex justify-between text-xl font-bold text-gray-900 border-t pt-2">
                        <span>Cena Celkom:</span>
                        <span>{totals.price.toFixed(2)} {activeQuote.currency}</span>
                    </div>
                    <div className="text-right text-xs text-gray-500 mt-1">bez DPH</div>
                </div>
            </div>

            {/* Terms & Conditions */}
            <div className="mt-12 print:break-inside-avoid">
                <div className="flex justify-between items-center mb-4 no-print">
                    <h3 className="font-bold uppercase text-sm">Obchodné podmienky</h3>
                    <div className="flex gap-2">
                        <button onClick={handleGenerateTerms} disabled={isAiLoading} className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded hover:bg-yellow-200 flex items-center gap-1"><Lightbulb size={12}/> AI Návrh</button>
                        <button onClick={() => setIsContractRepoOpen(true)} className="text-xs bg-gray-100 text-gray-800 px-2 py-1 rounded hover:bg-gray-200 flex items-center gap-1"><FileText size={12}/> Zo Šablóny</button>
                    </div>
                </div>
                <StandaloneRichTextEditor 
                    content={activeQuote.terms} 
                    onChange={val => setActiveQuote({...activeQuote, terms: val})}
                    placeholder="Sem vložte text obchodných podmienok..."
                />
            </div>

            {/* Signature Area */}
            <div className="mt-16 flex justify-between print:break-inside-avoid text-sm">
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Objednávateľ)</div>
                </div>
                <div className="text-center">
                    <div className="border-b border-black w-48 mb-2 h-16"></div>
                    <div>Dátum a podpis (Dodávateľ)</div>
                </div>
            </div>
        </main>

        {/* Editor Modals */}
        {isProductDbOpen && <ProductDatabaseModal isOpen={isProductDbOpen} onClose={() => setIsProductDbOpen(false)} products={products} onSelectProduct={handleSelectProduct} onAddProduct={p => setProducts([...products, p])} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} layout={activeQuote.layout} />}
        {isMaterialCalcOpen && activeQuote.layout && <MaterialCalculatorModal isOpen={isMaterialCalcOpen} onClose={() => setIsMaterialCalcOpen(false)} layout={activeQuote.layout} onInsert={handleMaterialInsert} products={products} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} cabinClasses={cabinClasses} />}
        {isEmailOpen && <EmailModal isOpen={isEmailOpen} onClose={() => setIsEmailOpen(false)} onSend={(to, sub, msg) => window.open(`mailto:${to}?subject=${encodeURIComponent(sub)}&body=${encodeURIComponent(msg)}`)} defaultTo={activeQuote.client.email} defaultSubject={`Cenová ponuka ${activeQuote.number}`} defaultMessage={`Dobrý deň,\n\nv prílohe posielame cenovú ponuku č. ${activeQuote.number}.\n\nS pozdravom,\n${activeQuote.supplier.name}`} />}
        {isSupplierDbOpen && <SupplierDatabaseModal isOpen={isSupplierDbOpen} onClose={() => setIsSupplierDbOpen(false)} suppliers={suppliers} onSelectSupplier={s => setActiveQuote({...activeQuote, supplier: { name: s.name, details: s.details, email: s.email, phone: s.phone }})} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />}
        {isClientDbOpen && <ClientDatabaseModal isOpen={isClientDbOpen} onClose={() => setIsClientDbOpen(false)} clients={clients} onSelectClient={c => setActiveQuote({...activeQuote, client: { name: c.name, details: c.details, email: c.email, phone: c.phone }})} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />}
        {isContractRepoOpen && <ContractRepositoryModal isOpen={isContractRepoOpen} onClose={() => setIsContractRepoOpen(false)} templates={contractTemplates} onSelectTemplate={content => setActiveQuote({...activeQuote, terms: content})} onSaveCurrent={name => setContractTemplates([...contractTemplates, { id: generateId(), name, content: activeQuote.terms }])} onDeleteTemplate={id => setContractTemplates(contractTemplates.filter(t => t.id !== id))} />}
        {isSettingsOpen && <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} onSaveSettings={setSettings} onExportData={() => {}} onImportData={() => {}} onFactoryReset={() => {}} appVersion="1.0.0" />}
        {isCatalogOpen && <CatalogManagerModal isOpen={isCatalogOpen} onClose={() => setIsCatalogOpen(false)} products={products} onAddProduct={p => setProducts([...products, p])} onUpdateProduct={p => setProducts(products.map(pr => pr.id === p.id ? p : pr))} onDeleteProduct={id => setProducts(products.filter(p => p.id !== id))} customCategories={customCategories} onAddCategory={c => setCustomCategories([...customCategories, c])} onDeleteCategory={c => setCustomCategories(customCategories.filter(cat => cat !== c))} onImportCatalog={() => {}} cabinClasses={cabinClasses} onAddCabinClass={c => setCabinClasses([...cabinClasses, c])} onUpdateCabinClass={c => setCabinClasses(cabinClasses.map(cc => cc.id === c.id ? c : cc))} onDeleteCabinClass={id => setCabinClasses(cabinClasses.filter(c => c.id !== id))} />}

    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { LiftLayoutData, Product, CabinClass } from '../types';
import { X, Calculator, Check, AlertTriangle, Settings, Box, Zap, Construction, Truck, Package, Hammer, ArrowLeft, ArrowRight, ListCheck, Search, Plus, Filter, Layers, Save, Trash2, GripVertical, Gauge, ScanLine } from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try {
        return crypto.randomUUID();
      } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

interface MaterialCalculatorModalProps {
  isOpen: boolean;
  onClose: () => void;
  layout: LiftLayoutData;
  onInsert: (data: MaterialWizardData) => void;
  products: Product[];
  customCategories: string[]; // These are ALL available categories (Master + Custom)
  onAddCategory?: (name: string) => void;
  cabinClasses?: CabinClass[]; // Passed from App to resolve links
}

export interface MaterialWizardData {
    items: {
        category: string;
        description: string;
        quantity: number;
        unit: string;
        productId?: string;
        price?: number;
        isAuto?: boolean; // Flag to distinguish calculated vs manual items
    }[];
    includeTransport: boolean;
    includePackaging: boolean;
    includeAssembly: boolean;
    categoryOrder: string[]; // Only active categories
}

export const MaterialCalculatorModal: React.FC<MaterialCalculatorModalProps> = ({
  isOpen,
  onClose,
  layout,
  onInsert,
  products,
  customCategories,
  onAddCategory,
  cabinClasses
}) => {
  // Configurable Tabs Order
  const [tabs, setTabs] = useState<{id: string, label: string, color: string}[]>([]);
  const [activeTab, setActiveTab] = useState('Dvere'); // Default to first logical
  const [bomItems, setBomItems] = useState<MaterialWizardData['items']>([]);

  // Active Categories State (User can toggle which categories to include)
  const [activeCategories, setActiveCategories] = useState<Set<string>>(new Set());

  const [isCategorySettingsOpen, setIsCategorySettingsOpen] = useState(false);
  const [newCatName, setNewCatName] = useState('');

  // Options - DEFAULT OFF
  const [includeTransport, setIncludeTransport] = useState(false);
  const [includePackaging, setIncludePackaging] = useState(false);
  const [includeAssembly, setIncludeAssembly] = useState(false);

  // Memory Option
  const [rememberManual, setRememberManual] = useState(true);

  // Drag State
  const [draggedItemIdx, setDraggedItemIdx] = useState<number | null>(null);

  // Initialize Active Categories on Open
  useEffect(() => {
      if(isOpen && customCategories.length > 0) {
          // Default all to active if empty (first run)
          if(activeCategories.size === 0) {
              setActiveCategories(new Set(customCategories));
          }
      }
  }, [isOpen, customCategories]);

  // Sync Tabs with Active Categories
  useEffect(() => {
    // Generate tabs from customCategories (which contains MASTER + Custom)
    const generatedTabs = customCategories
        .filter(cat => {
            // Special Logic: 'Oceľová konštrukcia' is only visible if configured
            if (cat === 'Oceľová konštrukcia' && !layout.hasExternalShaft) return false;
            // Always exclude 'addons' from tabs list, handled in footer
            if (['Montáž', 'Doprava', 'Balné'].includes(cat)) return false;
            // Only show if active
            return activeCategories.has(cat);
        })
        .map(cat => ({
            id: cat,
            label: cat,
            color: 'blue' // Default color
        }));

    setTabs(generatedTabs);

    // If active tab is gone, switch to first available
    if (!generatedTabs.find(t => t.id === activeTab)) {
        if (generatedTabs.length > 0) setActiveTab(generatedTabs[0].id);
    }
  }, [customCategories, activeCategories, layout.hasExternalShaft, activeTab]);

  // --- HELPER FUNCTIONS ---

  // UPDATED: Added Subcategory Filter Logic
  const findStockItem = (keywords: string[], category?: string, subcategory?: string) => {
      const lowerKeys = keywords.map(k => k.toLowerCase());
      return products.find(p => {
          const matchName = lowerKeys.every(k => p.name.toLowerCase().includes(k));
          const matchCat = category ? p.category === category : true;
          const matchSub = subcategory ? p.subcategory === subcategory : true;
          return matchName && matchCat && matchSub;
      });
  };

  const findMatchProps = (keys: string[], category?: string, subcategory?: string) => {
      const p = findStockItem(keys, category, subcategory);
      return { productId: p?.id, price: p?.price };
  };

  useEffect(() => {
    if (isOpen) {
        calculateBOM();
    }
  }, [isOpen, layout]);

  const calculateBOM = () => {
    const items: MaterialWizardData['items'] = [];

    const travel = layout.travelHeight || 0;
    const totalHeight = travel + (layout.headroomHeight || 0) + (layout.pitDepth || 0);
    const cwtPos = layout.counterWeightPosition || 'left';
    const railLength = layout.guideRailLength || 5000;
    const railLengthLabel = railLength === 2500 ? '(2.5m)' : '(5m)';

    // --- MAP INTERNAL LOGIC TO CATEGORY NAMES ---
    // This allows us to put calculated items into the correct dynamic category
    const catMap = {
        guides: 'Vodítka a kotvenie',
        doors: 'Dvere',
        cabin: 'Kabína a rám',
        drive: 'Pohon',
        electro: 'Elektro',
        shaftInt: 'Ostatné šachta', // Internals
        construction: 'Oceľová konštrukcia' // Steel Structure
    };

    // --- GUIDES ---
    // Use configured rail length for calculation
    const railsPerLine = Math.ceil(Math.max(0, totalHeight) / railLength) || 1;

    const carRails = railsPerLine * 2;
    const cwtRails = railsPerLine * 2;
    const carFish = Math.max(0, railsPerLine - 1) * 2;
    const cwtFish = Math.max(0, railsPerLine - 1) * 2;

    // Brackets Logic
    const bracketRows = 1 + Math.ceil(Math.max(0, totalHeight - 500) / 2800);
    let mainBrackets = 0, busBrackets = 0, cwtBrackets = 0;

    const isCombined = layout.bracketType === 'combined';

    if (isCombined && (cwtPos === 'left' || cwtPos === 'right')) {
        busBrackets = bracketRows; // 1 per row (Combined BUS console)
        mainBrackets = bracketRows; // 1 per row (Other side)
        cwtBrackets = 0; // BUS console handles CWT
    } else {
        mainBrackets = bracketRows * 2; 
        cwtBrackets = bracketRows;
        busBrackets = 0;
    }

    // Clips Logic
    const isBigCarRail = ['T89', 'T90', 'T125', 'T127'].includes(layout.guideTypeCar || '');
    const isBigCwtRail = ['T89', 'T90', 'T125', 'T127'].includes(layout.guideTypeCwt || '');

    const clipsT2 = (isBigCarRail ? (busBrackets*2 + mainBrackets*2) : 0) + (isBigCwtRail ? (cwtBrackets*2) : 0);
    const clipsT1 = (!isBigCarRail ? (busBrackets*2 + mainBrackets*2) : 0) + (!isBigCwtRail ? (cwtBrackets*2) : 0);

    // --- GENERATE BOM ITEMS (MARKED AS AUTO) ---
    const addAutoItem = (item: any) => items.push({ ...item, isAuto: true });

    // 1. Guides
    const pCarRail = findStockItem([layout.guideTypeCar || 'T90'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Vodidlá Kabína ${layout.guideTypeCar} ${railLengthLabel}`, quantity: carRails, unit: 'ks', productId: pCarRail?.id, price: pCarRail?.price });

    const pCwtRail = findStockItem([layout.guideTypeCwt || 'T50'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Vodidlá Protiváha ${layout.guideTypeCwt} ${railLengthLabel}`, quantity: cwtRails, unit: 'ks', productId: pCwtRail?.id, price: pCwtRail?.price });

    const pCarFish = findStockItem(['spojka', layout.guideTypeCar || 'T90'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Spojka ${layout.guideTypeCar}`, quantity: carFish, unit: 'ks', productId: pCarFish?.id, price: pCarFish?.price });
    const pCwtFish = findStockItem(['spojka', layout.guideTypeCwt || 'T50'], catMap.guides);
    addAutoItem({ category: catMap.guides, description: `Spojka ${layout.guideTypeCwt}`, quantity: cwtFish, unit: 'ks', productId: pCwtFish?.id, price: pCwtFish?.price });

    if (mainBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola Hlavná', quantity: mainBrackets, unit: 'ks', ...findMatchProps(['konzola', 'hlavná'], catMap.guides) });
    if (busBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola BUS (Kombinovaná)', quantity: busBrackets, unit: 'ks', ...findMatchProps(['konzola', 'bus'], catMap.guides) });
    if (cwtBrackets > 0) addAutoItem({ category: catMap.guides, description: 'Konzola Protiváhová', quantity: cwtBrackets, unit: 'ks', ...findMatchProps(['konzola', 'protiváh'], catMap.guides) });

    if (clipsT2 > 0) addAutoItem({ category: catMap.guides, description: 'Príchytky T2 (Veľké)', quantity: clipsT2, unit: 'ks', ...findMatchProps(['príchytka', 't2'], catMap.guides) });
    if (clipsT1 > 0) addAutoItem({ category: catMap.guides, description: 'Príchytky T1 (Malé)', quantity: clipsT1, unit: 'ks', ...findMatchProps(['príchytka', 't1'], catMap.guides) });

    // 2. Doors (UPDATED WITH SUBCATEGORY)
    const shaftDoorTxt = layout.doorOperation === 'manual' ? 'Manuálne' : 'Automatické';
    const cabinDoorTxt = layout.doorType === 'bus' ? 'BUS' : 'Automatické';

    if (layout.numberOfStops) {
        addAutoItem({ 
            category: catMap.doors, 
            description: `Šachtové dvere ${shaftDoorTxt} ${layout.doorWidth}mm`, 
            quantity: layout.numberOfStops, 
            unit: 'ks', 
            ...findMatchProps([shaftDoorTxt === 'Manuálne' ? 'krídlové' : 'automatické'], catMap.doors, 'Šachtové') 
        });
    }
    addAutoItem({ 
        category: catMap.doors, 
        description: `Kabínové dvere ${cabinDoorTxt} ${layout.doorWidth}mm`, 
        quantity: layout.isThroughCar ? 2 : 1, 
        unit: 'ks', 
        ...findMatchProps([cabinDoorTxt === 'BUS' ? 'bus' : 'automatické'], catMap.doors, 'Kabínové') 
    });

    // 3. Cabin (UPDATED WITH CLASS LINKING)
    // Try to find if the selected class has a linked Set
    let linkedCabinProduct: Product | undefined;
    if (cabinClasses && layout.cabinClass) {
        const selectedClass = cabinClasses.find(c => c.name === layout.cabinClass);
        if (selectedClass?.linkedProductId) {
            linkedCabinProduct = products.find(p => p.id === selectedClass.linkedProductId);
        }
    }

    if (linkedCabinProduct) {
        // Use the linked set
        addAutoItem({ 
            category: catMap.cabin, 
            description: linkedCabinProduct.name, // Use name of the set (e.g., Kabína SKY Set)
            quantity: 1, 
            unit: 'ks', 
            productId: linkedCabinProduct.id, 
            price: linkedCabinProduct.price 
        });
    } else {
        // Fallback to generic search
        addAutoItem({ category: catMap.cabin, description: `Kabína Kompletná (${layout.cabinClass || 'FUN'})`, quantity: 1, unit: 'ks', ...findMatchProps(['kabína'], catMap.cabin) });
    }

    addAutoItem({ category: catMap.cabin, description: 'Rám Kabíny', quantity: 1, unit: 'ks', ...findMatchProps(['rám', String(layout.ratedLoad)], catMap.cabin) });

    // 4. Drive
    const driveKey = layout.tractionMedium === 'ctp' ? 'ctp' : 'lan';
    addAutoItem({ category: catMap.drive, description: 'Trakčný stroj', quantity: 1, unit: 'ks', ...findMatchProps([driveKey, 'stroj'], catMap.drive) });

    const frameKey = layout.machineRoomPosition === 'head' ? 'mrl' : 'rošt';
    addAutoItem({ category: catMap.drive, description: layout.machineRoomPosition === 'head' ? 'Rám pod stroj MRL' : 'Roznášací rošt', quantity: 1, unit: 'ks', ...findMatchProps(['rám', frameKey], catMap.drive) });

    if (layout.suspensionType === '1:1') {
        addAutoItem({ category: catMap.drive, description: 'Odkláňacie kladky', quantity: 2, unit: 'ks', ...findMatchProps(['kladk'], catMap.drive) });
    }

    // 5. Electro
    addAutoItem({ category: catMap.electro, description: 'Rozvádzač a riadenie', quantity: 1, unit: 'ks', ...findMatchProps(['rozvádzač'], catMap.electro) });
    addAutoItem({ category: catMap.electro, description: 'Revízna jazda', quantity: 1, unit: 'ks', ...findMatchProps(['revízna'], catMap.electro) });
    addAutoItem({ category: catMap.electro, description: 'Privolávače a kabeláž', quantity: 1, unit: 'kpl', ...findMatchProps(['kabeláž'], catMap.electro) });

    // 6. Shaft
    addAutoItem({ category: catMap.shaftInt, description: 'Osvetlenie šachty', quantity: 1, unit: 'kpl', ...findMatchProps(['osvetlenie'], catMap.shaftInt) });
    addAutoItem({ category: catMap.shaftInt, description: 'Rebrík do priehlbeňe', quantity: 1, unit: 'ks', ...findMatchProps(['rebrík'], catMap.shaftInt) });

    // 7. Structure (Only if configured)
    if (layout.hasExternalShaft) {
        addAutoItem({ category: catMap.construction, description: 'Oceľové profily (Konštrukcia)', quantity: 1, unit: 'kpl', ...findMatchProps(['profil', 'oceľ'], catMap.construction) });
        addAutoItem({ category: catMap.construction, description: 'Opláštenie (Sklo/Sádrokartón)', quantity: 45, unit: 'm2', ...findMatchProps(['opláštenie', 'sklo'], catMap.construction) });
    }

    // --- LOAD SAVED MANUAL ITEMS ---
    if (rememberManual) {
        try {
            const savedManualItemsStr = localStorage.getItem('smartquote_manual_items');
            if (savedManualItemsStr) {
                const savedManualItems: MaterialWizardData['items'] = JSON.parse(savedManualItemsStr);
                // Validate saved items (ensure category is still valid?) - we just append
                savedManualItems.forEach(manualItem => {
                    // Update price if product ID exists (in case price changed in DB)
                    if (manualItem.productId) {
                        const p = products.find(prod => prod.id === manualItem.productId);
                        if(p) manualItem.price = p.price;
                    }
                    items.push({ ...manualItem, isAuto: false });
                });
            }
        } catch (e) {
            console.error("Failed to load saved manual items", e);
        }
    }

    setBomItems(items);
  };

  const moveTab = (index: number, direction: 'left' | 'right') => {
      if (direction === 'left' && index === 0) return;
      if (direction === 'right' && index === tabs.length - 1) return;

      const newTabs = [...tabs];
      const targetIndex = direction === 'left' ? index - 1 : index + 1;
      [newTabs[index], newTabs[targetIndex]] = [newTabs[targetIndex], newTabs[index]];
      setTabs(newTabs);
  };

  const toggleCategory = (catId: string) => {
      const newSet = new Set(activeCategories);
      if (newSet.has(catId)) {
          newSet.delete(catId);
      } else {
          newSet.add(catId);
      }
      setActiveCategories(newSet);
  };

  const handleAddCategory = () => {
      if(newCatName && onAddCategory) {
          onAddCategory(newCatName);
          setNewCatName('');
          toggleCategory(newCatName); // Auto activate
      }
  };

  const updateItem = (idx: number, field: string, value: any) => {
      const newItems = [...bomItems];
      // @ts-ignore
      newItems[idx][field] = value;
      if (field === 'productId') {
          const p = products.find(prod => prod.id === value);
          if (p) {
              newItems[idx].price = p.price;
              newItems[idx].description = p.name;
              newItems[idx].unit = p.unit;
          }
      }
      setBomItems(newItems);
  };

  const handleDeleteItem = (index: number) => {
      const newItems = bomItems.filter((_, i) => i !== index);
      setBomItems(newItems);
  };

  const addCustomItem = (isSet: boolean = false) => {
      const cat = activeTab;
      setBomItems([
          ...bomItems, 
          { 
              category: cat, 
              description: isSet ? 'Výber SETU...' : 'Nová požiadavka', 
              quantity: 1, 
              unit: isSet ? 'set' : 'ks', 
              price: 0,
              isAuto: false // Marked as Manual
          }
      ]);
  };

  const handleInsert = () => {
      // SAVE MANUAL ITEMS TO LOCALSTORAGE
      if (rememberManual) {
          const manualItems = bomItems.filter(item => !item.isAuto);
          localStorage.setItem('smartquote_manual_items', JSON.stringify(manualItems));
      } else {
          localStorage.removeItem('smartquote_manual_items');
      }

      // Pass categoryOrder as the list of ACTIVE tabs only
      onInsert({
          items: bomItems,
          includeTransport: includeTransport,
          includePackaging: includePackaging,
          includeAssembly: includeAssembly,
          categoryOrder: tabs.map(t => t.id)
      });
      onClose();
  };

  // DRAG AND DROP FOR BOM ITEMS
  const onDragStartItem = (e: React.DragEvent, index: number) => {
      setDraggedItemIdx(index);
      e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOverItem = (e: React.DragEvent, targetIndex: number) => {
      e.preventDefault();
      if (draggedItemIdx === null || draggedItemIdx === targetIndex) return;

      const newItems = [...bomItems];
      const [reorderedItem] = newItems.splice(draggedItemIdx, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      setBomItems(newItems);
      setDraggedItemIdx(targetIndex);
  };

  if (!isOpen) return null;

  // Items for active tab
  const currentCatName = activeTab;
  const currentItems = bomItems.map((item, index) => ({ item, index })).filter(({ item }) => item.category === currentCatName);

  // Products for dropdown - Filter by active category AND SUBCATEGORY IF DOOR
  const currentAvailableProducts = products.filter(p => {
      if (p.category !== currentCatName) return false;
      // Filter Logic for Doors:
      if (currentCatName === 'Dvere') {
          // Can't easily filter the dropdown PER row if they are different types of doors (shaft/cabin)
          // But we can enable all doors in dropdown.
          return true;
      }
      return true;
  });

  // CABIN AREA CALCULATION
  const cabinArea = ((layout.cabinWidth || 0) * (layout.cabinDepth || 0) / 1000000).toFixed(2);
  const cabinPerimeter = 2 * ((layout.cabinWidth || 0) + (layout.cabinDepth || 0)) / 1000;
  const cabinWallArea = (cabinPerimeter * 2.04).toFixed(2); // 2040mm height (Fundermax)

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-[95vw] max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Calculator className="text-orange-500" />
            <div>
                <h2 className="text-xl font-bold text-gray-800">Materiálový Sprievodca</h2>
                <div className="text-xs text-gray-500">Nákupný zoznam komponentov</div>
            </div>
          </div>

          {/* CABIN AREA DASHBOARD */}
          <div className="hidden md:flex gap-4 items-center bg-white border px-3 py-1 rounded shadow-sm">
              <div className="flex items-center gap-2 text-sm text-gray-600 border-r pr-3">
                  <ScanLine size={16} className="text-blue-500"/>
                  Podlaha: <span className="font-bold text-black">{cabinArea} m²</span>
              </div>
              <div className="flex items-center gap-2 text-sm text-gray-600">
                  <Gauge size={16} className="text-purple-500"/>
                  Steny (2040mm): <span className="font-bold text-black">{cabinWallArea} m²</span>
              </div>
          </div>

          <div className="flex gap-2">
               <button onClick={() => setIsCategorySettingsOpen(!isCategorySettingsOpen)} className={`p-2 rounded-full border transition ${isCategorySettingsOpen ? 'bg-blue-100 text-blue-600 border-blue-300' : 'text-gray-500 hover:bg-gray-100'}`} title="Správa Kategórií">
                    <Filter size={20}/>
               </button>
               <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
          </div>
        </div>

        {/* Category Settings Popover */}
        {isCategorySettingsOpen && (
            <div className="bg-gray-50 border-b p-4 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4 shadow-inner max-h-48 overflow-y-auto">
                <div className="col-span-full text-xs font-bold text-gray-500 uppercase">Vyberte kategórie, ktoré chcete riešiť (Vypnuté sa vymažú):</div>
                {customCategories.filter(c => !['Montáž','Doprava','Balné'].includes(c)).map(c => (
                    <label key={c} className="flex items-center gap-2 cursor-pointer bg-white border p-2 rounded shadow-sm hover:bg-blue-50">
                        <input type="checkbox" checked={activeCategories.has(c)} onChange={() => toggleCategory(c)} className="rounded text-blue-600"/>
                        <span className="text-sm font-medium break-all">{c}</span>
                    </label>
                ))}

                {/* Add Custom Category Input */}
                <div className="col-span-full flex gap-2 pt-2 border-t mt-2">
                    <input className="border rounded px-2 py-1 text-sm w-48" placeholder="Nová kategória..." value={newCatName} onChange={e=>setNewCatName(e.target.value)} onKeyDown={e=>e.key==='Enter'&&handleAddCategory()}/>
                    <button onClick={handleAddCategory} className="px-3 py-1 bg-blue-600 text-white rounded text-xs font-bold">Pridať</button>
                </div>
            </div>
        )}

        {/* Tabs with Reordering */}
        <div className="flex border-b border-gray-200 overflow-x-auto bg-gray-50 p-1 gap-1">
            {tabs.map((tab, idx) => (
                 <div key={tab.id} className={`flex items-center rounded-t-lg border-t border-l border-r px-2 py-2 transition ${activeTab===tab.id ? 'bg-white border-gray-300' : 'bg-gray-100 border-transparent opacity-70 hover:opacity-100'}`}>
                     {activeTab === tab.id && idx > 0 && <button onClick={() => moveTab(idx, 'left')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowLeft size={12}/></button>}

                     <button 
                        onClick={() => setActiveTab(tab.id)} 
                        className={`mx-2 text-sm font-bold whitespace-nowrap ${activeTab===tab.id ? `text-${tab.color}-600` : 'text-gray-500'}`}
                     >
                         {tab.label}
                     </button>

                     {activeTab === tab.id && idx < tabs.length - 1 && <button onClick={() => moveTab(idx, 'right')} className="p-1 hover:bg-gray-200 rounded-full text-gray-400"><ArrowRight size={12}/></button>}
                 </div>
            ))}
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 bg-white">
            {currentItems.length === 0 && <div className="text-center text-gray-400 italic py-8">Žiadne položky v tejto kategórii.<br/>Kliknite na tlačidlá nižšie pre pridanie.</div>}

            {currentItems.length > 0 && (
            <div className="border rounded-xl overflow-hidden shadow-sm mb-4">
                <table className="w-full text-sm">
                    <thead className="bg-gray-100 text-gray-600 font-bold text-xs uppercase">
                        <tr>
                            <th className="w-8"></th>
                            <th className="p-3 text-left w-1/3">Požiadavka (Výpočet)</th>
                            <th className="p-3 text-left w-1/3">Produkt zo Skladu / SET</th>
                            <th className="p-3 text-right w-24">Mn.</th>
                            <th className="p-3 text-right w-24">Cena</th>
                            <th className="p-3 text-center w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {currentItems.map(({ item, index: originalIndex }) => {
                            // Filter logic for specific row dropdown
                            let rowProducts = currentAvailableProducts;
                            if (currentCatName === 'Dvere') {
                                // Smart filtering based on item description content
                                if (item.description.includes('Šachtové')) {
                                    rowProducts = currentAvailableProducts.filter(p => !p.subcategory || p.subcategory === 'Šachtové');
                                } else if (item.description.includes('Kabínové')) {
                                    rowProducts = currentAvailableProducts.filter(p => !p.subcategory || p.subcategory === 'Kabínové');
                                }
                            }

                            return (
                                <tr 
                                    key={originalIndex} 
                                    draggable
                                    onDragStart={(e) => onDragStartItem(e, originalIndex)}
                                    onDragOver={(e) => onDragOverItem(e, originalIndex)}
                                    className={`transition ${item.isAuto ? 'hover:bg-blue-50' : 'bg-yellow-50 hover:bg-yellow-100'}`}
                                >
                                    <td className="p-2 text-center text-gray-300 cursor-grab hover:text-gray-500">
                                        <GripVertical size={16}/>
                                    </td>
                                    <td className="p-3 relative">
                                        <input 
                                            value={item.description} 
                                            onChange={e => updateItem(originalIndex, 'description', e.target.value)}
                                            className="w-full bg-transparent font-medium text-gray-800 focus:outline-none"
                                        />
                                        {!item.isAuto && <span className="text-[9px] font-bold text-yellow-600 uppercase absolute top-1 right-2 bg-yellow-100 px-1 rounded">Manual</span>}
                                    </td>
                                    <td className="p-3">
                                        <div className="relative">
                                            <select 
                                                value={item.productId || ''} 
                                                onChange={e => updateItem(originalIndex, 'productId', e.target.value)}
                                                className={`w-full p-2 border rounded text-sm font-bold ${item.productId ? 'bg-green-50 text-green-700 border-green-200' : 'bg-gray-50 text-gray-400 border-gray-200'}`}
                                            >
                                                <option value="">-- Vybrať --</option>
                                                {rowProducts.sort((a,b) => (a.type === 'composite' ? -1 : 1)).map(p => (
                                                    <option key={p.id} value={p.id}>
                                                        {p.type === 'composite' ? '📦 [SET] ' : ''}{p.name} ({p.price}€)
                                                    </option>
                                                ))}
                                            </select>
                                            {!item.productId && (
                                                <div title="Položka nie je spárovaná so skladom" className="absolute right-8 top-1/2 -translate-y-1/2 text-orange-400 pointer-events-none">
                                                    <AlertTriangle size={14} />
                                                </div>
                                            )}
                                        </div>
                                    </td>
                                    <td className="p-3 text-right">
                                        <input 
                                            type="number" 
                                            value={item.quantity} 
                                            onChange={e => updateItem(originalIndex, 'quantity', +e.target.value)}
                                            className="w-full text-right font-bold text-blue-600 bg-transparent focus:outline-none text-base"
                                        />
                                    </td>
                                    <td className="p-3 text-right font-mono text-gray-600">
                                        {item.price ? item.price.toFixed(2) : '-'} €
                                    </td>
                                    <td className="p-3 text-center">
                                        <button 
                                            onClick={() => handleDeleteItem(originalIndex)}
                                            className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition"
                                            title="Vymazať položku"
                                        >
                                            <Trash2 size={16}/>
                                        </button>
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            )}

            <div className="flex gap-2">
                <button 
                    onClick={() => addCustomItem(false)}
                    className="flex-1 py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-500 hover:border-blue-400 hover:text-blue-600 hover:bg-blue-50 transition flex justify-center items-center gap-2 font-medium"
                >
                    <Plus size={18} /> Pridať vlastnú požiadavku
                </button>
                <button 
                    onClick={() => addCustomItem(true)}
                    className="flex-1 py-3 border-2 border-dashed border-purple-300 rounded-lg text-purple-600 hover:border-purple-500 hover:bg-purple-50 transition flex justify-center items-center gap-2 font-bold bg-purple-50/50"
                >
                    <Layers size={18} /> + Pridať SET
                </button>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-gray-50 rounded-b-xl flex flex-col gap-4">

            {/* Addons Checkboxes - DEFAULT OFF */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-2 bg-blue-50 p-3 rounded border border-blue-100">
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includeAssembly} onChange={e => setIncludeAssembly(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Hammer size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Montáž technológie</span>
                 </label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includeTransport} onChange={e => setIncludeTransport(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Truck size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Doprava materiálu</span>
                 </label>
                 <label className="flex items-center gap-3 cursor-pointer hover:bg-blue-100 p-2 rounded transition">
                    <input type="checkbox" checked={includePackaging} onChange={e => setIncludePackaging(e.target.checked)} className="rounded text-blue-600 w-5 h-5"/>
                    <Package size={18} className="text-blue-600"/>
                    <span className="text-sm font-bold text-blue-800">Balné a manipulácia</span>
                 </label>
            </div>

            <div className="flex justify-between items-center">
                <div className="text-xs text-gray-500 flex items-center gap-4">
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-yellow-50 px-3 py-1 rounded">
                        <input type="checkbox" checked={rememberManual} onChange={e => setRememberManual(e.target.checked)} className="rounded text-yellow-600"/>
                        <span className="font-bold text-yellow-800 text-xs">💾 Zapamätať manuálne položky pre ďalšie ponuky</span>
                    </label>
                </div>
                <div className="flex gap-2">
                    <button onClick={onClose} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg font-medium transition">
                        Zrušiť
                    </button>
                    <button onClick={handleInsert} className="px-6 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg font-bold flex items-center gap-2 shadow-sm transition">
                        <Check size={18} /> Potvrdiť a Vložiť
                    </button>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, FolderOpen, Folder,
  AlertTriangle, Box
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try {
        return crypto.randomUUID();
      } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk Actions State
  const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());
  const [isBulkMoveMode, setIsBulkMoveMode] = useState(false);
  const [bulkTargetCat, setBulkTargetCat] = useState('');
  const [bulkTargetSubcat, setBulkTargetSubcat] = useState('');

  // Editing State
  const [editingProductId, setEditingProductId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<Product>>({});

  // New Category State
  const [newCategoryName, setNewCategoryName] = useState('');

  // New Class State
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLinkedSet, setNewClassLinkedSet] = useState('');

  // Grouping State (Expanded Subcategories)
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize active category
  useEffect(() => {
      if (customCategories.length > 0 && !activeCategory) {
          setActiveCategory(customCategories[0]);
      }
  }, [customCategories, activeCategory]);

  // Filtered Products
  const filteredProducts = products.filter(p => {
      const matchCat = activeCategory ? p.category === activeCategory : true;
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCat && matchSearch;
  });

  // GROUPING LOGIC
  const { generalProducts, groupedProducts, sortedSubcategories } = useMemo(() => {
      const general: Product[] = [];
      const groups: Record<string, Product[]> = {};

      filteredProducts.forEach(p => {
          if (p.subcategory) {
              if (!groups[p.subcategory]) groups[p.subcategory] = [];
              groups[p.subcategory].push(p);
          } else {
              general.push(p);
          }
      });

      return {
          generalProducts: general,
          groupedProducts: groups,
          sortedSubcategories: Object.keys(groups).sort()
      };
  }, [filteredProducts]);

  // Derived Data
  const allCategories = customCategories;

  // Get all unique subcategories for the selected target category (for suggestions)
  const bulkTargetSubcategoriesOptions = Array.from(new Set(
      products
        .filter(p => p.category === bulkTargetCat && p.subcategory)
        .map(p => p.subcategory!)
  ));

  // --- Handlers ---

  const handleBulkSelection = (id: string) => {
      const newSet = new Set(selectedProductIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedProductIds(newSet);
  };

  const toggleSelectAll = () => {
      if (selectedProductIds.size === filteredProducts.length && filteredProducts.length > 0) {
          setSelectedProductIds(new Set());
      } else {
          setSelectedProductIds(new Set(filteredProducts.map(p => p.id)));
      }
  };

  const toggleGroupExpand = (subcat: string) => {
      const newSet = new Set(expandedGroups);
      if (newSet.has(subcat)) newSet.delete(subcat);
      else newSet.add(subcat);
      setExpandedGroups(newSet);
  };

  const handleBulkMoveConfirm = () => {
      if (!bulkTargetCat) return;

      const targetSub = bulkTargetSubcat.trim();
      const idsToMove = Array.from(selectedProductIds);

      idsToMove.forEach(id => {
          const product = products.find(p => p.id === id);
          if (product) {
              onUpdateProduct({
                  ...product,
                  category: bulkTargetCat,
                  subcategory: targetSub || undefined 
              });
          }
      });

      // Auto expand the target group if we are staying in the same category
      if (activeCategory === bulkTargetCat && targetSub) {
           setExpandedGroups(prev => {
               const next = new Set(prev);
               next.add(targetSub);
               return next;
           });
      }

      setSelectedProductIds(new Set());
      setIsBulkMoveMode(false);
      setBulkTargetCat('');
      setBulkTargetSubcat('');
  };

  const handleDeleteSelected = () => {
      if (window.confirm(`Naozaj vymazať ${selectedProductIds.size} produktov?`)) {
          selectedProductIds.forEach(id => onDeleteProduct(id));
          setSelectedProductIds(new Set());
      }
  };

  const handleStartEdit = (p: Product) => {
      setEditingProductId(p.id);
      setEditForm({...p});
  };

  const handleSaveEdit = () => {
      if (editingProductId && editForm.name) {
          const original = products.find(p => p.id === editingProductId);
          if (original) {
              onUpdateProduct({ ...original, ...editForm } as Product);
          }
          setEditingProductId(null);
          setEditForm({});
      }
  };

  const handleAddCategorySubmit = () => {
      if (newCategoryName && !customCategories.includes(newCategoryName)) {
          onAddCategory(newCategoryName);
          setNewCategoryName('');
      }
  };

  const handleAddClassSubmit = () => {
      if (newClassName) {
          onAddCabinClass({
              id: generateId(),
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
          setNewClassName('');
          setNewClassDesc('');
          setNewClassLinkedSet('');
      }
  };

  if (!isOpen) return null;

  // Helper to render a single row
  const renderProductRow = (product: Product) => (
    <tr key={product.id} className={`hover:bg-blue-50 transition ${selectedProductIds.has(product.id) ? 'bg-blue-50' : ''}`}>
        <td className="p-3 w-10 text-center">
            <button onClick={() => handleBulkSelection(product.id)} className={`text-gray-400 hover:text-purple-600 ${selectedProductIds.has(product.id) ? 'text-purple-600' : ''}`}>
                {selectedProductIds.has(product.id) ? <CheckSquare size={16}/> : <Square size={16}/>}
            </button>
        </td>

        {/* Name */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded font-bold" 
                    value={editForm.name || ''} 
                    onChange={e => setEditForm({...editForm, name: e.target.value})}
                    autoFocus
                />
            ) : (
                <div className="font-bold text-gray-800">{product.name}</div>
            )}
        </td>

        {/* Subcategory */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded text-xs" 
                    value={editForm.subcategory || ''} 
                    onChange={e => setEditForm({...editForm, subcategory: e.target.value})}
                    placeholder="-"
                />
            ) : (
                <span className={`text-xs px-2 py-1 rounded-full border ${product.subcategory ? 'bg-blue-50 text-blue-700 border-blue-100' : 'bg-gray-50 text-gray-400 border-gray-200'}`}>
                    {product.subcategory || '-'}
                </span>
            )}
        </td>

        {/* Price */}
        <td className="p-3 text-right font-mono">
            {editingProductId === product.id ? (
                <input 
                    type="number"
                    className="w-full border p-1 rounded text-right" 
                    value={editForm.price || ''} 
                    onChange={e => setEditForm({...editForm, price: parseFloat(e.target.value) || 0})}
                />
            ) : (
                product.price.toFixed(2)
            )}
        </td>

        {/* Unit */}
        <td className="p-3 text-right">
            {editingProductId === product.id ? (
                <select
                    className="border p-1 rounded text-xs" 
                    value={editForm.unit || 'ks'} 
                    onChange={e => setEditForm({...editForm, unit: e.target.value})}
                >
