interface ContractRepositoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  templates: ContractTemplate[];
  onSelectTemplate: (content: string) => void;
  onSaveCurrent: (name: string) => void;
  onDeleteTemplate: (id: string) => void;
}

export const ContractRepositoryModal: React.FC<ContractRepositoryModalProps> = ({
  isOpen,
  onClose,
  templates,
  onSelectTemplate,
  onSaveCurrent,
  onDeleteTemplate
}) => {
  const [mode, setMode] = useState<'list' | 'save'>('list');
  const [newName, setNewName] = useState('');

  if (!isOpen) return null;

  const handleSave = () => {
      if (newName.trim()) {
          onSaveCurrent(newName);
          setNewName('');
          setMode('list');
      }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-lg max-h-[80vh] flex flex-col">
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <FileText className="text-blue-600" />
            <h2 className="text-xl font-bold text-gray-800">Vzory Zmlúv</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
            <X size={20}/>
          </button>
        </div>

        <div className="p-4 bg-gray-50 flex-1 overflow-y-auto">
            {/* Toolbar */}
            <div className="flex gap-2 mb-4">
                <button 
                    onClick={() => setMode('list')}
                    className={`flex-1 py-2 text-sm font-medium rounded transition ${mode === 'list' ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:bg-gray-200'}`}
                >
                    Zoznam vzorov
                </button>
                <button 
                    onClick={() => setMode('save')}
                    className={`flex-1 py-2 text-sm font-medium rounded transition ${mode === 'save' ? 'bg-white shadow text-green-600' : 'text-gray-500 hover:bg-gray-200'}`}
                >
                    Uložiť aktuálny text
                </button>
            </div>

            {mode === 'save' && (
                <div className="bg-white p-4 rounded-lg border border-gray-200">
                    <label className="block text-sm font-bold text-gray-700 mb-2">Názov nového vzoru</label>
                    <input 
                        type="text" 
                        value={newName} 
                        onChange={e => setNewName(e.target.value)}
                        placeholder="Napr. Zmluva o dielo - Bytový dom"
                        className="w-full border border-gray-300 p-2 rounded mb-3"
                    />
                    <button 
                        onClick={handleSave}
                        disabled={!newName.trim()}
                        className="w-full py-2 bg-green-600 text-white rounded font-bold hover:bg-green-700 disabled:opacity-50"
                    >
                        Uložiť do knižnice
                    </button>
                </div>
            )}

            {mode === 'list' && (
                <div className="space-y-2">
                    {templates.length === 0 ? (
                        <div className="text-center py-8 text-gray-400 italic">Žiadne uložené vzory zmlúv.</div>
                    ) : (
                        templates.map(t => (
                            <div key={t.id} className="bg-white p-3 rounded-lg border border-gray-200 hover:border-blue-300 shadow-sm flex justify-between items-center group">
                                <div className="font-bold text-gray-800">{t.name}</div>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={() => onDeleteTemplate(t.id)}
                                        className="p-2 text-gray-300 hover:text-red-600 rounded"
                                    >
                                        <Trash2 size={16}/>
                                    </button>
                                    <button 
                                        onClick={() => onSelectTemplate(t.content)}
                                        className="px-3 py-1.5 bg-blue-50 text-blue-700 font-bold rounded hover:bg-blue-100 flex items-center gap-1"
                                    >
                                        <Download size={14}/> Načítať
                                    </button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, FolderOpen, Folder,
  AlertTriangle, Box
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try {
        return crypto.randomUUID();
      } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [activeSubcategoryFilter, setActiveSubcategoryFilter] = useState<string>('ALL'); // 'ALL' or specific subcategory
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk Actions State
  const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());

  // Editing State
  const [editingProductId, setEditingProductId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<Product>>({});

  // New Category State
  const [newCategoryName, setNewCategoryName] = useState('');

  // New Class State
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLinkedSet, setNewClassLinkedSet] = useState('');

  // Grouping State (Expanded Subcategories)
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize active category
  useEffect(() => {
      if (customCategories.length > 0 && !activeCategory) {
          setActiveCategory(customCategories[0]);
      }
  }, [customCategories, activeCategory]);

  // Filtered Products Base (By Category & Search)
  const filteredProductsBase = products.filter(p => {
      const matchCat = activeCategory ? p.category === activeCategory : true;
      const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
      return matchCat && matchSearch;
  });

  // Derived Data: Subcategories in current Category
  const currentSubcategories = useMemo(() => {
      const subs = new Set<string>();
      filteredProductsBase.forEach(p => {
          if (p.subcategory) subs.add(p.subcategory);
      });
      return Array.from(subs).sort();
  }, [filteredProductsBase]);

  // GROUPING LOGIC for Display
  const { generalProducts, groupedProducts, sortedSubcategories } = useMemo(() => {
      const general: Product[] = [];
      const groups: Record<string, Product[]> = {};

      // Logic: If filter is active, only show that group. If ALL, show grouping.
      const productsToProcess = activeSubcategoryFilter === 'ALL' 
          ? filteredProductsBase 
          : filteredProductsBase.filter(p => (activeSubcategoryFilter === 'General' ? !p.subcategory : p.subcategory === activeSubcategoryFilter));

      productsToProcess.forEach(p => {
          if (p.subcategory) {
              if (!groups[p.subcategory]) groups[p.subcategory] = [];
              groups[p.subcategory].push(p);
          } else {
              general.push(p);
          }
      });

      // Auto-expand groups if searching or if filter is specific
      if (searchTerm || activeSubcategoryFilter !== 'ALL') {
          // Effectively expand all relevant for view
          // (We handle visual expansion separately, but this helps logic)
      }

      return {
          generalProducts: general,
          groupedProducts: groups,
          sortedSubcategories: Object.keys(groups).sort()
      };
  }, [filteredProductsBase, activeSubcategoryFilter, searchTerm]);

  // --- Handlers ---

  const handleBulkSelection = (id: string) => {
      const newSet = new Set(selectedProductIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedProductIds(newSet);
  };

  const toggleSelectAll = () => {
      // Select visible products
      const visibleIds = [
          ...generalProducts.map(p => p.id),
          ...sortedSubcategories.flatMap(s => groupedProducts[s].map(p => p.id))
      ];

      if (selectedProductIds.size >= visibleIds.length && visibleIds.length > 0) {
          setSelectedProductIds(new Set());
      } else {
          setSelectedProductIds(new Set(visibleIds));
      }
  };

  const toggleGroupExpand = (subcat: string) => {
      const newSet = new Set(expandedGroups);
      if (newSet.has(subcat)) newSet.delete(subcat);
      else newSet.add(subcat);
      setExpandedGroups(newSet);
  };

  // QUICK MOVE HANDLER (Click on Subcategory Pill)
  const handleQuickMoveToSubcat = (targetSubcat: string | null) => {
      if (selectedProductIds.size === 0) return;

      const idsToMove = Array.from(selectedProductIds);
      const subcatName = targetSubcat === 'General' ? undefined : targetSubcat;

      if (window.confirm(`Presunúť ${idsToMove.length} označených produktov do "${targetSubcat || 'Bez podkategórie'}"?`)) {
          idsToMove.forEach(id => {
              const product = products.find(p => p.id === id);
              if (product) {
                  onUpdateProduct({
                      ...product,
                      category: activeCategory, // Stay in current main category
                      subcategory: subcatName || undefined
                  });
              }
          });
          setSelectedProductIds(new Set());
      }
  };

  const handleDeleteSelected = () => {
      if (window.confirm(`Naozaj vymazať ${selectedProductIds.size} produktov?`)) {
          selectedProductIds.forEach(id => onDeleteProduct(id));
          setSelectedProductIds(new Set());
      }
  };

  const handleStartEdit = (p: Product) => {
      setEditingProductId(p.id);
      setEditForm({...p});
  };

  const handleSaveEdit = () => {
      if (editingProductId && editForm.name) {
          const original = products.find(p => p.id === editingProductId);
          if (original) {
              onUpdateProduct({ ...original, ...editForm } as Product);
          }
          setEditingProductId(null);
          setEditForm({});
      }
  };

  const handleAddCategorySubmit = () => {
      if (newCategoryName && !customCategories.includes(newCategoryName)) {
          onAddCategory(newCategoryName);
          setNewCategoryName('');
      }
  };

  const handleAddClassSubmit = () => {
      if (newClassName) {
          onAddCabinClass({
              id: generateId(),
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
          setNewClassName('');
          setNewClassDesc('');
          setNewClassLinkedSet('');
      }
  };

  // Helper to add new subcategory (Just creates a placeholder essentially, or logic to add item to it)
  const promptAddSubcategory = () => {
      const name = prompt("Názov novej podkategórie:");
      if (name) {
          // We can't really "create" a subcategory without a product in it in this data model.
          // So we either add a dummy product or just filter by it.
          // Better UX: Just set filter, and if user adds product, it uses this subcat.
          // BUT simpler: Alert user to edit a product to create it.
          alert("Podkategória sa vytvorí automaticky, keď do nej priradíte prvý produkt (cez úpravu produktu).");
      }
  };

  if (!isOpen) return null;

  // Helper to render a single row
  const renderProductRow = (product: Product) => (
    <tr key={product.id} className={`hover:bg-blue-50 transition ${selectedProductIds.has(product.id) ? 'bg-blue-50' : ''}`}>
        <td className="p-3 w-10 text-center">
            <button onClick={() => handleBulkSelection(product.id)} className={`text-gray-400 hover:text-purple-600 ${selectedProductIds.has(product.id) ? 'text-purple-600' : ''}`}>
                {selectedProductIds.has(product.id) ? <CheckSquare size={16}/> : <Square size={16}/>}
            </button>
        </td>

        {/* Name */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    className="w-full border p-1 rounded font-bold" 
                    value={editForm.name || ''} 
                    onChange={e => setEditForm({...editForm, name: e.target.value})}
                    autoFocus
                />
            ) : (
                <div className="font-bold text-gray-800">{product.name}</div>
            )}
        </td>

        {/* Subcategory Edit */}
        <td className="p-3">
            {editingProductId === product.id ? (
                <input 
                    list="subcat-options-edit"
                    className="w-full border p-1 rounded text-xs" 
                    value={editForm.subcategory || ''} 
                    onChange={e => setEditForm({...editForm, subcategory: e.target.value})}
                    placeholder="-"
                />
            ) : (
                <span className={`text-xs px-2 py-1 rounded-full border ${product.subcategory ? 'bg-blue-50 text-blue-700 border-blue-100' : 'bg-gray-50 text-gray-400 border-gray-200'}`}>
                    {product.subcategory || '-'}
                </span>
            )}
            <datalist id="subcat-options-edit">
                {currentSubcategories.map(s => <option key={s} value={s}/>)}
            </datalist>
        </td>

        {/* Price */}
        <td className="p-3 text-right font-mono">
            {editingProductId === product.id ? (
                <input 
                    type="number"
                    className="w-full border p-1 rounded text-right" 
                    value={editForm.price || ''} 
                    onChange={e => setEditForm({...editForm, price: parseFloat(e.target.value) || 0})}
                />
            ) : (
                product.price.toFixed(2)
            )}
        </td>

        {/* Unit */}
        <td className="p-3 text-right">
            {editingProductId === product.id ? (
                <select
                    className="border p-1 rounded text-xs" 
                    value={editForm.unit || 'ks'} 
                    onChange={e => setEditForm({...editForm, unit: e.target.value})}
                >
                    <option value="ks">ks</option>
                    <option value="m">m</option>
                    <option value="kpl">kpl</option>
                </select>
            ) : (
                <span className="text-gray-500 text-xs">{product.unit}</span>
            )}
        </td>

        {/* Actions */}
        <td className="p-3 text-center">
            {editingProductId === product.id ? (
                <div className="flex justify-center gap-1">
                    <button onClick={handleSaveEdit} className="p-1 bg-green-100 text-green-700 rounded hover:bg-green-200"><Check size={16}/></button>
                    <button onClick={() => setEditingProductId(null)} className="p-1 bg-gray-100 text-gray-500 rounded hover:bg-gray-200"><X size={16}/></button>
                </div>
            ) : (
                <div className="flex justify-center gap-1">
                    <button onClick={() => handleStartEdit(product)} className="p-1 text-blue-500 hover:bg-blue-50 rounded"><Edit size={16}/></button>
                    <button onClick={() => onDeleteProduct(product.id)} className="p-1 text-red-500 hover:bg-red-50 rounded"><Trash2 size={16}/></button>
                </div>
            )}
        </td>
    </tr>
  );

  return (
    <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-6xl max-h-[90vh] flex flex-col">

        {/* Header */}
        <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
          <div className="flex items-center gap-2">
            <Settings className="text-purple-600" />
            <h2 className="text-xl font-bold text-gray-800">Správca Katalógu</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full text-gray-500">
            <X size={20}/>
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200">
            <button 
                onClick={() => setActiveTab('products')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='products' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Produkty
            </button>
            <button 
                onClick={() => setActiveTab('categories')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='categories' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Kategórie
            </button>
            <button 
                onClick={() => setActiveTab('classes')} 
                className={`flex-1 py-3 font-bold text-sm border-b-2 transition ${activeTab==='classes' ? 'border-purple-600 text-purple-700 bg-purple-50' : 'border-transparent text-gray-500 hover:bg-gray-50'}`}
            >
                Triedy Kabín
            </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-hidden flex flex-col">

            {/* --- PRODUCTS TAB --- */}
            {activeTab === 'products' && (
                <div className="flex-1 flex flex-col min-h-0">
                    {/* Toolbar & Categories */}
                    <div className="p-4 border-b bg-white flex flex-col gap-4">
                        {/* Top Row: Main Categories & Actions */}
                        <div className="flex flex-wrap gap-4 items-center justify-between">
                            <div className="flex items-center gap-2 flex-1">
                                <select 
                                    value={activeCategory} 
                                    onChange={e => setActiveCategory(e.target.value)} 
                                    className="border rounded-lg px-3 py-2 text-sm font-bold bg-gray-50 min-w-[200px]"
                                >
                                    {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>

                                <div className="relative flex-1 max-w-sm">
                                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
                                    <input 
                                        type="text" 
                                        placeholder="Hľadať produkt..." 
                                        value={searchTerm} 
                                        onChange={e => setSearchTerm(e.target.value)}
                                        className="w-full pl-9 pr-3 py-2 border rounded-lg text-sm focus:ring-2 focus:ring-purple-500 outline-none"
                                    />
                                </div>
                            </div>

                            <div className="flex items-center gap-2">
                                <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={e => e.target.files?.[0] && onImportCatalog(e.target.files[0])} />
                                <button onClick={() => fileInputRef.current?.click()} className="p-2 text-gray-600 hover:bg-gray-100 rounded" title="Importovať JSON katalóg">
                                    <Upload size={20}/>
                                </button>
                            </div>
                        </div>

                        {/* Middle Row: SUBCATEGORY PILLS (Visual Filter & Drop Target) */}
                        <div className="flex items-center gap-2 overflow-x-auto pb-2 scrollbar-thin">
                            <span className="text-xs font-bold text-gray-400 uppercase shrink-0 mr-2 flex items-center gap-1">
                                <Filter size={12}/> Podkategórie:
                            </span>

                            {/* ALL button */}
                            <button 
                                onClick={() => setActiveSubcategoryFilter('ALL')}
                                className={`px-3 py-1.5 rounded-full text-xs font-bold border whitespace-nowrap transition flex items-center gap-2 ${activeSubcategoryFilter === 'ALL' ? 'bg-purple-600 text-white border-purple-600' : 'bg-white text-gray-600 border-gray-300 hover:bg-gray-100'}`}
                            >
                                Všetko (Zoskupené)
                            </button>

                            {/* General (Uncategorized) button */}
                            <button 
                                onClick={() => selectedProductIds.size > 0 ? handleQuickMoveToSubcat(null) : setActiveSubcategoryFilter('General')}
                                className={`px-3 py-1.5 rounded-full text-xs font-bold border whitespace-nowrap transition flex items-center gap-2 ${activeSubcategoryFilter === 'General' ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-gray-600 border-gray-300 hover:bg-gray-100'}`}
                            >
                                {selectedProductIds.size > 0 && <CornerDownRight size={14}/>} Bez podkategórie
                            </button>

                            {/* Subcategory Buttons */}
                            {currentSubcategories.map(sub => (
                                <button 
                                    key={sub}
                                    onClick={() => selectedProductIds.size > 0 ? handleQuickMoveToSubcat(sub) : setActiveSubcategoryFilter(sub)}
                                    className={`px-3 py-1.5 rounded-full text-xs font-bold border whitespace-nowrap transition flex items-center gap-2 ${activeSubcategoryFilter === sub ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-blue-600 border-blue-200 hover:bg-blue-50'}`}
                                >
                                    {selectedProductIds.size > 0 && <CornerDownRight size={14}/>} {sub}
                                </button>
                            ))}

                            {/* Add New Subcategory Hint */}
                            <button onClick={promptAddSubcategory} className="px-2 py-1 rounded-full text-xs text-gray-400 hover:bg-gray-100 border border-dashed border-gray-300 ml-auto whitespace-nowrap">
                                + Nová
                            </button>
                        </div>

                        {/* Bulk Action Hint Bar */}
                        {selectedProductIds.size > 0 && (
                            <div className="bg-blue-50 p-2 rounded-lg border border-blue-200 flex justify-between items-center text-xs animate-in slide-in-from-top-2">
                                <div className="flex items-center gap-2 font-bold text-blue-800">
                                    <CheckSquare size={14}/> {selectedProductIds.size} vybraných
                                    <span className="font-normal text-gray-600 ml-2">← Kliknite na tlačidlo podkategórie vyššie pre okamžitý presun.</span>
                                </div>
                                <button onClick={handleDeleteSelected} className="text-red-600 hover:underline font-bold flex items-center gap-1">
                                    <Trash2 size={12}/> Vymazať označené
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Products Table */}
                    <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
                        <table className="w-full text-sm bg-white border rounded-lg shadow-sm overflow-hidden">
                            <thead className="bg-gray-100 text-gray-600 font-bold uppercase text-xs sticky top-0 z-10 shadow-sm">
                                <tr>
                                    <th className="p-3 w-10 text-center">
                                        <button onClick={toggleSelectAll} className="text-gray-500 hover:text-black">
                                            {selectedProductIds.size > 0 ? <CheckSquare size={16}/> : <Square size={16}/>}
                                        </button>
                                    </th>
                                    <th className="p-3 text-left">Názov Produktu</th>
