                                                          <button onClick={() => removeComponentFromSet(sub.productId)} className="text-red-400 hover:text-red-600 p-1"><X size={14}/></button>
                                                      </div>
                                                  </div>
                                              );
                                          })}
                                      </div>

                                      <div className="mt-2 bg-purple-50 p-2 rounded text-right text-xs font-bold text-purple-800">
                                          Súčet komponentov: {calculateSetPrice().toFixed(2)} €
                                      </div>
