                    <div className="p-4 border-b bg-white flex flex-col gap-4">
                        {/* Top Row: Main Categories & Actions */}
                        <div className="flex flex-wrap gap-4 items-center justify-between">
                            <div className="flex items-center gap-2 flex-1">
