                  const importedCats = imported.customCategories as string[];
                  // Use Array.from(new Set(...)) to ensure type safety and uniqueness
                  const mergedCats = Array.from(new Set<string>([...DEFAULT_CATEGORIES, ...importedCats]));
                  setAvailableCategories(mergedCats);
              } else if (imported.products && Array.isArray(imported.products)) {
                  // Fallback if no categories property in file
                  // Fix: Explicitly cast imported.products to Product[] to avoid type errors
                  const prodCats = (imported.products as any[]).map((p: any) => p.category);
                  const mergedCats = Array.from(new Set<string>([...DEFAULT_CATEGORIES, ...prodCats]));
                  setAvailableCategories(mergedCats);
              }

              if (imported.cabinClasses) setCabinClasses(imported.cabinClasses);
              if (imported.data) setData(imported.data);
              alert("Dáta boli úspešne obnovené.");
          } catch (err) { 
              console.error(err);
              alert("Chyba pri importe súboru.");
          }
      };
      reader.readAsText(file);
  };

