            layout: { ...DEFAULT_LAYOUT },
            categories: INITIAL_CATEGORIES, // Reset categories
            terms: data.terms,
            currency: '€',
            globalMargin: 15,
            shaftMargin: 20,
            hideItemPrices: true, 
