  const titleInputRef = useRef<HTMLTextAreaElement>(null);

  // Derived state
  const isContractMode = data.type === 'contract';
  const isOrderMode = data.type === 'order';

  // --- PERSISTENCE: LOAD ON START ---
  useEffect(() => {
      const storedQuotes = localStorage.getItem('smartquote_archive');
      if (storedQuotes) {
          try {
              setSavedQuotes(JSON.parse(storedQuotes));
          } catch (e) { console.error("Failed to load archive", e); }
      }

      const storedSettings = localStorage.getItem('smartquote_settings');
      if (storedSettings) {
          try {
              setSettings(JSON.parse(storedSettings));
          } catch (e) { console.error("Failed to load settings", e); }
      }

      // Load products if stored
      const storedProducts = localStorage.getItem('smartquote_products');
      let loadedProducts: Product[] = [];
      if (storedProducts) {
          try {
              loadedProducts = JSON.parse(storedProducts);
              setProducts(loadedProducts);
          } catch (e) { console.error("Failed to load products", e); }
      }

      // Load categories OR RECOVER FROM PRODUCTS (Safe Mode)
      const storedCategories = localStorage.getItem('smartquote_categories');
      if (storedCategories) {
          try {
              let savedCats = JSON.parse(storedCategories);
              // CRITICAL: Merge saved categories with categories found in products to avoid data loss
              const productCategories = new Set(loadedProducts.map(p => p.category));
              const mergedCategories = new Set([...DEFAULT_CATEGORIES, ...savedCats, ...productCategories]);
              setAvailableCategories(Array.from(mergedCategories));
          } catch (e) { console.error("Failed to load categories", e); }
      } else {
          // If no categories stored, initialize from Default + Products
          const productCategories = new Set(loadedProducts.map(p => p.category));
          const mergedCategories = new Set([...DEFAULT_CATEGORIES, ...productCategories]);
          setAvailableCategories(Array.from(mergedCategories));
      }

      // Load cabin classes if stored
      const storedCabinClasses = localStorage.getItem('smartquote_cabin_classes');
      if (storedCabinClasses) {
          try {
              setCabinClasses(JSON.parse(storedCabinClasses));
          } catch (e) { console.error("Failed to load cabin classes", e); }
      }
  }, []);

  // --- PERSISTENCE: SAVE ON CHANGE ---
  useEffect(() => {
      localStorage.setItem('smartquote_archive', JSON.stringify(savedQuotes));
  }, [savedQuotes]);

  useEffect(() => {
      localStorage.setItem('smartquote_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
      localStorage.setItem('smartquote_products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
      localStorage.setItem('smartquote_categories', JSON.stringify(availableCategories));
  }, [availableCategories]);

  useEffect(() => {
      localStorage.setItem('smartquote_cabin_classes', JSON.stringify(cabinClasses));
  }, [cabinClasses]);


  // --- Calculations ---
  const calculateTotals = () => {
      let totalSelling = 0;
      let totalPurchase = 0;

      data.categories.forEach(cat => {
          if (cat.isHidden) return; // Completely excluded

          const margin = cat.section === 'shaft' ? data.shaftMargin : data.globalMargin;

          cat.items.forEach(item => {
              const itemTotal = item.quantity * item.unitPrice; 
              // If item is hidden from print, we still include it in calculation!
              totalPurchase += itemTotal;
              totalSelling += itemTotal * (1 + margin / 100);
          });
      });

      return {
          totalSelling,
          vat: totalSelling * 0.23, // 23% VAT
          gross: totalSelling * 1.23
      };
  };

