      reader.onload = (e) => {
          try {
              const importedProducts: Product[] = JSON.parse(e.target?.result as string);
              if (Array.isArray(importedProducts)) {
                  // Merge strategy: Overwrite by ID, append new
                  const newProductMap = new Map(products.map(p => [p.id, p]));
                  importedProducts.forEach(p => newProductMap.set(p.id, p));
                  const finalProducts = Array.from(newProductMap.values());

                  setProducts(finalProducts);

                  // SYNC CATEGORIES: Ensure all categories in imported products exist in availableCategories
                  const newCats = new Set(availableCategories);
                  finalProducts.forEach(p => newCats.add(p.category));
                  setAvailableCategories(Array.from(newCats));

                  alert(`Katalóg úspešne aktualizovaný (${importedProducts.length} produktov).`);
              } else {
                  alert("Chybný formát súboru.");
              }
          } catch (err) {
              console.error(err);
              alert("Chyba pri čítaní súboru.");
          }
      };
      reader.readAsText(file);
  };

