                                <button onClick={() => addCategory('text', 'Textová Sekcia')} className="px-3 py-1.5 bg-white border border-gray-300 rounded-full text-sm font-bold hover:border-purple-500 hover:text-purple-600 shadow-sm flex items-center gap-1 transition"><FileText size={14}/> Text / Obrázok</button>
                            </div>
                        </div>
                    </div>

                    {/* Totals Section */}
                    <div className="mt-12 pt-4 border-t-2 border-gray-800 flex justify-end break-inside-avoid">
                        <div className="w-64">
                            <div className="flex justify-between mb-2 text-sm text-gray-500 no-print">
                                <span>Náklady (Bez DPH):</span>
                                <span>{formatCurrency(totals.totalSelling / (1 + data.globalMargin/100))}</span>
                            </div>
                            <div className="flex justify-between text-xl font-bold text-gray-900">
                                <span>Cena Celkom:</span>
                                <span>{formatCurrency(totals.totalSelling)}</span>
                            </div>
                            <div className="text-right text-xs text-gray-500 mt-1">bez DPH</div>
                            <div className="flex justify-between text-sm text-gray-600 mt-2 pt-2 border-t border-gray-200">
                                <span>DPH (20%):</span>
                                <span>{formatCurrency(totals.vat)}</span>
                            </div>
                            <div className="flex justify-between text-lg font-bold text-black mt-1">
                                <span>Spolu s DPH:</span>
                                <span>{formatCurrency(totals.gross)}</span>
                            </div>
                        </div>
                    </div>
                </>
            )}

            {/* Terms - Auto Height in Print */}
            {!isContractMode && (
                <div className="mt-12 break-inside-avoid">
                    <h3 className="font-bold uppercase text-sm mb-2 text-gray-800">Obchodné podmienky & Záruka</h3>
                    <StandaloneRichTextEditor 
                        content={data.terms} 
                        onChange={val => setData({...data, terms: val})} 
                        className="print:min-h-0 print:h-auto" // Override default A4 height for Terms
                    />
                </div>
            )}

            {/* Signature - SHOW ONLY FOR ORDER OR CONTRACT (NOT QUOTE) */}
            {data.type !== 'quote' && (
                <div className="mt-16 grid grid-cols-2 gap-8 break-inside-avoid">
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Objednávateľ)</div>
                    </div>
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Dodávateľ)</div>
                    </div>
                </div>
            )}

        </div>
      </div>

      {/* Print Footer */}
      <div className="print-footer">
          <div>{data.number} | {data.title}</div>
          <div>Strana <span className="pageNumber"></span></div>
          <div>SmartQuote SK</div>
      </div>

    </div>
  );
};

