  const [isCatalogOpen, setIsCatalogOpen] = useState(false);
  const [isClientModalOpen, setIsClientModalOpen] = useState(false);
  const [isSupplierModalOpen, setIsSupplierModalOpen] = useState(false);
  const [isTemplateModalOpen, setIsTemplateModalOpen] = useState(false);
  const [isContractRepoOpen, setIsContractRepoOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const [isMaterialModalOpen, setIsMaterialModalOpen] = useState(false);

  const [showArchive, setShowArchive] = useState(false);
  const [archiveSearch, setArchiveSearch] = useState('');

  const [templateModalMode, setTemplateModalMode] = useState<'select' | 'save'>('select');
  const [templateContext, setTemplateContext] = useState<'lift' | 'shaft'>('lift');

  const [emailModalProps, setEmailModalProps] = useState({ to: '', subject: '', message: '' });

  const [calcSuccess, setCalcSuccess] = useState<string | null>(null);
  const [isAiLoading, setIsAiLoading] = useState<string | false>(false);
  const [showLayout, setShowLayout] = useState(true);
  const [hasShaft, setHasShaft] = useState(false);
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  // DRAG AND DROP STATE
  const [draggedCatId, setDraggedCatId] = useState<string | null>(null);

  const printContentRef = useRef<HTMLDivElement>(null);
  const titleInputRef = useRef<HTMLTextAreaElement>(null);

  // Derived state
  const isContractMode = data.type === 'contract';
  const isOrderMode = data.type === 'order';
  const relatedDoc = savedQuotes.find(q => q.id === data.relatedDocId); // LINKING VISUALIZATION

  // --- PERSISTENCE: LOAD ON START ---
  useEffect(() => {
      const storedQuotes = localStorage.getItem('smartquote_archive');
      if (storedQuotes) {
          try {
              setSavedQuotes(JSON.parse(storedQuotes));
          } catch (e) { console.error("Failed to load archive", e); }
      }

      const storedSettings = localStorage.getItem('smartquote_settings');
      if (storedSettings) {
          try {
              setSettings(JSON.parse(storedSettings));
          } catch (e) { console.error("Failed to load settings", e); }
      }

      // Load products if stored
      const storedProducts = localStorage.getItem('smartquote_products');
      let loadedProducts: Product[] = [];
      if (storedProducts) {
          try {
              loadedProducts = JSON.parse(storedProducts);
              setProducts(loadedProducts);
          } catch (e) { console.error("Failed to load products", e); }
      }

      // Load categories OR RECOVER FROM PRODUCTS (Safe Mode)
      const storedCategories = localStorage.getItem('smartquote_categories');
      if (storedCategories) {
          try {
              let savedCats = JSON.parse(storedCategories);
              // CRITICAL: Merge saved categories with categories found in products to avoid data loss
              const productCategories = new Set(loadedProducts.map(p => p.category));
              const mergedCategories = new Set([...DEFAULT_CATEGORIES, ...savedCats, ...productCategories]);
              setAvailableCategories(Array.from(mergedCategories));
          } catch (e) { console.error("Failed to load categories", e); }
      } else {
          // If no categories stored, initialize from Default + Products
          const productCategories = new Set(loadedProducts.map(p => p.category));
          const mergedCategories = new Set([...DEFAULT_CATEGORIES, ...productCategories]);
          setAvailableCategories(Array.from(mergedCategories));
      }

      // Load cabin classes if stored
      const storedCabinClasses = localStorage.getItem('smartquote_cabin_classes');
      if (storedCabinClasses) {
          try {
              setCabinClasses(JSON.parse(storedCabinClasses));
          } catch (e) { console.error("Failed to load cabin classes", e); }
      }
  }, []);

  // --- PERSISTENCE: SAVE ON CHANGE ---
  useEffect(() => {
      localStorage.setItem('smartquote_archive', JSON.stringify(savedQuotes));
  }, [savedQuotes]);

  useEffect(() => {
      localStorage.setItem('smartquote_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
      localStorage.setItem('smartquote_products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
      localStorage.setItem('smartquote_categories', JSON.stringify(availableCategories));
  }, [availableCategories]);

  useEffect(() => {
      localStorage.setItem('smartquote_cabin_classes', JSON.stringify(cabinClasses));
  }, [cabinClasses]);


  // --- Calculations ---
  const calculateTotals = () => {
      let totalSelling = 0;
      let totalPurchase = 0;

      data.categories.forEach(cat => {
          if (cat.isHidden) return; // Completely excluded

          const margin = cat.section === 'shaft' ? data.shaftMargin : data.globalMargin;

          cat.items.forEach(item => {
              const itemTotal = item.quantity * item.unitPrice; 
              // If item is hidden from print, we still include it in calculation!
              totalPurchase += itemTotal;
              totalSelling += itemTotal * (1 + margin / 100);
          });
      });

      return {
          totalSelling,
          vat: totalSelling * 0.23, // 23% VAT
          gross: totalSelling * 1.23
      };
  };

  const totals = calculateTotals();

  const handleLogin = () => {
      sessionStorage.setItem('auth', 'true');
      setIsAuthenticated(true);
  };

  const handleLogout = () => {
      sessionStorage.removeItem('auth');
      setIsAuthenticated(false);
  }

  // Auto-generate station labels if missing
  useEffect(() => {
      if (data.layout && (!data.layout.stationLabels || data.layout.stationLabels.length === 0)) {
          const stops = data.layout.numberOfStops || 2;
          const start = data.layout.startStation || 0;
          const labels = Array.from({length: stops}, (_, i) => i + start).join(',');
          handleLayoutChange('stationLabels', labels);
      }
  }, [data.layout?.numberOfStops, data.layout?.startStation]);

  // Quote Number Year Update
  useEffect(() => {
      const year = new Date().getFullYear().toString().slice(-2);
      if (!data.number.includes(year)) {
          if (data.categories.length === 0 && data.type === 'quote') {
              const num = generateDocNumber('quote');
              setData(prev => ({...prev, number: num}));
          }
      }
  }, []);

  // --- Handlers ---

  const handleAddCategory = (name: string) => {
      if (name && !availableCategories.includes(name)) {
          setAvailableCategories([...availableCategories, name]);
      }
  };

  const handleDeleteCategory = (name: string) => {
      setAvailableCategories(availableCategories.filter(c => c !== name));
  };

  // Cabin Class Handlers
  const handleAddCabinClass = (cc: CabinClass) => setCabinClasses([...cabinClasses, cc]);
  const handleDeleteCabinClass = (id: string) => setCabinClasses(cabinClasses.filter(c => c.id !== id));
  // UPDATED: Handle updates for linking sets to classes
  const handleUpdateCabinClass = (updatedClass: CabinClass) => {
      setCabinClasses(prev => prev.map(c => c.id === updatedClass.id ? updatedClass : c));
  };

  // Helper logic for Guide Rails based on Load
  const getRailTypesForLoad = (load: number): { car: RailType, cwt: RailType } => {
      let carRail: RailType = 'T70';
      let cwtRail: RailType = 'T50';

      if (load < 450) { carRail = 'T70'; cwtRail = 'T50'; }
      else if (load >= 450 && load < 630) { carRail = 'T75'; cwtRail = 'T50'; }
      else if (load >= 630 && load < 1000) { carRail = 'T89'; cwtRail = 'T50'; }
      else if (load >= 1000 && load < 1275) { carRail = 'T90'; cwtRail = 'T70'; }
      else if (load >= 1275) { carRail = 'T125'; cwtRail = 'T90'; }

      return { car: carRail, cwt: cwtRail };
  };

  const handleLayoutChange = (field: keyof LiftLayoutData, value: any) => {
      setData(prev => {
          const newData = {
              ...prev,
              layout: { ...prev.layout!, [field]: value }
          };

          // --- TRIAD AUTOMATION LOGIC ---
          // Update dependent fields directly in the new state object
          if (field === 'machineRoomPosition') {
              if (value === 'above') {
                  newData.layout.suspensionType = '1:1';
                  newData.layout.bracketType = 'standard';
              } else if (value === 'head') {
                  // MRL -> 2:1 -> Combined Logic forced
                  newData.layout.suspensionType = '2:1';
                  newData.layout.bracketType = 'combined';
              }
          }
          else if (field === 'suspensionType') {
              if (value === '1:1') {
                  newData.layout.machineRoomPosition = 'above';
                  newData.layout.bracketType = 'standard';
              } else if (value === '2:1') {
                  newData.layout.machineRoomPosition = 'head';
                  newData.layout.bracketType = 'combined';
              }
          }
          // -----------------------------

          // Auto-calculate capacity based on area (EN 81-20 Table 6)
          if (field === 'cabinWidth' || field === 'cabinDepth') {
               const width = field === 'cabinWidth' ? value : prev.layout?.cabinWidth || 0;
               const depth = field === 'cabinDepth' ? value : prev.layout?.cabinDepth || 0;
               const area = (width * depth) / 1000000;

               let persons = Math.floor(area / 0.15); // Rough approx
               let load = Math.floor(persons * 75);

               if (load < 320) { load = 320; persons = 4; }
               else if (load < 450) { load = 450; persons = 6; }
               else if (load < 630) { load = 630; persons = 8; }
               else if (load < 800) { load = 800; persons = 10; }
               else if (load < 1000) { load = 1000; persons = 13; }

               newData.layout!.ratedLoad = load;
               newData.layout!.numberOfPersons = persons;

               // TRIGGER RAIL CALC - because load changed via dimension
               const rails = getRailTypesForLoad(load);
               newData.layout!.guideTypeCar = rails.car;
               newData.layout!.guideTypeCwt = rails.cwt;
          }

          // ITEM 1: Guide Rail Auto Calculation based on Load (Direct Change)
          if (field === 'ratedLoad') {
              const rails = getRailTypesForLoad(value);
              newData.layout!.guideTypeCar = rails.car;
              newData.layout!.guideTypeCwt = rails.cwt;
          }

          if (field === 'numberOfStops' || field === 'startStation') {
              const stops = field === 'numberOfStops' ? value : prev.layout?.numberOfStops || 2;
              const start = field === 'startStation' ? value : prev.layout?.startStation || 0;
              const labels = Array.from({length: stops}, (_, i) => i + start).join(',');
              newData.layout!.stationLabels = labels;
          }

          return newData;
      });
  };

