              const imported = JSON.parse(e.target?.result as string) as {
                  products?: Product[];
                  clients?: Client[];
                  suppliers?: Supplier[];
                  templates?: QuoteTemplate[];
                  settings?: AppSettings;
                  savedQuotes?: QuoteData[];
