      // Fallback for drag preview transparency
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndCat = (e: React.DragEvent) => {
      setDraggedCatId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverCat = (e: React.DragEvent, targetId: string) => {
      e.preventDefault(); // Necessary to allow dropping
      if (!draggedCatId || draggedCatId === targetId) return;

      const items = data.categories;
      const draggedIndex = items.findIndex(i => i.id === draggedCatId);
      const targetIndex = items.findIndex(i => i.id === targetId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      setData(prev => ({...prev, categories: newItems}));
  };

  const handleAiCategoryItems = (catId: string, name: string) => handleAiSuggest(catId, name);

  if (!isAuthenticated) {
      return <LoginGate onLogin={handleLogin} />;
  }

