            {/* Signature - SHOW ONLY FOR ORDER OR CONTRACT (NOT QUOTE) */}
            {data.type !== 'quote' && (
                <div className="mt-16 grid grid-cols-2 gap-8 break-inside-avoid">
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Objednávateľ)</div>
                    </div>
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Dodávateľ)</div>
                    </div>
                </div>
            )}

        </div>
      </div>

      {/* Print Footer */}
      <div className="print-footer">
          <div>{data.number} | {data.title}</div>
          <div>Strana <span className="pageNumber"></span></div>
          <div>SmartQuote SK</div>
