  }, [availableCategories]);

  useEffect(() => {
      localStorage.setItem('smartquote_cabin_classes', JSON.stringify(cabinClasses));
  }, [cabinClasses]);


  // --- Calculations ---
  const calculateTotals = () => {
      let totalSelling = 0;
      let totalPurchase = 0;

      data.categories.forEach(cat => {
          if (cat.isHidden) return; // Completely excluded

          const margin = cat.section === 'shaft' ? data.shaftMargin : data.globalMargin;

          cat.items.forEach(item => {
              const itemTotal = item.quantity * item.unitPrice; 
              // If item is hidden from print, we still include it in calculation!
              totalPurchase += itemTotal;
              totalSelling += itemTotal * (1 + margin / 100);
          });
      });

      return {
          totalSelling,
          vat: totalSelling * 0.23, // 23% VAT
          gross: totalSelling * 1.23
      };
  };

