              totalSelling += itemTotal * (1 + margin / 100);
          });
      });

      const vatRate = data.vatRate ?? 23; // Default to 23 if undefined (migration)

      return {
          totalPurchase,
          totalSelling,
          vat: totalSelling * (vatRate / 100),
          gross: totalSelling * (1 + vatRate / 100)
      };
