          ...prev,
          categories: [...prev.categories, ...template.data.categories.map(c => ({...c, id: generateId(), items: c.items.map(i => ({...i, id: generateId()}))}))]
      }));
      setIsTemplateModalOpen(false);
  };

  const handleSaveTemplate = (name: string, type: 'lift' | 'shaft') => {
      const newTemplate: QuoteTemplate = {
          id: generateId(),
          name,
          type,
          data: {
              categories: data.categories.filter(c => c.section === type),
              layout: data.layout,
              margin: type === 'shaft' ? data.shaftMargin : data.globalMargin
          }
      };
      setTemplates([...templates, newTemplate]);
  };

  const handleDeleteTemplate = (id: string) => setTemplates(templates.filter(t => t.id !== id));

  const handleSelectContractTemplate = (content: string) => {
      setData(prev => ({ ...prev, contractBody: content }));
      setIsContractRepoOpen(false);
  };
  const handleSaveContractTemplate = (name: string) => {
      setContractTemplates([...contractTemplates, { id: generateId(), name, content: data.contractBody || '' }]);
  };
  const handleDeleteContractTemplate = (id: string) => setContractTemplates(contractTemplates.filter(t => t.id !== id));

  const handleSaveSettings = (newSettings: AppSettings) => setSettings(newSettings);

  // UPDATED EXPORT: Must include customCategories
  const handleExportData = () => {
      const blob = new Blob([JSON.stringify({ 
          data, 
          products, 
          clients, 
          suppliers, 
          templates, 
          settings, 
          savedQuotes, 
          contractTemplates, 
          customCategories: availableCategories, // Explicitly export categories
          cabinClasses: cabinClasses 
      }, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `smartquote-backup-${new Date().toISOString().split('T')[0]}.json`;
      a.click();
  };

  const handleFactoryReset = () => {
      setProducts([]);
      setClients([]);
      setSuppliers([]);
      setTemplates([]);
      setSavedQuotes([]);
      setAvailableCategories(DEFAULT_CATEGORIES);
      setCabinClasses(DEFAULT_CABIN_CLASSES);
      setSettings({ nextCpSequence: 1, nextObjSequence: 1, nextPlSequence: 1 });
      setData({...data, id: generateId(), categories: []});
      localStorage.clear();
      window.location.reload();
  };

  const handleSendEmail = (to: string, subject: string, message: string) => {
      window.open(`mailto:${to}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(message)}`);
      setIsEmailModalOpen(false);
  };

  const openEmailModal = () => {
      setEmailModalProps({
          to: data.client.email || '',
          subject: `${data.number} - ${data.title}`,
          message: `Vážený obchodný partner,\n\nv nadväznosti na Váš dopyt Vám v prílohe zasielame cenovú ponuku č. ${data.number}.\n\nVeríme, že naša ponuka splní Vaše očakávan a tešíme sa na prípadnú spoluprácu.\n\nV prípade akýchkoľvek otázok nás neváhajte kontaktovať.\n\nS úctou,\n\n${data.supplier.name}\n${data.supplier.email || ''}\n${data.supplier.phone || ''}`
      });
      setIsEmailModalOpen(true);
  };

  // --- DOCUMENT WORKFLOW & SAVING ---

  const generateDocNumber = (type: 'quote' | 'order' | 'contract') => {
      const year = new Date().getFullYear().toString().slice(-2);
      let seq = 1;
      let prefix = 'CP';

      if (type === 'quote') { seq = settings.nextCpSequence; prefix = 'CP'; }
      if (type === 'order') { seq = settings.nextObjSequence; prefix = 'OBJ'; }
      if (type === 'contract') { seq = settings.nextPlSequence; prefix = 'PL'; }

      const numStr = seq.toString().padStart(3, '0');
      return `${prefix}_SK_${numStr}_${year}_BA`;
  };

  const handleUnlockNumber = () => {
      const code = prompt("Zadajte admin kód pre úpravu čísla:");
      if (code === '123') {
          setIsNumberEditable(true);
      } else if (code !== null) {
          alert("Nesprávny kód");
      }
  };

  const handleSaveCurrentQuote = () => {
      const now = Date.now();
      const quoteToSave = { ...data, lastUpdated: now };

      // Update existing or add new
      const exists = savedQuotes.find(q => q.id === data.id);
      let newSavedQuotes;

      if (exists) {
          newSavedQuotes = savedQuotes.map(q => q.id === data.id ? quoteToSave : q);
      } else {
          newSavedQuotes = [...savedQuotes, quoteToSave];
      }

      setSavedQuotes(newSavedQuotes);
      // Auto-saved to localStorage via useEffect
      alert(`Doklad ${data.number} bol uložený do Archívu.`);
  };

  const handleNewQuote = () => {
      if (data.categories.length > 0) {
          if (window.confirm("Chcete uložiť aktuálne rozpracovanú ponuku do Archívu?")) {
              handleSaveCurrentQuote();
          }
      }

      if (window.confirm("Naozaj chcete vytvoriť novú prázdnu ponuku?")) {
          // Force new ID
          const newId = generateId();
          const newNum = generateDocNumber('quote');

          // CRITICAL: Auto-increment Quote Sequence so next one is +1
          setSettings(prev => ({...prev, nextCpSequence: prev.nextCpSequence + 1}));

          setData({
            id: newId,
            number: newNum,
            type: 'quote',
            title: 'Cenová Ponuka - Výťah',
            date: new Date().toISOString().split('T')[0],
            validUntil: new Date(Date.now() + 30*24*60*60*1000).toISOString().split('T')[0],
            supplier: data.supplier, // Keep supplier info
            client: { name: '', details: '' },
            layout: { ...DEFAULT_LAYOUT },
            categories: [], // Reset categories
            terms: DEFAULT_TERMS_HTML,
            currency: '€',
            globalMargin: 15,
            shaftMargin: 20,
            vatRate: 23, 
            hideItemPrices: true, 
            showTechSpecs: true,
            contractBody: DEFAULT_CONTRACT_TEXT
          });
          setCalcSuccess(null);
          setHasShaft(false);
      }
  };

  const handleDeleteQuote = (id: string) => {
      if (window.confirm("Naozaj chcete vymazať tento doklad z archívu? Táto akcia je nevratná.")) {
          setSavedQuotes(savedQuotes.filter(q => q.id !== id));
      }
  };

  const loadFromStorage = (q: QuoteData) => {
      setData(q);
      setShowArchive(false);
  };

  const createRelatedOrder = (q: QuoteData) => {
      const newNum = generateDocNumber('order');
      const newId = generateId();

      const orderDoc: QuoteData = {
          ...q,
          id: newId,
          relatedDocId: q.id,
          number: newNum,
          type: 'order',
          title: `Objednávka k ${q.number}`,
          date: new Date().toISOString().split('T')[0],
      };

      setSavedQuotes(prev => [...prev, orderDoc]);
      setSettings(prev => ({...prev, nextObjSequence: prev.nextObjSequence + 1}));

      setData(orderDoc);
      setShowArchive(false);
      alert(`Vytvorená Objednávka: ${newNum}`);
  };

  const createRelatedContract = (q: QuoteData) => {
      const newNum = generateDocNumber('contract');
      const newId = generateId();

      // Replace placeholders in contract text
      let contractBody = contractTemplates.length > 0 ? contractTemplates[0].content : DEFAULT_CONTRACT_TEXT;
      contractBody = contractBody.replace('[CISLO_DOKLADU]', newNum);
      contractBody = contractBody.replace('[NAZOV_DODAVATELA]', q.supplier.name);
      contractBody = contractBody.replace('[DETAILY_DODAVATELA]', q.supplier.details.replace(/\n/g, '<br>'));
      contractBody = contractBody.replace('[NAZOV_KLIENTA]', q.client.name);
      contractBody = contractBody.replace('[DETAILY_KLIENTA]', q.client.details.replace(/\n/g, '<br>'));

      const totals = calculateTotals(); // Use current totals (might have changed in Order)
      contractBody = contractBody.replace('[CENA_CELKOM]', totals.gross.toLocaleString('sk-SK', {minimumFractionDigits: 2}) + ' ' + q.currency);

      const contractDoc: QuoteData = {
          ...q,
          id: newId,
          relatedDocId: q.id,
          number: newNum,
          type: 'contract',
          title: `Zmluva o dielo č. ${newNum}`,
          date: new Date().toISOString().split('T')[0],
          contractBody: contractBody
      };

      setSavedQuotes(prev => [...prev, contractDoc]);
      setSettings(prev => ({...prev, nextPlSequence: prev.nextPlSequence + 1}));

      setData(contractDoc);
      setShowArchive(false);
      alert(`Vytvorená Zmluva: ${newNum}`);
  };

  // NAVIGATION HANDLER
  const handleNavigateToRelated = (targetType: DocumentType) => {
      let targetDoc: QuoteData | undefined;

      if (data.type === 'quote' && targetType === 'order') {
          targetDoc = savedQuotes.find(q => q.type === 'order' && q.relatedDocId === data.id);
      } else if (data.type === 'order') {
           if (targetType === 'quote') {
               targetDoc = savedQuotes.find(q => q.id === data.relatedDocId);
           } else if (targetType === 'contract') {
               targetDoc = savedQuotes.find(q => q.type === 'contract' && q.relatedDocId === data.id);
           }
      } else if (data.type === 'contract') {
           if (targetType === 'order') {
               targetDoc = savedQuotes.find(q => q.id === data.relatedDocId);
           }
      }

      if (targetDoc) {
          loadFromStorage(targetDoc);
      } else {
          alert("Súvisiaci doklad sa nenašiel v archíve.");
      }
  };


  const handleCalculateDim = (std: string) => {
      if (!data.layout) return;
      const { shaftWidth, shaftDepth, gapLeft, gapRight, gapFront, gapRear, frameType, guideTypeCar } = data.layout;

      const getRailDepth = (type?: string) => {
          if (!type) return 80;
          if (type.includes('T45') || type.includes('T50')) return 50;
          if (type.includes('T70') || type.includes('T75')) return 70;
          if (type.includes('T89') || type.includes('T90')) return 90;
          if (type.includes('T125') || type.includes('T127')) return 125;
          return 80;
      };

      const railDepth = getRailDepth(guideTypeCar);
      const wallThickness = 30; // 30mm per side

      let newWidth = shaftWidth - gapLeft - gapRight - (2 * wallThickness);
      if (frameType === 'central') {
          newWidth = newWidth - (2 * railDepth);
      }

      let newDepth = shaftDepth - gapFront - gapRear - (2 * wallThickness);

      newWidth = Math.floor(newWidth / 10) * 10;
      newDepth = Math.floor(newDepth / 10) * 10;

      setData(prev => ({
          ...prev,
          layout: {
              ...prev.layout!,
              cabinWidth: newWidth,
              cabinDepth: newDepth
          }
      }));

      handleLayoutChange('cabinWidth', newWidth);
      setCalcSuccess(std);
      setTimeout(() => setCalcSuccess(null), 2000);
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
       const file = e.target.files?.[0];
       if(file) {
           const reader = new FileReader();
           reader.onload = (ev) => setData({...data, logoUrl: ev.target?.result as string});
           reader.readAsDataURL(file);
       }
  };

  const toggleTechSpecs = () => setData(prev => ({...prev, showTechSpecs: !prev.showTechSpecs}));
  const toggleShaft = () => setHasShaft(!hasShaft);

  // FIXED CURRENCY FORMATTER
  const formatCurrency = (val: number) => {
      return val.toLocaleString('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' ' + data.currency;
  };

  const addCategory = (type: 'items'|'text', name?: string, items?: QuoteItem[], section: 'lift'|'shaft' = 'lift', textContent?: string) => {
      setData(prev => ({
          ...prev,
          categories: [...prev.categories, {
              id: generateId(),
              type,
              name: name || (type === 'text' ? 'Textová sekcia' : 'Nová kategória'),
              items: items ? items.map(i => ({...i, id: generateId()})) : [],
              isExpanded: true,
              section,
              textContent: textContent || (type === 'text' ? '<p>Sem napíšte text...</p>' : undefined)
          }]
      }));
  };

  const handleAddItem = (catId: string, isSurcharge = false) => {
      setData(prev => ({
          ...prev,
          categories: prev.categories.map(c => c.id === catId ? {
              ...c,
              items: [...c.items, {
                  id: generateId(), 
                  description: isSurcharge ? 'Príplatok / Príslušenstvo' : 'Nová položka', 
                  unit: 'ks', 
                  quantity: 1, 
                  unitPrice: 0, 
                  purchasePrice: 0, 
                  vatRate: 23,
                  isSurcharge // Mark as surcharge
              }]
          } : c)
      }));
  };

  const handleOpenCatalog = (catId: string, itemId?: string) => {
      setIsProductModalOpen(true);
  };

  const handleAiSuggest = async (catId: string, catName: string) => {
      setIsAiLoading(catId);
      const suggestions = await generateSuggestion(catName, 'category_items');
      if (suggestions) {
          const items = suggestions.split(',').map(s => ({
              id: generateId(), description: s.trim(), unit: 'ks', quantity: 1, unitPrice: 0, purchasePrice: 0, vatRate: 23
          }));
          setData(prev => ({
             ...prev,
             categories: prev.categories.map(c => c.id === catId ? {...c, items: [...c.items, ...items]} : c)
          }));
      }
      setIsAiLoading(false);
  };

  const moveCategory = (id: string, dir: 'up' | 'down') => {
      const idx = data.categories.findIndex(c => c.id === id);
      if (idx === -1) return;
      if (dir === 'up' && idx === 0) return;
      if (dir === 'down' && idx === data.categories.length - 1) return;

      const newCats = [...data.categories];
      const targetIdx = dir === 'up' ? idx - 1 : idx + 1;
      [newCats[idx], newCats[targetIdx]] = [newCats[targetIdx], newCats[idx]];
      setData(prev => ({ ...prev, categories: newCats }));
  };

  // DRAG AND DROP HANDLERS FOR CATEGORIES
  const onDragStartCat = (e: React.DragEvent, id: string) => {
      setDraggedCatId(id);
      e.dataTransfer.effectAllowed = 'move';
      // Fallback for drag preview transparency
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndCat = (e: React.DragEvent) => {
      setDraggedCatId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverCat = (e: React.DragEvent, targetId: string) => {
      e.preventDefault(); // Necessary to allow dropping
      if (!draggedCatId || draggedCatId === targetId) return;

      const items = data.categories;
      const draggedIndex = items.findIndex(i => i.id === draggedCatId);
      const targetIndex = items.findIndex(i => i.id === targetId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      setData(prev => ({...prev, categories: newItems}));
  };

  const handleAiCategoryItems = (catId: string, name: string) => handleAiSuggest(catId, name);

  if (!isAuthenticated) {
      return <LoginGate onLogin={handleLogin} />;
  }

  return (
      <div className="min-h-screen bg-gray-100 p-4 md:p-8 font-sans print:bg-white print:p-0">
      {/* GLOBAL PRINT STYLE OVERRIDE */}
      <style>{`
        @media print {
            body, #root, .print-container {
                overflow: visible !important;
                height: auto !important;
                margin: 0 !important;
            }
        }
      `}</style>

      {/* WORKFLOW TOOLBAR - Visible under Header */}
      <div className="no-print mb-6">
        <div className="flex justify-between items-center mb-4">
            <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                <Calculator className="text-blue-600"/> SmartQuote SK <span className="text-xs bg-gray-200 text-gray-600 px-2 py-1 rounded">v{APP_VERSION}</span>
            </h1>

            <div className="flex gap-2 items-center">
                {/* Unified Print/PDF Button */}
                <button onClick={() => window.print()} className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm" title="Tlačiť alebo Uložiť ako PDF">
                    <Printer size={16}/> Tlačiť / PDF
                </button>
                <button onClick={openEmailModal} className="px-3 py-2 bg-green-600 hover:bg-green-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm" title="Odoslať PDF E-mailom">
                    <Mail size={16}/> Odoslať
                </button>

                <div className="h-6 w-px bg-gray-300 mx-2"></div>

                <button onClick={handleNewQuote} className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded flex items-center gap-2 shadow text-sm border border-blue-800" title="Nová prázdna ponuka">
                    <PlusCircle size={16}/> Nová CP
                </button>

                <button onClick={() => setIsCatalogOpen(true)} className="px-3 py-2 bg-purple-100 hover:bg-purple-200 text-purple-800 font-bold rounded flex items-center gap-2 border border-purple-300 text-sm"><Settings size={16}/> Katalóg</button>
                <button onClick={handleSaveCurrentQuote} className="px-3 py-2 bg-green-100 hover:bg-green-200 text-green-800 font-bold rounded flex items-center gap-2 border border-green-300 text-sm" title="Uložiť zmeny"><Save size={16}/> Uložiť</button>
                <button onClick={() => setShowArchive(true)} className="px-3 py-2 bg-gray-200 hover:bg-gray-300 rounded text-gray-700 font-bold flex items-center gap-2 text-sm"><Archive size={16}/> Archív</button>
                <button onClick={() => setIsSettingsModalOpen(true)} className="p-2 bg-gray-200 hover:bg-gray-300 rounded text-gray-700"><Settings size={18}/></button>
                <label className="flex items-center gap-2 ml-2 cursor-pointer bg-white border px-3 py-1 rounded-full shadow-sm hover:bg-gray-50">
                    <input type="checkbox" checked={data.hideItemPrices} onChange={e => setData({...data, hideItemPrices: e.target.checked})} className="rounded text-blue-600 focus:ring-blue-500"/>
                    <span className="text-xs font-bold text-gray-600">Skryť ceny (Tlač)</span>
                </label>
                <button onClick={handleLogout} className="ml-2 p-2 bg-red-100 hover:bg-red-200 text-red-700 rounded-full" title="Odhlásiť"><LogOut size={16}/></button>
            </div>
        </div>

        {/* WORKFLOW STATUS BAR */}
        <div className="bg-white p-2 rounded-lg border border-blue-200 shadow-sm flex items-center justify-between">
            <div className="flex items-center gap-4">
                 <button 
                    onClick={() => handleNavigateToRelated('quote')}
                    disabled={data.type === 'quote'}
                    className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'quote' ? 'bg-yellow-100 text-yellow-800 ring-2 ring-yellow-400 cursor-default' : 'bg-gray-100 text-gray-500 hover:bg-yellow-50 hover:text-yellow-700'}`}
                 >
                     1. Cenová Ponuka
                     {data.type !== 'quote' && <CheckCircle size={12}/>}
                 </button>
                 <ArrowRight size={16} className="text-gray-300"/>
                 <button 
                    onClick={() => handleNavigateToRelated('order')}
                    disabled={data.type === 'order'}
                    className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'order' ? 'bg-blue-100 text-blue-800 ring-2 ring-blue-400 cursor-default' : 'bg-gray-100 text-gray-500 hover:bg-blue-50 hover:text-blue-700'}`}
                 >
                     2. Objednávka
                     {data.type !== 'order' && savedQuotes.some(q => q.type === 'order' && q.relatedDocId === (data.type==='quote'?data.id:data.relatedDocId)) && <CheckCircle size={12}/>}
                 </button>
                 <ArrowRight size={16} className="text-gray-300"/>
                 <button 
                    onClick={() => handleNavigateToRelated('contract')}
                    disabled={data.type === 'contract'}
                    className={`px-3 py-1 rounded-full text-xs font-bold uppercase flex items-center gap-1 transition ${data.type === 'contract' ? 'bg-green-100 text-green-800 ring-2 ring-green-400 cursor-default' : 'bg-gray-100 text-gray-500 hover:bg-green-50 hover:text-green-700'}`}
                 >
                     3. Zmluva
                 </button>
            </div>

            <div className="flex gap-2">
                {data.type === 'quote' && (
                    <button onClick={() => createRelatedOrder(data)} className="px-4 py-1.5 bg-blue-600 text-white hover:bg-blue-700 rounded text-sm font-bold flex items-center gap-2 shadow">
                        <FileInput size={14}/> Vytvoriť Objednávku
                    </button>
                )}
                {data.type === 'order' && (
                    <button onClick={() => createRelatedContract(data)} className="px-4 py-1.5 bg-green-600 text-white hover:bg-green-700 rounded text-sm font-bold flex items-center gap-2 shadow">
                        <FileCheck size={14}/> Vytvoriť Zmluva
                    </button>
                )}
            </div>
        </div>
      </div>

      {/* Modals */}
      <ProductDatabaseModal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} onSelectProduct={handleSelectProduct} products={products} onAddProduct={handleAddProduct} onDeleteProduct={handleDeleteProduct} layout={data.layout} />

      {/* Updated Catalog Manager with synced categories */}
      <CatalogManagerModal 
        isOpen={isCatalogOpen} 
        onClose={() => setIsCatalogOpen(false)} 
        products={products} 
        onAddProduct={handleAddProduct} 
        onUpdateProduct={handleUpdateProduct} 
        onDeleteProduct={handleDeleteProduct} 
        customCategories={availableCategories} 
        onAddCategory={handleAddCategory}
        onDeleteCategory={handleDeleteCategory}
        onImportCatalog={handleImportCatalog}
        // Cabin Class Props
        cabinClasses={cabinClasses}
        onAddCabinClass={handleAddCabinClass}
        onUpdateCabinClass={handleUpdateCabinClass}
        onDeleteCabinClass={handleDeleteCabinClass}
      />

      <ClientDatabaseModal isOpen={isClientModalOpen} onClose={() => setIsClientModalOpen(false)} onSelectClient={c => setData({...data, client: {name: c.name, details: c.details, email: c.email, phone: c.phone}})} clients={clients} onAddClient={c => setClients([...clients, c])} onDeleteClient={id => setClients(clients.filter(c => c.id !== id))} />
      <SupplierDatabaseModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} onSelectSupplier={s => setData({...data, supplier: {name: s.name, details: s.details, email: s.email, phone: s.phone}, logoUrl: s.logoUrl})} suppliers={suppliers} onAddSupplier={s => setSuppliers([...suppliers, s])} onDeleteSupplier={id => setSuppliers(suppliers.filter(s => s.id !== id))} />
      <TemplateDatabaseModal isOpen={isTemplateModalOpen} onClose={() => setIsTemplateModalOpen(false)} mode={templateModalMode} templateType={templateContext} templates={templates} onSelectTemplate={handleLoadTemplate} onSaveTemplate={handleSaveTemplate} onDeleteTemplate={handleDeleteTemplate} />
      <ContractRepositoryModal isOpen={isContractRepoOpen} onClose={() => setIsContractRepoOpen(false)} templates={contractTemplates} onSelectTemplate={handleSelectContractTemplate} onSaveCurrent={handleSaveContractTemplate} onDeleteTemplate={handleDeleteContractTemplate} />
      <SettingsModal isOpen={isSettingsModalOpen} onClose={() => setIsSettingsModalOpen(false)} settings={settings} onSaveSettings={handleSaveSettings} onExportData={handleExportData} onImportData={handleImportData} onFactoryReset={handleFactoryReset} appVersion={APP_VERSION} />
      <EmailModal isOpen={isEmailModalOpen} onClose={() => setIsEmailModalOpen(false)} onSend={handleSendEmail} defaultTo={emailModalProps.to} defaultSubject={emailModalProps.subject} defaultMessage={emailModalProps.message} />

      {/* NEW MATERIAL WIZARD with synced categories */}
      <MaterialCalculatorModal 
        isOpen={isMaterialModalOpen} 
        onClose={() => setIsMaterialModalOpen(false)} 
        layout={data.layout || DEFAULT_LAYOUT} 
        onInsert={handleMaterialWizardInsert} 
        products={products} 
        customCategories={availableCategories} 
        onAddCategory={handleAddCategory}
        // Needed for linking class to set
        cabinClasses={cabinClasses}
      />

      {/* Archive Modal */}
      {showArchive && (
          <div className="fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 no-print">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-5xl max-h-[85vh] flex flex-col">
                  <div className="p-4 border-b flex justify-between items-center bg-gray-50 rounded-t-xl">
                      <h2 className="text-xl font-bold flex items-center gap-2"><Archive className="text-blue-600"/> Archív Dokladov</h2>
                      <button onClick={() => setShowArchive(false)} className="p-2 hover:bg-gray-200 rounded-full text-gray-500"><X size={20}/></button>
                  </div>
                  <div className="p-4 border-b bg-white">
                      <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
