                            isAiLoading={isAiLoading === cat.id}
                            draggable={true}
                            onDragStart={onDragStartCat}
                            onDragOver={onDragOverCat}
                            onDragEnd={onDragEndCat}
                            hidePrices={data.hideItemPrices || isContractMode}
                            readOnly={data.type !== 'quote'}
