                {/* Totals Section */}
                <div className="mt-12 pt-4 border-t-2 border-gray-800 flex justify-end break-inside-avoid">
                    <div className="w-64">
                        {/* Cost Row */}
                        <div className="flex justify-between mb-2 text-sm text-gray-500 no-print">
                            <span>Náklady (Bez DPH):</span>
                            <span>{formatCurrency(totals.totalPurchase)}</span>
                        </div>

                        {/* COLORFUL MARGIN & VAT INPUTS (New Design) */}
                        <div className="no-print mb-4 bg-gray-50 p-3 rounded-xl border border-gray-200 flex flex-col gap-2 shadow-inner">
                            <div className="text-[10px] font-bold text-gray-400 uppercase tracking-wider text-center mb-1">Nastavenia Ceny & Zisk</div>
                            <div className="flex gap-2 justify-between">
                                {/* Lift Margin - Blue */}
                                <div className="flex flex-col items-center p-2 bg-blue-50 rounded-lg border border-blue-100 w-1/3 hover:bg-blue-100 transition relative group">
                                    <label className="text-[9px] font-bold text-blue-700 uppercase mb-1">Marža Výťah</label>
                                    <div className="relative w-full mb-1">
                                        <input 
                                            type="number" 
                                            value={data.globalMargin} 
                                            onChange={e => setData({...data, globalMargin: +e.target.value})}
                                            className="w-full text-center font-bold text-blue-800 bg-white border border-blue-200 rounded px-1 text-sm focus:ring-2 focus:ring-blue-400 outline-none h-8"
                                        />
                                        <span className="absolute right-1 top-1/2 -translate-y-1/2 text-[9px] text-blue-400 font-bold">%</span>
                                    </div>
                                    {/* Profit Display */}
                                    <div className="text-[10px] text-blue-600 font-bold bg-blue-100 px-1 rounded flex items-center gap-1" title="Čistý zisk z výťahu">
                                        <TrendingUp size={10}/> {totals.liftProfit.toFixed(0)} €
                                    </div>
                                </div>

                                {/* Shaft Margin - Orange */}
                                <div className="flex flex-col items-center p-2 bg-orange-50 rounded-lg border border-orange-100 w-1/3 hover:bg-orange-100 transition">
                                    <label className="text-[9px] font-bold text-orange-700 uppercase mb-1">Marža Šachta</label>
                                    <div className="relative w-full mb-1">
                                        <input 
                                            type="number" 
                                            value={data.shaftMargin} 
                                            onChange={e => setData({...data, shaftMargin: +e.target.value})}
                                            className="w-full text-center font-bold text-orange-800 bg-white border border-orange-200 rounded px-1 text-sm focus:ring-2 focus:ring-orange-400 outline-none h-8"
                                        />
                                        <span className="absolute right-1 top-1/2 -translate-y-1/2 text-[9px] text-orange-400 font-bold">%</span>
                                    </div>
                                    {/* Profit Display */}
                                    <div className="text-[10px] text-orange-600 font-bold bg-orange-100 px-1 rounded flex items-center gap-1" title="Čistý zisk zo šachty">
                                        <TrendingUp size={10}/> {totals.shaftProfit.toFixed(0)} €
                                    </div>
                                </div>

                                {/* VAT - Purple */}
                                <div className="flex flex-col items-center p-2 bg-purple-50 rounded-lg border border-purple-100 w-1/3 hover:bg-purple-100 transition">
                                    <label className="text-[9px] font-bold text-purple-700 uppercase mb-1">Sadzba DPH</label>
                                    <div className="relative w-full mb-1">
                                        <input 
                                            type="number" 
                                            value={data.vatRate ?? 23} 
                                            onChange={e => setData({...data, vatRate: +e.target.value})}
                                            className="w-full text-center font-bold text-purple-800 bg-white border border-purple-200 rounded px-1 text-sm focus:ring-2 focus:ring-purple-400 outline-none h-8"
                                        />
                                        <span className="absolute right-1 top-1/2 -translate-y-1/2 text-[9px] text-purple-400 font-bold">%</span>
                                    </div>
                                    <div className="text-[10px] text-purple-600 font-bold bg-purple-100 px-1 rounded flex items-center gap-1">
                                        <Coins size={10}/> DPH
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-between text-xl font-bold text-gray-900">
                            <span>Cena Celkom:</span>
                            <span>{formatCurrency(totals.totalSelling)}</span>
                        </div>
                        <div className="text-right text-xs text-gray-500 mt-1">bez DPH</div>
                        <div className="flex justify-between text-sm text-gray-600 mt-2 pt-2 border-t border-gray-200">
                            <span>DPH ({data.vatRate ?? 23}%):</span>
                            <span>{formatCurrency(totals.vat)}</span>
                        </div>
                        <div className="flex justify-between text-lg font-bold text-black mt-1">
                            <span>Spolu s DPH:</span>
                            <span>{formatCurrency(totals.gross)}</span>
                        </div>
                    </div>
                </div>
            </>

            {/* Terms */}
            {!isContractMode && (
                <div className="mt-12 break-inside-avoid">
                    <h3 className="font-bold uppercase text-sm mb-2 text-gray-800">Obchodné podmienky & Záruka</h3>
                    <StandaloneRichTextEditor 
                        content={data.terms} 
                        onChange={val => setData({...data, terms: val})} 
                        className="min-h-[200px] print:min-h-0 print:h-auto" 
                        stickyToolbar={false} 
                        minimalPadding={true} 
                    />
                </div>
            )}

            {/* Signature */}
            {data.type !== 'quote' && (
                <div className="mt-16 grid grid-cols-2 gap-8 break-inside-avoid">
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Objednávateľ)</div>
                    </div>
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Dodávateľ)</div>
                    </div>
                </div>
            )}

        </div>
      </div>

      {/* Print Footer */}
      <div className="print-footer">
          <div>{data.number} | {data.title}</div>
          <div>Strana <span className="pageNumber"></span></div>
