                                    <div className="text-[10px] font-bold text-orange-800 uppercase text-center border-b border-orange-100 pb-1">Šachta / Montáž</div>
                                    <div className="flex justify-between text-[10px] text-gray-500">
                                        <span>Náklad:</span>
                                        <span>{totals.shaftCost.toFixed(0)}€</span>
                                    </div>
                                    <div className="relative w-full">
                                        <input 
                                            type="number" 
