                                        className="w-full text-center font-bold text-purple-800 bg-white border border-purple-200 rounded px-1 text-sm focus:ring-2 focus:ring-purple-400 outline-none h-7"
                                    />
                                    <span className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] text-purple-400 font-bold">%</span>
                                </div>
