                                              </label>
                                              <label className="flex items-center gap-2 text-xs font-bold cursor-pointer">
                                                  <input 
                                                      type="radio" name="priceType" 
                                                      checked={editorProduct.priceType === 'fixed'} 
                                                      onChange={() => setEditorProduct({...editorProduct, priceType: 'fixed'})}
                                                  />
