                                                      <span className="font-bold truncate">{p.name}</span>
                                                      <span className="text-gray-500 whitespace-nowrap ml-2">{p.price} €</span>
                                                  </div>
                                              ))}
                                          </div>
                                      )}

                                      <div className="flex-1 bg-gray-50 rounded border border-gray-200 overflow-y-auto p-2 space-y-1 max-h-[400px]">
