// App.tsx
import React, { useState } from 'react';
import { Product, Category } from './types';

function App() {
  const [products, setProducts] = useState<Product[]>([]);
  const [customCategories, setCustomCategories] = useState<Category[]>([]);

  const handleImportData = (file: File) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const fileContent = event.target?.result as string;
        const imported: { products?: Product[]; customCategories?: Category[] } = JSON.parse(fileContent);

        if (imported.customCategories && Array.isArray(imported.customCategories)) {
          // Merge imported custom categories with existing ones, ensuring uniqueness
          const mergedCategories = Array.from(new Set([...customCategories, ...imported.customCategories]));
          setCustomCategories(mergedCategories);

          if (imported.products && Array.isArray(imported.products)) {
            // merge products with new categories
            const newProducts = imported.products.map(p => {
                const category = mergedCategories.find(c => c.name === p.category)
                return {
                    ...p,
                    category: category ? category : {name: 'Default', id: 'default'}
                }
            })
            setProducts([...products, ...newProducts]);
          }

        } else if (imported.products && Array.isArray(imported.products)) {
          // If no custom categories, import products as usual
          const productsList = imported.products
          const newProducts = productsList.map(p => {
              const category = customCategories.find(c => c.name === p.category)
              return {
                  ...p,
                  category: category ? category : {name: 'Default', id: 'default'}
              }
          })
          setProducts([...products, ...newProducts]);
        }
      } catch (error) {
        console.error('Error importing data:', error);
      }
    };
    reader.readAsText(file);
  };


  return (
    <div>
      <input type="file" onChange={(e) => e.target.files && handleImportData(e.target.files[0])} />
      {/* ... rest of the app */}
    </div>
  );
}

export default App;
```


