                  const productsList = imported.products as any[];
                  const prodCats = productsList.map((p: any) => p.category);
                  const mergedCats = Array.from(new Set<string>([...DEFAULT_CATEGORIES, ...prodCats]));
                  setAvailableCategories(mergedCats);
