                                                                  <span className="text-gray-500 whitespace-nowrap">{p.price.toFixed(2)} €</span>
                                                                  <Plus size={14} className="text-purple-600"/>
                                                              </div>
                                                          </div>
                                                      ))}
                                                  </div>
                                              ))
                                          )}
