                                            </button>
                                            <button onClick={() => onDeleteCabinClass(cc.id)} className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded transition" title="Vymazať">
                                                <Trash2 size={20}/>
                                            </button>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
