                        />
                    ))}

                    {!isContractMode && (
                    <div className="no-print mt-4 p-4 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center gap-2 bg-gray-50 text-gray-500 hover:bg-gray-100 transition">
                        <span className="text-sm font-bold uppercase mb-2">Pridať novú sekciu</span>
                        <div className="flex flex-wrap justify-center gap-2">
                            <button onClick={() => addCategory('items', 'Nová Kategória')} className="px-3 py-1.5 bg-white border border-gray-300 rounded-full text-sm font-bold hover:border-blue-500 hover:text-blue-600 shadow-sm flex items-center gap-1 transition"><PlusCircle size={14}/> Prázdna Kategória</button>
                            <button onClick={() => addCategory('text', 'Textová Sekcia')} className="px-3 py-1.5 bg-white border border-gray-300 rounded-full text-sm font-bold hover:border-purple-500 hover:text-purple-600 shadow-sm flex items-center gap-1 transition"><FileText size={14}/> Text / Obrázok</button>
                        </div>
                    </div>
                    )}
                </div>

                {/* Totals Section - NEW LARGE DESIGN */}
                <div className="mt-12 pt-4 border-t-2 border-gray-800 flex justify-end break-inside-avoid">
                    <div className="w-full max-w-md">
                        {/* Cost Row */}
                        <div className="flex justify-between mb-2 text-sm text-gray-500 no-print">
                            <span>Náklady (Bez DPH):</span>
                            <span>{formatCurrency(totals.totalPurchase)}</span>
                        </div>

                        {/* COLORFUL MARGIN & VAT INPUTS (New Large Design) */}
                        <div className="no-print mb-6 bg-white p-4 rounded-xl border-2 border-blue-100 shadow-lg">
                            <div className="text-sm font-bold text-gray-800 uppercase tracking-wider text-center mb-3 border-b pb-2">Ekonomika projektu</div>

                            <div className="grid grid-cols-2 gap-6 mb-4">
                                {/* Lift Column */}
                                <div className="flex flex-col gap-2 p-3 bg-blue-50/50 rounded-lg border border-blue-200">
                                    <div className="text-xs font-bold text-blue-800 uppercase text-center border-b border-blue-200 pb-1">Výťah (Technológia)</div>
                                    <div className="flex justify-between text-xs text-gray-600">
                                        <span>Nákup:</span>
                                        <span className="font-mono font-bold">{totals.liftCost.toFixed(0)} €</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs font-bold w-12">Marža:</span>
                                        <div className="relative flex-1">
                                            <input 
                                                type="number" 
                                                value={data.globalMargin} 
                                                onChange={e => setData({...data, globalMargin: +e.target.value})}
                                                className="w-full text-center font-bold text-blue-800 bg-white border border-blue-300 rounded px-1 text-sm focus:ring-2 focus:ring-blue-400 outline-none h-8"
                                            />
                                            <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-blue-400 font-bold">%</span>
                                        </div>
                                    </div>
                                    <div className="flex justify-between items-center bg-blue-600 text-white p-2 rounded shadow-sm font-bold text-sm" title="Čistý zisk z výťahu">
                                        <span>Zisk:</span>
                                        <span>{totals.liftProfit.toFixed(2)} €</span>
                                    </div>
                                </div>

                                {/* Shaft Column */}
                                <div className="flex flex-col gap-2 p-3 bg-orange-50/50 rounded-lg border border-orange-200">
                                    <div className="text-xs font-bold text-orange-800 uppercase text-center border-b border-orange-200 pb-1">Šachta / Montáž</div>
                                    <div className="flex justify-between text-xs text-gray-600">
                                        <span>Nákup:</span>
                                        <span className="font-mono font-bold">{totals.shaftCost.toFixed(0)} €</span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span className="text-xs font-bold w-12">Marža:</span>
                                        <div className="relative flex-1">
                                            <input 
                                                type="number" 
                                                value={data.shaftMargin} 
                                                onChange={e => setData({...data, shaftMargin: +e.target.value})}
                                                className="w-full text-center font-bold text-orange-800 bg-white border border-orange-300 rounded px-1 text-sm focus:ring-2 focus:ring-orange-400 outline-none h-8"
                                            />
                                            <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-orange-400 font-bold">%</span>
                                        </div>
                                    </div>
                                    <div className="flex justify-between items-center bg-orange-500 text-white p-2 rounded shadow-sm font-bold text-sm" title="Čistý zisk zo šachty">
                                        <span>Zisk:</span>
                                        <span>{totals.shaftProfit.toFixed(2)} €</span>
                                    </div>
                                </div>
                            </div>

                            {/* VAT Row */}
                            <div className="flex items-center gap-3 bg-purple-50 p-2 rounded border border-purple-100">
                                <label className="text-xs font-bold text-purple-700 uppercase shrink-0">Sadzba DPH:</label>
                                <div className="relative w-20">
                                    <input 
                                        type="number" 
                                        value={data.vatRate ?? 23} 
                                        onChange={e => setData({...data, vatRate: +e.target.value})}
                                        className="w-full text-center font-bold text-purple-800 bg-white border border-purple-200 rounded px-1 text-sm focus:ring-2 focus:ring-purple-400 outline-none h-7"
                                    />
                                    <span className="absolute right-1 top-1/2 -translate-y-1/2 text-[10px] text-purple-400 font-bold">%</span>
                                </div>
                                <div className="text-sm text-purple-600 font-bold ml-auto">
                                    {formatCurrency(totals.vat)}
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-between text-2xl font-bold text-gray-900 mb-1">
                            <span>Cena Celkom:</span>
                            <span>{formatCurrency(totals.totalSelling)}</span>
                        </div>
                        <div className="text-right text-xs text-gray-500 mb-2">bez DPH</div>

                        <div className="flex justify-between text-sm text-gray-600 pt-2 border-t border-gray-200">
                            <span>DPH ({data.vatRate ?? 23}%):</span>
                            <span>{formatCurrency(totals.vat)}</span>
                        </div>
                        <div className="flex justify-between text-lg font-bold text-black mt-2 bg-gray-100 p-2 rounded">
                            <span>Spolu s DPH:</span>
                            <span>{formatCurrency(totals.gross)}</span>
                        </div>
                    </div>
                </div>
            </>

            {/* Terms */}
            {!isContractMode && (
                <div className="mt-12 break-inside-avoid">
                    <h3 className="font-bold uppercase text-sm mb-2 text-gray-800">Obchodné podmienky & Záruka</h3>
                    <StandaloneRichTextEditor 
                        content={data.terms} 
                        onChange={val => setData({...data, terms: val})} 
                        className="min-h-[200px] print:min-h-0 print:h-auto" 
                        stickyToolbar={false} 
                        minimalPadding={true} 
                    />
                </div>
            )}

            {/* Signature */}
            {data.type !== 'quote' && (
                <div className="mt-16 grid grid-cols-2 gap-8 break-inside-avoid">
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Objednávateľ)</div>
                    </div>
                    <div className="text-center">
                        <div className="border-b border-black w-48 mx-auto mb-2 h-16"></div>
                        <div className="text-xs font-bold uppercase">Dátum a Podpis (Dodávateľ)</div>
                    </div>
                </div>
            )}

        </div>
      </div>

      {/* Print Footer */}
      <div className="print-footer">
          <div>{data.number} | {data.title}</div>
          <div>Strana <span className="pageNumber"></span></div>
          <div>SmartQuote SK</div>
      </div>

    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
import { QuoteCategory, QuoteItem } from '../types';
import { Trash2, Plus, Sparkles, Bold, Italic, Link, Image as ImageIcon, Table, List, ListOrdered, FileText, ChevronDown, ChevronUp, BookOpen, Layers, Box, Eye, EyeOff, Replace, Printer, Percent, GripVertical } from 'lucide-react';

interface CategoryTableProps {
  category: QuoteCategory;
  currency: string;
  globalMargin: number;
  onUpdateCategory: (id: string, field: keyof QuoteCategory, value: any) => void;
  onDeleteCategory: (id: string) => void;
  onAddItem: (categoryId: string, isSurcharge?: boolean) => void;
  onUpdateItem: (categoryId: string, itemId: string, field: keyof QuoteItem, value: any) => void;
  onDeleteItem: (categoryId: string, itemId: string) => void;
  onAiSuggest: (categoryId: string, categoryName: string) => void;
  onOpenCatalog: (categoryId: string, itemId?: string) => void;
  onMoveCategory?: (id: string, direction: 'up' | 'down') => void;
  isAiLoading: boolean;
  readOnly?: boolean; // New prop for locking edits
  hidePrices?: boolean; // New prop for hiding price columns (Contract mode or Toggle)

  // Drag Category Props
  draggable?: boolean;
  onDragStart?: (e: React.DragEvent, id: string) => void;
  onDragOver?: (e: React.DragEvent, id: string) => void;
  onDragEnd?: (e: React.DragEvent) => void;
}

export const CategoryTable: React.FC<CategoryTableProps> = ({
  category,
  currency,
  globalMargin,
  onUpdateCategory,
  onDeleteCategory,
  onAddItem,
  onUpdateItem,
  onDeleteItem,
  onAiSuggest,
  onOpenCatalog,
  onMoveCategory,
  isAiLoading,
  readOnly = false,
  hidePrices = false,
  draggable, onDragStart, onDragOver, onDragEnd
}) => {
  const [showRichText, setShowRichText] = useState(!!category.textContent);
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null);
  const editorRef = useRef<HTMLDivElement>(null);

  // Sync initial content
  useEffect(() => {
    if (showRichText && editorRef.current && category.textContent && editorRef.current.innerHTML !== category.textContent) {
       editorRef.current.innerHTML = category.textContent;
    }
  }, [showRichText, category.id]); 

  const formatNumber = (num: number) => {
    return num.toLocaleString('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const getSellingPrice = (costPrice: number) => {
    return costPrice * (1 + globalMargin / 100);
  };

  const isEmpty = category.items.length === 0 && !category.textContent;
  const isHidden = category.isHidden;
  const isHiddenFromPrint = category.isHiddenFromPrint;

  // --- Editor Logic ---
  const handleInput = () => {
    if (editorRef.current && !readOnly) {
      onUpdateCategory(category.id, 'textContent', editorRef.current.innerHTML);
    }
  };

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
  };

  const insertImage = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (readerEvent) => {
          const result = readerEvent.target?.result as string;
          execCmd('insertImage', result);
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const insertLink = () => {
    const url = prompt('Vložte URL odkazu (napr. na video):');
    if (url) execCmd('createLink', url);
  };

  const insertTable = () => {
    const html = `
      <table style="width: 100%; border-collapse: collapse; margin: 10px 0;">
        <tbody>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
          <tr>
            <td style="border: 1px solid #ccc; padding: 5px; background-color: #f9fafb; font-weight: bold;">Parameter</td>
            <td style="border: 1px solid #ccc; padding: 5px;">Hodnota</td>
          </tr>
        </tbody>
      </table>
      <p><br/></p>
    `;
    execCmd('insertHTML', html);
  };

  const toggleRichText = () => {
      setShowRichText(!showRichText);
  };

  const toggleSection = () => {
      if(readOnly) return;
      const newSection = category.section === 'shaft' ? 'lift' : 'shaft';
      onUpdateCategory(category.id, 'section', newSection);
  };

  const toggleVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHidden', !isHidden);
  };

  const togglePrintVisibility = () => {
      if(readOnly) return;
      onUpdateCategory(category.id, 'isHiddenFromPrint', !isHiddenFromPrint);
  }

  // --- ITEM DRAG & DROP HANDLERS ---
  const onDragStartItem = (e: React.DragEvent, itemId: string) => {
      e.stopPropagation(); // Stop propagation so category D&D doesn't trigger
      setDraggedItemId(itemId);
      e.dataTransfer.effectAllowed = 'move';
      e.currentTarget.classList.add('opacity-50');
  };

  const onDragEndItem = (e: React.DragEvent) => {
      e.stopPropagation();
      setDraggedItemId(null);
      e.currentTarget.classList.remove('opacity-50');
  };

  const onDragOverItem = (e: React.DragEvent, targetItemId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!draggedItemId || draggedItemId === targetItemId) return;

      const items = category.items;
      const draggedIndex = items.findIndex(i => i.id === draggedItemId);
      const targetIndex = items.findIndex(i => i.id === targetItemId);

      if (draggedIndex === -1 || targetIndex === -1) return;

      const newItems = [...items];
      const [reorderedItem] = newItems.splice(draggedIndex, 1);
      newItems.splice(targetIndex, 0, reorderedItem);

      onUpdateCategory(category.id, 'items', newItems);
  };

  // Determine classes based on hidden states
  let wrapperClasses = "mb-4 flex border rounded-lg overflow-hidden bg-white shadow-sm break-inside-avoid transition-all";
  if (isHidden) {
      // Completely hidden (Grayed out)
      wrapperClasses += " opacity-60 grayscale border-dashed border-gray-400 print:hidden";
  } else if (isHiddenFromPrint) {
      // Hidden from Print ONLY (Red dashed border in UI)
      wrapperClasses += " border-red-300 border-2 border-dashed print:hidden bg-red-50/30";
  } else {
      // Normal
      wrapperClasses += " border-gray-300 print:border-gray-300 print:shadow-none";
  }

  if (isEmpty) wrapperClasses += " print:hidden";
  if (readOnly) wrapperClasses += " border-gray-200";

  return (
    <div className={wrapperClasses}>

      {/* STRICT PRINT HIDING LOGIC */}
      {/* This allows Admin to see prices on screen, but enforces hiding in Print */}
      {hidePrices && (
          <style>{`
              @media print {
                  .price-column-strict { display: none !important; }
              }
          `}</style>
      )}

      {/* Left Vertical Sidebar - Category Name (With D&D Handle) */}
      <div 
          className={`w-10 border-r border-gray-300 flex flex-col items-center py-2 relative print:border-gray-300 print:w-8 ${isHidden ? 'bg-gray-200' : isHiddenFromPrint ? 'bg-red-50' : 'bg-gray-100'} ${draggable && !readOnly ? 'cursor-grab active:cursor-grabbing' : ''}`}
          draggable={draggable && !readOnly}
          onDragStart={(e) => onDragStart && onDragStart(e, category.id)}
          onDragOver={(e) => onDragOver && onDragOver(e, category.id)}
          onDragEnd={onDragEnd}
      >

        {/* Section Toggle (Lift/Shaft) */}
        <button 
            onClick={toggleSection}
            disabled={readOnly}
            className={`no-print p-1 rounded mb-2 transition ${category.section === 'shaft' ? 'text-blue-600 bg-blue-100 hover:bg-blue-200' : 'text-gray-500 hover:bg-gray-200'} ${readOnly ? 'opacity-50 cursor-not-allowed' : ''}`}
            title={category.section === 'shaft' ? "Patrí do: Šachta / Konštrukcia" : "Patrí do: Výťah / Technológia"}
        >
            {category.section === 'shaft' ? <Box size={18} /> : <Layers size={18} />}
        </button>

        {/* Vertically Centered Text */}
        <div className="flex-1 flex items-center justify-center">
             <div className="transform -rotate-90 whitespace-nowrap">
                {readOnly ? (
                    <span className="font-bold text-lg text-gray-800 w-64 text-center block">{category.name}</span>
                ) : (
                    <input
                        type="text"
                        value={category.name}
                        onChange={(e) => onUpdateCategory(category.id, 'name', e.target.value)}
                        className="bg-transparent font-bold text-lg text-gray-800 text-center focus:outline-none focus:text-black placeholder-gray-400 print:text-black w-64"
                        placeholder="Názov Kategórie"
                    />
                )}
            </div>
        </div>
      </div>

      {/* Right Content - Table & Actions */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* Category Toolbar - Hide most actions if ReadOnly */}
        <div className={`bg-gray-50 p-1 flex justify-end gap-2 border-b border-gray-200 print:hidden ${readOnly ? 'bg-gray-100' : ''}`}>

           {/* Move Buttons */}
           {!readOnly && onMoveCategory && (
                <div className="flex gap-1 mr-auto border-r pr-2 border-gray-300">
                     <button onClick={() => onMoveCategory(category.id, 'up')} className="p-1 hover:bg-gray-200 rounded text-gray-600" title="Posunúť hore"><ChevronUp size={16}/></button>
                     <button onClick={() => onMoveCategory(category.id, 'down')} className="p-1 hover:bg-gray-200 rounded text-gray-600" title="Posunúť dole"><ChevronDown size={16}/></button>
                </div>
           )}

           {category.section === 'shaft' && (
               <span className="mr-auto text-xs font-bold text-blue-600 uppercase tracking-wider bg-blue-50 px-2 py-1 rounded border border-blue-100 flex items-center gap-1">
                   <Box size={12}/> Šachta / Konštrukcia
               </span>
           )}

            {!readOnly && (
                <>
                    {/* HIDE FROM PRINT (But Calculate) */}
                    <button
                        onClick={togglePrintVisibility}
                        className={`flex items-center gap-1 px-2 py-1 text-xs font-medium rounded transition ${isHiddenFromPrint ? 'bg-red-100 text-red-600 border border-red-200' : 'text-gray-400 hover:bg-gray-200 hover:text-black'}`}
                        title={isHiddenFromPrint ? "Položka sa TLAČÍ (Zahrnutá v cene)" : "Skryť pri tlači (ALE POČÍTAŤ CENU)"}
                    >
                         <div className="relative">
                            <Printer size={18} />
                            {isHiddenFromPrint && <div className="absolute inset-0 flex items-center justify-center"><div className="w-full h-0.5 bg-red-600 rotate-45 transform"></div></div>}
                         </div>
                    </button>

                    {/* HIDE COMPLETELY (Exclude) */}
                    <button
                        onClick={toggleVisibility}
                        className={`flex items-center gap-1 px-2 py-1 text-xs font-medium rounded transition ${isHidden ? 'bg-gray-300 text-gray-700' : 'text-gray-400 hover:bg-gray-200 hover:text-black'}`}
                        title={isHidden ? "Zobraziť (Zahrnúť do ceny)" : "Skryť ÚPLNE (Vyradiť z ceny)"}
                    >
                        {isHidden ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>

                    <div className="w-px bg-gray-300 mx-1"></div>

                    <button
                        onClick={toggleRichText}
                        className={`flex items-center gap-1 px-3 py-1 text-xs font-medium rounded transition ${showRichText ? 'bg-blue-100 text-blue-700' : 'text-gray-600 hover:bg-gray-200'}`}
                        title="Pridať textový popis, obrázky alebo tabuľky"
                    >
                        <FileText size={14} />
                        {showRichText ? 'Skryť popis' : 'Pridať technický popis'}
                    </button>
                    <button
                        onClick={() => onAiSuggest(category.id, category.name)}
                        disabled={isAiLoading}
                        className="flex items-center gap-1 px-3 py-1 text-xs font-medium text-black bg-yellow-400 rounded hover:bg-yellow-500 transition disabled:opacity-50"
                        title="AI Navrhnúť položky"
                    >
                        <Sparkles size={14} />
                        {isAiLoading ? '...' : 'AI Položky'}
                    </button>
                    <button
                        onClick={() => onDeleteCategory(category.id)}
                        className="text-gray-400 hover:text-red-600 transition"
                        title="Odstrániť kategóriu"
                    >
                        <Trash2 size={18} />
                    </button>
                </>
            )}
            {readOnly && (
                 <span className="text-xs text-gray-400 font-medium uppercase tracking-wider flex items-center gap-1">
                     <FileText size={12}/> Príloha
                 </span>
            )}
        </div>

        {/* 1. Items Table - REDUCED PADDING */}
        {category.items.length > 0 && (
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-100 text-gray-600 font-medium print:bg-gray-50 print:text-gray-600 print:border-b print:border-gray-300 text-xs">
              <tr>
                {!readOnly && <th className="px-1 py-1 w-6 no-print"></th>}
                <th className="px-2 py-1 w-8 no-print align-top border-b border-gray-200">#</th>
                <th className="px-2 py-1 align-top border-b border-gray-200 w-auto">Popis položky</th>
                <th className="px-2 py-1 w-14 text-right align-top border-b border-gray-200">M.J.</th>
                <th className="px-2 py-1 w-16 text-right align-top border-b border-gray-200">Mn.</th>

                {/* Price Column - Visible on Screen, Hidden in Print if toggled */}
                <th className={`px-2 py-1 w-24 text-right align-top border-b border-gray-200 price-column-strict ${hidePrices ? '' : ''}`}>
                    <span className={`print:hidden ${readOnly ? 'text-black' : 'text-blue-600'}`}>
                        {readOnly ? 'Cena/J' : 'Nákup/J'}
                    </span>
                    <span className="hidden print:inline">Cena/J</span>
                </th>

                {!readOnly && <th className="px-2 py-1 w-16 no-print align-top border-b border-gray-200"></th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 print:divide-gray-200">
              {category.items.map((item, index) => {
                const sellingPrice = getSellingPrice(item.unitPrice);
                return (
                <tr 
                    key={item.id} 
                    className={`hover:bg-gray-50 group transition-colors print:hover:bg-transparent ${item.isSurcharge ? 'bg-gray-50/50' : ''}`}
                    draggable={!readOnly}
                    onDragStart={(e) => onDragStartItem(e, item.id)}
                    onDragOver={(e) => onDragOverItem(e, item.id)}
                    onDragEnd={onDragEndItem}
                >
                  {!readOnly && (
                      <td className="px-1 py-1 text-center no-print text-gray-300 cursor-grab hover:text-gray-500">
                          <GripVertical size={14}/>
                      </td>
                  )}
                  <td className="px-2 py-1 text-gray-500 no-print align-top text-xs">{index + 1}</td>
                  <td className="px-2 py-1 align-top relative">
                    {readOnly ? (
                        <div className={`text-gray-900 whitespace-pre-wrap leading-tight ${item.isSurcharge ? 'pl-6 italic text-gray-600' : ''}`}>
                            {item.isSurcharge && <span className="absolute left-2 top-1 text-gray-400 text-[10px]">•</span>}
                            {item.description}
                        </div>
                    ) : (
                        <div className={`flex gap-2 ${item.isSurcharge ? 'pl-6' : ''}`}>
                             {item.isSurcharge && <span className="absolute left-2 top-2 text-gray-400 text-[10px]">•</span>}
                             <textarea
                                rows={1}
                                value={item.description}
                                onChange={(e) => {
                                    onUpdateItem(category.id, item.id, 'description', e.target.value);
                                    // Auto-resize
                                    e.target.style.height = 'auto';
                                    e.target.style.height = e.target.scrollHeight + 'px';
                                }}
                                onInput={(e) => {
                                    const target = e.target as HTMLTextAreaElement;
                                    target.style.height = 'auto';
                                    target.style.height = target.scrollHeight + 'px';
                                }}
                                className={`w-full bg-transparent focus:outline-none focus:text-black resize-none min-h-[1.5rem] placeholder-gray-400 print:text-black leading-tight overflow-hidden ${item.isSurcharge ? 'italic text-gray-600' : 'text-gray-900'}`}
                                placeholder="Názov položky..."
                            />
                            {/* In-row Catalog Button = Swap Item */}
                            <button
                                onClick={() => onOpenCatalog(category.id, item.id)}
                                className="no-print self-start p-1.5 text-blue-400 bg-blue-50 hover:bg-blue-100 hover:text-blue-700 rounded transition opacity-0 group-hover:opacity-100 focus:opacity-100"
                                title="Vybrať variant z katalógu (Vymeniť)"
                            >
                                <BookOpen size={14} />
                            </button>
                        </div>
                    )}
                  </td>
                  <td className="px-2 py-1 align-top text-right">
                    {readOnly ? (
                         <span className="text-gray-900 text-xs">{item.unit}</span>
                    ) : (
                        <select
                            value={item.unit}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'unit', e.target.value)}
                            className="w-full text-right bg-white text-gray-900 border border-gray-300 rounded px-1 py-0 focus:outline-none focus:border-yellow-500 appearance-none print:bg-transparent print:text-black print:border-none print:appearance-auto text-xs"
                        >
                            <option value="ks">ks</option>
                            <option value="m">m</option>
                            <option value="hod">hod</option>
                            <option value="kpl">kpl</option>
                            <option value="set">set</option>
                        </select>
                    )}
                  </td>
                  <td className="px-2 py-1 align-top text-right">
                    {readOnly ? (
                        <span className="text-gray-900 font-medium text-xs">{item.quantity}</span>
                    ) : (
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            value={item.quantity}
                            onChange={(e) => onUpdateItem(category.id, item.id, 'quantity', parseFloat(e.target.value) || 0)}
                            className="w-full text-right bg-transparent text-gray-900 font-medium focus:outline-none print:text-black text-xs"
                        />
                    )}
                  </td>

                  {/* Price Column - Controlled by CSS Style Block */}
                  <td className="px-2 py-1 align-top text-right price-column-strict">
                    {readOnly ? (
                        <span className="text-xs font-medium text-black block">
                            {formatNumber(sellingPrice)} {currency}
                        </span>
                    ) : (
                        <>
                            {/* EDIT MODE: Input for Cost - Visually dimmed if intended hidden, but still visible to admin */}
                            <input
                                type="number"
                                min="0"
                                step="0.01"
                                value={item.unitPrice}
                                onChange={(e) => onUpdateItem(category.id, item.id, 'unitPrice', parseFloat(e.target.value) || 0)}
                                className={`w-full text-right bg-transparent font-bold focus:outline-none text-xs print:hidden cursor-text ${hidePrices ? 'text-gray-400' : 'text-blue-700 bg-blue-50/20'}`}
                                placeholder="0.00"
                                title="Upraviť cenu (Len pre túto ponuku)"
                            />
                            {/* PRINT MODE: Calculated Selling Price */}
                            <span className="hidden print:block text-xs font-medium text-black">
                                {formatNumber(sellingPrice)} {currency}
                            </span>
                        </>
                    )}
                  </td>

                  {/* Delete/Add Surcharge Action - Hidden in ReadOnly */}
                  {!readOnly && (
                    <td className="px-2 py-1 text-center no-print align-top flex justify-center gap-1">
                        <button
                            onClick={() => onAddItem(category.id, true)}
                            className="text-gray-300 hover:text-blue-500 hover:bg-blue-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                            title="Pridať príplatok / pod-položku"
                        >
                            <Percent size={14} />
                        </button>
                        <button
                            onClick={() => onDeleteItem(category.id, item.id)}
                            className="text-gray-300 hover:text-red-500 hover:bg-red-50 p-1 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <Trash2 size={14} />
                        </button>
                    </td>
                  )}
                </tr>
              )})}
            </tbody>
          </table>
        </div>
        )}

          {!readOnly && (
            <div className="p-2 border-t border-gray-200 bg-gray-50 no-print flex gap-2">
                <button
                onClick={() => onAddItem(category.id)}
                className="flex items-center gap-1 text-sm font-medium text-gray-600 hover:text-black px-2 py-1 rounded hover:bg-gray-200 transition"
                >
                <Plus size={16} /> Pridať položku
                </button>
                <button
                onClick={() => onOpenCatalog(category.id)}
                className="flex items-center gap-1 text-sm font-medium text-blue-600 hover:text-blue-800 px-2 py-1 rounded hover:bg-blue-50 transition ml-auto"
                >
                <BookOpen size={16} /> Z katalógu
                </button>
            </div>
          )}

          {/* 2. Embedded Rich Text Area - RENDERED BELOW ITEMS */}
          {(showRichText || (readOnly && category.textContent)) && (
            <div className="border-t border-gray-200 p-4 bg-white">
                <div className="mb-2 text-xs font-bold text-gray-400 uppercase tracking-wider print:hidden">Technická špecifikácia / Prílohy</div>

                {/* Editor Content */}
                <div
                    ref={editorRef}
                    contentEditable={!readOnly}
                    onInput={handleInput}
                    className={`rich-text-content w-full min-h-[80px] outline-none text-gray-900 text-sm ${readOnly ? 'pointer-events-none' : ''}`}
                    dangerouslySetInnerHTML={{ __html: category.textContent || '' }}
                />
            </div>
          )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Product, CabinClass, ProductComponent } from '../types';
import { 
  X, Search, Plus, Trash2, Save, Upload, Settings, Layers, Edit, Check, 
  ArrowRightCircle, CornerDownRight, CheckSquare, Square, Filter, ChevronDown, ChevronRight, AlertTriangle, Box, Download, Package, ListPlus, Calculator, RotateCcw, Factory, Truck, Tag, FileText
} from 'lucide-react';

const generateId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      try {
        return crypto.randomUUID();
      } catch (e) { }
    }
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
};

// Helper to generate consistent pastel colors from string
const getSubcatColor = (str: string) => {
    if (!str) return 'bg-gray-100 text-gray-600 border-gray-200';
    const colors = [
        'bg-blue-100 text-blue-700 border-blue-200',
        'bg-green-100 text-green-700 border-green-200',
        'bg-purple-100 text-purple-700 border-purple-200',
        'bg-orange-100 text-orange-700 border-orange-200',
        'bg-teal-100 text-teal-700 border-teal-200',
        'bg-indigo-100 text-indigo-700 border-indigo-200',
        'bg-pink-100 text-pink-700 border-pink-200',
        'bg-yellow-100 text-yellow-700 border-yellow-200',
    ];
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    const index = Math.abs(hash) % colors.length;
    return colors[index];
};

interface CatalogManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  onAddProduct: (product: Product) => void;
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  customCategories: string[];
  onAddCategory: (name: string) => void;
  onDeleteCategory: (name: string) => void;
  onImportCatalog: (file: File) => void;
  cabinClasses: CabinClass[];
  onAddCabinClass: (cc: CabinClass) => void;
  onUpdateCabinClass: (cc: CabinClass) => void;
  onDeleteCabinClass: (id: string) => void;
}

export const CatalogManagerModal: React.FC<CatalogManagerModalProps> = ({
  isOpen, onClose, products = [], onAddProduct, onUpdateProduct, onDeleteProduct,
  customCategories = [], onAddCategory, onDeleteCategory, onImportCatalog,
  cabinClasses = [], onAddCabinClass, onUpdateCabinClass, onDeleteCabinClass
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'categories' | 'classes'>('products');
  const [activeCategory, setActiveCategory] = useState<string>(''); 
  const [activeSubcategoryFilter, setActiveSubcategoryFilter] = useState<string>('ALL'); // 'ALL', 'NONE', or specific name
  const [searchTerm, setSearchTerm] = useState('');

  // Bulk Actions State
  const [selectedProductIds, setSelectedProductIds] = useState<Set<string>>(new Set());

  // PRODUCT EDITOR STATE
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editorProduct, setEditorProduct] = useState<Partial<Product>>({});

  // Component Selection State inside Editor
  const [componentSearch, setComponentSearch] = useState('');
  const [componentCategoryFilter, setComponentCategoryFilter] = useState<string>('ALL'); // New filter inside editor

  // New Category State
  const [newCategoryName, setNewCategoryName] = useState('');

  // Class Management State
  const [editingClassId, setEditingClassId] = useState<string | null>(null);
  const [newClassName, setNewClassName] = useState('');
  const [newClassDesc, setNewClassDesc] = useState('');
  const [newClassLinkedSet, setNewClassLinkedSet] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize active category
  useEffect(() => {
      if (customCategories.length > 0 && !activeCategory) {
          setActiveCategory(customCategories[0]);
      }
  }, [customCategories, activeCategory]);

  // Reset Subcategory filter when Category changes
  useEffect(() => {
      setActiveSubcategoryFilter('ALL');
      setSelectedProductIds(new Set());
  }, [activeCategory]);

  // Reset component filters when editor opens
  useEffect(() => {
      if (isEditorOpen) {
          setComponentSearch('');
          setComponentCategoryFilter('ALL');
      }
  }, [isEditorOpen]);

  // 1. Base Filter (Category + Search)
  const productsInCurrentCategory = useMemo(() => {
      return products.filter(p => {
          const matchCat = activeCategory ? p.category === activeCategory : true;
          const matchSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
          return matchCat && matchSearch;
      });
  }, [products, activeCategory, searchTerm]);

  // 2. Identify Subcategories in current view
  const currentSubcategories = useMemo(() => {
      const subs = new Set<string>();
      productsInCurrentCategory.forEach(p => {
          if (p.subcategory) subs.add(p.subcategory);
      });
      return Array.from(subs).sort();
  }, [productsInCurrentCategory]);

  // 3. Final Display Filter (Subcategory Pill)
  const displayedProducts = useMemo(() => {
      if (activeSubcategoryFilter === 'ALL') return productsInCurrentCategory;
      if (activeSubcategoryFilter === 'NONE') return productsInCurrentCategory.filter(p => !p.subcategory);
      return productsInCurrentCategory.filter(p => p.subcategory === activeSubcategoryFilter);
  }, [productsInCurrentCategory, activeSubcategoryFilter]);


  // --- COMPONENT SELECTION LOGIC (Inside Editor) ---
  const availableComponentsGrouped = useMemo(() => {
      if (editorProduct.type !== 'composite') return { grouped: {}, sortedKeys: [] };

      // 1. Filter products based on search and category filter
      const filtered = products.filter(p => {
          if (p.id === editorProduct.id) return false; // Prevent self-reference
          const matchSearch = p.name.toLowerCase().includes(componentSearch.toLowerCase());
          const matchCat = componentCategoryFilter === 'ALL' || p.category === componentCategoryFilter;
          return matchSearch && matchCat;
      });

      // 2. Group by Subcategory
      const grouped: Record<string, Product[]> = {};

      filtered.forEach(p => {
          const sub = p.subcategory || 'Bez podkategórie';
          if (!grouped[sub]) grouped[sub] = [];
          grouped[sub].push(p);
      });

      // Sort categories: "Bez podkategórie" last, others alphabetical
      const sortedKeys = Object.keys(grouped).sort((a, b) => {
          if (a === 'Bez podkategórie') return 1;
          if (b === 'Bez podkategórie') return -1;
          return a.localeCompare(b);
      });

      return { grouped, sortedKeys };
  }, [products, editorProduct.id, componentSearch, componentCategoryFilter, editorProduct.type]);


  // --- Handlers ---

  const handleExportCatalog = () => {
      const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(products, null, 2));
      const downloadAnchorNode = document.createElement('a');
      downloadAnchorNode.setAttribute("href", dataStr);
      downloadAnchorNode.setAttribute("download", `katalog_export_${new Date().toISOString().split('T')[0]}.json`);
      document.body.appendChild(downloadAnchorNode);
      downloadAnchorNode.click();
      downloadAnchorNode.remove();
  };

  const handleBulkSelection = (id: string) => {
      const newSet = new Set(selectedProductIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setSelectedProductIds(newSet);
  };

  const toggleSelectAll = () => {
      if (selectedProductIds.size === displayedProducts.length && displayedProducts.length > 0) {
          setSelectedProductIds(new Set());
      } else {
          setSelectedProductIds(new Set(displayedProducts.map(p => p.id)));
      }
  };

  const handlePillClick = (subcat: string | 'ALL' | 'NONE') => {
      if (selectedProductIds.size > 0) {
          if (subcat === 'ALL') return; // Cannot move to ALL

          const targetSubcatName = subcat === 'NONE' ? undefined : subcat;
          const idsToMove = Array.from(selectedProductIds);

          if (window.confirm(`Presunúť ${idsToMove.length} označených produktov do podkategórie "${subcat === 'NONE' ? 'Bez podkategórie' : subcat}"?`)) {
              idsToMove.forEach(id => {
                  const product = products.find(p => p.id === id);
                  if (product) {
                      onUpdateProduct({
                          ...product,
                          // IMPORTANT: Keep existing category, just update subcategory
                          subcategory: targetSubcatName
                      });
                  }
              });
              // Clear selection after move
              setSelectedProductIds(new Set());
          }
          return;
      }
      setActiveSubcategoryFilter(subcat);
  };

  const handleDeleteSelected = () => {
      if (window.confirm(`Naozaj vymazať ${selectedProductIds.size} produktov?`)) {
          selectedProductIds.forEach(id => onDeleteProduct(id));
          setSelectedProductIds(new Set());
      }
  };

  // --- EDITOR HANDLERS (Create/Edit) ---

  const openEditor = (product?: Product) => {
      if (product) {
          setEditorProduct({ ...product }); // Edit Mode
      } else {
          setEditorProduct({ // Create Mode
              id: generateId(),
              category: activeCategory,
              subcategory: activeSubcategoryFilter !== 'ALL' && activeSubcategoryFilter !== 'NONE' ? activeSubcategoryFilter : undefined,
              type: 'simple',
              unit: 'ks',
              price: 0,
              priceType: 'fixed',
              displayMode: 'itemized',
              subProducts: []
          });
      }
      setIsEditorOpen(true);
  };

  const saveEditor = () => {
      if (!editorProduct.name) {
          alert("Zadajte názov produktu.");
          return;
      }

      const finalProduct = {
          ...editorProduct,
          price: Number(editorProduct.price) || 0
      } as Product;

      if (products.find(p => p.id === finalProduct.id)) {
          onUpdateProduct(finalProduct);
      } else {
          onAddProduct(finalProduct);
      }
      setIsEditorOpen(false);
  };

  const addComponentToSet = (component: Product) => {
      const currentSubs = editorProduct.subProducts || [];
      const exists = currentSubs.find(s => s.productId === component.id);
      if (exists) {
          // Move to top if updated? Or just update qty? Let's just update qty for existing.
          const updated = currentSubs.map(s => s.productId === component.id ? { ...s, quantity: s.quantity + 1 } : s);
          setEditorProduct({ ...editorProduct, subProducts: updated });
      } else {
          // PREPEND new item so it appears at the TOP
          setEditorProduct({ ...editorProduct, subProducts: [{ productId: component.id, quantity: 1 }, ...currentSubs] });
      }
      // Keep search open for multiple adds
  };

  const removeComponentFromSet = (productId: string) => {
      const currentSubs = editorProduct.subProducts || [];
      setEditorProduct({ ...editorProduct, subProducts: currentSubs.filter(s => s.productId !== productId) });
  };

  const updateComponentQty = (productId: string, qty: number) => {
      const currentSubs = editorProduct.subProducts || [];
      setEditorProduct({ ...editorProduct, subProducts: currentSubs.map(s => s.productId === productId ? { ...s, quantity: qty } : s) });
  };

  const calculateSetPrice = () => {
      if (!editorProduct.subProducts) return 0;
      return editorProduct.subProducts.reduce((sum, sub) => {
          const p = products.find(prod => prod.id === sub.productId);
          return sum + ((p?.price || 0) * sub.quantity);
      }, 0);
  };

  const generateDescriptionFromComponents = () => {
      if (!editorProduct.subProducts || editorProduct.subProducts.length === 0) return;

      const componentNames = editorProduct.subProducts
          .map(sub => {
              const p = products.find(prod => prod.id === sub.productId);
              return p ? p.name : '';
          })
          .filter(Boolean)
          .join(' + ');

      if (componentNames) {
          // Append to name or just alert? Let's append to Name as requested "dopisat do textu"
          // Assuming user wants to edit the Product Name or have it in description (no desc field in Product yet, using Name for now or creating composite name)
          const currentName = editorProduct.name || '';
          const newName = currentName.includes('(') 
              ? currentName.replace(/\(.*\)/, `(${componentNames})`) // Replace existing parenthesis content
              : `${currentName} (${componentNames})`;

          setEditorProduct({...editorProduct, name: newName});
      }
  };

  useEffect(() => {
      if (editorProduct.type === 'composite' && editorProduct.priceType === 'calculated') {
          const total = calculateSetPrice();
          if (total !== editorProduct.price) {
              setEditorProduct(prev => ({ ...prev, price: total }));
          }
      }
  }, [editorProduct.subProducts, editorProduct.priceType, editorProduct.type]);


  const handleAddCategorySubmit = () => {
      if (newCategoryName && !customCategories.includes(newCategoryName)) {
          onAddCategory(newCategoryName);
          setNewCategoryName('');
      }
  };

  // --- CABIN CLASS HANDLERS ---
  const handleEditClass = (cc: CabinClass) => {
      setEditingClassId(cc.id);
      setNewClassName(cc.name);
      setNewClassDesc(cc.description);
      setNewClassLinkedSet(cc.linkedProductId || '');
  };

  const handleCancelClassEdit = () => {
      setEditingClassId(null);
      setNewClassName('');
      setNewClassDesc('');
      setNewClassLinkedSet('');
  };

  const handleClassSubmit = () => {
      if (!newClassName) return;

      if (editingClassId) {
          // Update existing
          onUpdateCabinClass({
              id: editingClassId,
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
      } else {
          // Create new
          onAddCabinClass({
              id: generateId(),
              name: newClassName,
              description: newClassDesc,
              linkedProductId: newClassLinkedSet || undefined
          });
      }
      handleCancelClassEdit();
  };

  const handleAddSubcategory = () => {
      const name = prompt("Názov novej podkategórie:");
      if (name) {
          // Just setting filter doesn't create it, but shows user intention
          alert(`Pre vytvorenie podkategórie "${name}" stačí pri úprave produktu napísať tento názov do poľa Podkategória.`);
      }
  };

  if (!isOpen) return null;

  // --- EDITOR OVERLAY ---
  if (isEditorOpen) {
      const isSet = editorProduct.type === 'composite';
      return (
          <div className="fixed inset-0 bg-black/60 z-[110] flex items-center justify-center p-4">
              {/* WIDER MODAL FOR EDITOR */}
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-7xl max-h-[95vh] flex flex-col animate-in fade-in zoom-in-95">
                  <div className="p-4 border-b bg-gray-50 flex justify-between items-center rounded-t-xl">
                      <h2 className="text-xl font-bold text-gray-800">
                          {products.find(p => p.id === editorProduct.id) ? 'Upraviť Produkt' : 'Nový Produkt'}
                      </h2>
                      <button onClick={() => setIsEditorOpen(false)} className="p-2 hover:bg-gray-200 rounded-full"><X size={20}/></button>
                  </div>

                  <div className="p-6 flex-1 overflow-y-auto">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 h-full">
                          {/* Left Column: Basic Info */}
                          <div className="space-y-6 overflow-y-auto pr-2">
                              <div>
                                  <label className="block text-sm font-bold text-gray-700 mb-1">Názov produktu</label>
                                  <div className="flex gap-2">
                                      <input 
                                          className="w-full p-2 border rounded focus:ring-2 focus:ring-purple-500 font-bold text-lg" 
                                          value={editorProduct.name || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, name: e.target.value})}
                                          autoFocus
                                      />
                                      {isSet && (
                                          <button 
                                            onClick={generateDescriptionFromComponents}
                                            className="px-3 py-2 bg-yellow-100 text-yellow-800 border border-yellow-300 rounded hover:bg-yellow-200 text-xs font-bold whitespace-nowrap flex items-center gap-1"
                                            title="Vložiť zoznam komponentov do názvu (napr. do zátvorky)"
                                          >
                                              <FileText size={14}/> Doplniť zloženie
                                          </button>
                                      )}
                                  </div>
                              </div>

                              {/* NEW: Manufacturer & Supplier Inputs */}
                              <div className="grid grid-cols-2 gap-4 bg-gray-50 p-3 rounded border border-gray-200">
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1 flex items-center gap-1"><Factory size={12}/> Výrobca</label>
                                      <input 
                                          className="w-full p-2 border rounded text-sm bg-white" 
                                          placeholder="napr. Fermator"
                                          value={editorProduct.manufacturer || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, manufacturer: e.target.value})}
                                      />
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1 flex items-center gap-1"><Truck size={12}/> Dodávateľ</label>
                                      <input 
                                          className="w-full p-2 border rounded text-sm bg-white" 
                                          placeholder="napr. Sklad / Výťahy s.r.o."
                                          value={editorProduct.supplier || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, supplier: e.target.value})}
                                      />
                                  </div>
                              </div>

                              <div className="grid grid-cols-2 gap-4">
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Kategória</label>
                                      <select 
                                          className="w-full p-2 border rounded text-sm bg-gray-50"
                                          value={editorProduct.category || activeCategory} 
                                          onChange={e => setEditorProduct({...editorProduct, category: e.target.value})}
                                      >
                                          {customCategories.map(c => <option key={c} value={c}>{c}</option>)}
                                      </select>
                                  </div>
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Podkategória</label>
                                      <input 
                                          className="w-full p-2 border rounded text-sm" 
                                          list="subcat-options"
                                          value={editorProduct.subcategory || ''} 
                                          onChange={e => setEditorProduct({...editorProduct, subcategory: e.target.value})}
                                          placeholder="napr. Trakčné stroje"
                                      />
                                      <datalist id="subcat-options">
                                          {currentSubcategories.map(s => <option key={s} value={s}/>)}
                                      </datalist>
                                  </div>
                              </div>

                              {/* TYPE SWITCHER */}
                              <div className="bg-gray-100 p-1 rounded-lg flex text-sm font-bold mt-4">
                                  <button 
                                      className={`flex-1 py-2 rounded-md transition flex items-center justify-center gap-2 ${!isSet ? 'bg-white shadow text-gray-800' : 'text-gray-500 hover:text-gray-700'}`}
                                      onClick={() => setEditorProduct({...editorProduct, type: 'simple'})}
                                  >
                                      <Box size={16}/> Jednoduchý Diel
                                  </button>
                                  <button 
                                      className={`flex-1 py-2 rounded-md transition flex items-center justify-center gap-2 ${isSet ? 'bg-purple-600 text-white shadow' : 'text-gray-500 hover:text-gray-700'}`}
                                      onClick={() => setEditorProduct({...editorProduct, type: 'composite', priceType: 'calculated'})}
                                  >
                                      <Layers size={16}/> Zložený SET
                                  </button>
                              </div>

                              <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-lg border border-gray-200">
                                  <div>
                                      <label className="block text-xs font-bold text-gray-500 mb-1">Cena (€)</label>
                                      <input 
                                          type="number"
