                                                          <input 
                                                              type="number" 
                                                              className="w-12 p-1 text-center border rounded text-xs font-bold" 
                                                              value={sub.quantity}
                                                              onChange={e => updateComponentQty(sub.productId, parseFloat(e.target.value) || 0)}
