                                  </div>
                              )}
                          </div>
                      </div>
                  </div>

                  <div className="p-4 border-t bg-gray-50 rounded-b-xl flex justify-end gap-2">
                      <button onClick={() => setIsEditorOpen(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-bold">Zrušiť</button>
