              </div>
          </div>
      );
  }

  // Render Product Row
  const renderProductRow = (product: Product) => (
    <tr key={product.id} className={`hover:bg-blue-50 transition border-b border-gray-100 ${selectedProductIds.has(product.id) ? 'bg-blue-50' : ''}`}>
